/// FFT-backed predictor for a standard MFS component model.
///
/// This mirrors the standard-gridder model prediction path used during major
/// cycle residual refreshes, but exposes only the per-sample model visibility
/// needed by frontends that persist a `MODEL_DATA` column.
pub struct StandardMfsModelPredictor {
    gridder: StandardGridder,
    model_grid: Option<Array2<Complex32>>,
}

/// Planner for bounded standard-MFS weighted sample blocks.
///
/// Frontends use this helper after applying natural/uniform/Briggs weighting to
/// convert compact weighted samples into the shared planned representation used
/// by the CPU gridders. The planner owns the private standard gridder state, so
/// callers do not need access to internal tap tables.
pub struct StandardMfsPlannedSampleBuilder {
    gridder: StandardGridder,
}

/// Replayable source of bounded standard-MFS planned sample blocks.
///
/// This is the core streaming input boundary for standard-MFS backends. A
/// frontend may read MeasurementSet rows, apply weighting, and plan compact tap
/// identities however it chooses, but it must be able to replay the same
/// bounded blocks for the initial dirty/PSF pass and every exact residual
/// refresh pass.
pub(crate) trait StandardMfsPlannedSampleBlockSource {
    /// Replay planned samples in stable input order.
    fn replay_planned_sample_blocks(
        &mut self,
        consumer: &mut dyn FnMut(&[StandardMfsPlannedWeightedSample]) -> Result<(), ImagingError>,
    ) -> Result<(), ImagingError>;

    /// Replay planned samples with explicit scalar-run ranges when available.
    fn replay_planned_sample_run_blocks(
        &mut self,
        consumer: &mut dyn FnMut(
            &StandardMfsPlannedWeightedSampleRunBlock,
        ) -> Result<(), ImagingError>,
    ) -> Result<(), ImagingError> {
        let mut run_block = StandardMfsPlannedWeightedSampleRunBlock::default();
        self.replay_planned_sample_blocks(&mut |samples| {
            run_block.clear();
            run_block.push_run_from_slice(samples);
            consumer(&run_block)
        })
    }
}

/// Replayable source of standard-MFS routed visibility runs.
///
/// This boundary publishes each row/channel run as soon as it is routed, so the
/// fixed-tile scheduler can enqueue tile work without waiting for a frontend
/// row-block staging vector.
pub(crate) trait StandardMfsRoutedVisibilityRunSource {
    /// Replay routed row/channel runs in stable input order.
    fn replay_routed_visibility_runs(
        &mut self,
        consumer: &mut dyn FnMut(&StandardMfsRoutedVisibilityRun) -> Result<(), ImagingError>,
    ) -> Result<(), ImagingError>;
}

impl<F> StandardMfsPlannedSampleBlockSource for F
where
    F: FnMut(
        &mut dyn FnMut(&[StandardMfsPlannedWeightedSample]) -> Result<(), ImagingError>,
    ) -> Result<(), ImagingError>,
{
    fn replay_planned_sample_blocks(
        &mut self,
        consumer: &mut dyn FnMut(&[StandardMfsPlannedWeightedSample]) -> Result<(), ImagingError>,
    ) -> Result<(), ImagingError> {
        self(consumer)
    }
}

impl StandardMfsPlannedSampleBuilder {
    /// Build a planner for standard-MFS image geometry.
    #[inline]
    pub fn new(geometry: ImageGeometry) -> Result<Self, ImagingError> {
        Ok(Self {
            gridder: StandardGridder::new(geometry)?,
        })
    }

    /// Plan one weighted sample, returning `None` when it does not grid.
    #[inline]
    pub(crate) fn plan_sample(
        &self,
        sample: StandardMfsWeightedSample,
    ) -> Result<Option<StandardMfsPlannedWeightedSample>, ImagingError> {
        if !sample.gridable {
            return Ok(None);
        }
        if !(sample.weight.is_finite()
            && sample.weight > 0.0
            && sample.sumwt_factor.is_finite()
            && sample.sumwt_factor > 0.0)
        {
            return Ok(None);
        }
        let grid_weight = sample.weight * sample.sumwt_factor;
        if !(grid_weight.is_finite() && grid_weight > 0.0) {
            return Ok(None);
        }
        let Some(taps) = self
            .gridder
            .plan_positive_taps(sample.u_lambda, sample.v_lambda)
        else {
            return Ok(None);
        };
        let center = taps.center();
        let flags = if finite_visibility(sample.visibility) {
            StandardMfsPlannedWeightedSample::FINITE_VISIBILITY
        } else {
            StandardMfsPlannedWeightedSample::PSF_ONLY
        };
        Ok(Some(StandardMfsPlannedWeightedSample {
            u_lambda: sample.u_lambda,
            v_lambda: sample.v_lambda,
            center_x: center[0] as u32,
            center_y: center[1] as u32,
            x_start: taps.x.start as u32,
            y_start: taps.y.start as u32,
            x_weight_index: taps.x.weight_index as u32,
            y_weight_index: taps.y.weight_index as u32,
            flags,
            tap_count: (STANDARD_GRIDDER_TAP_COUNT * STANDARD_GRIDDER_TAP_COUNT) as u8,
            grid_weight,
            w_lambda: sample.w_lambda,
            visibility: sample.visibility,
        }))
    }

    /// Plan and append one scalar visibility sample to an opaque planned block.
    ///
    /// Returns `true` when the sample contributes to the block, or `false` when
    /// it is outside the grid or otherwise not gridable.
    pub fn push_sample(
        &self,
        block: &mut StandardMfsPlannedSampleBlock,
        sample: ScalarVisibilitySample,
    ) -> Result<bool, ImagingError> {
        if let Some(planned_sample) = self.plan_sample(sample.into())? {
            block.push_sample(planned_sample);
            Ok(true)
        } else {
            Ok(false)
        }
    }

    /// Plan a weighted row block into a caller-provided output buffer.
    #[cfg(test)]
    pub(crate) fn plan_samples_into(
        &self,
        samples: &[StandardMfsWeightedSample],
        planned: &mut Vec<StandardMfsPlannedWeightedSample>,
    ) -> Result<usize, ImagingError> {
        let initial_len = planned.len();
        planned.reserve(samples.len());
        for &sample in samples {
            if let Some(planned_sample) = self.plan_sample(sample)? {
                planned.push(planned_sample);
            }
        }
        Ok(planned.len() - initial_len)
    }

    /// Plan an owned visibility batch into a caller-provided output buffer.
    #[cfg(test)]
    pub(crate) fn plan_visibility_batch_into(
        &self,
        batch: &VisibilityBatch,
        planned: &mut Vec<StandardMfsPlannedWeightedSample>,
    ) -> Result<usize, ImagingError> {
        batch.validate()?;
        let initial_len = planned.len();
        planned.reserve(batch.len());
        for sample_index in 0..batch.len() {
            let sample = StandardMfsWeightedSample {
                u_lambda: batch.u_lambda[sample_index],
                v_lambda: batch.v_lambda[sample_index],
                w_lambda: batch.w_lambda[sample_index],
                weight: batch.weight[sample_index],
                sumwt_factor: batch.sumwt_factor[sample_index],
                gridable: batch.gridable[sample_index],
                visibility: batch.visibility[sample_index],
            };
            if let Some(planned_sample) = self.plan_sample(sample)? {
                planned.push(planned_sample);
            }
        }
        Ok(planned.len() - initial_len)
    }

    /// Locate the positive-tap center used for fixed-tile routing.
    #[inline]
    pub fn route_tap_center(&self, u_lambda: f64, v_lambda: f64) -> Option<[u32; 2]> {
        self.gridder
            .locate_positive_tap_center(u_lambda, v_lambda)
            .map(|center| [center[0] as u32, center[1] as u32])
    }
}

impl StandardMfsRoutedVisibilityBlock {
    /// Route one row-shaped standard-MFS input into this replay block.
    ///
    /// The block stores private backend runs while the caller receives only the
    /// candidate/planned lane counts needed for telemetry.
    pub fn append_visibility_row(
        &mut self,
        row: StandardMfsVisibilityRow,
        planned_sample_builder: &StandardMfsPlannedSampleBuilder,
        next_input_seq: &mut u64,
    ) -> Result<StandardMfsRoutedVisibilityAppendCounts, ImagingError> {
        let mut counts = StandardMfsRoutedVisibilityAppendCounts::default();
        if row.source_channel_indices.len() != row.channel_lambda_scales.len() {
            return Err(ImagingError::InvalidRequest(format!(
                "standard MFS routed row source slot count {} differs from lambda scale count {}",
                row.source_channel_indices.len(),
                row.channel_lambda_scales.len()
            )));
        }
        if !row.gridable {
            return Ok(counts);
        }

        let uvw_m = row.uvw_m;
        let channel_lambda_scales = Arc::clone(&row.channel_lambda_scales);
        let routed_row = Arc::new(row.into_routed_row());
        let mut run_start = None::<usize>;
        let mut tap_centers = Vec::<[u32; 2]>::new();

        for (source_slot, lambda_scale) in channel_lambda_scales.iter().copied().enumerate() {
            counts.candidate_samples += 1;
            let u_lambda = uvw_m[0] * lambda_scale;
            let v_lambda = uvw_m[1] * lambda_scale;
            let Some(center) = planned_sample_builder.route_tap_center(u_lambda, v_lambda) else {
                if let Some(start) = run_start.take() {
                    let run_len = tap_centers.len();
                    let centers = Arc::<[[u32; 2]]>::from(
                        std::mem::take(&mut tap_centers).into_boxed_slice(),
                    );
                    self.push_run(StandardMfsRoutedVisibilityRun {
                        row: Arc::clone(&routed_row),
                        source_slot_range: start..source_slot,
                        tap_centers: centers,
                        first_input_seq: *next_input_seq,
                    });
                    *next_input_seq = (*next_input_seq).saturating_add(run_len as u64);
                    counts.planned_samples += run_len;
                }
                continue;
            };
            if run_start.is_none() {
                run_start = Some(source_slot);
            }
            tap_centers.push(center);
        }

        if let Some(start) = run_start {
            let run_len = tap_centers.len();
            let centers = Arc::<[[u32; 2]]>::from(tap_centers.into_boxed_slice());
            self.push_run(StandardMfsRoutedVisibilityRun {
                row: routed_row,
                source_slot_range: start..channel_lambda_scales.len(),
                tap_centers: centers,
                first_input_seq: *next_input_seq,
            });
            *next_input_seq = (*next_input_seq).saturating_add(run_len as u64);
            counts.planned_samples += run_len;
        }

        Ok(counts)
    }

    /// Append cloned runs from another routed block.
    pub fn extend_from_block(&mut self, block: &Self) {
        self.runs.extend_from_slice(block.runs());
    }

    /// Append runs from another routed block and assign contiguous input
    /// sequence numbers in the receiving replay order.
    pub fn extend_resequenced_from_block(&mut self, mut block: Self, next_input_seq: &mut u64) {
        for mut run in block.drain_runs() {
            run.first_input_seq = *next_input_seq;
            *next_input_seq = (*next_input_seq).saturating_add(run.len() as u64);
            self.push_run(run);
        }
    }

    /// Conservative estimate of host memory retained by this replay block.
    pub fn estimated_host_bytes(&self) -> usize {
        let mut bytes = self
            .runs
            .len()
            .saturating_mul(std::mem::size_of::<StandardMfsRoutedVisibilityRun>());
        let mut row_ptrs = HashSet::<usize>::new();
        let mut source_channel_ptrs = HashSet::<(usize, usize)>::new();
        let mut lambda_scale_ptrs = HashSet::<(usize, usize)>::new();
        let mut tap_center_ptrs = HashSet::<(usize, usize)>::new();

        for run in &self.runs {
            let tap_ptr = run.tap_centers.as_ptr() as usize;
            let tap_len = run.tap_centers.len();
            if tap_center_ptrs.insert((tap_ptr, tap_len)) {
                bytes =
                    bytes.saturating_add(tap_len.saturating_mul(std::mem::size_of::<[u32; 2]>()));
            }

            let row = run.row.as_ref();
            let row_ptr = Arc::as_ptr(&run.row) as usize;
            if row_ptrs.insert(row_ptr) {
                bytes = bytes
                    .saturating_add(std::mem::size_of::<StandardMfsRoutedVisibilityRow>())
                    .saturating_add(
                        row.data
                            .len()
                            .saturating_mul(std::mem::size_of::<Complex32>()),
                    )
                    .saturating_add(row.flag.len().saturating_mul(std::mem::size_of::<bool>()))
                    .saturating_add(row.weight.len().saturating_mul(std::mem::size_of::<f32>()));
                if let Some(weight_spectrum) = row.weight_spectrum.as_ref() {
                    bytes = bytes.saturating_add(
                        weight_spectrum
                            .len()
                            .saturating_mul(std::mem::size_of::<f32>()),
                    );
                }
            }

            let source_ptr = row.source_channel_indices.as_ptr() as usize;
            let source_len = row.source_channel_indices.len();
            if source_channel_ptrs.insert((source_ptr, source_len)) {
                bytes =
                    bytes.saturating_add(source_len.saturating_mul(std::mem::size_of::<usize>()));
            }

            let lambda_ptr = row.channel_lambda_scales.as_ptr() as usize;
            let lambda_len = row.channel_lambda_scales.len();
            if lambda_scale_ptrs.insert((lambda_ptr, lambda_len)) {
                bytes = bytes.saturating_add(lambda_len.saturating_mul(std::mem::size_of::<f64>()));
            }
        }

        bytes
    }

    /// Visit finite weighted scalar grid samples represented by this block.
    ///
    /// This is a diagnostic/export boundary for tools that need compact sample
    /// records without inspecting routed worker payloads.
    pub fn for_each_weighted_grid_sample(
        &self,
        weighting_plan: &StandardMfsStreamingWeightingPlan,
        consumer: &mut dyn FnMut(StandardMfsRoutedGridSample) -> Result<(), ImagingError>,
    ) -> Result<usize, ImagingError> {
        let mut accepted = 0usize;
        for run in &self.runs {
            for lane_index in 0..run.len() {
                let Some(sample) =
                    routed_weighted_grid_sample_from_run(run, lane_index, weighting_plan)?
                else {
                    continue;
                };
                consumer(sample)?;
                accepted = accepted.saturating_add(1);
            }
        }
        Ok(accepted)
    }
}

/// Weighted scalar grid sample decoded from an opaque routed replay block.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct StandardMfsRoutedGridSample {
    /// Positive-tap center in the padded standard grid.
    pub center: [u32; 2],
    /// Final grid weight including CASA-style `sumwt` factor.
    pub grid_weight: f32,
    /// Scalar visibility after any configured polarization collapse.
    pub visibility: Complex32,
}

fn routed_weighted_grid_sample_from_run(
    run: &StandardMfsRoutedVisibilityRun,
    lane_index: usize,
    weighting_plan: &StandardMfsStreamingWeightingPlan,
) -> Result<Option<StandardMfsRoutedGridSample>, ImagingError> {
    let row = &run.row;
    if !row.gridable {
        return Ok(None);
    }
    let source_slot = run
        .source_slot_range
        .start
        .checked_add(lane_index)
        .ok_or_else(|| {
            ImagingError::InvalidRequest("routed lane source index overflowed".to_string())
        })?;
    let source_channel = *row.source_channel_indices.get(source_slot).ok_or_else(|| {
        ImagingError::InvalidRequest(format!("source slot {source_slot} is out of bounds"))
    })?;
    let local_channel = source_channel
        .checked_sub(row.channel_origin)
        .ok_or_else(|| {
            ImagingError::InvalidRequest(format!(
                "source channel {source_channel} precedes loaded channel origin {}",
                row.channel_origin
            ))
        })?;
    let lambda_scale = *row.channel_lambda_scales.get(source_slot).ok_or_else(|| {
        ImagingError::InvalidRequest(format!("lambda scale slot {source_slot} is out of bounds"))
    })?;
    let center = *run.tap_centers.get(lane_index).ok_or_else(|| {
        ImagingError::InvalidRequest(format!("tap center lane {lane_index} is out of bounds"))
    })?;
    let (visibility, natural_weight, sumwt_factor) = match row.polarization {
        StandardMfsVisibilityPolarization::Explicit {
            corr_index,
            sumwt_factor,
        } => {
            if *row.flag.get((corr_index, local_channel)).ok_or_else(|| {
                ImagingError::InvalidRequest(format!(
                    "FLAG index [{corr_index}, {source_channel}] is out of bounds"
                ))
            })? {
                return Ok(None);
            }
            let visibility = *row.data.get((corr_index, local_channel)).ok_or_else(|| {
                ImagingError::InvalidRequest(format!(
                    "DATA index [{corr_index}, {source_channel}] is out of bounds"
                ))
            })?;
            if !(visibility.re.is_finite() && visibility.im.is_finite()) {
                return Ok(None);
            }
            let natural_weight = if let Some(weight_spectrum) = &row.weight_spectrum {
                *weight_spectrum
                    .get((corr_index, local_channel))
                    .ok_or_else(|| {
                        ImagingError::InvalidRequest(format!(
                            "WEIGHT_SPECTRUM index [{corr_index}, {source_channel}] is out of bounds"
                        ))
                    })?
            } else {
                *row.weight.get(corr_index).ok_or_else(|| {
                    ImagingError::InvalidRequest(format!(
                        "WEIGHT correlation {corr_index} is out of bounds"
                    ))
                })?
            };
            (visibility, natural_weight, sumwt_factor)
        }
        StandardMfsVisibilityPolarization::CollapsedPair {
            first_corr_index,
            second_corr_index,
            transform,
            sumwt_factor,
        } => {
            if *row
                .flag
                .get((first_corr_index, local_channel))
                .ok_or_else(|| {
                    ImagingError::InvalidRequest(format!(
                        "FLAG index [{first_corr_index}, {source_channel}] is out of bounds"
                    ))
                })?
                || *row
                    .flag
                    .get((second_corr_index, local_channel))
                    .ok_or_else(|| {
                        ImagingError::InvalidRequest(format!(
                            "FLAG index [{second_corr_index}, {source_channel}] is out of bounds"
                        ))
                    })?
            {
                return Ok(None);
            }
            let first_visibility =
                *row.data
                    .get((first_corr_index, local_channel))
                    .ok_or_else(|| {
                        ImagingError::InvalidRequest(format!(
                            "DATA index [{first_corr_index}, {source_channel}] is out of bounds"
                        ))
                    })?;
            let second_visibility = *row
                .data
                .get((second_corr_index, local_channel))
                .ok_or_else(|| {
                    ImagingError::InvalidRequest(format!(
                        "DATA index [{second_corr_index}, {source_channel}] is out of bounds"
                    ))
                })?;
            let visibility = transform.collapse(first_visibility, second_visibility);
            if !(visibility.re.is_finite() && visibility.im.is_finite()) {
                return Ok(None);
            }
            let (first_weight, second_weight) = if let Some(weight_spectrum) = &row.weight_spectrum
            {
                (
                    *weight_spectrum
                        .get((first_corr_index, local_channel))
                        .ok_or_else(|| {
                            ImagingError::InvalidRequest(format!(
                                "WEIGHT_SPECTRUM index [{first_corr_index}, {source_channel}] is out of bounds"
                            ))
                        })?,
                    *weight_spectrum
                        .get((second_corr_index, local_channel))
                        .ok_or_else(|| {
                            ImagingError::InvalidRequest(format!(
                                "WEIGHT_SPECTRUM index [{second_corr_index}, {source_channel}] is out of bounds"
                            ))
                        })?,
                )
            } else {
                (
                    *row.weight.get(first_corr_index).ok_or_else(|| {
                        ImagingError::InvalidRequest(format!(
                            "WEIGHT correlation {first_corr_index} is out of bounds"
                        ))
                    })?,
                    *row.weight.get(second_corr_index).ok_or_else(|| {
                        ImagingError::InvalidRequest(format!(
                            "WEIGHT correlation {second_corr_index} is out of bounds"
                        ))
                    })?,
                )
            };
            if !(first_weight.is_finite()
                && first_weight > 0.0
                && second_weight.is_finite()
                && second_weight > 0.0)
            {
                return Ok(None);
            }
            (
                visibility,
                0.5 * (first_weight + second_weight),
                sumwt_factor,
            )
        }
    };
    if !(natural_weight.is_finite()
        && natural_weight > 0.0
        && sumwt_factor.is_finite()
        && sumwt_factor > 0.0)
    {
        return Ok(None);
    }
    let u_lambda = row.uvw_m[0] * lambda_scale;
    let v_lambda = row.uvw_m[1] * lambda_scale;
    let weight = weighting_plan.weight_sample(u_lambda, v_lambda, natural_weight)?;
    let grid_weight = weight * sumwt_factor;
    if !(grid_weight.is_finite() && grid_weight > 0.0) {
        return Ok(None);
    }
    Ok(Some(StandardMfsRoutedGridSample {
        center,
        grid_weight,
        visibility,
    }))
}

/// Opaque acceleration cache for routed standard-MFS input.
#[derive(Debug, Default)]
pub struct StandardMfsRoutedInputCache {
    inner: StandardMfsMetalGroupedInputCache,
}

/// Incremental builder for an opaque routed standard-MFS input cache.
pub struct StandardMfsRoutedInputCachePrefill {
    inner: StandardMfsMetalGroupedInputCachePrefill,
}

impl StandardMfsRoutedInputCachePrefill {
    /// Create a grouped Metal cache prefill for one standard-MFS geometry.
    pub fn metal_grouped(
        geometry: ImageGeometry,
        execution: &StandardMfsExecutionPlan,
    ) -> Result<Self, ImagingError> {
        Ok(Self {
            inner: StandardMfsMetalGroupedInputCachePrefill::new_with_execution_plan(
                geometry, execution,
            )?,
        })
    }

    /// Append one routed replay block to the prefill cache.
    pub fn append_block(
        &mut self,
        block: &StandardMfsRoutedVisibilityBlock,
    ) -> Result<(), ImagingError> {
        for run in block.runs() {
            self.inner.append_run(run)?;
        }
        Ok(())
    }

    /// Number of routed runs appended so far.
    pub fn run_count(&self) -> usize {
        self.inner.run_count()
    }

    /// Number of logical channel lanes appended so far.
    pub fn logical_lanes(&self) -> usize {
        self.inner.logical_lanes()
    }

    /// Conservative host byte estimate for finalized and open grouped chunks.
    pub fn estimated_host_bytes(&self) -> usize {
        self.inner.estimated_host_bytes()
    }

    /// Finalize into a reusable routed input cache after weighting is known.
    pub fn finish(
        self,
        weighting_plan: &StandardMfsStreamingWeightingPlan,
    ) -> Result<StandardMfsRoutedInputCache, ImagingError> {
        Ok(StandardMfsRoutedInputCache {
            inner: self.inner.finish(weighting_plan)?,
        })
    }
}

/// Minor-cycle execution backend selected by the frontend standard-MFS planner.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub enum StandardMfsMinorCycleBackend {
    /// Run the minor cycle on the CPU.
    #[default]
    Cpu,
    /// Run the minor cycle with the Metal backend when the selected deconvolver supports it.
    Metal,
}

impl StandardMfsMinorCycleBackend {
    /// Stable diagnostic label for plan logs and benchmark metadata.
    pub fn label(self) -> &'static str {
        match self {
            Self::Cpu => "cpu",
            Self::Metal => "metal",
        }
    }
}

/// Coarse standard-MFS phase emitted by the CLEAN controller.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum StandardMfsProgressPhase {
    /// The controller is building the initial dirty image, PSF, and residual grid.
    InitialGridStart,
    /// The controller has built the initial dirty image, PSF, and residual grid.
    InitialGridEnd,
    /// A minor-cycle deconvolver pass is about to start.
    MinorCycleStart,
    /// A minor-cycle deconvolver pass is still running and has made bounded progress.
    MinorCycleProgress,
    /// A minor-cycle deconvolver pass has finished.
    MinorCycleEnd,
    /// The controller is about to refresh residuals from the current model.
    ResidualRefreshStart,
    /// The controller has refreshed residuals from the current model.
    ResidualRefreshEnd,
    /// The controller is about to run an FFT-backed image-plane transform.
    FftStart,
    /// The controller has finished an FFT-backed image-plane transform.
    FftEnd,
    /// The controller is about to grid residual visibilities.
    ResidualGridStart,
    /// The controller has finished gridding residual visibilities.
    ResidualGridEnd,
    /// The controller is about to form weighted mosaic pointing groups.
    WeightedMosaicStart,
    /// The controller has finished forming weighted mosaic pointing groups.
    WeightedMosaicEnd,
}

/// Coarse standard-MFS progress event emitted from the imaging controller.
#[derive(Clone, Debug, PartialEq)]
pub struct StandardMfsProgressEvent {
    /// Controller phase represented by this event.
    pub phase: StandardMfsProgressPhase,
    /// Deconvolver selected by the request.
    pub deconvolver: Deconvolver,
    /// Minor-cycle backend selected by the execution planner.
    pub minor_cycle_backend: StandardMfsMinorCycleBackend,
    /// Completed major cycles before this event.
    pub major_cycle: usize,
    /// Reported minor iterations before or after this event, depending on phase.
    pub minor_iterations: usize,
    /// Requested minor-iteration limit for the run.
    pub minor_iteration_limit: usize,
    /// Planned reported iterations for the current minor cycle.
    pub cycle_iteration_limit: usize,
    /// Current peak residual for phases where it is known.
    pub peak_residual_jy_per_beam: Option<f32>,
    /// Cycle threshold for phases where it is known.
    pub cycle_threshold_jy_per_beam: Option<f32>,
}

/// Callback used by frontends to observe standard-MFS controller progress.
pub type StandardMfsProgressCallback =
    Arc<dyn Fn(StandardMfsProgressEvent) + Send + Sync + 'static>;

/// Confidence class for standard-MFS scheduler queue telemetry.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum StandardMfsQueueProgressConfidence {
    /// Queue length and byte counters came from the scheduler state.
    Measured,
    /// Queue exists conceptually, but live counters are not available.
    Unknown,
}

/// Coarse standard-MFS queue snapshot emitted by execution schedulers.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct StandardMfsQueueProgress {
    /// Stable queue id within the standard-MFS execution model.
    pub id: String,
    /// Human-readable queue label.
    pub label: String,
    /// Current queue depth when known.
    pub len: Option<usize>,
    /// Queue capacity or worker capacity when known.
    pub capacity: Option<usize>,
    /// Currently queued or reserved bytes when known.
    pub bytes: Option<usize>,
    /// Highest queued or reserved bytes observed by this scheduler.
    pub high_water_bytes: Option<usize>,
    /// Whether a producer is currently filling this queue.
    pub producers_active: bool,
    /// Whether workers are currently consuming this queue.
    pub consumers_active: bool,
    /// Number of blocked producers or consumers observed by the scheduler.
    pub blocked_count: usize,
    /// Confidence class for this snapshot.
    pub confidence: StandardMfsQueueProgressConfidence,
    /// Short note explaining the queue observation.
    pub note: Option<String>,
}

/// Coarse standard-MFS execution-state snapshot emitted by shared schedulers.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct StandardMfsObservabilityEvent {
    /// Stable stage label such as `dirty`, `psf`, or `residual`.
    pub stage: String,
    /// Active worker count at the time of the snapshot.
    pub active_workers: usize,
    /// Planned worker capacity at the time of the snapshot.
    pub worker_capacity: usize,
    /// Queue snapshots reported by this scheduler.
    pub queues: Vec<StandardMfsQueueProgress>,
}

/// Callback used by frontends to observe scheduler/resource state.
pub type StandardMfsObservabilityCallback =
    Arc<dyn Fn(StandardMfsObservabilityEvent) + Send + Sync + 'static>;

/// Exact worst-case host bytes charged for one fixed-tile queue entry.
pub const fn standard_mfs_tile_queue_entry_bytes() -> usize {
    execution::standard_mfs_tile_queue_entry_bytes()
}

/// Kernel halo required by the canonical standard-MFS gridder.
pub const fn standard_mfs_kernel_halo() -> usize {
    gridder::STANDARD_GRIDDER_SUPPORT
}

/// Exact worst-case host bytes retained per logical lane while building a
/// grouped Metal replay cache for the supplied correlation count.
pub const fn standard_mfs_metal_grouped_cache_bytes_per_lane(correlation_count: usize) -> usize {
    execution::standard_mfs_metal_grouped_cache_bytes_per_lane(correlation_count)
}

/// Requested precision and backend policy for dirty-product FFTs.
///
/// The policy records caller intent. Precision and backend are resolved
/// together only when the exact padded shape, batch count, placement, and
/// memory requirements are known.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub struct DirtyProductFftPolicy {
    /// Requested precision policy.
    pub precision: FftPrecisionChoice,
    /// Requested backend policy.
    pub backend: FftBackendChoice,
    /// Product planes admitted to one FFT batch by the run memory ledger.
    pub max_batch_products: Option<usize>,
    /// Maximum host threads assigned to one FFT operation.
    pub max_threads: Option<usize>,
}

impl DirtyProductFftPolicy {
    /// Construct an explicit dirty-product FFT policy.
    pub const fn new(precision: FftPrecisionChoice, backend: FftBackendChoice) -> Self {
        Self {
            precision,
            backend,
            max_batch_products: None,
            max_threads: None,
        }
    }

    /// Assign the planner-resolved host thread ceiling.
    pub const fn with_max_threads(mut self, max_threads: usize) -> Self {
        self.max_threads = Some(max_threads);
        self
    }

    /// Correctness-first CPU-capable policy for direct library callers.
    pub const fn correctness_first() -> Self {
        Self::new(FftPrecisionChoice::F64, FftBackendChoice::Auto)
    }
}

/// Mode-general FFT execution configuration.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub struct ImagingFftPlan {
    /// Dirty PSF and residual product policy.
    pub dirty_products: DirtyProductFftPolicy,
}

#[derive(Clone, Debug, PartialEq, Eq)]
enum ParallelWorkerSelectionSource {
    AutoCalibrated,
    AutoConservativeFallback,
}

#[derive(Clone, Debug, PartialEq, Eq)]
struct ParallelWorkerResolution {
    workers: usize,
    source: ParallelWorkerSelectionSource,
    explanation: String,
}

#[derive(Debug)]
struct ParallelWorkerOnlineCalibrationState {
    candidates: Vec<usize>,
    sequence: Vec<usize>,
    cursor: usize,
    observations: Vec<parallel_worker::ParallelWorkerTimingObservation>,
    elapsed: Duration,
    windows: usize,
    extension_rounds: usize,
}

#[derive(Clone, Debug)]
struct ParallelWorkerCalibrationControl {
    request: ParallelWorkerCalibrationRequest,
    resolution: Arc<OnceLock<ParallelWorkerResolution>>,
    online: Arc<Mutex<Option<ParallelWorkerOnlineCalibrationState>>>,
}

/// Runtime execution knobs for standard-MFS backends.
///
/// These values are deliberately separate from [`ImagingRequest`] so callers
/// can tune memory residency without changing the imaging contract itself.
#[derive(Clone)]
pub struct StandardMfsExecutionPlan {
    /// Canonical workload, resource, scheduling, and memory decisions.
    pub resolved: ImagingResolvedPlan,
    /// Backend for the initial dirty and PSF grid unless overridden below.
    pub grid_backend: StandardMfsBackend,
    /// Optional backend override for residual refreshes.
    pub residual_backend: Option<StandardMfsBackend>,
    /// Optional backend override for the initial dirty grid.
    pub initial_dirty_backend: Option<StandardMfsBackend>,
    /// Minor-cycle backend selected by the frontend planner.
    pub minor_cycle_backend: StandardMfsMinorCycleBackend,
    /// Keep the fixed-tile path when the resolved worker count is one.
    pub force_tiled_one_worker: bool,
    /// Route fixed-tile sample replay through planned run blocks.
    ///
    /// This is selected by public standard-MFS plan variants, not by frontends.
    /// Keeping it private prevents an internal replay shape from becoming
    /// application API.
    fixed_tile_use_planned_run_blocks: bool,
    /// Optional frontend-computed maximum absolute W coordinate, in wavelengths.
    ///
    /// W-projection needs this value before kernels can be built. Supplying it
    /// lets streaming frontends compute the range from bounded row geometry
    /// instead of replaying and materializing every weighted visibility block
    /// once solely for a metadata scan.
    pub w_project_max_abs_w_lambda: Option<f64>,
    /// Optional coarse progress callback fired by the standard-MFS controller.
    ///
    /// The callback is intentionally outside the per-component hot loop. It is
    /// suitable for user-interface phase state, not detailed profiling.
    pub progress_callback: Option<StandardMfsProgressCallback>,
    /// Optional observability callback fired by execution schedulers.
    ///
    /// This reports bounded aggregate scheduler facts such as queue depth,
    /// queued bytes, worker activity, and backpressure. It must not emit
    /// per-visibility records.
    pub observability_callback: Option<StandardMfsObservabilityCallback>,
    /// Optional frontend-supplied, resource-bounded worker calibration.
    ///
    /// The request contains no host discovery. Initial production windows run
    /// a deterministic counterbalanced worker trial; no visibility or output
    /// update is replayed solely for calibration. Once resolved, all later
    /// windows reuse the admitted worker count.
    parallel_worker_calibration: Option<ParallelWorkerCalibrationControl>,
}

impl StandardMfsExecutionPlan {
    /// Construct backend options around an already admitted execution plan.
    pub fn new(resolved: ImagingResolvedPlan) -> Self {
        Self {
            resolved,
            grid_backend: StandardMfsBackend::default(),
            residual_backend: None,
            initial_dirty_backend: None,
            minor_cycle_backend: StandardMfsMinorCycleBackend::default(),
            force_tiled_one_worker: false,
            fixed_tile_use_planned_run_blocks: false,
            w_project_max_abs_w_lambda: None,
            progress_callback: None,
            observability_callback: None,
            parallel_worker_calibration: None,
        }
    }

    /// Adds a bounded exact-kernel worker calibration request.
    ///
    /// Frontends remain responsible for detecting assigned CPU resources and
    /// generating topology-informed candidates. Explicit worker requests
    /// should not use this builder.
    pub fn with_parallel_worker_calibration(
        mut self,
        request: ParallelWorkerCalibrationRequest,
    ) -> Self {
        self.parallel_worker_calibration = Some(ParallelWorkerCalibrationControl {
            request,
            resolution: Arc::new(OnceLock::new()),
            online: Arc::new(Mutex::new(None)),
        });
        self
    }
}

#[cfg(test)]
