fn trace_mosaic_weight_image(label: &str, image: &Array2<f32>) {
    if !mosaic_weight_trace_enabled() {
        return;
    }
    let (nx, ny) = image.dim();
    let mut count = 0usize;
    let mut positive_count = 0usize;
    let mut sum = 0.0f64;
    let mut min_value = f32::INFINITY;
    let mut max_value = f32::NEG_INFINITY;
    let mut max_location = (0usize, 0usize);
    for ((x, y), value) in image.indexed_iter() {
        if !value.is_finite() {
            continue;
        }
        count += 1;
        if *value > 0.0 {
            positive_count += 1;
        }
        sum += f64::from(*value);
        if *value < min_value {
            min_value = *value;
        }
        if *value > max_value {
            max_value = *value;
            max_location = (x, y);
        }
    }
    eprintln!(
        "CASA_RS_W3_MOSAIC_WEIGHT_TRACE label={} nx={} ny={} finite={} positive={} sum={:.17e} min={:.17e} max={:.17e} max_x={} max_y={}",
        label,
        nx,
        ny,
        count,
        positive_count,
        sum,
        min_value,
        max_value,
        max_location.0,
        max_location.1,
    );
    let step_x = (nx / 16).max(1);
    let step_y = (ny / 16).max(1);
    let mut x = 0usize;
    while x < nx {
        let mut y = 0usize;
        while y < ny {
            eprintln!(
                "CASA_RS_W3_MOSAIC_WEIGHT_SAMPLE label={} x={} y={} value={:.17e}",
                label,
                x,
                y,
                image[(x, y)],
            );
            y = y.saturating_add(step_y);
        }
        x = x.saturating_add(step_x);
    }
    let center_x = nx / 2;
    let center_y = ny / 2;
    eprintln!(
        "CASA_RS_W3_MOSAIC_WEIGHT_SAMPLE label={} x={} y={} value={:.17e}",
        label,
        center_x,
        center_y,
        image[(center_x, center_y)],
    );
}

struct MosaicPbTraceSample {
    label: &'static str,
    primary_beam_model: PrimaryBeamModel,
    pointing_x: f64,
    pointing_y: f64,
    x: usize,
    y: usize,
    radius_rad: f64,
    frequency_hz: f64,
    vp: f32,
}

fn trace_mosaic_pb_sample(sample: MosaicPbTraceSample) {
    if !mosaic_weight_trace_enabled() {
        return;
    }
    let radius_arcmin_ghz =
        (sample.radius_rad.to_degrees() * 60.0 * (sample.frequency_hz / 1.0e9)) as f32 as f64;
    let maximum_radius_arcmin_ghz =
        primary_beam_max_radius_arcsec_at_100ghz(sample.primary_beam_model).unwrap_or(0.0) * 100.0
            / 60.0;
    let index = if radius_arcmin_ghz > maximum_radius_arcmin_ghz {
        -1
    } else {
        (radius_arcmin_ghz * 9_999.0 / maximum_radius_arcmin_ghz)
            .floor()
            .clamp(0.0, 9_999.0) as i32
    };
    let pb = sample.vp * sample.vp;
    let label = sample.label;
    let pointing_x = sample.pointing_x;
    let pointing_y = sample.pointing_y;
    let x = sample.x;
    let y = sample.y;
    let radius_rad = sample.radius_rad;
    let frequency_hz = sample.frequency_hz;
    let vp = sample.vp;
    eprintln!(
        "CASA_RS_W3_MOSAIC_PB_SAMPLE label={label} pointing_x={pointing_x:.12e} pointing_y={pointing_y:.12e} x={x} y={y} radius_rad={radius_rad:.17e} radius_arcmin_ghz={radius_arcmin_ghz:.17e} frequency_hz={frequency_hz:.9e} index={index} vp={vp:.17e} pb={pb:.17e} pb2={:.17e}",
        pb * pb
    );
}

fn build_mosaic_weight_image(
    geometry: ImageGeometry,
    config: &MosaicGridderConfig,
    groups: &[MosaicPointingGroup],
) -> Result<Array2<f32>, ImagingError> {
    let mut pointing_weights =
        BTreeMap::<MosaicPointingWeightKey, MosaicPointingWeightValue>::new();
    for group in groups {
        if !mosaic_pointing_contributes_by_simple_pb_center(
            geometry,
            config.phase_center_direction_rad,
            group.pointing_direction_rad,
        ) {
            continue;
        }
        let mut group_weight = 0.0f64;
        for sample_index in 0..group.batch.len() {
            if !group.batch.gridable[sample_index] {
                continue;
            }
            let weight = group.batch.weight[sample_index];
            if weight.is_finite() && weight > 0.0 {
                group_weight += f64::from(weight);
            }
        }
        if !(group_weight.is_finite() && group_weight > 0.0) {
            continue;
        }
        let key = (
            group.pointing_direction_rad[0].to_bits(),
            group.pointing_direction_rad[1].to_bits(),
            group.frequency_hz.to_bits(),
            primary_beam_model_key(group.primary_beam_model),
        );
        let entry = pointing_weights.entry(key).or_insert((
            group.pointing_direction_rad,
            group.primary_beam_model,
            group.frequency_hz,
            0.0,
        ));
        entry.3 += group_weight;
    }

    let mut weight_image = Array2::<f32>::zeros((geometry.nx(), geometry.ny()));
    for (pointing_direction_rad, primary_beam_model, frequency_hz, pointing_weight) in
        pointing_weights.into_values()
    {
        if !(pointing_weight.is_finite() && pointing_weight > 0.0) {
            continue;
        }
        let [pointing_x, pointing_y] = mosaic_pointing_pixel_position(
            geometry,
            config.phase_center_direction_rad,
            pointing_direction_rad,
        );
        if mosaic_weight_trace_enabled() {
            eprintln!(
                "CASA_RS_W3_MOSAIC_PB_POINTING label=rust_nonstream pointing_x={pointing_x:.12e} pointing_y={pointing_y:.12e} frequency_hz={frequency_hz:.9e} pointing_weight={pointing_weight:.17e}"
            );
        }
        let voltage_pattern = MosaicWeightImageVoltagePattern::new(primary_beam_model);
        let (x_range, y_range) = mosaic_weight_image_pixel_bounds(
            geometry,
            primary_beam_model,
            pointing_x,
            pointing_y,
            frequency_hz,
        );
        for x in x_range {
            let l = (x as f64 - pointing_x) * geometry.cell_size_rad[0].abs();
            for y in y_range.clone() {
                let m = (y as f64 - pointing_y) * geometry.cell_size_rad[1].abs();
                let radius_rad = (l * l + m * m).sqrt();
                let vp = voltage_pattern.evaluate(l, m, frequency_hz);
                if (x == 640 || x % 160 == 0) && (y == 640 || y % 160 == 0) {
                    trace_mosaic_pb_sample(MosaicPbTraceSample {
                        label: "rust_nonstream",
                        primary_beam_model,
                        pointing_x,
                        pointing_y,
                        x,
                        y,
                        radius_rad,
                        frequency_hz,
                        vp,
                    });
                }
                let pb = vp * vp;
                weight_image[(x, y)] += (pointing_weight as f32) * pb * pb;
            }
        }
    }
    if weight_image
        .iter()
        .copied()
        .any(|value| value.is_finite() && value > 0.0)
    {
        Ok(weight_image)
    } else {
        Err(ImagingError::Normalization(
            "mosaic weight image has no finite positive samples".to_string(),
        ))
    }
}

fn build_mosaic_clean_mask(
    weight_image: &Array2<f32>,
    pb_limit: f32,
    user_clean_mask: Option<&Array2<bool>>,
) -> Result<Array2<bool>, ImagingError> {
    let peak = weight_image
        .iter()
        .copied()
        .filter(|value| value.is_finite())
        .fold(0.0f32, f32::max);
    if !(peak.is_finite() && peak > 0.0) {
        return Err(ImagingError::Normalization(
            "mosaic PB clean mask peak is non-finite or zero".to_string(),
        ));
    }
    let threshold = pb_limit.abs() * pb_limit.abs() * peak;
    let mut mask = Array2::<bool>::from_elem(weight_image.dim(), false);
    for ((x, y), value) in weight_image.indexed_iter() {
        let in_pb_support = value.is_finite() && *value > threshold;
        let in_user_mask = user_clean_mask.is_none_or(|user_mask| user_mask[(x, y)]);
        mask[(x, y)] = in_pb_support && in_user_mask;
    }
    Ok(mask)
}

fn request_for_mosaic_clean_mask(
    request: &ImagingRequest,
    clean_mask: Array2<bool>,
) -> ImagingRequest {
    ImagingRequest {
        geometry: request.geometry,
        visibility_batches: Vec::new(),
        gridder_mode: GridderMode::Standard,
        plane_stokes: request.plane_stokes,
        weighting: request.weighting,
        reffreq_hz: request.reffreq_hz,
        selected_frequency_range_hz: request.selected_frequency_range_hz,
        deconvolver: request.deconvolver,
        multiscale_scales: request.multiscale_scales.clone(),
        small_scale_bias: request.small_scale_bias,
        clean: request.clean,
        clean_mask: Some(clean_mask),
        initial_model: None,
        w_term_mode: request.w_term_mode,
        w_project_planes: request.w_project_planes,
        compatibility: request.compatibility,
    }
}

fn clean_mask_summary(
    clean_mask: Option<&Array2<bool>>,
    fallback_shape: (usize, usize),
) -> CleanMaskSummary {
    let Some(clean_mask) = clean_mask else {
        return CleanMaskSummary {
            has_mask: false,
            pixels: fallback_shape.0.saturating_mul(fallback_shape.1),
            fingerprint: 0,
        };
    };

    let mut pixels = 0usize;
    let mut fingerprint = 0xcbf29ce484222325u64;
    fingerprint ^= clean_mask.dim().0 as u64;
    fingerprint = fingerprint.wrapping_mul(0x100000001b3);
    fingerprint ^= clean_mask.dim().1 as u64;
    fingerprint = fingerprint.wrapping_mul(0x100000001b3);
    for ((x, y), value) in clean_mask.indexed_iter() {
        if !*value {
            continue;
        }
        pixels = pixels.saturating_add(1);
        fingerprint ^= ((x as u64) << 32) ^ y as u64;
        fingerprint = fingerprint.wrapping_mul(0x100000001b3);
    }
    CleanMaskSummary {
        has_mask: true,
        pixels,
        fingerprint,
    }
}

#[allow(clippy::too_many_arguments)]
fn compute_mosaic_residual(
    request: &ImagingRequest,
    config: &MosaicGridderConfig,
    gridder: &StandardGridder,
    groups: &[MosaicPointingGroup],
    projector_cache: &mut MosaicProjectorCache,
    conv_sampling: usize,
    model: &Array2<f32>,
    psf_state: &PsfState,
    weight_image: &Array2<f32>,
    dirty_product_fft_policy: DirtyProductFftPolicy,
    stage_timings: &mut ImagingStageTimings,
    metal_group_cache: Option<&[Option<MosaicMetalPreparedGroup>]>,
    progress_callback: Option<&StandardMfsProgressCallback>,
    progress_context: Option<StandardMfsProgressContext>,
    requested_threads: usize,
) -> Result<Array2<f32>, ImagingError> {
    let refresh_started = Instant::now();
    let [grid_nx, grid_ny] = gridder.grid_shape();
    let mut timings = ResidualComputationTimings::default();
    let model_grid = if model.iter().any(|value| value.abs() > 0.0) {
        emit_standard_mfs_context_progress(
            progress_callback,
            progress_context,
            StandardMfsProgressPhase::FftStart,
        );
        let model_fft_started = Instant::now();
        let model_for_prediction =
            flat_sky_mosaic_model_for_prediction(model, weight_image, config.pb_limit)?;
        let transformed =
            centered_fft2(&gridder.apodize_mosaic_model(&model_for_prediction, conv_sampling));
        timings.model_fft = model_fft_started.elapsed();
        emit_standard_mfs_context_progress(
            progress_callback,
            progress_context,
            StandardMfsProgressPhase::FftEnd,
        );
        Some(transformed)
    } else {
        None
    };

    emit_standard_mfs_context_progress(
        progress_callback,
        progress_context,
        StandardMfsProgressPhase::ResidualGridStart,
    );
    let degrid_started = Instant::now();
    let mut accumulated_residual_grid = Array2::<Complex64>::zeros((grid_nx, grid_ny));
    let residual_parallel_threads = mosaic_parallel_thread_count(groups.len(), requested_threads);
    if residual_parallel_threads > 1 {
        let parallel = compute_mosaic_residual_parallel(
            request,
            config,
            gridder,
            groups,
            conv_sampling,
            model_grid.as_ref(),
            residual_parallel_threads,
            metal_group_cache,
            None,
        )?;
        accumulated_residual_grid = parallel.residual_grid;
        timings.degrid_grid = parallel.elapsed;
        profile::log_parallel_stage(profile::ParallelStageProfile {
            stage: "mosaic_residual_grid",
            requested_threads,
            actual_threads: parallel.worker_compute.len(),
            chunking: "pointing-group",
            chunk_len: groups.len().div_ceil(parallel.worker_compute.len().max(1)),
            samples_total: groups.iter().map(|group| group.batch.len()).sum(),
            samples_per_worker: parallel.worker_samples,
            local_grid_bytes_per_worker: complex64_grid_bytes(grid_nx, grid_ny, 1),
            local_grid_count: 1,
            local_alloc_zero_by_worker: parallel.worker_alloc,
            worker_compute_by_worker: parallel.worker_compute,
            join_duration: parallel.join_elapsed,
            merge_duration: parallel.merge_elapsed,
            stage_duration: parallel.elapsed,
        });
    } else {
        for (group_index, group) in groups.iter().enumerate() {
            let prepared_metal = metal_group_cache
                .and_then(|cache| cache.get(group_index))
                .and_then(Option::as_ref);
            let contribution = compute_mosaic_residual_group_contribution(
                request,
                config,
                gridder,
                group,
                conv_sampling,
                model_grid.as_ref(),
                requested_threads,
                Some(&mut *projector_cache),
                prepared_metal,
                None,
            )?;
            add_complex64_grid(&mut accumulated_residual_grid, &contribution.residual_grid);
        }
        timings.degrid_grid = degrid_started.elapsed();
    }
    emit_standard_mfs_context_progress(
        progress_callback,
        progress_context,
        StandardMfsProgressPhase::ResidualGridEnd,
    );

    emit_standard_mfs_context_progress(
        progress_callback,
        progress_context,
        StandardMfsProgressPhase::FftStart,
    );
    let fft_started = Instant::now();
    let (mut raw_grids, _) = execute_dirty_product_host_f64_batch(
        &[&accumulated_residual_grid],
        dirty_product_fft_policy,
    )?;
    let raw_residual = raw_grids.pop().expect("mosaic residual FFT");
    timings.fft += fft_started.elapsed();
    emit_standard_mfs_context_progress(
        progress_callback,
        progress_context,
        StandardMfsProgressPhase::FftEnd,
    );
    let normalize_started = Instant::now();
    let accumulated_residual_image =
        gridder.corrected_mosaic_image_from_grid_f64(&raw_residual, conv_sampling);
    timings.normalize += normalize_started.elapsed();

    let normalize_started = Instant::now();
    let fft_sumwt_scale =
        (request.geometry.nx() * request.geometry.ny()) as f32 / psf_state.normalization_sumwt;
    let mut residual = accumulated_residual_image;
    residual.mapv_inplace(|value| value * fft_sumwt_scale);
    let weight_peak = weight_image
        .iter()
        .copied()
        .fold(0.0f32, |peak, value| peak.max(value));
    if !(weight_peak.is_finite() && weight_peak > 0.0) {
        return Err(ImagingError::Normalization(
            "mosaic residual refresh weight peak is non-finite or zero".to_string(),
        ));
    }
    let pb_limit_threshold = config.pb_limit.abs() * config.pb_limit.abs() * weight_peak;
    for ((x, y), weight_value) in weight_image.indexed_iter() {
        let sensitivity = weight_value.max(0.0);
        if sensitivity > pb_limit_threshold {
            residual[(x, y)] /= (sensitivity * weight_peak).sqrt();
        } else {
            residual[(x, y)] = 0.0;
        }
    }
    timings.normalize += normalize_started.elapsed();
    stage_timings.model_fft += timings.model_fft;
    stage_timings.residual_degrid_grid += timings.degrid_grid;
    stage_timings.residual_fft += timings.fft;
    stage_timings.residual_normalize += timings.normalize;
    stage_timings.major_cycle_refresh += refresh_started.elapsed();
    Ok(residual)
}

#[allow(clippy::too_many_arguments)]
fn compute_mosaic_residual_parallel(
    request: &ImagingRequest,
    config: &MosaicGridderConfig,
    gridder: &StandardGridder,
    groups: &[MosaicPointingGroup],
    conv_sampling: usize,
    model_grid: Option<&Array2<Complex32>>,
    thread_count: usize,
    metal_group_cache: Option<&[Option<MosaicMetalPreparedGroup>]>,
    residual_projectors: Option<&[Option<MosaicResidualProjector>]>,
) -> Result<MosaicResidualParallelContribution, ImagingError> {
    let [grid_nx, grid_ny] = gridder.grid_shape();
    let chunk_len = groups.len().div_ceil(thread_count.max(1)).max(1);
    let indexed_groups = groups.iter().enumerate().collect::<Vec<_>>();
    let started = Instant::now();
    let mut worker_results = Vec::new();
    let join_started = Instant::now();
    thread::scope(|scope| {
        let mut handles = Vec::new();
        for chunk in indexed_groups.chunks(chunk_len) {
            handles.push(scope.spawn(move || {
                let alloc_started = Instant::now();
                let mut residual_grid = Array2::<Complex64>::zeros((grid_nx, grid_ny));
                let alloc_elapsed = alloc_started.elapsed();
                let worker_started = Instant::now();
                let mut worker_samples = 0usize;
                let mut metal_stats = MosaicMetalGridStats::default();
                for &(group_index, group) in chunk {
                    worker_samples += group.batch.len();
                    let prepared_metal = metal_group_cache
                        .and_then(|cache| cache.get(group_index))
                        .and_then(Option::as_ref);
                    let residual_projector = residual_projectors
                        .and_then(|projectors| projectors.get(group_index))
                        .and_then(Option::as_ref)
                        .map(|projector| &projector.projector);
                    if let Some(projector) = residual_projector
                        && mosaic_pointing_contributes_by_simple_pb_center(
                            request.geometry,
                            config.phase_center_direction_rad,
                            group.pointing_direction_rad,
                        )
                    {
                        let collected_prepared;
                        let prepared = match prepared_metal {
                            Some(prepared) => prepared,
                            None => {
                                collected_prepared =
                                    collect_mosaic_metal_samples(group, projector, None)?;
                                &collected_prepared
                            }
                        };
                        let costs = mosaic_group_backend_cost(
                            gridder.grid_shape(),
                            projector.support().saturating_mul(2).saturating_add(1),
                            group.batch.len(),
                            prepared.samples.len(),
                            1,
                            thread_count,
                        );
                        if metal_group_cache.is_some()
                            && costs.metal_byte_work
                                <= costs.raw_cpu_byte_work.min(costs.grouped_cpu_byte_work)
                        {
                            let contribution = compute_mosaic_residual_group_grid_metal(
                                gridder,
                                group,
                                projector,
                                model_grid,
                                Some(prepared),
                            )?;
                            metal_stats.add_assign(contribution.metal_stats);
                            add_complex64_grid(&mut residual_grid, &contribution.residual_grid);
                            continue;
                        }
                        if costs.grouped_cpu_byte_work <= costs.raw_cpu_byte_work {
                            accumulate_mosaic_residual_group_grid_grouped_cpu_into(
                                projector,
                                model_grid,
                                prepared,
                                &mut residual_grid,
                            );
                            continue;
                        }
                    }
                    let contribution = compute_mosaic_residual_group_contribution(
                        request,
                        config,
                        gridder,
                        group,
                        conv_sampling,
                        model_grid,
                        thread_count,
                        None,
                        prepared_metal,
                        residual_projector,
                    )?;
                    metal_stats.add_assign(contribution.metal_stats);
                    add_complex64_grid(&mut residual_grid, &contribution.residual_grid);
                }
                Ok::<_, ImagingError>((
                    worker_samples,
                    alloc_elapsed,
                    worker_started.elapsed(),
                    residual_grid,
                    metal_stats,
                ))
            }));
        }
        for handle in handles {
            worker_results.push(handle.join().expect("mosaic residual worker panicked")?);
        }
        Ok::<(), ImagingError>(())
    })?;
    let join_elapsed = join_started.elapsed();

    let mut residual_grid = Array2::<Complex64>::zeros((grid_nx, grid_ny));
    let mut worker_samples = Vec::with_capacity(worker_results.len());
    let mut worker_alloc = Vec::with_capacity(worker_results.len());
    let mut worker_compute = Vec::with_capacity(worker_results.len());
    let mut metal_stats = MosaicMetalGridStats::default();
    let merge_started = Instant::now();
    for (samples, alloc, compute, local_residual_grid, local_metal_stats) in worker_results {
        add_complex64_grid(&mut residual_grid, &local_residual_grid);
        worker_samples.push(samples);
        worker_alloc.push(alloc);
        worker_compute.push(compute);
        metal_stats.add_assign(local_metal_stats);
    }
    let merge_elapsed = merge_started.elapsed();
    if profile::standard_mfs_profile_block_detail_enabled() {
        let total_worker_samples = worker_samples.iter().sum::<usize>();
        let grouped_samples = groups.iter().map(|group| group.batch.len()).sum::<usize>();
        let residual_on_demand_candidate_groups = groups
            .iter()
            .filter(|group| {
                mosaic_pointing_contributes_by_simple_pb_center(
                    request.geometry,
                    config.phase_center_direction_rad,
                    group.pointing_direction_rad,
                )
            })
            .count();
        let residual_pb_rejected_groups = groups
            .iter()
            .filter(|group| {
                !mosaic_pointing_contributes_by_simple_pb_center(
                    request.geometry,
                    config.phase_center_direction_rad,
                    group.pointing_direction_rad,
                )
            })
            .count();
        let metal_cache_prepared_groups = metal_group_cache
            .map(|cache| cache.iter().filter(|group| group.is_some()).count())
            .unwrap_or(0);
        eprintln!(
            "mosaic_residual_parallel groups={} grouped_samples={} total_worker_samples={} requested_threads={} chunk_len={} partition=group-contiguous actual_threads={} worker_samples={:?} worker_alloc_ms={:?} worker_ms={:?} metal_backend_enabled={} metal_cache_present={} metal_cache_prepared_groups={} metal_on_demand_candidate_groups={} metal_pb_rejected_groups={} backend_selection=byte-work-formula metal_calls={} metal_dirty_calls={} metal_residual_calls={} metal_samples={} metal_kernel_pack_ms={:.3} metal_device_queue_ms={:.3} metal_shader_compile_ms={:.3} metal_pipeline_ms={:.3} metal_buffer_alloc_ms={:.3} metal_model_pack_ms={:.3} metal_zero_outputs_ms={:.3} metal_encode_ms={:.3} metal_dispatch_wait_ms={:.3} metal_reduce_wait_ms={:.3} metal_readback_ms={:.3} metal_total_ms={:.3} join_ms={:.3} merge_ms={:.3} total_ms={:.3}",
            groups.len(),
            grouped_samples,
            total_worker_samples,
            thread_count,
            chunk_len,
            worker_samples.len(),
            worker_samples,
            worker_alloc
                .iter()
                .map(|elapsed| profile::millis(*elapsed))
                .collect::<Vec<_>>(),
            worker_compute
                .iter()
                .map(|elapsed| profile::millis(*elapsed))
                .collect::<Vec<_>>(),
            metal_group_cache.is_some(),
            metal_group_cache.is_some(),
            metal_cache_prepared_groups,
            residual_on_demand_candidate_groups,
            residual_pb_rejected_groups,
            metal_stats.calls,
            metal_stats.dirty_calls,
            metal_stats.residual_calls,
            metal_stats.samples,
            profile::millis(metal_stats.kernel_pack),
            profile::millis(metal_stats.device_queue),
            profile::millis(metal_stats.shader_compile),
            profile::millis(metal_stats.pipeline),
            profile::millis(metal_stats.buffer_alloc),
            profile::millis(metal_stats.model_pack),
            profile::millis(metal_stats.zero_outputs),
            profile::millis(metal_stats.encode),
            profile::millis(metal_stats.dispatch_wait),
            profile::millis(metal_stats.reduce_wait),
            profile::millis(metal_stats.readback),
            profile::millis(metal_stats.total),
            profile::millis(join_elapsed),
            profile::millis(merge_elapsed),
            profile::millis(started.elapsed()),
        );
    }

    Ok(MosaicResidualParallelContribution {
        residual_grid,
        worker_samples,
        worker_alloc,
        worker_compute,
        join_elapsed,
        merge_elapsed,
        elapsed: started.elapsed(),
    })
}

#[allow(clippy::too_many_arguments)]
fn compute_mosaic_residual_group_contribution(
    request: &ImagingRequest,
    config: &MosaicGridderConfig,
    gridder: &StandardGridder,
    group: &MosaicPointingGroup,
    conv_sampling: usize,
    model_grid: Option<&Array2<Complex32>>,
    thread_count: usize,
    projector_cache: Option<&mut MosaicProjectorCache>,
    prepared_metal: Option<&MosaicMetalPreparedGroup>,
    prepared_projector: Option<&ScreenProjector>,
) -> Result<MosaicResidualGroupContribution, ImagingError> {
    let [grid_nx, grid_ny] = gridder.grid_shape();
    if !mosaic_pointing_contributes_by_simple_pb_center(
        request.geometry,
        config.phase_center_direction_rad,
        group.pointing_direction_rad,
    ) {
        return Ok(MosaicResidualGroupContribution {
            residual_grid: Array2::<Complex64>::zeros((grid_nx, grid_ny)),
            metal_stats: MosaicMetalGridStats::default(),
            worker_samples: Vec::new(),
            worker_compute: Vec::new(),
            worker_alloc: Vec::new(),
            join_elapsed: Duration::ZERO,
            merge_elapsed: Duration::ZERO,
            stage_elapsed: Duration::ZERO,
        });
    }
    let built_projector;
    let cached_projector;
    let projector = match prepared_projector {
        Some(projector) => projector,
        None => match projector_cache {
            Some(cache) => {
                cached_projector = cached_mosaic_projector(
                    cache,
                    request.geometry,
                    gridder,
                    config.phase_center_direction_rad,
                    group.pointing_direction_rad,
                    group.primary_beam_model,
                    group.frequency_hz,
                    conv_sampling,
                    2,
                    true,
                )?;
                &cached_projector
            }
            None => {
                built_projector = build_mosaic_projector(
                    request.geometry,
                    gridder,
                    config.phase_center_direction_rad,
                    group.pointing_direction_rad,
                    group.primary_beam_model,
                    group.frequency_hz,
                    conv_sampling,
                    2,
                    true,
                )?;
                &built_projector
            }
        },
    };
    {
        let collected_prepared;
        let prepared = match prepared_metal {
            Some(prepared) => prepared,
            None => {
                collected_prepared = collect_mosaic_metal_samples(group, projector, None)?;
                &collected_prepared
            }
        };
        let costs = mosaic_group_backend_cost(
            gridder.grid_shape(),
            projector.support().saturating_mul(2).saturating_add(1),
            group.batch.len(),
            prepared.samples.len(),
            1,
            thread_count,
        );
        if prepared_metal.is_some()
            && costs.metal_byte_work <= costs.raw_cpu_byte_work.min(costs.grouped_cpu_byte_work)
        {
            return compute_mosaic_residual_group_grid_metal(
                gridder,
                group,
                projector,
                model_grid,
                Some(prepared),
            );
        }
        if costs.grouped_cpu_byte_work <= costs.raw_cpu_byte_work {
            return compute_mosaic_residual_group_grid_grouped_cpu(
                gridder, group, projector, model_grid, prepared,
            );
        }
    }
    let actual_threads = mosaic_parallel_thread_count(group.batch.len(), thread_count);
    if actual_threads > 1 {
        let contribution = compute_mosaic_residual_group_grid_sample_ranges(
            gridder,
            group,
            projector,
            model_grid,
            actual_threads,
        )?;
        profile::log_parallel_stage(profile::ParallelStageProfile {
            stage: "mosaic_residual_group_grid",
            requested_threads: thread_count,
            actual_threads: contribution.worker_compute.len(),
            chunking: "sample-range",
            chunk_len: group.batch.len().div_ceil(actual_threads),
            samples_total: group.batch.len(),
            samples_per_worker: contribution.worker_samples.clone(),
            local_grid_bytes_per_worker: complex64_grid_bytes(grid_nx, grid_ny, 1),
            local_grid_count: 1,
            local_alloc_zero_by_worker: contribution.worker_alloc.clone(),
            worker_compute_by_worker: contribution.worker_compute.clone(),
            join_duration: contribution.join_elapsed,
            merge_duration: contribution.merge_elapsed,
            stage_duration: contribution.stage_elapsed,
        });
        return Ok(contribution);
    }
    let started = Instant::now();
    let mut residual_grid = Array2::<Complex64>::zeros((grid_nx, grid_ny));
    for sample_index in 0..group.batch.len() {
        if !group.batch.gridable[sample_index] {
            continue;
        }
        let weight = group.batch.weight[sample_index];
        let sumwt_factor = group.batch.sumwt_factor[sample_index];
        let visibility = group.batch.visibility[sample_index];
        if !(weight.is_finite()
            && weight > 0.0
            && sumwt_factor.is_finite()
            && sumwt_factor > 0.0
            && visibility.re.is_finite()
            && visibility.im.is_finite())
        {
            continue;
        }
        let Some(plan) = projector.plan_sample_for_grid(
            group.batch.u_lambda[sample_index],
            group.batch.v_lambda[sample_index],
        ) else {
            continue;
        };
        let predicted = model_grid
            .map(|grid| projector.degrid_sample_planned(grid, &plan))
            .unwrap_or_else(|| Complex32::new(0.0, 0.0));
        let residual_visibility = visibility - predicted;
        let grid_weight = weight * sumwt_factor;
        projector.grid_sample_planned_f64(
            &mut residual_grid,
            &plan,
            residual_visibility * grid_weight,
        );
    }
    Ok(MosaicResidualGroupContribution {
        residual_grid,
        metal_stats: MosaicMetalGridStats::default(),
        worker_samples: vec![group.batch.len()],
        worker_compute: vec![started.elapsed()],
        worker_alloc: Vec::new(),
        join_elapsed: started.elapsed(),
        merge_elapsed: Duration::ZERO,
        stage_elapsed: started.elapsed(),
    })
}

fn compute_mosaic_residual_group_grid_grouped_cpu(
    gridder: &StandardGridder,
    group: &MosaicPointingGroup,
    projector: &ScreenProjector,
    model_grid: Option<&Array2<Complex32>>,
    prepared: &MosaicMetalPreparedGroup,
) -> Result<MosaicResidualGroupContribution, ImagingError> {
    let started = profile::standard_mfs_profile_block_detail_enabled().then(Instant::now);
    let [grid_nx, grid_ny] = gridder.grid_shape();
    let alloc_started = profile::standard_mfs_profile_block_detail_enabled().then(Instant::now);
    let mut residual_grid = Array2::<Complex64>::zeros((grid_nx, grid_ny));
    let alloc_elapsed = alloc_started.map_or(Duration::ZERO, |started| started.elapsed());
    let grid_started = profile::standard_mfs_profile_block_detail_enabled().then(Instant::now);
    accumulate_mosaic_grouped_residual_cpu(
        projector,
        &prepared.samples,
        model_grid,
        &mut residual_grid,
    );
    let grid_elapsed = grid_started.map_or(Duration::ZERO, |started| started.elapsed());
    let stage_elapsed = started.map_or(Duration::ZERO, |started| started.elapsed());
    if profile::standard_mfs_profile_block_detail_enabled() {
        eprintln!(
            "mosaic_grouped_cpu_residual raw_samples={} grouped_samples={} grouped_sample_ratio={:.6} grid_ms={:.3} alloc_ms={:.3} total_ms={:.3}",
            prepared.gridded_samples,
            prepared.samples.len(),
            if prepared.gridded_samples == 0 {
                0.0
            } else {
                prepared.samples.len() as f64 / prepared.gridded_samples as f64
            },
            profile::millis(grid_elapsed),
            profile::millis(alloc_elapsed),
            profile::millis(stage_elapsed),
        );
    }
    Ok(MosaicResidualGroupContribution {
        residual_grid,
        metal_stats: MosaicMetalGridStats::default(),
        worker_samples: vec![group.batch.len()],
        worker_compute: vec![grid_elapsed],
        worker_alloc: vec![alloc_elapsed],
        join_elapsed: stage_elapsed,
        merge_elapsed: Duration::ZERO,
        stage_elapsed,
    })
}

fn accumulate_mosaic_residual_group_grid_grouped_cpu_into(
    projector: &ScreenProjector,
    model_grid: Option<&Array2<Complex32>>,
    prepared: &MosaicMetalPreparedGroup,
    residual_grid: &mut Array2<Complex64>,
) {
    let started = profile::standard_mfs_profile_block_detail_enabled().then(Instant::now);
    let grid_started = profile::standard_mfs_profile_block_detail_enabled().then(Instant::now);
    accumulate_mosaic_grouped_residual_cpu(projector, &prepared.samples, model_grid, residual_grid);
    let grid_elapsed = grid_started.map_or(Duration::ZERO, |started| started.elapsed());
    let stage_elapsed = started.map_or(Duration::ZERO, |started| started.elapsed());
    if profile::standard_mfs_profile_block_detail_enabled() {
        eprintln!(
            "mosaic_grouped_cpu_residual_into raw_samples={} grouped_samples={} grouped_sample_ratio={:.6} grid_ms={:.3} total_ms={:.3}",
            prepared.gridded_samples,
            prepared.samples.len(),
            if prepared.gridded_samples == 0 {
                0.0
            } else {
                prepared.samples.len() as f64 / prepared.gridded_samples as f64
            },
            profile::millis(grid_elapsed),
            profile::millis(stage_elapsed),
        );
    }
}

fn compute_mosaic_residual_group_grid_sample_ranges(
    gridder: &StandardGridder,
    group: &MosaicPointingGroup,
    projector: &ScreenProjector,
    model_grid: Option<&Array2<Complex32>>,
    thread_count: usize,
) -> Result<MosaicResidualGroupContribution, ImagingError> {
    let [grid_nx, grid_ny] = gridder.grid_shape();
    let chunk_len = group.batch.len().div_ceil(thread_count);
    let stage_started = profile::maybe_profile_now();
    let join_started = profile::maybe_profile_now();
    let mut worker_results = Vec::<MosaicResidualRangeContribution>::new();
    thread::scope(|scope| {
        let mut handles = Vec::with_capacity(thread_count);
        for sample_start in (0..group.batch.len()).step_by(chunk_len) {
            let sample_end = (sample_start + chunk_len).min(group.batch.len());
            handles.push(scope.spawn(move || {
                let alloc_started = profile::maybe_profile_now();
                let mut residual_grid = Array2::<Complex64>::zeros((grid_nx, grid_ny));
                let alloc_elapsed = profile::elapsed_since(alloc_started);
                let compute_started = profile::maybe_profile_now();
                for sample_index in sample_start..sample_end {
                    if !group.batch.gridable[sample_index] {
                        continue;
                    }
                    let weight = group.batch.weight[sample_index];
                    let sumwt_factor = group.batch.sumwt_factor[sample_index];
                    let visibility = group.batch.visibility[sample_index];
                    if !(weight.is_finite()
                        && weight > 0.0
                        && sumwt_factor.is_finite()
                        && sumwt_factor > 0.0
                        && visibility.re.is_finite()
                        && visibility.im.is_finite())
                    {
                        continue;
                    }
                    let Some(plan) = projector.plan_sample_for_grid(
                        group.batch.u_lambda[sample_index],
                        group.batch.v_lambda[sample_index],
                    ) else {
                        continue;
                    };
                    let predicted = model_grid
                        .map(|grid| projector.degrid_sample_planned(grid, &plan))
                        .unwrap_or_else(|| Complex32::new(0.0, 0.0));
                    let residual_visibility = visibility - predicted;
                    let grid_weight = weight * sumwt_factor;
                    projector.grid_sample_planned_f64(
                        &mut residual_grid,
                        &plan,
                        residual_visibility * grid_weight,
                    );
                }
                MosaicResidualRangeContribution {
                    sample_start,
                    samples_assigned: sample_end - sample_start,
                    residual_grid,
                    alloc_elapsed,
                    compute_elapsed: profile::elapsed_since(compute_started),
                }
            }));
        }
        for handle in handles {
            worker_results.push(handle.join().map_err(|_| {
                ImagingError::Unsupported("mosaic residual sample worker panicked".to_string())
            })?);
        }
        Ok::<(), ImagingError>(())
    })?;
    let join_elapsed = profile::elapsed_since(join_started);

    worker_results.sort_by_key(|result| result.sample_start);
    let mut residual_grid = Array2::<Complex64>::zeros((grid_nx, grid_ny));
    let merge_started = profile::maybe_profile_now();
    for contribution in &worker_results {
        add_complex64_grid(&mut residual_grid, &contribution.residual_grid);
    }
    let merge_elapsed = profile::elapsed_since(merge_started);
    Ok(MosaicResidualGroupContribution {
        residual_grid,
        metal_stats: MosaicMetalGridStats::default(),
        worker_samples: worker_results
            .iter()
            .map(|result| result.samples_assigned)
            .collect(),
        worker_compute: worker_results
            .iter()
            .map(|result| result.compute_elapsed)
            .collect(),
        worker_alloc: worker_results
            .iter()
            .map(|result| result.alloc_elapsed)
            .collect(),
        join_elapsed,
        merge_elapsed,
        stage_elapsed: profile::elapsed_since(stage_started),
    })
}

fn compute_mosaic_residual_group_grid_metal(
    gridder: &StandardGridder,
    group: &MosaicPointingGroup,
    projector: &ScreenProjector,
    model_grid: Option<&Array2<Complex32>>,
    prepared_group: Option<&MosaicMetalPreparedGroup>,
) -> Result<MosaicResidualGroupContribution, ImagingError> {
    let [grid_nx, grid_ny] = gridder.grid_shape();
    let collected_prepared;
    let prepared = match prepared_group {
        Some(prepared) => prepared,
        None => {
            collected_prepared = collect_mosaic_metal_samples(group, projector, None)?;
            &collected_prepared
        }
    };
    if prepared.samples.is_empty() {
        return Ok(MosaicResidualGroupContribution {
            residual_grid: Array2::<Complex64>::zeros((grid_nx, grid_ny)),
            metal_stats: MosaicMetalGridStats::default(),
            worker_samples: Vec::new(),
            worker_compute: Vec::new(),
            worker_alloc: Vec::new(),
            join_elapsed: Duration::ZERO,
            merge_elapsed: Duration::ZERO,
            stage_elapsed: Duration::ZERO,
        });
    }
    let mut psf_grid = Array2::<Complex32>::zeros((grid_nx, grid_ny));
    let mut residual_grid = Array2::<Complex32>::zeros((grid_nx, grid_ny));
    let started = Instant::now();
    let metal_stats = accumulate_mosaic_grid_metal_samples(
        projector,
        &prepared.samples,
        model_grid,
        &mut psf_grid,
        &mut residual_grid,
        MOSAIC_METAL_MODE_RESIDUAL,
    )?;
    Ok(MosaicResidualGroupContribution {
        residual_grid: complex32_grid_to_complex64(&residual_grid),
        metal_stats,
        worker_samples: vec![prepared.samples.len()],
        worker_compute: vec![started.elapsed()],
        worker_alloc: Vec::new(),
        join_elapsed: started.elapsed(),
        merge_elapsed: Duration::ZERO,
        stage_elapsed: started.elapsed(),
    })
}

fn accumulate_mosaic_grid_metal_samples(
    projector: &ScreenProjector,
    samples: &[MosaicMetalSample],
    model_grid: Option<&Array2<Complex32>>,
    psf_grid: &mut Array2<Complex32>,
    residual_grid: &mut Array2<Complex32>,
    mode: u32,
) -> Result<MosaicMetalGridStats, ImagingError> {
    accumulate_mosaic_grid_metal_samples_impl(
        projector,
        samples,
        model_grid,
        psf_grid,
        residual_grid,
        mode,
    )
}

#[cfg(any(not(target_os = "macos"), coverage))]
fn accumulate_mosaic_grid_metal_samples_impl(
    _projector: &ScreenProjector,
    _samples: &[MosaicMetalSample],
    _model_grid: Option<&Array2<Complex32>>,
    _psf_grid: &mut Array2<Complex32>,
    _residual_grid: &mut Array2<Complex32>,
    _mode: u32,
) -> Result<MosaicMetalGridStats, ImagingError> {
    Err(ImagingError::Unsupported(
        "mosaic backend 'metal' requires macOS Metal and is not available on this platform"
            .to_string(),
    ))
}

#[cfg(all(target_os = "macos", not(coverage)))]
fn accumulate_mosaic_grid_metal_samples_impl(
    projector: &ScreenProjector,
    samples: &[MosaicMetalSample],
    model_grid: Option<&Array2<Complex32>>,
    psf_grid: &mut Array2<Complex32>,
    residual_grid: &mut Array2<Complex32>,
    mode: u32,
) -> Result<MosaicMetalGridStats, ImagingError> {
    use std::{ffi::c_void, mem, ptr, ptr::NonNull, slice};

    use objc2_metal::{
        MTLBuffer, MTLCommandBuffer, MTLCommandBufferStatus, MTLCommandEncoder, MTLCommandQueue,
        MTLComputeCommandEncoder, MTLComputePipelineState, MTLCreateSystemDefaultDevice, MTLDevice,
        MTLLibrary, MTLResourceOptions, MTLSize,
    };

    let profile_detail = profile::standard_mfs_profile_detail_enabled();
    let total_started = Instant::now();
    let [grid_width, grid_height] = gridder_shape_from_complex32_grid(psf_grid);
    let cell_count = grid_width.checked_mul(grid_height).ok_or_else(|| {
        ImagingError::InvalidRequest("mosaic Metal grid is too large".to_string())
    })?;
    if samples.is_empty() {
        return Ok(MosaicMetalGridStats::default());
    }
    let kernel_span = projector.support().saturating_mul(2).saturating_add(1);
    let sample_bytes = mem::size_of_val(samples);
    let kernel_pack_started = Instant::now();
    let compact_kernel = projector.compact_phased_kernel_weights();
    let kernel_values = compact_kernel
        .values
        .iter()
        .map(|value| WProjectMetalComplex {
            re: value.re,
            im: value.im,
        })
        .collect::<Vec<_>>();
    let kernel_pack_elapsed = kernel_pack_started.elapsed();
    let kernel_bytes = mem::size_of_val(kernel_values.as_slice());
    let model_pack_started = Instant::now();
    let model_values = if let Some(model_grid) = model_grid {
        model_grid
            .iter()
            .map(|value| WProjectMetalComplex {
                re: value.re,
                im: value.im,
            })
            .collect::<Vec<_>>()
    } else {
        vec![WProjectMetalComplex { re: 0.0, im: 0.0 }]
    };
    let model_pack_elapsed = model_pack_started.elapsed();
    let model_bytes = mem::size_of_val(model_values.as_slice());
    let device_queue_started = Instant::now();
    let device = MTLCreateSystemDefaultDevice().ok_or_else(|| {
        ImagingError::Unsupported(
            "mosaic backend 'metal' could not find a default Metal device".to_string(),
        )
    })?;
    let output_bytes = cell_count
        .checked_mul(mem::size_of::<u32>())
        .ok_or_else(|| {
            ImagingError::InvalidRequest("mosaic Metal output grid is too large".to_string())
        })?;
    let fixed_dispatch_bytes = sample_bytes
        .saturating_add(kernel_bytes)
        .saturating_add(model_bytes)
        .saturating_add(mem::size_of::<MosaicMetalParams>())
        .saturating_add(output_bytes.saturating_mul(4));
    let recommended_working_set_bytes = device.recommendedMaxWorkingSetSize();
    let current_allocated_bytes = device.currentAllocatedSize();
    let partial_grid_budget_bytes = metal_dispatch_temporary_budget(
        recommended_working_set_bytes,
        current_allocated_bytes,
        fixed_dispatch_bytes,
    );
    let desired_partial_grid_plan = plan_metal_partial_grids(
        samples.len(),
        cell_count,
        kernel_span.saturating_mul(kernel_span),
        4,
        usize::MAX,
    );
    let (partial_grid_plan, _partial_grid_reservation) =
        reserve_metal_partial_grids(desired_partial_grid_plan, partial_grid_budget_bytes);
    let partial_grid_count = partial_grid_plan.count;
    let partial_chunk_len = samples.len().div_ceil(partial_grid_count);
    let use_partial_grids = partial_grid_count > 1;
    let params = MosaicMetalParams {
        sample_count: u32::try_from(samples.len()).map_err(|_| {
            ImagingError::InvalidRequest("mosaic Metal sample count exceeds u32".to_string())
        })?,
        grid_width: u32::try_from(grid_width).map_err(|_| {
            ImagingError::InvalidRequest("mosaic Metal grid width exceeds u32".to_string())
        })?,
        grid_height: u32::try_from(grid_height).map_err(|_| {
            ImagingError::InvalidRequest("mosaic Metal grid height exceeds u32".to_string())
        })?,
        kernel_width: u32::try_from(compact_kernel.tap_width).map_err(|_| {
            ImagingError::InvalidRequest("mosaic Metal tap width exceeds u32".to_string())
        })?,
        kernel_center: u32::try_from(compact_kernel.offset_bias).map_err(|_| {
            ImagingError::InvalidRequest("mosaic Metal offset bias exceeds u32".to_string())
        })?,
        sampling: u32::try_from(compact_kernel.offset_count).map_err(|_| {
            ImagingError::InvalidRequest("mosaic Metal offset count exceeds u32".to_string())
        })?,
        mode,
        model_present: u32::from(model_grid.is_some()),
        partial_grid_count: u32::try_from(partial_grid_count).map_err(|_| {
            ImagingError::InvalidRequest("mosaic Metal partial grid count exceeds u32".to_string())
        })?,
        partial_chunk_len: u32::try_from(partial_chunk_len).map_err(|_| {
            ImagingError::InvalidRequest(
                "mosaic Metal partial grid chunk length exceeds u32".to_string(),
            )
        })?,
        _pad0: 0,
    };

    let queue = device.newCommandQueue().ok_or_else(|| {
        ImagingError::Unsupported(
            "mosaic backend 'metal' could not create a Metal command queue".to_string(),
        )
    })?;
    let device_queue_elapsed = device_queue_started.elapsed();
    let shader_compile_started = Instant::now();
    let source = objc2_foundation::NSString::from_str(MOSAIC_METAL_SHADER);
    let library = device
        .newLibraryWithSource_options_error(&source, None)
        .map_err(|error| {
            ImagingError::Unsupported(format!(
                "mosaic backend 'metal' failed to compile shader: {error:?}"
            ))
        })?;
    let shader_compile_elapsed = shader_compile_started.elapsed();
    let pipeline_started = Instant::now();
    let entry_point = if use_partial_grids {
        "mosaic_grid_chunked_samples"
    } else {
        "mosaic_grid_samples"
    };
    let function_name = objc2_foundation::NSString::from_str(entry_point);
    let function = library.newFunctionWithName(&function_name).ok_or_else(|| {
        ImagingError::Unsupported(
            "mosaic backend 'metal' shader entry point was not found".to_string(),
        )
    })?;
    let pipeline = device
        .newComputePipelineStateWithFunction_error(&function)
        .map_err(|error| {
            ImagingError::Unsupported(format!(
                "mosaic backend 'metal' failed to create pipeline: {error:?}"
            ))
        })?;
    let pipeline_elapsed = pipeline_started.elapsed();
    let reduce_pipeline = if use_partial_grids {
        let reduce_function_name =
            objc2_foundation::NSString::from_str("mosaic_reduce_chunked_grids");
        let reduce_function = library
            .newFunctionWithName(&reduce_function_name)
            .ok_or_else(|| {
                ImagingError::Unsupported(
                    "mosaic backend 'metal' reduction shader entry point was not found".to_string(),
                )
            })?;
        Some(
            device
                .newComputePipelineStateWithFunction_error(&reduce_function)
                .map_err(|error| {
                    ImagingError::Unsupported(format!(
                        "mosaic backend 'metal' failed to create reduction pipeline: {error:?}"
                    ))
                })?,
        )
    } else {
        None
    };
    let storage_options = MTLResourceOptions::StorageModeShared;

    let buffer_started = Instant::now();
    let sample_buffer = unsafe {
        let pointer =
            NonNull::new(samples.as_ptr().cast::<c_void>() as *mut c_void).ok_or_else(|| {
                ImagingError::InvalidRequest("mosaic Metal sample pointer was null".to_string())
            })?;
        device
            .newBufferWithBytesNoCopy_length_options_deallocator(
                pointer,
                sample_bytes,
                storage_options,
                None,
            )
            .ok_or_else(|| {
                ImagingError::Unsupported(
                    "mosaic backend 'metal' could not wrap sample buffer".to_string(),
                )
            })?
    };
    let kernel_buffer = unsafe {
        let pointer = NonNull::new(kernel_values.as_ptr().cast::<c_void>() as *mut c_void)
            .ok_or_else(|| {
                ImagingError::InvalidRequest("mosaic Metal kernel pointer was null".to_string())
            })?;
        device
            .newBufferWithBytesNoCopy_length_options_deallocator(
                pointer,
                kernel_bytes,
                storage_options,
                None,
            )
            .ok_or_else(|| {
                ImagingError::Unsupported(
                    "mosaic backend 'metal' could not wrap kernel buffer".to_string(),
                )
            })?
    };
    let model_buffer = unsafe {
        let pointer = NonNull::new(model_values.as_ptr().cast::<c_void>() as *mut c_void)
            .ok_or_else(|| {
                ImagingError::InvalidRequest("mosaic Metal model pointer was null".to_string())
            })?;
        device
            .newBufferWithBytesNoCopy_length_options_deallocator(
                pointer,
                model_bytes,
                storage_options,
                None,
            )
            .ok_or_else(|| {
                ImagingError::Unsupported(
                    "mosaic backend 'metal' could not wrap model buffer".to_string(),
                )
            })?
    };
    let params_buffer = unsafe {
        let params_slice = slice::from_ref(&params);
        let byte_len = mem::size_of_val(params_slice);
        let pointer = NonNull::new(params_slice.as_ptr().cast::<c_void>() as *mut c_void)
            .ok_or_else(|| {
                ImagingError::InvalidRequest("mosaic Metal params pointer was null".to_string())
            })?;
        device
            .newBufferWithBytes_length_options(pointer, byte_len, storage_options)
            .ok_or_else(|| {
                ImagingError::Unsupported(
                    "mosaic backend 'metal' could not allocate params buffer".to_string(),
                )
            })?
    };
    let partial_output_bytes = output_bytes
        .checked_mul(partial_grid_count)
        .ok_or_else(|| {
            ImagingError::InvalidRequest(
                "mosaic Metal partial output grid is too large".to_string(),
            )
        })?;
    let psf_re = device
        .newBufferWithLength_options(output_bytes, storage_options)
        .ok_or_else(|| {
            ImagingError::Unsupported(
                "mosaic backend 'metal' could not allocate PSF real buffer".to_string(),
            )
        })?;
    let psf_im = device
        .newBufferWithLength_options(output_bytes, storage_options)
        .ok_or_else(|| {
            ImagingError::Unsupported(
                "mosaic backend 'metal' could not allocate PSF imag buffer".to_string(),
            )
        })?;
    let residual_re = device
        .newBufferWithLength_options(output_bytes, storage_options)
        .ok_or_else(|| {
            ImagingError::Unsupported(
                "mosaic backend 'metal' could not allocate residual real buffer".to_string(),
            )
        })?;
    let residual_im = device
        .newBufferWithLength_options(output_bytes, storage_options)
        .ok_or_else(|| {
            ImagingError::Unsupported(
                "mosaic backend 'metal' could not allocate residual imag buffer".to_string(),
            )
        })?;
    let partial_psf_re = if use_partial_grids {
        Some(
            device
                .newBufferWithLength_options(partial_output_bytes, storage_options)
                .ok_or_else(|| {
                    ImagingError::Unsupported(
                        "mosaic backend 'metal' could not allocate partial PSF real buffer"
                            .to_string(),
                    )
                })?,
        )
    } else {
        None
    };
    let partial_psf_im = if use_partial_grids {
        Some(
            device
                .newBufferWithLength_options(partial_output_bytes, storage_options)
                .ok_or_else(|| {
                    ImagingError::Unsupported(
                        "mosaic backend 'metal' could not allocate partial PSF imag buffer"
                            .to_string(),
                    )
                })?,
        )
    } else {
        None
    };
    let partial_residual_re = if use_partial_grids {
        Some(
            device
                .newBufferWithLength_options(partial_output_bytes, storage_options)
                .ok_or_else(|| {
                    ImagingError::Unsupported(
                        "mosaic backend 'metal' could not allocate partial residual real buffer"
                            .to_string(),
                    )
                })?,
        )
    } else {
        None
    };
    let partial_residual_im = if use_partial_grids {
        Some(
            device
                .newBufferWithLength_options(partial_output_bytes, storage_options)
                .ok_or_else(|| {
                    ImagingError::Unsupported(
                        "mosaic backend 'metal' could not allocate partial residual imag buffer"
                            .to_string(),
                    )
                })?,
        )
    } else {
        None
    };
    let buffer_elapsed = buffer_started.elapsed();
    let accum_psf_re = partial_psf_re.as_ref().unwrap_or(&psf_re);
    let accum_psf_im = partial_psf_im.as_ref().unwrap_or(&psf_im);
    let accum_residual_re = partial_residual_re.as_ref().unwrap_or(&residual_re);
    let accum_residual_im = partial_residual_im.as_ref().unwrap_or(&residual_im);
    let accum_output_bytes = if use_partial_grids {
        partial_output_bytes
    } else {
        output_bytes
    };
    let zero_started = Instant::now();
    unsafe {
        ptr::write_bytes(
            accum_psf_re.contents().as_ptr().cast::<u8>(),
            0,
            accum_output_bytes,
        );
        ptr::write_bytes(
            accum_psf_im.contents().as_ptr().cast::<u8>(),
            0,
            accum_output_bytes,
        );
        ptr::write_bytes(
            accum_residual_re.contents().as_ptr().cast::<u8>(),
            0,
            accum_output_bytes,
        );
        ptr::write_bytes(
            accum_residual_im.contents().as_ptr().cast::<u8>(),
            0,
            accum_output_bytes,
        );
    }
    let zero_elapsed = zero_started.elapsed();

    if profile_detail {
        eprintln!(
            "mosaic_metal_dispatch_begin mode={} entry={} samples={} grid={}x{} support={} full_kernel_width={} compact_tap_width={} offset_count={} desired_partial_grids={} partial_grids={} partial_grid_reserved_bytes={} partial_chunk_len={} recommended_working_set_bytes={} current_allocated_bytes={} fixed_dispatch_bytes={} partial_grid_budget_bytes={} sample_bytes={} kernel_bytes={} model_bytes={} accum_output_bytes={}",
            mode,
            entry_point,
            samples.len(),
            grid_width,
            grid_height,
            projector.support(),
            projector.kernel_weight_width(),
            compact_kernel.tap_width,
            compact_kernel.offset_count,
            desired_partial_grid_plan.count,
            partial_grid_count,
            partial_grid_plan.reserved_bytes,
            partial_chunk_len,
            recommended_working_set_bytes,
            current_allocated_bytes,
            fixed_dispatch_bytes,
            partial_grid_budget_bytes,
            sample_bytes,
            kernel_bytes,
            model_bytes,
            accum_output_bytes * 4,
        );
    }

    let encode_started = Instant::now();
    let command_buffer = queue.commandBuffer().ok_or_else(|| {
        ImagingError::Unsupported(
            "mosaic backend 'metal' could not create a command buffer".to_string(),
        )
    })?;
    let encoder = command_buffer.computeCommandEncoder().ok_or_else(|| {
        ImagingError::Unsupported(
            "mosaic backend 'metal' could not create a compute encoder".to_string(),
        )
    })?;
    encoder.setComputePipelineState(&pipeline);
    unsafe {
        encoder.setBuffer_offset_atIndex(Some(&sample_buffer), 0, 0);
        encoder.setBuffer_offset_atIndex(Some(&kernel_buffer), 0, 1);
        encoder.setBuffer_offset_atIndex(Some(&model_buffer), 0, 2);
        encoder.setBuffer_offset_atIndex(Some(accum_psf_re), 0, 3);
        encoder.setBuffer_offset_atIndex(Some(accum_psf_im), 0, 4);
        encoder.setBuffer_offset_atIndex(Some(accum_residual_re), 0, 5);
        encoder.setBuffer_offset_atIndex(Some(accum_residual_im), 0, 6);
        encoder.setBuffer_offset_atIndex(Some(&params_buffer), 0, 7);
    }
    let thread_count = samples.len();
    let thread_width = pipeline.threadExecutionWidth().max(1);
    let max_threads = pipeline.maxTotalThreadsPerThreadgroup().max(1);
    let threads_per_group = thread_width.min(max_threads).min(thread_count).max(1);
    encoder.dispatchThreads_threadsPerThreadgroup(
        MTLSize {
            width: thread_count,
            height: 1,
            depth: 1,
        },
        MTLSize {
            width: threads_per_group,
            height: 1,
            depth: 1,
        },
    );
    encoder.endEncoding();
    let encode_elapsed = encode_started.elapsed();
    let dispatch_started = Instant::now();
    command_buffer.commit();
    command_buffer.waitUntilCompleted();
    let dispatch_elapsed = dispatch_started.elapsed();
    if command_buffer.status() == MTLCommandBufferStatus::Error {
        let message = command_buffer
            .error()
            .map(|error| format!("{error:?}"))
            .unwrap_or_else(|| "unknown Metal command buffer error".to_string());
        return Err(ImagingError::Unsupported(format!(
            "mosaic backend 'metal' command failed: {message}"
        )));
    }
    let mut reduce_elapsed = Duration::ZERO;
    if use_partial_grids {
        let reduce_started = Instant::now();
        let reduce_command_buffer = queue.commandBuffer().ok_or_else(|| {
            ImagingError::Unsupported(
                "mosaic backend 'metal' could not create a reduction command buffer".to_string(),
            )
        })?;
        let reduce_encoder = reduce_command_buffer
            .computeCommandEncoder()
            .ok_or_else(|| {
                ImagingError::Unsupported(
                    "mosaic backend 'metal' could not create a reduction compute encoder"
                        .to_string(),
                )
            })?;
        reduce_encoder
            .setComputePipelineState(reduce_pipeline.as_ref().expect("reduction pipeline"));
        unsafe {
            reduce_encoder.setBuffer_offset_atIndex(Some(accum_psf_re), 0, 0);
            reduce_encoder.setBuffer_offset_atIndex(Some(accum_psf_im), 0, 1);
            reduce_encoder.setBuffer_offset_atIndex(Some(accum_residual_re), 0, 2);
            reduce_encoder.setBuffer_offset_atIndex(Some(accum_residual_im), 0, 3);
            reduce_encoder.setBuffer_offset_atIndex(Some(&psf_re), 0, 4);
            reduce_encoder.setBuffer_offset_atIndex(Some(&psf_im), 0, 5);
            reduce_encoder.setBuffer_offset_atIndex(Some(&residual_re), 0, 6);
            reduce_encoder.setBuffer_offset_atIndex(Some(&residual_im), 0, 7);
            reduce_encoder.setBuffer_offset_atIndex(Some(&params_buffer), 0, 8);
        }
        let reduce_thread_count = cell_count;
        let reduce_thread_width = reduce_pipeline
            .as_ref()
            .expect("reduction pipeline")
            .threadExecutionWidth()
            .max(1);
        let reduce_max_threads = reduce_pipeline
            .as_ref()
            .expect("reduction pipeline")
            .maxTotalThreadsPerThreadgroup()
            .max(1);
        let reduce_threads_per_group = reduce_thread_width
            .min(reduce_max_threads)
            .min(reduce_thread_count)
            .max(1);
        reduce_encoder.dispatchThreads_threadsPerThreadgroup(
            MTLSize {
                width: reduce_thread_count,
                height: 1,
                depth: 1,
            },
            MTLSize {
                width: reduce_threads_per_group,
                height: 1,
                depth: 1,
            },
        );
        reduce_encoder.endEncoding();
        reduce_command_buffer.commit();
        reduce_command_buffer.waitUntilCompleted();
        reduce_elapsed = reduce_started.elapsed();
        if reduce_command_buffer.status() == MTLCommandBufferStatus::Error {
            let message = reduce_command_buffer
                .error()
                .map(|error| format!("{error:?}"))
                .unwrap_or_else(|| "unknown Metal command buffer error".to_string());
            return Err(ImagingError::Unsupported(format!(
                "mosaic backend 'metal' reduction command failed: {message}"
            )));
        }
    }

    let readback_started = Instant::now();
    let residual_re_values =
        unsafe { slice::from_raw_parts(residual_re.contents().as_ptr().cast::<f32>(), cell_count) };
    let residual_im_values =
        unsafe { slice::from_raw_parts(residual_im.contents().as_ptr().cast::<f32>(), cell_count) };
    if mode == MOSAIC_METAL_MODE_DIRTY {
        let psf_re_values =
            unsafe { slice::from_raw_parts(psf_re.contents().as_ptr().cast::<f32>(), cell_count) };
        let psf_im_values =
            unsafe { slice::from_raw_parts(psf_im.contents().as_ptr().cast::<f32>(), cell_count) };
        for (
            (((psf_cell, &psf_re_value), &psf_im_value), residual_cell),
            (&residual_re_value, &residual_im_value),
        ) in psf_grid
            .as_slice_memory_order_mut()
            .expect("mosaic PSF grid should be contiguous")
            .iter_mut()
            .zip(psf_re_values)
            .zip(psf_im_values)
            .zip(
                residual_grid
                    .as_slice_memory_order_mut()
                    .expect("mosaic residual grid should be contiguous")
                    .iter_mut(),
            )
            .zip(residual_re_values.iter().zip(residual_im_values))
        {
            *psf_cell = Complex32::new(psf_re_value, psf_im_value);
            *residual_cell = Complex32::new(residual_re_value, residual_im_value);
        }
    } else {
        for (residual_cell, (&residual_re_value, &residual_im_value)) in residual_grid
            .as_slice_memory_order_mut()
            .expect("mosaic residual grid should be contiguous")
            .iter_mut()
            .zip(residual_re_values.iter().zip(residual_im_values))
        {
            *residual_cell = Complex32::new(residual_re_value, residual_im_value);
        }
    }
    let readback_elapsed = readback_started.elapsed();

    let stats = MosaicMetalGridStats {
        calls: 1,
        dirty_calls: usize::from(mode == MOSAIC_METAL_MODE_DIRTY),
        residual_calls: usize::from(mode == MOSAIC_METAL_MODE_RESIDUAL),
        samples: samples.len(),
        kernel_pack: kernel_pack_elapsed,
        device_queue: device_queue_elapsed,
        shader_compile: shader_compile_elapsed,
        pipeline: pipeline_elapsed,
        buffer_alloc: buffer_elapsed,
        model_pack: model_pack_elapsed,
        zero_outputs: zero_elapsed,
        encode: encode_elapsed,
        dispatch_wait: dispatch_elapsed,
        reduce_wait: reduce_elapsed,
        readback: readback_elapsed,
        total: total_started.elapsed(),
    };

    if profile_detail {
        eprintln!(
            "mosaic_metal_grid mode={} entry={} samples={} grid={}x{} support={} full_kernel_width={} compact_tap_width={} offset_count={} partial_grids={} partial_chunk_len={} sample_bytes={} kernel_bytes={} model_bytes={} output_bytes={} partial_output_bytes={} thread_width={} max_threads={} threads_per_group={} kernel_pack_ms={:.3} device_queue_ms={:.3} shader_compile_ms={:.3} pipeline_ms={:.3} buffer_alloc_ms={:.3} model_pack_ms={:.3} zero_outputs_ms={:.3} encode_ms={:.3} dispatch_wait_ms={:.3} reduce_wait_ms={:.3} readback_ms={:.3} total_ms={:.3}",
            mode,
            entry_point,
            samples.len(),
            grid_width,
            grid_height,
            projector.support(),
            projector.kernel_weight_width(),
            compact_kernel.tap_width,
            compact_kernel.offset_count,
            partial_grid_count,
            partial_chunk_len,
            sample_bytes,
            kernel_bytes,
            model_bytes,
            output_bytes * 4,
            if use_partial_grids {
                partial_output_bytes * 4
            } else {
                0
            },
            thread_width,
            max_threads,
            threads_per_group,
            profile::millis(kernel_pack_elapsed),
            profile::millis(device_queue_elapsed),
            profile::millis(shader_compile_elapsed),
            profile::millis(pipeline_elapsed),
            profile::millis(buffer_elapsed),
            profile::millis(model_pack_elapsed),
            profile::millis(zero_elapsed),
            profile::millis(encode_elapsed),
            profile::millis(dispatch_elapsed),
            profile::millis(reduce_elapsed),
            profile::millis(readback_elapsed),
            profile::millis(stats.total),
        );
    }
    Ok(stats)
}

#[cfg_attr(any(not(target_os = "macos"), coverage), allow(dead_code))]
fn gridder_shape_from_complex32_grid(grid: &Array2<Complex32>) -> [usize; 2] {
    let dim = grid.dim();
    [dim.0, dim.1]
}

#[cfg(all(target_os = "macos", not(coverage)))]
const MOSAIC_METAL_SHADER: &str = r#"
#include <metal_stdlib>
using namespace metal;

struct MosaicSample {
    int loc_x;
    int loc_y;
    uint support;
    int offset_x;
    int offset_y;
    int range_x_min;
    int range_x_max;
    int range_y_min;
    int range_y_max;
    float weight;
    float visibility_re;
    float visibility_im;
    uint kernel_base;
};

struct MosaicParams {
    uint sample_count;
    uint grid_width;
    uint grid_height;
    uint kernel_width;
    uint kernel_center;
    uint sampling;
    uint mode;
    uint model_present;
    uint partial_grid_count;
    uint partial_chunk_len;
    uint _pad0;
};

static inline void mosaic_atomic_add_float(device atomic_float *address, float value) {
    atomic_fetch_add_explicit(address, value, memory_order_relaxed);
}

static inline uint mosaic_kernel_index(MosaicSample sample, constant MosaicParams &params, int ix, int iy) {
    const uint offset_x = uint(sample.offset_x + int(params.kernel_center));
    const uint offset_y = uint(sample.offset_y + int(params.kernel_center));
    const uint tap_x = uint(ix + int(sample.support));
    const uint tap_y = uint(iy + int(sample.support));
    const uint offset_base =
        (offset_y * params.sampling + offset_x) * params.kernel_width * params.kernel_width;
    return sample.kernel_base + offset_base + tap_y * params.kernel_width + tap_x;
}

kernel void mosaic_grid_samples(
    device const MosaicSample *samples [[buffer(0)]],
    device const float2 *kernels [[buffer(1)]],
    device const float2 *model [[buffer(2)]],
    device atomic_float *psf_re [[buffer(3)]],
    device atomic_float *psf_im [[buffer(4)]],
    device atomic_float *residual_re [[buffer(5)]],
    device atomic_float *residual_im [[buffer(6)]],
    constant MosaicParams &params [[buffer(7)]],
    uint sample_index [[thread_position_in_grid]]
) {
    if (sample_index >= params.sample_count) {
        return;
    }
    const MosaicSample sample = samples[sample_index];
    float predicted_re = 0.0f;
    float predicted_im = 0.0f;
    const bool needs_model = params.mode == 2u && params.model_present != 0u;
    if (needs_model) {
        for (int iy = sample.range_y_min; iy <= sample.range_y_max; ++iy) {
            const uint grid_y = uint(sample.loc_y + iy);
            for (int ix = sample.range_x_min; ix <= sample.range_x_max; ++ix) {
                const uint grid_x = uint(sample.loc_x + ix);
                const float2 cwt = kernels[mosaic_kernel_index(sample, params, ix, iy)];
                const float2 cell = model[grid_x * params.grid_height + grid_y];
                predicted_re += cwt.x * cell.x + cwt.y * cell.y;
                predicted_im += cwt.x * cell.y - cwt.y * cell.x;
            }
        }
    }

    const bool write_psf = params.mode == 1u;
    const bool write_residual = params.mode == 1u || params.mode == 2u;
    const float residual_value_re = sample.visibility_re - predicted_re;
    const float residual_value_im = sample.visibility_im - predicted_im;
    for (int iy = sample.range_y_min; iy <= sample.range_y_max; ++iy) {
        const uint grid_y = uint(sample.loc_y + iy);
        for (int ix = sample.range_x_min; ix <= sample.range_x_max; ++ix) {
            const uint grid_x = uint(sample.loc_x + ix);
            const float2 cwt = kernels[mosaic_kernel_index(sample, params, ix, iy)];
            const uint cell = grid_x * params.grid_height + grid_y;
            if (write_psf) {
                mosaic_atomic_add_float(&psf_re[cell], sample.weight * cwt.x);
                mosaic_atomic_add_float(&psf_im[cell], sample.weight * cwt.y);
            }
            if (write_residual) {
                const float weighted_re =
                    sample.weight * (residual_value_re * cwt.x - residual_value_im * cwt.y);
                const float weighted_im =
                    sample.weight * (residual_value_re * cwt.y + residual_value_im * cwt.x);
                mosaic_atomic_add_float(&residual_re[cell], weighted_re);
                mosaic_atomic_add_float(&residual_im[cell], weighted_im);
            }
        }
    }
}

kernel void mosaic_grid_chunked_samples(
    device const MosaicSample *samples [[buffer(0)]],
    device const float2 *kernels [[buffer(1)]],
    device const float2 *model [[buffer(2)]],
    device atomic_float *psf_re [[buffer(3)]],
    device atomic_float *psf_im [[buffer(4)]],
    device atomic_float *residual_re [[buffer(5)]],
    device atomic_float *residual_im [[buffer(6)]],
    constant MosaicParams &params [[buffer(7)]],
    uint sample_index [[thread_position_in_grid]]
) {
    if (sample_index >= params.sample_count) {
        return;
    }
    const MosaicSample sample = samples[sample_index];
    const uint partial_grid_index = min(
        sample_index / max(params.partial_chunk_len, 1u),
        params.partial_grid_count - 1u
    );
    const uint partial_grid_offset = partial_grid_index * params.grid_width * params.grid_height;
    float predicted_re = 0.0f;
    float predicted_im = 0.0f;
    const bool needs_model = params.mode == 2u && params.model_present != 0u;
    if (needs_model) {
        for (int iy = sample.range_y_min; iy <= sample.range_y_max; ++iy) {
            const uint grid_y = uint(sample.loc_y + iy);
            for (int ix = sample.range_x_min; ix <= sample.range_x_max; ++ix) {
                const uint grid_x = uint(sample.loc_x + ix);
                const float2 cwt = kernels[mosaic_kernel_index(sample, params, ix, iy)];
                const float2 cell = model[grid_x * params.grid_height + grid_y];
                predicted_re += cwt.x * cell.x + cwt.y * cell.y;
                predicted_im += cwt.x * cell.y - cwt.y * cell.x;
            }
        }
    }

    const bool write_psf = params.mode == 1u;
    const bool write_residual = params.mode == 1u || params.mode == 2u;
    const float residual_value_re = sample.visibility_re - predicted_re;
    const float residual_value_im = sample.visibility_im - predicted_im;
    for (int iy = sample.range_y_min; iy <= sample.range_y_max; ++iy) {
        const uint grid_y = uint(sample.loc_y + iy);
        for (int ix = sample.range_x_min; ix <= sample.range_x_max; ++ix) {
            const uint grid_x = uint(sample.loc_x + ix);
            const float2 cwt = kernels[mosaic_kernel_index(sample, params, ix, iy)];
            const uint cell = partial_grid_offset + grid_x * params.grid_height + grid_y;
            if (write_psf) {
                mosaic_atomic_add_float(&psf_re[cell], sample.weight * cwt.x);
                mosaic_atomic_add_float(&psf_im[cell], sample.weight * cwt.y);
            }
            if (write_residual) {
                const float weighted_re =
                    sample.weight * (residual_value_re * cwt.x - residual_value_im * cwt.y);
                const float weighted_im =
                    sample.weight * (residual_value_re * cwt.y + residual_value_im * cwt.x);
                mosaic_atomic_add_float(&residual_re[cell], weighted_re);
                mosaic_atomic_add_float(&residual_im[cell], weighted_im);
            }
        }
    }
}

kernel void mosaic_reduce_chunked_grids(
    device const float *partial_psf_re [[buffer(0)]],
    device const float *partial_psf_im [[buffer(1)]],
    device const float *partial_residual_re [[buffer(2)]],
    device const float *partial_residual_im [[buffer(3)]],
    device float *psf_re [[buffer(4)]],
    device float *psf_im [[buffer(5)]],
    device float *residual_re [[buffer(6)]],
    device float *residual_im [[buffer(7)]],
    constant MosaicParams &params [[buffer(8)]],
    uint cell [[thread_position_in_grid]]
) {
    const uint cell_count = params.grid_width * params.grid_height;
    if (cell >= cell_count) {
        return;
    }

    float sum_psf_re = 0.0f;
    float sum_psf_im = 0.0f;
    float sum_residual_re = 0.0f;
    float sum_residual_im = 0.0f;
    for (uint partial = 0; partial < params.partial_grid_count; ++partial) {
        const uint index = partial * cell_count + cell;
        sum_psf_re += partial_psf_re[index];
        sum_psf_im += partial_psf_im[index];
        sum_residual_re += partial_residual_re[index];
        sum_residual_im += partial_residual_im[index];
    }
    psf_re[cell] = sum_psf_re;
    psf_im[cell] = sum_psf_im;
    residual_re[cell] = sum_residual_re;
    residual_im[cell] = sum_residual_im;
}
"#;

fn flat_sky_mosaic_model_for_prediction(
    model: &Array2<f32>,
    weight_image: &Array2<f32>,
    pb_limit: f32,
) -> Result<Array2<f32>, ImagingError> {
    let weight_peak = weight_image
        .iter()
        .copied()
        .fold(0.0f32, |peak, value| peak.max(value));
    if !(weight_peak.is_finite() && weight_peak > 0.0) {
        return Err(ImagingError::Normalization(
            "mosaic model prediction weight peak is non-finite or zero".to_string(),
        ));
    }
    // SIImageStoreMultiTerm stores getPbMax() in a Double, but explicitly
    // materializes `sqrt(abs(weight)) / pbScale` as LatticeExpr<Float> before
    // constructing the Float mask and ratio expressions. Preserve that Float
    // denominator boundary and the subsequent mask arithmetic exactly.
    let pb_scale_factor = f64::from(weight_peak.sqrt());
    let pb_limit = pb_limit.abs();
    let mut prediction_model = Array2::<f32>::zeros(model.dim());
    for ((x, y), model_value) in model.indexed_iter() {
        prediction_model[(x, y)] = casa_flat_sky_model_prediction_pixel(
            *model_value,
            weight_image[(x, y)],
            pb_scale_factor,
            pb_limit,
        );
    }
    Ok(prediction_model)
}

#[inline]
fn casa_flat_sky_model_prediction_pixel(
    model_value: f32,
    weight_value: f32,
    pb_scale_factor: f64,
    pb_limit: f32,
) -> f32 {
    let denominator = (f64::from(weight_value.abs().sqrt()) / pb_scale_factor) as f32;
    let above_limit = denominator > pb_limit;
    let mask = if above_limit { 1.0_f32 } else { 0.0_f32 };
    let mask_inverse = if above_limit { 0.0_f32 } else { 1.0_f32 };
    (model_value * mask) / (denominator + mask_inverse)
}

fn sparse_flat_sky_awproject_model_casacore_storage(
    gridder: &StandardGridder,
    model: &Array2<f32>,
    weight_image: &Array2<f32>,
    pb_limit: f32,
    model_support_positions: &BTreeSet<(usize, usize)>,
) -> Result<Array2<Complex32>, ImagingError> {
    if model.dim() != weight_image.dim() {
        return Err(ImagingError::Normalization(
            "sparse AWProject model and weight images have different shapes".to_string(),
        ));
    }
    let weight_peak = weight_image
        .iter()
        .copied()
        .fold(0.0f32, |peak, value| peak.max(value));
    if !(weight_peak.is_finite() && weight_peak > 0.0) {
        return Err(ImagingError::Normalization(
            "mosaic model prediction weight peak is non-finite or zero".to_string(),
        ));
    }
    let [grid_nx, grid_ny] = gridder.grid_shape();
    let [grid_x0, grid_y0] = gridder.image_grid_origin();
    let pb_scale_factor = f64::from(weight_peak.sqrt());
    let pb_limit = pb_limit.abs();
    let mut prepared = Array2::<Complex32>::zeros((grid_ny, grid_nx));
    for &(x, y) in model_support_positions {
        if x >= model.dim().0 || y >= model.dim().1 {
            return Err(ImagingError::Normalization(
                "sparse AWProject model support escaped the model image".to_string(),
            ));
        }
        prepared[(grid_y0 + y, grid_x0 + x)] = Complex32::new(
            casa_flat_sky_model_prediction_pixel(
                model[(x, y)],
                weight_image[(x, y)],
                pb_scale_factor,
                pb_limit,
            ),
            0.0,
        );
    }
    Ok(prepared)
}

#[cfg(all(target_os = "macos", not(coverage)))]
type AwProjectSparsePreparedModelValues = Vec<BTreeMap<(usize, usize), Complex32>>;

#[cfg(all(target_os = "macos", not(coverage)))]
fn awproject_sparse_prepared_model_values(
    gridder: &StandardGridder,
    prepared_models: &[(Array2<Complex32>, bool)],
    model_support_positions: &BTreeSet<(usize, usize)>,
) -> Result<AwProjectSparsePreparedModelValues, ImagingError> {
    let [grid_x0, grid_y0] = gridder.image_grid_origin();
    prepared_models
        .iter()
        .map(|(prepared, casacore_storage)| {
            if !*casacore_storage {
                return Err(ImagingError::Unsupported(
                    "incremental AWProject model probe requires sparse casacore-layout preparation"
                        .to_string(),
                ));
            }
            let mut values = BTreeMap::new();
            for &(x, y) in model_support_positions {
                let input_x = grid_x0.checked_add(x).ok_or_else(|| {
                    ImagingError::InvalidRequest(
                        "incremental AWProject model X coordinate overflowed".to_string(),
                    )
                })?;
                let input_y = grid_y0.checked_add(y).ok_or_else(|| {
                    ImagingError::InvalidRequest(
                        "incremental AWProject model Y coordinate overflowed".to_string(),
                    )
                })?;
                let value = prepared.get((input_y, input_x)).copied().ok_or_else(|| {
                    ImagingError::Normalization(
                        "incremental AWProject model source escaped prepared storage".to_string(),
                    )
                })?;
                values.insert((input_x, input_y), value);
            }
            Ok(values)
        })
        .collect()
}

#[cfg(all(target_os = "macos", not(coverage)))]
fn awproject_incremental_model_deltas(
    previous: &[BTreeMap<(usize, usize), Complex32>],
    current: &[BTreeMap<(usize, usize), Complex32>],
) -> Result<Vec<AwProjectIncrementalModelDelta>, ImagingError> {
    let [previous_tt0, previous_tt1] = previous else {
        return Err(ImagingError::InvalidRequest(format!(
            "incremental AWProject model probe expected two previous terms, got {}",
            previous.len()
        )));
    };
    let [current_tt0, current_tt1] = current else {
        return Err(ImagingError::InvalidRequest(format!(
            "incremental AWProject model probe expected two current terms, got {}",
            current.len()
        )));
    };
    let positions = current_tt0
        .keys()
        .chain(current_tt1.keys())
        .copied()
        .collect::<BTreeSet<_>>();
    let mut deltas = Vec::new();
    for (input_x, input_y) in positions {
        let current_tt0_value = current_tt0
            .get(&(input_x, input_y))
            .copied()
            .unwrap_or_default();
        let current_tt1_value = current_tt1
            .get(&(input_x, input_y))
            .copied()
            .unwrap_or_default();
        let delta_tt0 = current_tt0_value
            - previous_tt0
                .get(&(input_x, input_y))
                .copied()
                .unwrap_or_default();
        let delta_tt1 = current_tt1_value
            - previous_tt1
                .get(&(input_x, input_y))
                .copied()
                .unwrap_or_default();
        if delta_tt0.re.to_bits() != 0.0f32.to_bits()
            || delta_tt0.im.to_bits() != 0.0f32.to_bits()
            || delta_tt1.re.to_bits() != 0.0f32.to_bits()
            || delta_tt1.im.to_bits() != 0.0f32.to_bits()
        {
            deltas.push(AwProjectIncrementalModelDelta {
                input_x,
                input_y,
                tt0: delta_tt0,
                tt1: delta_tt1,
            });
        }
    }
    Ok(deltas)
}

#[cfg(all(target_os = "macos", not(coverage)))]
fn compare_awproject_incremental_model_grids(
    actual: &[Array2<Complex32>],
    reference: &[Array2<Complex32>],
) -> Result<(usize, usize, f64, f64, f64), ImagingError> {
    if actual.len() != reference.len() {
        return Err(ImagingError::Normalization(
            "incremental AWProject model comparison term counts differ".to_string(),
        ));
    }
    let mut values = 0usize;
    let mut different = 0usize;
    let mut error_square_sum = 0.0f64;
    let mut reference_square_sum = 0.0f64;
    let mut max_abs = 0.0f64;
    for (actual_term, reference_term) in actual.iter().zip(reference) {
        if actual_term.dim() != reference_term.dim() {
            return Err(ImagingError::Normalization(
                "incremental AWProject model comparison shapes differ".to_string(),
            ));
        }
        for (&actual_value, &reference_value) in actual_term.iter().zip(reference_term) {
            let exact = actual_value.re.to_bits() == reference_value.re.to_bits()
                && actual_value.im.to_bits() == reference_value.im.to_bits();
            different = different.saturating_add(usize::from(!exact));
            let error = actual_value - reference_value;
            let error_square = f64::from(error.norm_sqr());
            error_square_sum += error_square;
            reference_square_sum += f64::from(reference_value.norm_sqr());
            max_abs = max_abs.max(error_square.sqrt());
            values = values.saturating_add(1);
        }
    }
    let rms = (error_square_sum / values.max(1) as f64).sqrt();
    let relative_rms = (error_square_sum / reference_square_sum.max(f64::MIN_POSITIVE)).sqrt();
    Ok((values, different, rms, relative_rms, max_abs))
}

#[cfg(all(target_os = "macos", not(coverage)))]
fn probe_awproject_incremental_model(
    gridder: &StandardGridder,
    prepared_models: &[(Array2<Complex32>, bool)],
    model_support_positions: &BTreeSet<(usize, usize)>,
    current_model_grids: &[Array2<Complex32>],
    replay_cache: &mut AwProjectCompactReplayCache,
) -> Result<(), ImagingError> {
    let current_values =
        awproject_sparse_prepared_model_values(gridder, prepared_models, model_support_positions)?;
    let max_delta_positions =
        env::var("CASA_RS_EXPERIMENTAL_AWPROJECT_INCREMENTAL_MODEL_MAX_DELTA_POSITIONS")
            .ok()
            .and_then(|value| value.parse::<usize>().ok())
            .unwrap_or(1);
    let Some(mut probe) = replay_cache.incremental_model_probe.take() else {
        replay_cache.incremental_model_probe = Some(AwProjectIncrementalModelProbeCache {
            prepared_values: current_values,
            model_grids: current_model_grids.to_vec(),
            refreshes: 1,
        });
        eprintln!(
            "awproject_incremental_model_probe action=seed refresh=0 support_positions={} \
             max_delta_positions={}",
            model_support_positions.len(),
            max_delta_positions,
        );
        return Ok(());
    };
    let deltas = awproject_incremental_model_deltas(&probe.prepared_values, &current_values)?;
    if deltas.len() > max_delta_positions {
        eprintln!(
            "awproject_incremental_model_probe action=fft-reset refresh={} delta_positions={} \
             support_positions={} max_delta_positions={}",
            probe.refreshes,
            deltas.len(),
            model_support_positions.len(),
            max_delta_positions,
        );
        probe.prepared_values = current_values;
        probe.model_grids = current_model_grids.to_vec();
        probe.refreshes = probe.refreshes.saturating_add(1);
        replay_cache.incremental_model_probe = Some(probe);
        return Ok(());
    }
    let update_elapsed = AWPROJECT_METAL_EXECUTOR.with(|slot| {
        let mut slot = slot.borrow_mut();
        if slot.is_none() {
            *slot = Some(AwProjectMetalExecutor::new()?);
        }
        slot.as_ref()
            .expect("incremental model probe executor")
            .dispatch_incremental_dense_model(&mut probe.model_grids, &deltas)
    })?;
    let compare_started = Instant::now();
    let (values, different, rms, relative_rms, max_abs) =
        compare_awproject_incremental_model_grids(&probe.model_grids, current_model_grids)?;
    let compare_elapsed = compare_started.elapsed();
    eprintln!(
        "awproject_incremental_model_probe action=direct-delta refresh={} delta_positions={} \
         support_positions={} values={} different={} rms={:.9e} relative_rms={:.9e} \
         max_abs={:.9e} update_ms={:.3} compare_ms={:.3}",
        probe.refreshes,
        deltas.len(),
        model_support_positions.len(),
        values,
        different,
        rms,
        relative_rms,
        max_abs,
        profile::millis(update_elapsed),
        profile::millis(compare_elapsed),
    );
    probe.prepared_values = current_values;
    probe.refreshes = probe.refreshes.saturating_add(1);
    replay_cache.incremental_model_probe = Some(probe);
    Ok(())
}

#[cfg(all(target_os = "macos", not(coverage)))]
type AwProjectIncrementalModelRuntime = (
    Option<Vec<Array2<Complex32>>>,
    Option<AwProjectIncrementalModelFullRefresh>,
);

#[cfg(all(target_os = "macos", not(coverage)))]
fn try_awproject_incremental_model_runtime(
    gridder: &StandardGridder,
    prepared_models: &[(Array2<Complex32>, bool)],
    model_support_positions: &BTreeSet<(usize, usize)>,
    replay_cache: &mut AwProjectCompactReplayCache,
) -> Result<AwProjectIncrementalModelRuntime, ImagingError> {
    let current_values =
        awproject_sparse_prepared_model_values(gridder, prepared_models, model_support_positions)?;
    let max_delta_positions =
        env::var("CASA_RS_EXPERIMENTAL_AWPROJECT_INCREMENTAL_MODEL_MAX_DELTA_POSITIONS")
            .ok()
            .and_then(|value| value.parse::<usize>().ok())
            .unwrap_or(1);
    let Some(mut runtime) = replay_cache.incremental_model_probe.take() else {
        return Ok((
            None,
            Some(AwProjectIncrementalModelFullRefresh {
                prepared_values: current_values,
                refresh: 0,
                delta_positions: None,
            }),
        ));
    };
    let deltas = awproject_incremental_model_deltas(&runtime.prepared_values, &current_values)?;
    if deltas.len() > max_delta_positions {
        return Ok((
            None,
            Some(AwProjectIncrementalModelFullRefresh {
                prepared_values: current_values,
                refresh: runtime.refreshes,
                delta_positions: Some(deltas.len()),
            }),
        ));
    }
    let update_elapsed = AWPROJECT_METAL_EXECUTOR.with(|slot| {
        let mut slot = slot.borrow_mut();
        if slot.is_none() {
            *slot = Some(AwProjectMetalExecutor::new()?);
        }
        slot.as_ref()
            .expect("incremental model runtime executor")
            .dispatch_incremental_dense_model(&mut runtime.model_grids, &deltas)
    })?;
    let clone_started = Instant::now();
    let model_grids = runtime.model_grids.clone();
    let clone_elapsed = clone_started.elapsed();
    eprintln!(
        "awproject_incremental_model_runtime action=direct-delta refresh={} \
         delta_positions={} support_positions={} max_delta_positions={} update_ms={:.3} \
         clone_ms={:.3} total_ms={:.3}",
        runtime.refreshes,
        deltas.len(),
        model_support_positions.len(),
        max_delta_positions,
        profile::millis(update_elapsed),
        profile::millis(clone_elapsed),
        profile::millis(update_elapsed + clone_elapsed),
    );
    runtime.prepared_values = current_values;
    runtime.refreshes = runtime.refreshes.saturating_add(1);
    replay_cache.incremental_model_probe = Some(runtime);
    Ok((Some(model_grids), None))
}

#[cfg(all(target_os = "macos", not(coverage)))]
fn finish_awproject_incremental_model_full_refresh(
    replay_cache: &mut AwProjectCompactReplayCache,
    state: AwProjectIncrementalModelFullRefresh,
    model_grids: &[Array2<Complex32>],
    model_support_positions: &BTreeSet<(usize, usize)>,
) {
    let clone_started = Instant::now();
    let cached_grids = model_grids.to_vec();
    let clone_elapsed = clone_started.elapsed();
    eprintln!(
        "awproject_incremental_model_runtime action=fft-reset refresh={} \
         delta_positions={} support_positions={} clone_ms={:.3}",
        state.refresh,
        state
            .delta_positions
            .map_or_else(|| "seed".to_string(), |value| value.to_string()),
        model_support_positions.len(),
        profile::millis(clone_elapsed),
    );
    replay_cache.incremental_model_probe = Some(AwProjectIncrementalModelProbeCache {
        prepared_values: state.prepared_values,
        model_grids: cached_grids,
        refreshes: state.refresh.saturating_add(1),
    });
}

#[cfg(all(target_os = "macos", not(coverage)))]
fn build_awproject_selected_model_dft_cache(
    plan: &AwProjectMetalSelectedModelPlan,
    support_positions: &[(usize, usize)],
) -> Result<AwProjectSelectedModelDftCache, ImagingError> {
    let started = Instant::now();
    let mut active_rows = support_positions
        .iter()
        .map(|&(_, input_y)| input_y)
        .collect::<Vec<_>>();
    active_rows.sort_unstable();
    active_rows.dedup();
    let mut row_offsets = Vec::with_capacity(active_rows.len() + 1);
    row_offsets.push(0u32);
    let mut source_cursor = 0usize;
    for &input_y in &active_rows {
        while source_cursor < support_positions.len()
            && support_positions[source_cursor].1 == input_y
        {
            source_cursor += 1;
        }
        row_offsets.push(u32::try_from(source_cursor).map_err(|_| {
            ImagingError::InvalidRequest(
                "selected AWProject model source offset exceeds u32".to_string(),
            )
        })?);
    }
    if source_cursor != support_positions.len() {
        return Err(ImagingError::Normalization(
            "selected AWProject model sources are not grouped in row order".to_string(),
        ));
    }
    let tau = std::f64::consts::TAU;
    let mut phase_x =
        Vec::with_capacity(support_positions.len().saturating_mul(plan.active_x.len()));
    for &(input_x, _) in support_positions {
        let shifted_input_x = (input_x + plan.grid_width / 2) % plan.grid_width;
        phase_x.extend(plan.active_x.iter().map(|&grid_x| {
            let shifted_frequency = (grid_x as usize + plan.grid_width / 2) % plan.grid_width;
            let angle =
                -tau * (shifted_frequency * shifted_input_x) as f64 / plan.grid_width as f64;
            WProjectMetalComplex {
                re: angle.cos() as f32,
                im: angle.sin() as f32,
            }
        }));
    }
    let mut phase_y = Vec::with_capacity(active_rows.len().saturating_mul(plan.active_y.len()));
    for &input_y in &active_rows {
        let shifted_input_y = (input_y + plan.grid_height / 2) % plan.grid_height;
        phase_y.extend(plan.active_y.iter().map(|&grid_y| {
            let shifted_frequency = (grid_y as usize + plan.grid_height / 2) % plan.grid_height;
            let angle =
                -tau * (shifted_frequency * shifted_input_y) as f64 / plan.grid_height as f64;
            WProjectMetalComplex {
                re: angle.cos() as f32,
                im: angle.sin() as f32,
            }
        }));
    }
    Ok(AwProjectSelectedModelDftCache {
        support_positions: support_positions.to_vec(),
        active_rows,
        row_offsets,
        phase_x,
        phase_y,
        build_elapsed: started.elapsed(),
    })
}

#[cfg(all(target_os = "macos", not(coverage)))]
fn try_awproject_selected_model_dft_runtime(
    gridder: &StandardGridder,
    prepared_models: &[(Array2<Complex32>, bool)],
    model_support_positions: &BTreeSet<(usize, usize)>,
    replay_cache: &mut AwProjectCompactReplayCache,
) -> Result<Option<Vec<Array2<Complex32>>>, ImagingError> {
    let current_values =
        awproject_sparse_prepared_model_values(gridder, prepared_models, model_support_positions)?;
    let [current_tt0, current_tt1] = current_values.as_slice() else {
        return Err(ImagingError::InvalidRequest(format!(
            "selected AWProject model DFT requires two terms, got {}",
            current_values.len()
        )));
    };
    let mut support_positions = current_tt0
        .keys()
        .chain(current_tt1.keys())
        .copied()
        .collect::<BTreeSet<_>>()
        .into_iter()
        .collect::<Vec<_>>();
    support_positions.sort_unstable_by_key(|&(input_x, input_y)| (input_y, input_x));
    let stable_support = replay_cache.selected_model_support == support_positions;
    if !stable_support {
        eprintln!(
            "awproject_selected_model_runtime action=fft-support-refresh previous_positions={} \
             current_positions={}",
            replay_cache.selected_model_support.len(),
            support_positions.len(),
        );
        replay_cache.selected_model_support = support_positions;
        replay_cache.selected_model_dft_cache = None;
        return Ok(None);
    }
    let Some(plan) = replay_cache
        .persistent_metal_global_program
        .as_ref()
        .and_then(|program| program.selected_model_plan.as_ref())
    else {
        eprintln!(
            "awproject_selected_model_runtime action=fft-program-warmup support_positions={}",
            support_positions.len(),
        );
        return Ok(None);
    };
    let rebuild_phase_cache = replay_cache
        .selected_model_dft_cache
        .as_ref()
        .is_none_or(|cache| cache.support_positions != support_positions);
    if rebuild_phase_cache {
        replay_cache.selected_model_dft_cache = Some(build_awproject_selected_model_dft_cache(
            plan,
            &support_positions,
        )?);
    }
    let phase_cache = replay_cache
        .selected_model_dft_cache
        .as_ref()
        .expect("selected model DFT phase cache was initialized");
    let sources = support_positions
        .iter()
        .map(|&(input_x, input_y)| {
            let tt0 = current_tt0
                .get(&(input_x, input_y))
                .copied()
                .unwrap_or_default();
            let tt1 = current_tt1
                .get(&(input_x, input_y))
                .copied()
                .unwrap_or_default();
            AwProjectMetalSelectedModelSource {
                tt0_re: tt0.re,
                tt0_im: tt0.im,
                tt1_re: tt1.re,
                tt1_im: tt1.im,
            }
        })
        .collect::<Vec<_>>();
    let total_started = Instant::now();
    let (grids, dispatch_elapsed) = AWPROJECT_METAL_EXECUTOR.with(|slot| {
        let mut slot = slot.borrow_mut();
        if slot.is_none() {
            *slot = Some(AwProjectMetalExecutor::new()?);
        }
        slot.as_ref()
            .expect("selected model DFT executor")
            .dispatch_selected_model_dft(plan, phase_cache, &sources)
    })?;
    eprintln!(
        "awproject_selected_model_runtime action=selected-dft support_positions={} \
         active_rows={} active_x={} active_y={} selected_cells={} phase_bytes={} \
         phase_build_ms={:.3} rebuilt_phase_cache={} dispatch_ms={:.3} total_ms={:.3}",
        support_positions.len(),
        phase_cache.active_rows.len(),
        plan.active_x.len(),
        plan.active_y.len(),
        plan.cells.len(),
        phase_cache
            .phase_x
            .len()
            .saturating_add(phase_cache.phase_y.len())
            .saturating_mul(std::mem::size_of::<WProjectMetalComplex>()),
        profile::millis(phase_cache.build_elapsed),
        rebuild_phase_cache,
        profile::millis(dispatch_elapsed),
        profile::millis(total_started.elapsed()),
    );
    Ok(Some(grids))
}

#[allow(clippy::too_many_arguments)]
fn cached_mosaic_projector(
    cache: &mut MosaicProjectorCache,
    geometry: ImageGeometry,
    gridder: &StandardGridder,
    phase_center_direction_rad: [f64; 2],
    pointing_direction_rad: [f64; 2],
    primary_beam_model: PrimaryBeamModel,
    frequency_hz: f64,
    conv_sampling: usize,
    screen_power: u8,
    apply_phase_gradient: bool,
) -> Result<ScreenProjector, ImagingError> {
    let key = mosaic_projector_key(primary_beam_model, frequency_hz, screen_power);
    let base = if let Some(projector) = cache.get(&key) {
        projector.clone()
    } else {
        let projector = build_mosaic_projector(
            geometry,
            gridder,
            phase_center_direction_rad,
            phase_center_direction_rad,
            primary_beam_model,
            frequency_hz,
            conv_sampling,
            screen_power,
            false,
        )?;
        cache.insert(key, projector.clone());
        projector
    };
    if !apply_phase_gradient {
        return Ok(base);
    }
    Ok(base
        .clone()
        .with_phase_gradient(mosaic_projector_phase_gradient_rad_per_sample(
            geometry,
            phase_center_direction_rad,
            pointing_direction_rad,
            conv_sampling,
        )))
}

fn mosaic_projector_key(
    primary_beam_model: PrimaryBeamModel,
    frequency_hz: f64,
    screen_power: u8,
) -> MosaicProjectorKey {
    (
        primary_beam_model_key(primary_beam_model),
        mosaic_projector_frequency_key_bits(frequency_hz),
        screen_power,
    )
}

fn mosaic_projector_frequency_key_bits(frequency_hz: f64) -> u64 {
    frequency_hz.to_bits()
}

#[allow(clippy::too_many_arguments)]
fn build_mosaic_projector(
    geometry: ImageGeometry,
    gridder: &StandardGridder,
    phase_center_direction_rad: [f64; 2],
    pointing_direction_rad: [f64; 2],
    primary_beam_model: PrimaryBeamModel,
    frequency_hz: f64,
    conv_sampling: usize,
    screen_power: u8,
    apply_phase_gradient: bool,
) -> Result<ScreenProjector, ImagingError> {
    let conv_size = hetarray_screen_conv_size(geometry);
    let projector = match primary_beam_model {
        PrimaryBeamModel::Airy {
            dish_diameter_m,
            blockage_diameter_m,
        } => {
            let airy_lookup = AiryVoltageLookup::new(dish_diameter_m, blockage_diameter_m);
            ScreenProjector::from_hetarray_screens(
                geometry,
                gridder,
                conv_sampling,
                conv_size,
                |l, m| {
                    let vp = airy_lookup.evaluate_offsets(l, m, frequency_hz);
                    let value = match screen_power {
                        1 => vp,
                        2 => vp * vp,
                        4 => {
                            let pb = vp * vp;
                            pb * pb
                        }
                        _ => unreachable!("unsupported mosaic screen power"),
                    };
                    Complex32::new(value, 0.0)
                },
                |l, m| {
                    let vp = airy_lookup.evaluate_offsets(l, m, frequency_hz);
                    let pb = vp * vp;
                    Complex32::new(pb * pb, 0.0)
                },
            )?
        }
        PrimaryBeamModel::EvlaLBandCommon => ScreenProjector::from_hetarray_screens(
            geometry,
            gridder,
            conv_sampling,
            conv_size,
            |l, m| {
                let vp = primary_beam_voltage_pattern_for_offsets(
                    primary_beam_model,
                    l,
                    m,
                    frequency_hz,
                );
                let value = match screen_power {
                    1 => vp,
                    2 => vp * vp,
                    4 => {
                        let pb = vp * vp;
                        pb * pb
                    }
                    _ => unreachable!("unsupported mosaic screen power"),
                };
                Complex32::new(value, 0.0)
            },
            |l, m| {
                let vp = primary_beam_voltage_pattern_for_offsets(
                    primary_beam_model,
                    l,
                    m,
                    frequency_hz,
                );
                let pb = vp * vp;
                Complex32::new(pb * pb, 0.0)
            },
        )?,
    };
    if !apply_phase_gradient {
        return Ok(projector);
    }
    let projector_sampling = projector.sampling();
    Ok(
        projector.with_phase_gradient(mosaic_projector_phase_gradient_rad_per_sample(
            geometry,
            phase_center_direction_rad,
            pointing_direction_rad,
            projector_sampling,
        )),
    )
}

fn mosaic_projector_phase_gradient_rad_per_sample(
    geometry: ImageGeometry,
    phase_center_direction_rad: [f64; 2],
    pointing_direction_rad: [f64; 2],
    conv_sampling: usize,
) -> [f64; 2] {
    let pixel_offset =
        mosaic_pointing_pixel_offset(geometry, phase_center_direction_rad, pointing_direction_rad);
    mosaic_projector_phase_gradient_rad_per_sample_from_pixel_offset(
        geometry,
        pixel_offset,
        conv_sampling,
    )
}

fn mosaic_projector_phase_gradient_rad_per_sample_for_group(
    geometry: ImageGeometry,
    phase_center_direction_rad: [f64; 2],
    pointing_direction_rad: [f64; 2],
    pointing_pixel_position: Option<[f64; 2]>,
    conv_sampling: usize,
) -> [f64; 2] {
    if env::var_os("CASA_RS_EXPERIMENTAL_AWPROJECT_DISABLE_POINTING_PHASE").is_some() {
        return [0.0, 0.0];
    }
    let pixel_offset = pointing_pixel_position.map_or_else(
        || {
            mosaic_pointing_pixel_offset(
                geometry,
                phase_center_direction_rad,
                pointing_direction_rad,
            )
        },
        |pixel| {
            [
                pixel[0] - geometry.nx() as f64 / 2.0,
                pixel[1] - geometry.ny() as f64 / 2.0,
            ]
        },
    );
    mosaic_projector_phase_gradient_rad_per_sample_from_pixel_offset(
        geometry,
        pixel_offset,
        conv_sampling,
    )
}

fn mosaic_projector_phase_gradient_rad_per_sample_from_pixel_offset(
    geometry: ImageGeometry,
    pixel_offset: [f64; 2],
    conv_sampling: usize,
) -> [f64; 2] {
    // CASA's HetArrayConvFunc applies the pointing phase ramp to the final
    // stored convolution function. MosaicFT passes mosaic.oversampling as
    // convSamp; the HetArray temporary lattice uses internal convSampling=1
    // and is resampled to this stored sampling before rephasing.
    let conv_samp = conv_sampling as f64;
    [
        -pixel_offset[0] * std::f64::consts::TAU / (geometry.nx() as f64 * conv_samp),
        -pixel_offset[1] * std::f64::consts::TAU / (geometry.ny() as f64 * conv_samp),
    ]
}

fn mosaic_projector_sampling(geometry: ImageGeometry) -> usize {
    // CASA's HetArrayConvFunc path uses the `mosaic.oversampling` Aipsrc value,
    // which defaults to 10, after enforcing a minimum of 10.
    let _ = geometry;
    10
}

fn mosaic_pointing_contributes_by_simple_pb_center(
    geometry: ImageGeometry,
    phase_center_direction_rad: [f64; 2],
    pointing_direction_rad: [f64; 2],
) -> bool {
    // CASA's SimplePBConvFunc::addPBToFlux() records PB coverage only when
    // the pointing center converts to a pixel inside the target image. This is
    // intentionally a center-pixel rule, not a PB-wing overlap estimate; an
    // earlier broader estimate admitted far off-image pointings and broke
    // `papersky_mosaic.ms` parity.
    let [pixel_x, pixel_y] = mosaic_pointing_pixel_position(
        geometry,
        phase_center_direction_rad,
        pointing_direction_rad,
    );
    mosaic_pointing_pixel_inside_image(geometry, [pixel_x, pixel_y])
}

fn mosaic_pointing_pixel_inside_image(geometry: ImageGeometry, pixel: [f64; 2]) -> bool {
    pixel[0] >= 0.0
        && pixel[0] < geometry.nx() as f64
        && pixel[1] >= 0.0
        && pixel[1] < geometry.ny() as f64
}

fn mosaic_pointing_pixel_offset(
    geometry: ImageGeometry,
    phase_center_direction_rad: [f64; 2],
    pointing_direction_rad: [f64; 2],
) -> [f64; 2] {
    let [pixel_x, pixel_y] = mosaic_pointing_pixel_position(
        geometry,
        phase_center_direction_rad,
        pointing_direction_rad,
    );
    [
        pixel_x - geometry.nx() as f64 / 2.0,
        pixel_y - geometry.ny() as f64 / 2.0,
    ]
}

fn mosaic_pointing_pixel_position(
    geometry: ImageGeometry,
    phase_center_direction_rad: [f64; 2],
    pointing_direction_rad: [f64; 2],
) -> [f64; 2] {
    let delta_ra =
        circular_angle_delta_rad(pointing_direction_rad[0] - phase_center_direction_rad[0]);
    let dec = pointing_direction_rad[1];
    let dec0 = phase_center_direction_rad[1];
    let l = dec.cos() * delta_ra.sin();
    let m = dec.sin() * dec0.cos() - dec.cos() * dec0.sin() * delta_ra.cos();
    [
        geometry.nx() as f64 / 2.0 - l / geometry.cell_size_rad[0].abs(),
        geometry.ny() as f64 / 2.0 + m / geometry.cell_size_rad[1].abs(),
    ]
}

fn circular_angle_delta_rad(angle_rad: f64) -> f64 {
    (angle_rad + std::f64::consts::PI).rem_euclid(std::f64::consts::TAU) - std::f64::consts::PI
}

/// Build the CASA-compatible image coordinate system for imager output products.
#[allow(clippy::too_many_arguments)]
pub fn build_image_coordinate_system(
    imsize: usize,
    phase_center: [f64; 2],
    cell_arcsec: f64,
    freq_ref: FrequencyRef,
    direction_ref: DirectionRef,
    plane_stokes: PlaneStokes,
    channel_frequencies_hz: &[f64],
    spectral_delta_hz: Option<f64>,
    requested_rest_frequency_hz: Option<f64>,
) -> CoordinateSystem {
    let cell_rad = cell_arcsec * std::f64::consts::PI / (180.0 * 3600.0);
    // CASA's SynthesisParamsImage normalizes the right ascension only when it
    // constructs the image DirectionCoordinate. Keep the observation-info
    // pointing center in the original measure representation, but serialize
    // the image reference longitude in casacore's canonical [0, 2π) range.
    let image_phase_center = [
        phase_center[0].rem_euclid(std::f64::consts::TAU),
        phase_center[1],
    ];
    let mut coords = CoordinateSystem::new();
    coords.add_coordinate(DirectionCoordinate::new(
        direction_ref,
        Projection::new(ProjectionType::SIN),
        image_phase_center,
        [-cell_rad, cell_rad],
        [imsize as f64 / 2.0, imsize as f64 / 2.0],
    ));
    coords.add_coordinate(StokesCoordinate::new(vec![plane_to_stokes_type(
        plane_stokes,
    )]));
    coords.add_coordinate(build_image_spectral_coordinate(
        freq_ref,
        channel_frequencies_hz,
        spectral_delta_hz,
        requested_rest_frequency_hz,
    ));
    coords
}

fn build_image_spectral_coordinate(
    freq_ref: FrequencyRef,
    channel_frequencies_hz: &[f64],
    spectral_delta_hz: Option<f64>,
    requested_rest_frequency_hz: Option<f64>,
) -> SpectralCoordinate {
    let rest_frequency = requested_rest_frequency_hz.unwrap_or_else(|| {
        if channel_frequencies_hz.is_empty() {
            0.0
        } else {
            0.5 * (channel_frequencies_hz[0]
                + channel_frequencies_hz[channel_frequencies_hz.len() - 1])
        }
    });
    match channel_frequencies_hz {
        [] => SpectralCoordinate::new(
            freq_ref,
            0.0,
            spectral_delta_hz.unwrap_or(1.0),
            0.0,
            rest_frequency,
        ),
        [single] => SpectralCoordinate::new(
            freq_ref,
            *single,
            spectral_delta_hz.unwrap_or(1.0),
            0.0,
            rest_frequency,
        ),
        frequencies => {
            let delta = frequencies[1] - frequencies[0];
            let is_linear = frequencies.windows(2).all(|window| {
                let step = window[1] - window[0];
                (step - delta).abs() <= delta.abs().max(1.0) * 1.0e-9
            });
            if is_linear {
                SpectralCoordinate::new(freq_ref, frequencies[0], delta, 0.0, rest_frequency)
            } else {
                SpectralCoordinate::from_tabular(
                    freq_ref,
                    (0..frequencies.len()).map(|index| index as f64).collect(),
                    frequencies.to_vec(),
                    frequencies[0],
                    delta,
                    0.0,
                    rest_frequency,
                )
                .expect("validated channel frequency table")
            }
        }
    }
}

fn plane_to_stokes_type(plane: PlaneStokes) -> StokesType {
    match plane {
        PlaneStokes::I => StokesType::I,
        PlaneStokes::Q => StokesType::Q,
        PlaneStokes::U => StokesType::U,
        PlaneStokes::V => StokesType::V,
        PlaneStokes::XX => StokesType::XX,
        PlaneStokes::YY => StokesType::YY,
        PlaneStokes::RR => StokesType::RR,
        PlaneStokes::LL => StokesType::LL,
    }
}

/// Return the CASA-compatible voltage-pattern value for a homogeneous primary beam.
pub fn primary_beam_voltage_pattern(
    primary_beam_model: PrimaryBeamModel,
    radius_rad: f64,
    frequency_hz: f64,
) -> f32 {
    match primary_beam_model {
        PrimaryBeamModel::Airy {
            dish_diameter_m,
            blockage_diameter_m,
        } => airy_voltage_pattern(
            radius_rad,
            frequency_hz,
            dish_diameter_m,
            blockage_diameter_m,
        ),
        PrimaryBeamModel::EvlaLBandCommon => evla_common_voltage_pattern(radius_rad, frequency_hz),
    }
}

#[derive(Clone, Copy, Debug)]
struct PrimaryBeamProductContext {
    phase_center_direction_rad: [f64; 2],
    primary_beam_model: PrimaryBeamModel,
}

/// Weighted frequency sample used when validating primary-beam product inputs.
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct PrimaryBeamWeightSample {
    /// Sample frequency in Hz.
    pub frequency_hz: f64,
    /// Sample weight.
    pub weight: f32,
}

/// Primary-beam product request.
pub enum PrimaryBeamProductRequest<'a> {
    /// Convert a mosaic weight product into a normalized primary-beam product.
    MosaicFromWeight {
        /// Mosaic weight product.
        weight_product: &'a Array4<f32>,
    },
    /// Build a single-field primary-beam power product using image coordinates.
    SingleField {
        /// Output coordinate system.
        coords: &'a CoordinateSystem,
        /// Output product shape `(nx, ny, nstokes, nchan)`.
        shape: (usize, usize, usize, usize),
        /// Image-channel frequencies in Hz.
        channel_frequencies_hz: &'a [f64],
        /// Phase-center direction used for the primary-beam product, in radians.
        phase_center_direction_rad: [f64; 2],
        /// Primary-beam model used to evaluate the product.
        primary_beam_model: PrimaryBeamModel,
    },
    /// Build a weighted single-field primary-beam product.
    WeightedSingleField {
        /// Output coordinate system.
        coords: &'a CoordinateSystem,
        /// Output product shape `(nx, ny, nstokes, nchan)`.
        shape: (usize, usize, usize, usize),
        /// Image-channel frequencies in Hz.
        channel_frequencies_hz: &'a [f64],
        /// Weighted source samples used to validate the request.
        samples: &'a [PrimaryBeamWeightSample],
        /// Phase-center direction used for the primary-beam product, in radians.
        phase_center_direction_rad: [f64; 2],
        /// Primary-beam model used to evaluate the product.
        primary_beam_model: PrimaryBeamModel,
    },
    /// Build the primary-beam spectral-index correction product.
    Alpha {
        /// Output coordinate system.
        coords: &'a CoordinateSystem,
        /// Output product shape `(nx, ny, nstokes, nchan)`.
        shape: (usize, usize, usize, usize),
        /// Reference frequency in Hz.
        reference_frequency_hz: f64,
        /// Phase-center direction used for the primary-beam product, in radians.
        phase_center_direction_rad: [f64; 2],
        /// Primary-beam model used to evaluate the product.
        primary_beam_model: PrimaryBeamModel,
    },
}

#[derive(Clone, Copy, Debug)]
struct PrimaryBeamPlaneGeometry {
    pointing_x_pixel: f64,
    pointing_y_pixel: f64,
    increment_x_rad: f64,
    increment_y_rad: f64,
}

/// Build a primary-beam product from a compact request.
pub fn primary_beam_product(
    request: PrimaryBeamProductRequest<'_>,
) -> Result<Array4<f32>, ImagingError> {
    match request {
        PrimaryBeamProductRequest::MosaicFromWeight { weight_product } => Ok(
            mosaic_primary_beam_product_from_weight_product(weight_product),
        ),
        PrimaryBeamProductRequest::SingleField {
            coords,
            shape,
            channel_frequencies_hz,
            phase_center_direction_rad,
            primary_beam_model,
        } => single_field_primary_beam_product(
            coords,
            shape,
            channel_frequencies_hz,
            PrimaryBeamProductContext {
                phase_center_direction_rad,
                primary_beam_model,
            },
        ),
        PrimaryBeamProductRequest::WeightedSingleField {
            coords,
            shape,
            channel_frequencies_hz,
            samples,
            phase_center_direction_rad,
            primary_beam_model,
        } => {
            let usable_samples = collapse_primary_beam_weight_samples(samples);
            if usable_samples.is_empty() {
                return Err(ImagingError::InvalidRequest(
                    "weighted primary-beam product requires at least one finite positive weighted sample"
                        .to_string(),
                ));
            }
            single_field_primary_beam_product(
                coords,
                shape,
                channel_frequencies_hz,
                PrimaryBeamProductContext {
                    phase_center_direction_rad,
                    primary_beam_model,
                },
            )
        }
        PrimaryBeamProductRequest::Alpha {
            coords,
            shape,
            reference_frequency_hz,
            phase_center_direction_rad,
            primary_beam_model,
        } => single_field_primary_beam_alpha_product(
            coords,
            shape,
            reference_frequency_hz,
            PrimaryBeamProductContext {
                phase_center_direction_rad,
                primary_beam_model,
            },
        ),
    }
}

fn mosaic_primary_beam_product_from_weight_product(weight_product: &Array4<f32>) -> Array4<f32> {
    let mut pb = Array4::<f32>::zeros(weight_product.dim());
    let (_, _, nstokes, nchan) = weight_product.dim();
    for stokes_index in 0..nstokes {
        for channel_index in 0..nchan {
            let weight_plane = weight_product.slice(s![.., .., stokes_index, channel_index]);
            let peak = weight_plane
                .iter()
                .copied()
                .filter(|value| value.is_finite())
                .fold(0.0f32, f32::max);
            if peak <= 0.0 {
                continue;
            }
            let mut pb_plane = pb.slice_mut(s![.., .., stokes_index, channel_index]);
            Zip::from(&mut pb_plane)
                .and(&weight_plane)
                .for_each(|pb_value, weight_value| {
                    let normalized = (*weight_value).max(0.0) / peak;
                    if normalized.is_finite() && normalized > 0.0 {
                        *pb_value = normalized.sqrt();
                    }
                });
        }
    }
    pb
}

/// Divide an image product by a primary beam above the configured cutoff.
pub fn primary_beam_correct_image_product(
    image: &Array4<f32>,
    pb: &Array4<f32>,
    pb_limit: f32,
) -> Array4<f32> {
    let pb_cutoff = pb_limit.abs();
    let mut corrected = Array4::<f32>::zeros(image.dim());
    Zip::from(&mut corrected).and(image).and(pb).for_each(
        |corrected_value, image_value, pb_value| {
            if pb_value.is_finite() && *pb_value > pb_cutoff {
                *corrected_value = *image_value / *pb_value;
            }
        },
    );
    corrected
}

/// Build a primary-beam support mask using the configured cutoff.
pub fn primary_beam_support_mask_product(pb: &Array4<f32>, pb_limit: f32) -> ArrayD<bool> {
    let pb_cutoff = pb_limit.abs();
    pb.mapv(|value| value.is_finite() && value > pb_cutoff)
        .into_dyn()
}

/// Zero primary-beam samples below the configured cutoff.
pub fn primary_beam_limited_product(pb: &Array4<f32>, pb_limit: f32) -> Array4<f32> {
    let pb_cutoff = pb_limit.abs();
    pb.mapv(|value| {
        if value.is_finite() && value > pb_cutoff {
            value
        } else {
            0.0
        }
    })
}

/// Clean-mask product request.
pub enum CleanMaskProductRequest<'a> {
    /// Repeat one 2-D mask plane across all output channels.
    Plane {
        /// Plane mask in image-pixel order.
        mask: &'a Array2<bool>,
        /// Number of output channels to materialize.
        channel_count: usize,
    },
    /// Convert an already channelized mask cube.
    Cube {
        /// Cube mask in CASA image-product order.
        mask: &'a Array4<bool>,
    },
}

/// Extract the `(x, y)` MFS plane from a CASA-style 4-D image product.
pub fn extract_mfs_plane_product(product: &Array4<f32>) -> Array2<f32> {
    product.slice(s![.., .., 0, 0]).to_owned()
}

/// Expand a single `(x, y)` image plane to a one-Stokes, one-channel product.
pub fn single_plane_image_product(plane: &Array2<f32>) -> Array4<f32> {
    let (nx, ny) = plane.dim();
    let mut product = Array4::<f32>::zeros((nx, ny, 1, 1));
    product.slice_mut(s![.., .., 0, 0]).assign(plane);
    product
}

/// Count true pixels in a 2-D clean mask.
pub fn clean_mask_pixel_count(mask: &Array2<bool>) -> usize {
    mask.iter().filter(|value| **value).count()
}

/// Return the absolute finite masked peak in the MFS plane of a 4-D product.
pub fn mfs_image_product_peak_abs_masked(
    product: &Array4<f32>,
    clean_mask: Option<&Array2<bool>>,
    relative_tolerance: f32,
) -> f32 {
    let plane = extract_mfs_plane_product(product);
    clean_peak_location_masked_with_relative_tolerance(&plane, clean_mask, relative_tolerance)
        .map(|(_, value)| value.abs())
        .unwrap_or(0.0)
}

/// Build the CASA-style floating clean-mask product.
pub fn clean_mask_image_product(request: CleanMaskProductRequest<'_>) -> Array4<f32> {
    match request {
        CleanMaskProductRequest::Plane {
            mask,
            channel_count,
        } => {
            let channel_count = channel_count.max(1);
            let (nx, ny) = mask.dim();
            let mut product = Array4::<f32>::zeros((nx, ny, 1, channel_count));
            for channel_index in 0..channel_count {
                for x in 0..nx {
                    for y in 0..ny {
                        product[(x, y, 0, channel_index)] = if mask[(x, y)] { 1.0 } else { 0.0 };
                    }
                }
            }
            product
        }
        CleanMaskProductRequest::Cube { mask } => mask.mapv(|value| if value { 1.0 } else { 0.0 }),
    }
}

/// Build primary-beam side products for one image product.
///
/// Returns `(limited_pb, support_mask, image_pbcor)`.
pub fn primary_beam_output_products(
    image: Option<&Array4<f32>>,
    pb: &Array4<f32>,
    pb_limit: f32,
    include_image_pbcor: bool,
) -> (Array4<f32>, ArrayD<bool>, Option<Array4<f32>>) {
    let limited_pb = primary_beam_limited_product(pb, pb_limit);
    let support_mask = primary_beam_support_mask_product(pb, pb_limit);
    let image_pbcor = if include_image_pbcor {
        image.map(|image| primary_beam_correct_image_product(image, pb, pb_limit))
    } else {
        None
    };
    (limited_pb, support_mask, image_pbcor)
}

/// Apply CASA-style primary-beam spectral-index correction.
pub fn primary_beam_correct_alpha_product(
    alpha: &Array4<f32>,
    pb_alpha: &Array4<f32>,
    pb: &Array4<f32>,
    pb_limit: f32,
) -> Array4<f32> {
    let pb_cutoff = pb_limit.abs();
    let mut corrected_alpha = alpha.clone();
    Zip::from(&mut corrected_alpha)
        .and(pb_alpha)
        .and(pb)
        .for_each(|alpha_value, pb_alpha_value, pb_value| {
            if pb_value.is_finite() && *pb_value > pb_cutoff {
                *alpha_value -= *pb_alpha_value;
            } else {
                *alpha_value = 0.0;
            }
        });
    corrected_alpha
}

fn primary_beam_plane_geometry(
    coords: &CoordinateSystem,
    context: PrimaryBeamProductContext,
) -> Result<PrimaryBeamPlaneGeometry, ImagingError> {
    let mut pixel_axis_offset = 0usize;
    let mut direction_coordinate_index = None;
    for coordinate_index in 0..coords.n_coordinates() {
        let coordinate = coords.coordinate(coordinate_index);
        if coordinate.coordinate_type() == CoordinateType::Direction {
            direction_coordinate_index = Some((coordinate_index, pixel_axis_offset));
            break;
        }
        pixel_axis_offset += coordinate.n_pixel_axes();
    }
    let (direction_coordinate_index, pixel_axis_offset) =
        direction_coordinate_index.ok_or_else(|| {
            ImagingError::InvalidRequest(
                "primary-beam product requires a direction coordinate".to_string(),
            )
        })?;
    if pixel_axis_offset != 0 {
        return Err(ImagingError::InvalidRequest(
            "primary-beam product requires direction pixel axes first".to_string(),
        ));
    }
    let direction_coordinate = coords.coordinate(direction_coordinate_index);
    let pointing_pixel = direction_coordinate
        .to_pixel(&context.phase_center_direction_rad)
        .map_err(|error| {
            ImagingError::InvalidRequest(format!("convert PB pointing direction to pixel: {error}"))
        })?;
    let increments = direction_coordinate.increment();
    if pointing_pixel.len() < 2 || increments.len() < 2 {
        return Err(ImagingError::InvalidRequest(
            "primary-beam direction coordinate must have two axes".to_string(),
        ));
    }
    Ok(PrimaryBeamPlaneGeometry {
        pointing_x_pixel: pointing_pixel[0],
        pointing_y_pixel: pointing_pixel[1],
        increment_x_rad: increments[0],
        increment_y_rad: increments[1],
    })
}

fn primary_beam_radius_rad_from_plane(
    geometry: PrimaryBeamPlaneGeometry,
    x: usize,
    y: usize,
) -> f64 {
    let dx = geometry.increment_x_rad * (x as f64 - geometry.pointing_x_pixel);
    let dy = geometry.increment_y_rad * (y as f64 - geometry.pointing_y_pixel);
    (dx * dx + dy * dy).sqrt()
}

fn single_field_primary_beam_product(
    coords: &CoordinateSystem,
    shape: (usize, usize, usize, usize),
    channel_frequencies_hz: &[f64],
    context: PrimaryBeamProductContext,
) -> Result<Array4<f32>, ImagingError> {
    let (nx, ny, nstokes, nchan) = shape;
    let mut pb = Array4::<f32>::zeros(shape);
    let pixel_axis_count = coords.n_pixel_axes();
    if pixel_axis_count < 2 {
        return Err(ImagingError::InvalidRequest(
            "primary-beam product requires at least two direction pixel axes".to_string(),
        ));
    }
    let plane_geometry = primary_beam_plane_geometry(coords, context)?;
    let fallback_frequency_hz = channel_frequencies_hz
        .iter()
        .copied()
        .find(|frequency_hz| frequency_hz.is_finite() && *frequency_hz > 0.0)
        .ok_or_else(|| {
            ImagingError::InvalidRequest(
                "primary-beam product requires a finite positive image frequency".to_string(),
            )
        })?;
    for channel_index in 0..nchan {
        let frequency_hz = channel_frequencies_hz
            .get(channel_index)
            .copied()
            .filter(|frequency_hz| frequency_hz.is_finite() && *frequency_hz > 0.0)
            .unwrap_or(fallback_frequency_hz);
        for x in 0..nx {
            for y in 0..ny {
                let radius_rad = primary_beam_radius_rad_from_plane(plane_geometry, x, y);
                let value = primary_beam_voltage_pattern(
                    context.primary_beam_model,
                    radius_rad,
                    frequency_hz,
                );
                let value = value * value;
                for stokes_index in 0..nstokes {
                    pb[(x, y, stokes_index, channel_index)] = value;
                }
            }
        }
    }
    Ok(pb)
}

fn collapse_primary_beam_weight_samples(
    samples: &[PrimaryBeamWeightSample],
) -> Vec<PrimaryBeamWeightSample> {
    const CASA_PB_FREQUENCY_BIN_FRACTION: f64 = 0.005;
    let log_bin_width = (1.0 + CASA_PB_FREQUENCY_BIN_FRACTION).ln();
    let mut by_frequency_bin = BTreeMap::<i64, (f64, f64)>::new();
    for sample in samples {
        if !(sample.frequency_hz.is_finite()
            && sample.frequency_hz > 0.0
            && sample.weight.is_finite()
            && sample.weight > 0.0)
        {
            continue;
        }
        let key = (sample.frequency_hz.ln() / log_bin_width).round() as i64;
        let weight = f64::from(sample.weight);
        let entry = by_frequency_bin.entry(key).or_insert((0.0, 0.0));
        entry.0 += sample.frequency_hz * weight;
        entry.1 += weight;
    }
    by_frequency_bin
        .into_values()
        .filter_map(|(weighted_frequency_sum, weight)| {
            (weight.is_finite() && weight > 0.0).then_some(PrimaryBeamWeightSample {
                frequency_hz: weighted_frequency_sum / weight,
                weight: weight as f32,
            })
        })
        .collect()
}

#[cfg(test)]
fn normalized_weighted_primary_beam_product(
    coords: &CoordinateSystem,
    shape: (usize, usize, usize, usize),
    samples: &[PrimaryBeamWeightSample],
    context: PrimaryBeamProductContext,
) -> Result<Array4<f32>, ImagingError> {
    let usable_samples = collapse_primary_beam_weight_samples(samples);
    if usable_samples.is_empty() {
        return Err(ImagingError::InvalidRequest(
            "weighted primary-beam product requires at least one finite positive weighted sample"
                .to_string(),
        ));
    }

    let (nx, ny, nstokes, nchan) = shape;
    let mut pb = Array4::<f32>::zeros(shape);
    let pixel_axis_count = coords.n_pixel_axes();
    if pixel_axis_count < 2 {
        return Err(ImagingError::InvalidRequest(
            "primary-beam product requires at least two direction pixel axes".to_string(),
        ));
    }
    let total_weight = usable_samples
        .iter()
        .map(|sample| f64::from(sample.weight))
        .sum::<f64>();
    if !(total_weight.is_finite() && total_weight > 0.0) {
        return Err(ImagingError::InvalidRequest(
            "weighted primary-beam product has non-positive total weight".to_string(),
        ));
    }

    let plane_geometry = primary_beam_plane_geometry(coords, context)?;
    let mut peak = 0.0f32;
    for channel_index in 0..nchan {
        for x in 0..nx {
            for y in 0..ny {
                let radius_rad = primary_beam_radius_rad_from_plane(plane_geometry, x, y);
                let weighted_power = usable_samples
                    .iter()
                    .map(|sample| {
                        let voltage = primary_beam_voltage_pattern(
                            context.primary_beam_model,
                            radius_rad,
                            sample.frequency_hz,
                        ) as f64;
                        f64::from(sample.weight) * voltage * voltage
                    })
                    .sum::<f64>();
                let value = (weighted_power / total_weight).max(0.0).sqrt() as f32;
                peak = peak.max(value);
                for stokes_index in 0..nstokes {
                    pb[(x, y, stokes_index, channel_index)] = value;
                }
            }
        }
    }
    if peak > 0.0 {
        pb.mapv_inplace(|value| value / peak);
    }
    Ok(pb)
}

fn single_field_primary_beam_alpha_product(
    coords: &CoordinateSystem,
    shape: (usize, usize, usize, usize),
    reference_frequency_hz: f64,
    context: PrimaryBeamProductContext,
) -> Result<Array4<f32>, ImagingError> {
    if !(reference_frequency_hz.is_finite() && reference_frequency_hz > 0.0) {
        return Err(ImagingError::InvalidRequest(
            "primary-beam alpha product requires a finite positive reference frequency".to_string(),
        ));
    }
    let lower_frequency_hz = reference_frequency_hz * 0.995;
    let upper_frequency_hz = reference_frequency_hz * 1.005;
    let log_frequency_ratio = (upper_frequency_hz / lower_frequency_hz).ln();
    let lower = single_field_primary_beam_product(coords, shape, &[lower_frequency_hz], context)?;
    let upper = single_field_primary_beam_product(coords, shape, &[upper_frequency_hz], context)?;
    let mut alpha = Array4::<f32>::zeros(shape);
    Zip::from(&mut alpha).and(&lower).and(&upper).for_each(
        |alpha_value, lower_value, upper_value| {
            if *lower_value > 0.0 && *upper_value > 0.0 {
                *alpha_value =
                    ((*upper_value as f64 / *lower_value as f64).ln() / log_frequency_ratio) as f32;
            }
        },
    );
    Ok(alpha)
}

fn primary_beam_voltage_pattern_for_offsets(
    primary_beam_model: PrimaryBeamModel,
    l_rad: f64,
    m_rad: f64,
    frequency_hz: f64,
) -> f32 {
    match primary_beam_model {
        PrimaryBeamModel::Airy {
            dish_diameter_m,
            blockage_diameter_m,
        } => airy_voltage_pattern_for_offsets(
            l_rad,
            m_rad,
            frequency_hz,
            dish_diameter_m,
            blockage_diameter_m,
        ),
        PrimaryBeamModel::EvlaLBandCommon => {
            let radius_rad = (l_rad * l_rad + m_rad * m_rad).sqrt();
            evla_common_voltage_pattern(radius_rad, frequency_hz)
        }
    }
}

fn airy_voltage_pattern(
    radius_rad: f64,
    frequency_hz: f64,
    dish_diameter_m: f64,
    blockage_diameter_m: f64,
) -> f32 {
    if !(radius_rad.is_finite()
        && radius_rad >= 0.0
        && frequency_hz.is_finite()
        && frequency_hz > 0.0)
    {
        return 0.0;
    }
    // CASA PBMath1D stores per-pixel radius terms as Float before looking up
    // the tabulated voltage pattern.
    let radius_arcmin_ghz = (radius_rad.to_degrees() * 60.0 * (frequency_hz / 1.0e9)) as f32 as f64;
    airy_voltage_pattern_from_arcmin_ghz(radius_arcmin_ghz, dish_diameter_m, blockage_diameter_m)
}

fn airy_voltage_pattern_for_offsets(
    l_rad: f64,
    m_rad: f64,
    frequency_hz: f64,
    dish_diameter_m: f64,
    blockage_diameter_m: f64,
) -> f32 {
    if !(l_rad.is_finite() && m_rad.is_finite() && frequency_hz.is_finite() && frequency_hz > 0.0) {
        return 0.0;
    }
    let l_deg = l_rad.to_degrees() as f32;
    let m_deg = m_rad.to_degrees() as f32;
    let radius_deg = (l_deg * l_deg + m_deg * m_deg).sqrt();
    let radius_arcmin_ghz = (f64::from(radius_deg) * 60.0 * (frequency_hz / 1.0e9)) as f32 as f64;
    airy_voltage_pattern_from_arcmin_ghz(radius_arcmin_ghz, dish_diameter_m, blockage_diameter_m)
}

#[derive(Clone)]
struct AiryVoltageLookup {
    maximum_radius_arcmin_ghz: f64,
    values: Vec<f32>,
}

impl AiryVoltageLookup {
    fn new(dish_diameter_m: f64, blockage_diameter_m: f64) -> Self {
        let maximum_radius_arcmin_ghz =
            casa_airy_max_radius_arcmin_ghz(dish_diameter_m, blockage_diameter_m);
        Self::new_with_maximum_radius(
            maximum_radius_arcmin_ghz,
            dish_diameter_m,
            blockage_diameter_m,
        )
    }

    fn new_with_maximum_radius(
        maximum_radius_arcmin_ghz: f64,
        dish_diameter_m: f64,
        blockage_diameter_m: f64,
    ) -> Self {
        let sample_count_minus_one = 9_999.0;
        let values = (0..=sample_count_minus_one as usize)
            .map(|index| {
                airy_voltage_pattern_from_table_index(
                    index as f64,
                    maximum_radius_arcmin_ghz,
                    dish_diameter_m,
                    blockage_diameter_m,
                )
            })
            .collect();
        Self {
            maximum_radius_arcmin_ghz,
            values,
        }
    }

    fn evaluate_offsets(&self, l_rad: f64, m_rad: f64, frequency_hz: f64) -> f32 {
        if !(l_rad.is_finite()
            && m_rad.is_finite()
            && frequency_hz.is_finite()
            && frequency_hz > 0.0)
        {
            return 0.0;
        }
        let l_deg = l_rad.to_degrees() as f32;
        let m_deg = m_rad.to_degrees() as f32;
        let radius_deg = (l_deg * l_deg + m_deg * m_deg).sqrt();
        let radius_arcmin_ghz =
            (f64::from(radius_deg) * 60.0 * (frequency_hz / 1.0e9)) as f32 as f64;
        if radius_arcmin_ghz > self.maximum_radius_arcmin_ghz {
            return 0.0;
        }
        let sample_count_minus_one = (self.values.len() - 1) as f64;
        let index = (radius_arcmin_ghz * sample_count_minus_one / self.maximum_radius_arcmin_ghz)
            .floor()
            .clamp(0.0, sample_count_minus_one) as usize;
        self.values[index]
    }
}

fn airy_voltage_pattern_from_arcmin_ghz(
    radius_arcmin_ghz: f64,
    dish_diameter_m: f64,
    blockage_diameter_m: f64,
) -> f32 {
    let maximum_radius_arcmin_ghz =
        casa_airy_max_radius_arcmin_ghz(dish_diameter_m, blockage_diameter_m);
    if radius_arcmin_ghz > maximum_radius_arcmin_ghz {
        return 0.0;
    }
    let sample_count_minus_one = 9_999.0;
    let index = (radius_arcmin_ghz * sample_count_minus_one / maximum_radius_arcmin_ghz)
        .floor()
        .clamp(0.0, sample_count_minus_one);
    airy_voltage_pattern_from_table_index(
        index,
        maximum_radius_arcmin_ghz,
        dish_diameter_m,
        blockage_diameter_m,
    )
}

fn airy_voltage_pattern_from_table_index(
    index: f64,
    maximum_radius_arcmin_ghz: f64,
    dish_diameter_m: f64,
    blockage_diameter_m: f64,
) -> f32 {
    let sample_count_minus_one = 9_999.0;
    let dimensionless_max_radius =
        maximum_radius_arcmin_ghz * 7.016 / (1.566 * 60.0) * dish_diameter_m / 24.5;
    let x = index * dimensionless_max_radius / sample_count_minus_one;
    if x.abs() <= f64::EPSILON {
        return 1.0;
    }
    if blockage_diameter_m <= 0.0 {
        return (2.0 * j1(x) / x) as f32;
    }
    let area_ratio = (dish_diameter_m / blockage_diameter_m).powi(2);
    let area_norm = area_ratio - 1.0;
    let length_ratio = dish_diameter_m / blockage_diameter_m;
    ((area_ratio * 2.0 * j1(x) / x - 2.0 * j1(x * length_ratio) / (x * length_ratio)) / area_norm)
        as f32
}

fn primary_beam_max_radius_arcsec_at_100ghz(primary_beam_model: PrimaryBeamModel) -> Option<f64> {
    match primary_beam_model {
        PrimaryBeamModel::Airy {
            dish_diameter_m,
            blockage_diameter_m,
        } => Some(
            casa_airy_max_radius_arcmin_ghz(dish_diameter_m, blockage_diameter_m) * 60.0 / 100.0,
        ),
        PrimaryBeamModel::EvlaLBandCommon => Some(58.0 * 60.0 / 100.0),
    }
}

fn casa_airy_max_radius_arcmin_ghz(dish_diameter_m: f64, blockage_diameter_m: f64) -> f64 {
    if approx_eq(dish_diameter_m, 10.7, 1.0e-6) && approx_eq(blockage_diameter_m, 0.75, 1.0e-6) {
        // CASA's HetArrayConvFunc ALMA 12m override builds PBMath1DAiry with
        // support=max(150 arcsec, fov/5) at 100 GHz for typical Wave 3 images.
        250.0
    } else if approx_eq(dish_diameter_m, 6.25, 1.0e-6)
        && approx_eq(blockage_diameter_m, 0.75, 1.0e-6)
    {
        // CASA's ACA override uses support=max(300 arcsec, fov/3) at 100 GHz.
        500.0
    } else {
        1.784 * 60.0
    }
}

fn approx_eq(left: f64, right: f64, tolerance: f64) -> bool {
    (left - right).abs() <= tolerance
}

fn evla_common_voltage_pattern(radius_rad: f64, frequency_hz: f64) -> f32 {
    if !(radius_rad.is_finite()
        && radius_rad >= 0.0
        && frequency_hz.is_finite()
        && frequency_hz > 0.0)
    {
        return 0.0;
    }
    // Mirror CASA PBMath1DEVLA::nearestVPArray(), PBMath1DPoly::fillPBArray(),
    // and PBMath1D::apply(): CASA samples 10,000 voltage-pattern entries and
    // then uses integer-truncated radial lookup when applying the image PB.
    let coefficients = nearest_evla_common_coefficients(frequency_hz * 1.0e-6);
    let radius_arcmin_ghz = radius_rad.to_degrees() * 60.0 * (frequency_hz / 1.0e9);
    if radius_arcmin_ghz > 58.0 {
        return 0.0;
    }
    let inverse_increment_radius = 9_999.0 / 58.0;
    let sample_index = (radius_arcmin_ghz * inverse_increment_radius).floor();
    let sampled_radius_arcmin_ghz = sample_index / inverse_increment_radius;
    let x2 = sampled_radius_arcmin_ghz * sampled_radius_arcmin_ghz;
    let mut taper = 0.0f64;
    let mut power = 1.0f64;
    for coefficient in coefficients {
        taper += coefficient * power;
        power *= x2;
    }
    if taper <= 0.0 {
        0.0
    } else {
        taper.sqrt() as f32
    }
}

fn nearest_evla_common_coefficients(frequency_mhz: f64) -> [f64; 4] {
    let (clamped_frequency_mhz, coefficients) = if (3990.0..=8001.0).contains(&frequency_mhz) {
        (
            frequency_mhz.clamp(4052.0, 7948.0),
            EVLA_C_BAND_COEFFICIENTS,
        )
    } else {
        (
            frequency_mhz.clamp(1040.0, 2000.0),
            EVLA_L_BAND_COEFFICIENTS,
        )
    };
    let mut best = coefficients[0].1;
    let mut best_delta_mhz = f64::INFINITY;
    for &(candidate_frequency_mhz, candidate_coefficients) in coefficients {
        let delta_mhz = (clamped_frequency_mhz - candidate_frequency_mhz).abs();
        if delta_mhz < best_delta_mhz {
            best_delta_mhz = delta_mhz;
            best = candidate_coefficients;
        }
    }
    best
}

