#[allow(clippy::too_many_arguments)]
#[cfg(all(target_os = "macos", not(coverage)))]
fn run_hogbom_minor_cycle_metal_with_progress(
    request: &ImagingRequest,
    psf_state: &PsfState,
    model: &mut Array2<f32>,
    residual: &mut Array2<f32>,
    cycle_reported_niter: usize,
    cycle_threshold_jy_per_beam: f32,
    nsigma_threshold_jy_per_beam: f32,
    stage_timings: &mut ImagingStageTimings,
    minor_progress: &mut StandardMfsMinorCycleProgressReporter<'_>,
) -> Result<HogbomMinorCycleOutcome, ImagingError> {
    use std::{mem, slice};

    use objc2_metal::{MTLBuffer, MTLCreateSystemDefaultDevice, MTLDevice, MTLResourceOptions};

    let (nx, ny) = residual.dim();
    if nx == 0 || ny == 0 {
        return Ok(HogbomMinorCycleOutcome {
            updated_model: false,
            actual_updates: 0,
            reported_updates: 0,
            stop_reason: Some(CleanStopReason::NoCleanablePixels),
            final_cycle_threshold_jy_per_beam: cycle_threshold_jy_per_beam,
            final_nsigma_threshold_jy_per_beam: nsigma_threshold_jy_per_beam,
        });
    }
    if psf_state.psf.dim() != (nx, ny) {
        return Err(ImagingError::InvalidRequest(
            "Hogbom Metal minor cycle requires residual and PSF shapes to match".to_string(),
        ));
    }
    if let Some(mask) = request.clean_mask.as_ref()
        && mask.dim() != (nx, ny)
    {
        return Err(ImagingError::InvalidRequest(
            "Hogbom Metal minor cycle requires clean-mask and residual shapes to match".to_string(),
        ));
    }
    let cell_count = nx
        .checked_mul(ny)
        .ok_or_else(|| ImagingError::InvalidRequest("Hogbom image is too large".to_string()))?;
    let cell_count_u32 = u32::try_from(cell_count).map_err(|_| {
        ImagingError::InvalidRequest("Hogbom Metal image cell count exceeds u32".to_string())
    })?;
    let nx_u32 = u32::try_from(nx).map_err(|_| {
        ImagingError::InvalidRequest("Hogbom Metal image width exceeds u32".to_string())
    })?;
    let ny_u32 = u32::try_from(ny).map_err(|_| {
        ImagingError::InvalidRequest("Hogbom Metal image height exceeds u32".to_string())
    })?;

    let total_started = Instant::now();
    let collect_profile = profile::standard_mfs_profile_detail_enabled();
    let verify_cpu = env::var_os("CASA_RS_HOGBOM_METAL_VERIFY_CPU").is_some();
    let setup_started = Instant::now();
    let cpu_reference_peak = collect_profile
        .then(|| hclean_peak_location_masked(residual, request.clean_mask.as_ref()))
        .flatten();
    let (cpu_reference_peak_abs, cpu_reference_peak_x, cpu_reference_peak_y) = cpu_reference_peak
        .map(|((x, y), value)| (value.abs(), x, y))
        .unwrap_or((0.0, 0, 0));
    let clean_mask = clean_mask_summary(request.clean_mask.as_ref(), (nx, ny));
    let residual_values = hogbom_flatten_array2_x_major(residual);
    let psf_values = hogbom_flatten_array2_x_major(&psf_state.psf);
    let mask_values = request.clean_mask.as_ref().map(|mask| {
        let (mask_nx, mask_ny) = mask.dim();
        let mut values = Vec::with_capacity(mask_nx.saturating_mul(mask_ny));
        for x in 0..mask_nx {
            for y in 0..mask_ny {
                values.push(u32::from(mask[(x, y)]));
            }
        }
        values
    });
    let cpu_verify_inputs = verify_cpu.then(|| (model.clone(), residual.clone()));
    let setup_elapsed = setup_started.elapsed();

    let device_queue_started = Instant::now();
    let device = MTLCreateSystemDefaultDevice().ok_or_else(|| {
        ImagingError::Unsupported(
            "Hogbom minor-cycle backend 'metal' could not find a default Metal device".to_string(),
        )
    })?;
    let queue = device.newCommandQueue().ok_or_else(|| {
        ImagingError::Unsupported(
            "Hogbom minor-cycle backend 'metal' could not create a Metal command queue".to_string(),
        )
    })?;
    let device_queue_elapsed = device_queue_started.elapsed();
    let shader_compile_started = Instant::now();
    let source = objc2_foundation::NSString::from_str(HOGBOM_MINOR_CYCLE_METAL_SHADER);
    let library = device
        .newLibraryWithSource_options_error(&source, None)
        .map_err(|error| {
            ImagingError::Unsupported(format!(
                "Hogbom minor-cycle backend 'metal' failed to compile shader: {error:?}"
            ))
        })?;
    let shader_compile_elapsed = shader_compile_started.elapsed();
    let pipeline_started = Instant::now();
    let peak_pipeline = hogbom_metal_pipeline(&device, &library, "hogbom_peak_reduce_pixels")?;
    let reduce_pipeline = hogbom_metal_pipeline(&device, &library, "hogbom_reduce_candidates")?;
    let select_pipeline =
        hogbom_metal_pipeline(&device, &library, "hogbom_select_peak_from_candidate")?;
    let subtract_peak_pipeline =
        hogbom_metal_pipeline(&device, &library, "hogbom_subtract_psf_and_find_next_peak")?;
    let pipeline_elapsed = pipeline_started.elapsed();

    let storage_options = MTLResourceOptions::StorageModeShared;
    let buffer_started = Instant::now();
    let residual_buffer = hogbom_metal_buffer_from_slice(
        &device,
        residual_values.as_slice(),
        storage_options,
        "residual",
    )?;
    let model_values = hogbom_flatten_array2_x_major(model);
    let model_buffer =
        hogbom_metal_buffer_from_slice(&device, model_values.as_slice(), storage_options, "model")?;
    let psf_buffer =
        hogbom_metal_buffer_from_slice(&device, psf_values.as_slice(), storage_options, "psf")?;
    let mask_storage = mask_values.unwrap_or_else(|| vec![0u32]);
    let mask_buffer =
        hogbom_metal_buffer_from_slice(&device, mask_storage.as_slice(), storage_options, "mask")?;
    let peak_threads_per_group = hogbom_metal_threads_per_group(&peak_pipeline, cell_count);
    let first_candidate_count = cell_count.div_ceil(peak_threads_per_group);
    let candidate_bytes = first_candidate_count
        .max(1)
        .checked_mul(mem::size_of::<HogbomMetalPeakCandidate>())
        .ok_or_else(|| {
            ImagingError::InvalidRequest("Hogbom Metal candidate buffer is too large".to_string())
        })?;
    let candidate_a = device
        .newBufferWithLength_options(candidate_bytes, storage_options)
        .ok_or_else(|| {
            ImagingError::Unsupported(
                "Hogbom minor-cycle backend 'metal' could not allocate candidate buffer"
                    .to_string(),
            )
        })?;
    let candidate_b = device
        .newBufferWithLength_options(candidate_bytes, storage_options)
        .ok_or_else(|| {
            ImagingError::Unsupported(
                "Hogbom minor-cycle backend 'metal' could not allocate reduction buffer"
                    .to_string(),
            )
        })?;
    let selected_peak_buffer = hogbom_metal_buffer_from_slice(
        &device,
        &[HogbomMetalPeakCandidate::default()],
        storage_options,
        "selected peak",
    )?;
    let buffer_elapsed = buffer_started.elapsed();

    let cycle_component_budget = hogbom_component_budget(cycle_reported_niter, request.clean);
    let cycle_component_budget_u32 = u32::try_from(cycle_component_budget).map_err(|_| {
        ImagingError::InvalidRequest("Hogbom Metal component budget exceeds u32".to_string())
    })?;
    let mut readback_elapsed = Duration::ZERO;
    let peak_threads_per_group_u32 = u32::try_from(peak_threads_per_group).map_err(|_| {
        ImagingError::InvalidRequest("Hogbom Metal peak threadgroup width exceeds u32".to_string())
    })?;
    let cycle_params = HogbomMetalCycleParams {
        cell_count: cell_count_u32,
        nx: nx_u32,
        ny: ny_u32,
        has_mask: u32::from(request.clean_mask.is_some()),
        peak_threads_per_group: peak_threads_per_group_u32,
        component_budget: cycle_component_budget_u32,
        gain: request.clean.gain,
        threshold_jy_per_beam: request.clean.threshold_jy_per_beam,
        cycle_threshold_jy_per_beam,
        nsigma_threshold_jy_per_beam,
        trace_components: u32::from(env::var_os("CASA_RS_HOGBOM_TRACE").is_some()),
        _pad0: 0,
    };
    let trace_storage = vec![
        HogbomMetalComponentTrace::default();
        if cycle_params.trace_components != 0 {
            cycle_component_budget.max(1)
        } else {
            1
        }
    ];
    let trace_buffer = hogbom_metal_buffer_from_slice(
        &device,
        trace_storage.as_slice(),
        storage_options,
        "component trace",
    )?;
    let cycle_started = Instant::now();
    let (
        cycle_state,
        cycle_timing,
        peak_dispatches,
        reduce_dispatches,
        select_dispatches,
        subtract_peak_dispatches,
    ) = hogbom_metal_run_resident_cycle(
        &queue,
        &device,
        &peak_pipeline,
        &reduce_pipeline,
        &select_pipeline,
        &subtract_peak_pipeline,
        &residual_buffer,
        &model_buffer,
        &psf_buffer,
        &mask_buffer,
        &candidate_a,
        &candidate_b,
        &selected_peak_buffer,
        &trace_buffer,
        storage_options,
        cycle_params,
        first_candidate_count,
    )?;
    let cycle_elapsed = cycle_started.elapsed();
    let cycle_component_updates = usize::try_from(cycle_state.updates).map_err(|_| {
        ImagingError::InvalidRequest("Hogbom Metal update count overflowed".to_string())
    })?;
    let updated_model = cycle_component_updates > 0;
    let stop_reason = hogbom_metal_stop_reason(cycle_state.stop_reason);
    let peak_searches = cycle_component_budget;
    let subtract_updates = cycle_component_updates;
    let command_buffers = 1usize;
    let last_peak_abs = cycle_state.peak.abs_value;
    let last_peak_value = cycle_state.peak.value;
    let last_peak_index = cycle_state.peak.flat_index;
    minor_progress.emit(cycle_component_updates, Some(last_peak_abs));

    let readback_started = Instant::now();
    let residual_slice = unsafe {
        slice::from_raw_parts(
            residual_buffer.contents().as_ptr().cast::<f32>(),
            cell_count,
        )
    };
    copy_x_major_slice_to_array2(residual, residual_slice)?;
    let model_slice = unsafe {
        slice::from_raw_parts(model_buffer.contents().as_ptr().cast::<f32>(), cell_count)
    };
    copy_x_major_slice_to_array2(model, model_slice)?;
    readback_elapsed += readback_started.elapsed();
    if cycle_params.trace_components != 0 {
        let trace_slice = unsafe {
            slice::from_raw_parts(
                trace_buffer
                    .contents()
                    .as_ptr()
                    .cast::<HogbomMetalComponentTrace>(),
                trace_storage.len(),
            )
        };
        for trace in trace_slice.iter().take(cycle_component_updates) {
            let x = usize::try_from(trace.flat_index)
                .ok()
                .map(|flat| flat / ny)
                .unwrap_or(0);
            let y = usize::try_from(trace.flat_index)
                .ok()
                .map(|flat| flat % ny)
                .unwrap_or(0);
            append_hogbom_trace(format!(
                "{{\"event\":\"component\",\"backend\":\"metal\",\"reffreq_hz\":{:.17e},\"cycle_update\":{},\"x\":{},\"y\":{},\"peak\":{:.17e},\"component\":{:.17e}}}",
                request.reffreq_hz, trace.update_index, x, y, trace.value, trace.component
            ));
        }
    }
    if let Some((mut cpu_model, mut cpu_residual)) = cpu_verify_inputs {
        let mut cpu_timings = ImagingStageTimings::default();
        let cpu_outcome = run_hogbom_minor_cycle_cpu(
            request,
            psf_state,
            &mut cpu_model,
            &mut cpu_residual,
            cycle_reported_niter,
            cycle_threshold_jy_per_beam,
            nsigma_threshold_jy_per_beam,
            &mut cpu_timings,
        );
        let model_diff = array2_max_abs_diff_with_first(model, &cpu_model);
        let residual_diff = array2_max_abs_diff_with_first(residual, &cpu_residual);
        eprintln!(
            "hogbom_metal_cpu_verify metal_updates={} cpu_updates={} metal_stop={:?} cpu_stop={:?} model_max_abs_diff={:.9e} model_first_diff={:?} residual_max_abs_diff={:.9e} residual_first_diff={:?}",
            cycle_component_updates,
            cpu_outcome.actual_updates,
            stop_reason,
            cpu_outcome.stop_reason,
            model_diff.0,
            model_diff.1,
            residual_diff.0,
            residual_diff.1,
        );
    }

    let total_elapsed = total_started.elapsed();
    if collect_profile {
        eprintln!(
            "standard_mfs_hogbom_minor_cycle_summary backend=metal_resident_fused_peak updates={} reported_budget={} component_budget={} stop_reason={:?} image_pixels={} has_mask={} mask_pixels={} mask_fingerprint={:016x} cpu_reference_peak_abs={:.9e} cpu_reference_peak_x={} cpu_reference_peak_y={} peak_searches={} subtract_updates={} initial_peak_dispatches={} reduce_dispatches={} select_dispatches={} subtract_peak_dispatches={} command_buffers={} first_candidate_count={} candidate_bytes={} last_peak_abs={:.9e} last_peak_value={:.9e} last_peak_index={} setup_ms={:.3} device_queue_ms={:.3} shader_compile_ms={:.3} pipeline_ms={:.3} buffer_ms={:.3} cycle_wall_ms={:.3} cycle_gpu_ms={:.3} cycle_host_wait_ms={:.3} readback_ms={:.3} total_ms={:.3}",
            cycle_component_updates,
            cycle_reported_niter,
            cycle_component_budget,
            stop_reason,
            cell_count,
            clean_mask.has_mask,
            clean_mask.pixels,
            clean_mask.fingerprint,
            cpu_reference_peak_abs,
            cpu_reference_peak_x,
            cpu_reference_peak_y,
            peak_searches,
            subtract_updates,
            peak_dispatches,
            reduce_dispatches,
            select_dispatches,
            subtract_peak_dispatches,
            command_buffers,
            first_candidate_count,
            candidate_bytes,
            last_peak_abs,
            last_peak_value,
            last_peak_index,
            profile::millis(setup_elapsed),
            profile::millis(device_queue_elapsed),
            profile::millis(shader_compile_elapsed),
            profile::millis(pipeline_elapsed),
            profile::millis(buffer_elapsed),
            profile::millis(cycle_elapsed),
            profile::millis(cycle_timing.kernel_elapsed),
            profile::millis(cycle_elapsed.saturating_sub(cycle_timing.kernel_elapsed)),
            profile::millis(readback_elapsed),
            profile::millis(total_elapsed),
        );
    }
    stage_timings.minor_cycle += total_elapsed;
    stage_timings.minor_cycle_solve += total_elapsed;
    Ok(HogbomMinorCycleOutcome {
        updated_model,
        actual_updates: cycle_component_updates,
        reported_updates: cycle_component_updates.min(cycle_reported_niter),
        stop_reason,
        final_cycle_threshold_jy_per_beam: cycle_threshold_jy_per_beam,
        final_nsigma_threshold_jy_per_beam: nsigma_threshold_jy_per_beam,
    })
}

#[cfg(all(target_os = "macos", not(coverage)))]
const HOGBOM_METAL_THREADS_PER_GROUP: usize = 1024;

#[cfg(all(target_os = "macos", not(coverage)))]
type HogbomMetalBuffer =
    objc2::rc::Retained<objc2::runtime::ProtocolObject<dyn objc2_metal::MTLBuffer>>;

#[cfg(all(target_os = "macos", not(coverage)))]
type HogbomMetalPipeline =
    objc2::rc::Retained<objc2::runtime::ProtocolObject<dyn objc2_metal::MTLComputePipelineState>>;

#[cfg(all(target_os = "macos", not(coverage)))]
#[derive(Debug, Default, Clone, Copy)]
struct HogbomMetalCommandTiming {
    kernel_elapsed: Duration,
}

#[cfg(all(target_os = "macos", not(coverage)))]
impl HogbomMetalCommandTiming {
    fn from_command_buffer(
        command_buffer: &objc2::runtime::ProtocolObject<dyn objc2_metal::MTLCommandBuffer>,
    ) -> Self {
        use objc2_metal::MTLCommandBuffer;

        let start = command_buffer.kernelStartTime();
        let end = command_buffer.kernelEndTime();
        let kernel_elapsed = if end > start {
            Duration::from_secs_f64(end - start)
        } else {
            Duration::ZERO
        };
        Self { kernel_elapsed }
    }
}

#[cfg(all(target_os = "macos", not(coverage)))]
fn hogbom_metal_pipeline(
    device: &objc2::runtime::ProtocolObject<dyn objc2_metal::MTLDevice>,
    library: &objc2::runtime::ProtocolObject<dyn objc2_metal::MTLLibrary>,
    entry_point: &str,
) -> Result<HogbomMetalPipeline, ImagingError> {
    use objc2_metal::{MTLDevice, MTLLibrary};

    let function_name = objc2_foundation::NSString::from_str(entry_point);
    let function = library.newFunctionWithName(&function_name).ok_or_else(|| {
        ImagingError::Unsupported(format!(
            "Hogbom minor-cycle backend 'metal' shader entry point '{entry_point}' was not found"
        ))
    })?;
    device
        .newComputePipelineStateWithFunction_error(&function)
        .map_err(|error| {
            ImagingError::Unsupported(format!(
                "Hogbom minor-cycle backend 'metal' failed to create pipeline '{entry_point}': {error:?}"
            ))
        })
}

#[cfg(all(target_os = "macos", not(coverage)))]
fn hogbom_metal_buffer_from_slice<T>(
    device: &objc2::runtime::ProtocolObject<dyn objc2_metal::MTLDevice>,
    values: &[T],
    storage_options: objc2_metal::MTLResourceOptions,
    label: &str,
) -> Result<HogbomMetalBuffer, ImagingError> {
    use std::{mem, ptr};

    use objc2_metal::{MTLBuffer, MTLDevice};

    let byte_len = mem::size_of_val(values);
    let buffer = device
        .newBufferWithLength_options(byte_len, storage_options)
        .ok_or_else(|| {
            ImagingError::Unsupported(format!(
                "Hogbom minor-cycle backend 'metal' could not allocate {label} buffer"
            ))
        })?;
    if byte_len > 0 {
        unsafe {
            ptr::copy_nonoverlapping(
                values.as_ptr().cast::<u8>(),
                buffer.contents().as_ptr().cast::<u8>(),
                byte_len,
            );
        }
    }
    Ok(buffer)
}

#[cfg(all(target_os = "macos", not(coverage)))]
fn hogbom_metal_params_buffer<T>(
    device: &objc2::runtime::ProtocolObject<dyn objc2_metal::MTLDevice>,
    params: &T,
    storage_options: objc2_metal::MTLResourceOptions,
    label: &str,
) -> Result<HogbomMetalBuffer, ImagingError> {
    hogbom_metal_buffer_from_slice(device, std::slice::from_ref(params), storage_options, label)
}

#[cfg(all(target_os = "macos", not(coverage)))]
fn hogbom_metal_stop_reason(code: u32) -> Option<CleanStopReason> {
    match code {
        0 => None,
        1 => Some(CleanStopReason::GlobalThresholdReached),
        2 => Some(CleanStopReason::NsigmaThresholdReached),
        3 => Some(CleanStopReason::CycleThresholdReached),
        6 => Some(CleanStopReason::NoCleanablePixels),
        7 => Some(CleanStopReason::DivergenceDetected),
        _ => None,
    }
}

#[derive(Debug, Clone, Copy, PartialEq)]
#[cfg(any(test, all(target_os = "macos", not(coverage))))]
enum StandardMfsMetalMinorCycleChunkKind {
    Full,
    Fixed,
    Auto,
}

#[derive(Debug, Clone, Copy)]
#[cfg(any(test, all(target_os = "macos", not(coverage))))]
struct StandardMfsMetalMinorCycleChunkPlanner {
    kind: StandardMfsMetalMinorCycleChunkKind,
    next_chunk: usize,
    min_chunk: usize,
    max_chunk: usize,
    target_ms: Option<f64>,
    observations: usize,
    sum_updates: f64,
    sum_updates_squared: f64,
    sum_ms: f64,
    sum_update_ms: f64,
    fixed_ms: Option<f64>,
    ms_per_update: Option<f64>,
    predicted_next_ms: Option<f64>,
}

#[cfg(any(test, all(target_os = "macos", not(coverage))))]
impl StandardMfsMetalMinorCycleChunkPlanner {
    fn next_chunk(&self, updates_remaining: usize) -> usize {
        self.next_chunk.max(1).min(updates_remaining.max(1))
    }

    fn observe_command(&mut self, command_elapsed: Duration, encoded_updates: usize) {
        if self.kind != StandardMfsMetalMinorCycleChunkKind::Auto {
            return;
        }
        let Some(target_ms) = self.target_ms else {
            return;
        };
        let encoded_updates = encoded_updates.max(1);
        let observed_ms = profile::millis(command_elapsed);
        if !observed_ms.is_finite() || observed_ms <= 0.0 {
            return;
        }
        self.observations = self.observations.saturating_add(1);
        let updates = encoded_updates as f64;
        self.sum_updates += updates;
        self.sum_updates_squared += updates * updates;
        self.sum_ms += observed_ms;
        self.sum_update_ms += updates * observed_ms;
        self.recompute_cost_model();
        self.next_chunk = self
            .planned_chunk_for_target(target_ms)
            .clamp(self.min_chunk, self.max_chunk);
        self.predicted_next_ms = self.predict_ms(self.next_chunk);
    }

    fn recompute_cost_model(&mut self) {
        if self.observations >= 2 {
            let count = self.observations as f64;
            let denominator = count * self.sum_updates_squared - self.sum_updates.powi(2);
            if denominator.abs() > f64::EPSILON {
                let slope =
                    (count * self.sum_update_ms - self.sum_updates * self.sum_ms) / denominator;
                let intercept = (self.sum_ms - slope * self.sum_updates) / count;
                if slope.is_finite() && slope > 0.0 && intercept.is_finite() {
                    self.ms_per_update = Some(slope);
                    self.fixed_ms = Some(intercept.max(0.0));
                    return;
                }
            }
        }
        if self.sum_updates > 0.0 {
            let slope = self.sum_ms / self.sum_updates;
            if slope.is_finite() && slope > 0.0 {
                self.ms_per_update = Some(slope);
                self.fixed_ms = Some(0.0);
            }
        }
    }

    fn planned_chunk_for_target(&self, target_ms: f64) -> usize {
        let Some(ms_per_update) = self.ms_per_update else {
            return self.next_chunk;
        };
        if !ms_per_update.is_finite() || ms_per_update <= 0.0 {
            return self.next_chunk;
        }
        let fixed_ms = self.fixed_ms.unwrap_or(0.0).max(0.0);
        let variable_budget_ms = (target_ms - fixed_ms).max(ms_per_update);
        let modeled_chunk = (variable_budget_ms / ms_per_update).floor() as usize;
        modeled_chunk.max(1)
    }

    fn predict_ms(&self, chunk: usize) -> Option<f64> {
        let ms_per_update = self.ms_per_update?;
        let fixed_ms = self.fixed_ms.unwrap_or(0.0).max(0.0);
        Some(fixed_ms + ms_per_update * chunk.max(1) as f64)
    }
}

#[cfg(all(target_os = "macos", not(coverage)))]
fn standard_mfs_metal_minor_cycle_chunk_planner(
    cycle_reported_niter: usize,
    cell_count: usize,
    scale_count: usize,
) -> StandardMfsMetalMinorCycleChunkPlanner {
    standard_mfs_metal_minor_cycle_chunk_planner_from_value(
        None,
        cycle_reported_niter,
        cell_count,
        scale_count,
    )
}

#[cfg(any(test, all(target_os = "macos", not(coverage))))]
fn standard_mfs_metal_minor_cycle_chunk_planner_from_value(
    value: Option<&str>,
    cycle_reported_niter: usize,
    cell_count: usize,
    scale_count: usize,
) -> StandardMfsMetalMinorCycleChunkPlanner {
    let cycle_reported_niter = cycle_reported_niter.max(1);
    let Some(value) = value.map(str::trim).filter(|value| !value.is_empty()) else {
        return StandardMfsMetalMinorCycleChunkPlanner {
            kind: StandardMfsMetalMinorCycleChunkKind::Full,
            next_chunk: cycle_reported_niter,
            min_chunk: cycle_reported_niter,
            max_chunk: cycle_reported_niter,
            target_ms: None,
            observations: 0,
            sum_updates: 0.0,
            sum_updates_squared: 0.0,
            sum_ms: 0.0,
            sum_update_ms: 0.0,
            fixed_ms: None,
            ms_per_update: None,
            predicted_next_ms: None,
        };
    };
    if value.eq_ignore_ascii_case("full") || value == "0" {
        return StandardMfsMetalMinorCycleChunkPlanner {
            kind: StandardMfsMetalMinorCycleChunkKind::Full,
            next_chunk: cycle_reported_niter,
            min_chunk: cycle_reported_niter,
            max_chunk: cycle_reported_niter,
            target_ms: None,
            observations: 0,
            sum_updates: 0.0,
            sum_updates_squared: 0.0,
            sum_ms: 0.0,
            sum_update_ms: 0.0,
            fixed_ms: None,
            ms_per_update: None,
            predicted_next_ms: None,
        };
    }
    if let Some(target_ms) = parse_standard_mfs_metal_minor_cycle_auto_target_ms(value) {
        let max_chunk = STANDARD_MFS_METAL_MINOR_CYCLE_MAX_AUTO_CHUNK.min(cycle_reported_niter);
        let min_chunk = STANDARD_MFS_METAL_MINOR_CYCLE_MIN_AUTO_CHUNK
            .min(max_chunk)
            .max(1);
        return StandardMfsMetalMinorCycleChunkPlanner {
            kind: StandardMfsMetalMinorCycleChunkKind::Auto,
            next_chunk: standard_mfs_metal_minor_cycle_initial_auto_chunk(
                cycle_reported_niter,
                cell_count,
                scale_count,
                min_chunk,
                max_chunk,
            ),
            min_chunk,
            max_chunk,
            target_ms: Some(target_ms),
            observations: 0,
            sum_updates: 0.0,
            sum_updates_squared: 0.0,
            sum_ms: 0.0,
            sum_update_ms: 0.0,
            fixed_ms: None,
            ms_per_update: None,
            predicted_next_ms: None,
        };
    }
    if let Some(chunk) = value.parse::<usize>().ok().filter(|value| *value > 0) {
        let chunk = chunk.min(cycle_reported_niter).max(1);
        return StandardMfsMetalMinorCycleChunkPlanner {
            kind: StandardMfsMetalMinorCycleChunkKind::Fixed,
            next_chunk: chunk,
            min_chunk: chunk,
            max_chunk: chunk,
            target_ms: None,
            observations: 0,
            sum_updates: 0.0,
            sum_updates_squared: 0.0,
            sum_ms: 0.0,
            sum_update_ms: 0.0,
            fixed_ms: None,
            ms_per_update: None,
            predicted_next_ms: None,
        };
    }
    StandardMfsMetalMinorCycleChunkPlanner {
        kind: StandardMfsMetalMinorCycleChunkKind::Full,
        next_chunk: cycle_reported_niter,
        min_chunk: cycle_reported_niter,
        max_chunk: cycle_reported_niter,
        target_ms: None,
        observations: 0,
        sum_updates: 0.0,
        sum_updates_squared: 0.0,
        sum_ms: 0.0,
        sum_update_ms: 0.0,
        fixed_ms: None,
        ms_per_update: None,
        predicted_next_ms: None,
    }
}

#[cfg(any(test, all(target_os = "macos", not(coverage))))]
fn parse_standard_mfs_metal_minor_cycle_auto_target_ms(value: &str) -> Option<f64> {
    if value.eq_ignore_ascii_case("auto") {
        return Some(DEFAULT_STANDARD_MFS_METAL_MINOR_CYCLE_TARGET_MS);
    }
    let lowercase = value.to_ascii_lowercase();
    let suffix = lowercase.strip_prefix("auto:")?;
    let target_ms = suffix.parse::<f64>().ok()?;
    target_ms
        .is_finite()
        .then_some(target_ms)
        .filter(|value| *value > 0.0)
}

#[cfg(any(test, all(target_os = "macos", not(coverage))))]
fn standard_mfs_metal_minor_cycle_initial_auto_chunk(
    cycle_reported_niter: usize,
    _cell_count: usize,
    _scale_count: usize,
    min_chunk: usize,
    max_chunk: usize,
) -> usize {
    min_chunk
        .clamp(min_chunk, max_chunk)
        .min(cycle_reported_niter.max(1))
}

#[cfg(all(target_os = "macos", not(coverage)))]
#[allow(clippy::too_many_arguments)]
fn hogbom_metal_run_resident_cycle(
    queue: &objc2::runtime::ProtocolObject<dyn objc2_metal::MTLCommandQueue>,
    device: &objc2::runtime::ProtocolObject<dyn objc2_metal::MTLDevice>,
    peak_pipeline: &objc2::runtime::ProtocolObject<dyn objc2_metal::MTLComputePipelineState>,
    reduce_pipeline: &objc2::runtime::ProtocolObject<dyn objc2_metal::MTLComputePipelineState>,
    select_pipeline: &objc2::runtime::ProtocolObject<dyn objc2_metal::MTLComputePipelineState>,
    subtract_peak_pipeline: &objc2::runtime::ProtocolObject<
        dyn objc2_metal::MTLComputePipelineState,
    >,
    residual_buffer: &objc2::runtime::ProtocolObject<dyn objc2_metal::MTLBuffer>,
    model_buffer: &objc2::runtime::ProtocolObject<dyn objc2_metal::MTLBuffer>,
    psf_buffer: &objc2::runtime::ProtocolObject<dyn objc2_metal::MTLBuffer>,
    mask_buffer: &objc2::runtime::ProtocolObject<dyn objc2_metal::MTLBuffer>,
    candidate_a: &objc2::runtime::ProtocolObject<dyn objc2_metal::MTLBuffer>,
    candidate_b: &objc2::runtime::ProtocolObject<dyn objc2_metal::MTLBuffer>,
    selected_peak_buffer: &objc2::runtime::ProtocolObject<dyn objc2_metal::MTLBuffer>,
    trace_buffer: &objc2::runtime::ProtocolObject<dyn objc2_metal::MTLBuffer>,
    storage_options: objc2_metal::MTLResourceOptions,
    params: HogbomMetalCycleParams,
    first_candidate_count: usize,
) -> Result<
    (
        HogbomMetalCycleState,
        HogbomMetalCommandTiming,
        usize,
        usize,
        usize,
        usize,
    ),
    ImagingError,
> {
    use objc2_metal::{
        MTLBuffer, MTLCommandBuffer, MTLCommandBufferStatus, MTLCommandEncoder, MTLCommandQueue,
        MTLComputeCommandEncoder, MTLSize,
    };

    let command_buffer = queue.commandBuffer().ok_or_else(|| {
        ImagingError::Unsupported(
            "Hogbom minor-cycle backend 'metal' could not create resident command buffer"
                .to_string(),
        )
    })?;
    let cycle_params_buffer =
        hogbom_metal_params_buffer(device, &params, storage_options, "resident cycle params")?;
    let initial_state = HogbomMetalCycleState::default();
    let state_buffer =
        hogbom_metal_buffer_from_slice(device, &[initial_state], storage_options, "cycle state")?;

    let peak_threads = usize::try_from(params.cell_count).map_err(|_| {
        ImagingError::InvalidRequest("Hogbom Metal peak thread count overflowed".to_string())
    })?;
    let peak_threads_per_group = usize::try_from(params.peak_threads_per_group).map_err(|_| {
        ImagingError::InvalidRequest("Hogbom Metal peak threadgroup width overflowed".to_string())
    })?;
    let peak_group_count = peak_threads.div_ceil(peak_threads_per_group);

    let mut reduce_param_buffers = Vec::new();
    let mut reduce_plan = Vec::new();
    let mut input_a = true;
    let mut current_count = first_candidate_count.max(1);
    while current_count > 1 {
        let reduce_threads_per_group =
            hogbom_metal_threads_per_group(reduce_pipeline, current_count);
        let output_count = current_count.div_ceil(reduce_threads_per_group);
        let reduce_params = HogbomMetalReduceParams {
            candidate_count: u32::try_from(current_count).map_err(|_| {
                ImagingError::InvalidRequest("Hogbom Metal candidate count exceeds u32".to_string())
            })?,
            nx: params.nx,
            ny: params.ny,
            threads_per_group: u32::try_from(reduce_threads_per_group).map_err(|_| {
                ImagingError::InvalidRequest(
                    "Hogbom Metal reduce threadgroup width exceeds u32".to_string(),
                )
            })?,
        };
        let reduce_params_buffer =
            hogbom_metal_params_buffer(device, &reduce_params, storage_options, "reduce params")?;
        reduce_param_buffers.push(reduce_params_buffer);
        reduce_plan.push((input_a, output_count, reduce_threads_per_group));
        input_a = !input_a;
        current_count = output_count.max(1);
    }
    let final_candidate_from_a = input_a;

    let component_budget = usize::try_from(params.component_budget).map_err(|_| {
        ImagingError::InvalidRequest("Hogbom Metal component budget overflowed".to_string())
    })?;
    let mut peak_dispatches = 0usize;
    let mut reduce_dispatches = 0usize;
    let mut select_dispatches = 0usize;
    let mut subtract_peak_dispatches = 0usize;

    if component_budget > 0 {
        let peak_encoder = command_buffer.computeCommandEncoder().ok_or_else(|| {
            ImagingError::Unsupported(
                "Hogbom minor-cycle backend 'metal' could not create resident peak encoder"
                    .to_string(),
            )
        })?;
        peak_encoder.setComputePipelineState(peak_pipeline);
        unsafe {
            peak_encoder.setBuffer_offset_atIndex(Some(residual_buffer), 0, 0);
            peak_encoder.setBuffer_offset_atIndex(Some(mask_buffer), 0, 1);
            peak_encoder.setBuffer_offset_atIndex(Some(candidate_a), 0, 2);
            peak_encoder.setBuffer_offset_atIndex(Some(&cycle_params_buffer), 0, 3);
            peak_encoder.setBuffer_offset_atIndex(Some(&state_buffer), 0, 4);
        }
        peak_encoder.dispatchThreadgroups_threadsPerThreadgroup(
            MTLSize {
                width: peak_group_count,
                height: 1,
                depth: 1,
            },
            MTLSize {
                width: peak_threads_per_group,
                height: 1,
                depth: 1,
            },
        );
        peak_encoder.endEncoding();
        peak_dispatches = peak_dispatches.saturating_add(1);

        reduce_dispatches = reduce_dispatches.saturating_add(hogbom_metal_encode_reduce_plan(
            &command_buffer,
            reduce_pipeline,
            candidate_a,
            candidate_b,
            &reduce_param_buffers,
            &reduce_plan,
            &state_buffer,
        )?);

        let final_candidate_buffer = if final_candidate_from_a {
            candidate_a
        } else {
            candidate_b
        };
        hogbom_metal_encode_select_peak(
            &command_buffer,
            select_pipeline,
            final_candidate_buffer,
            selected_peak_buffer,
            &state_buffer,
            model_buffer,
            &cycle_params_buffer,
            trace_buffer,
        )?;
        select_dispatches = select_dispatches.saturating_add(1);

        for component_index in 0..component_budget {
            let subtract_encoder = command_buffer.computeCommandEncoder().ok_or_else(|| {
                ImagingError::Unsupported(
                    "Hogbom minor-cycle backend 'metal' could not create resident subtract/peak encoder"
                        .to_string(),
                )
            })?;
            subtract_encoder.setComputePipelineState(subtract_peak_pipeline);
            unsafe {
                subtract_encoder.setBuffer_offset_atIndex(Some(selected_peak_buffer), 0, 0);
                subtract_encoder.setBuffer_offset_atIndex(Some(residual_buffer), 0, 1);
                subtract_encoder.setBuffer_offset_atIndex(Some(psf_buffer), 0, 2);
                subtract_encoder.setBuffer_offset_atIndex(Some(mask_buffer), 0, 3);
                subtract_encoder.setBuffer_offset_atIndex(Some(candidate_a), 0, 4);
                subtract_encoder.setBuffer_offset_atIndex(Some(&cycle_params_buffer), 0, 5);
                subtract_encoder.setBuffer_offset_atIndex(Some(&state_buffer), 0, 6);
            }
            subtract_encoder.dispatchThreadgroups_threadsPerThreadgroup(
                MTLSize {
                    width: peak_group_count,
                    height: 1,
                    depth: 1,
                },
                MTLSize {
                    width: peak_threads_per_group,
                    height: 1,
                    depth: 1,
                },
            );
            subtract_encoder.endEncoding();
            subtract_peak_dispatches = subtract_peak_dispatches.saturating_add(1);

            if component_index + 1 == component_budget {
                break;
            }
            reduce_dispatches = reduce_dispatches.saturating_add(hogbom_metal_encode_reduce_plan(
                &command_buffer,
                reduce_pipeline,
                candidate_a,
                candidate_b,
                &reduce_param_buffers,
                &reduce_plan,
                &state_buffer,
            )?);
            hogbom_metal_encode_select_peak(
                &command_buffer,
                select_pipeline,
                final_candidate_buffer,
                selected_peak_buffer,
                &state_buffer,
                model_buffer,
                &cycle_params_buffer,
                trace_buffer,
            )?;
            select_dispatches = select_dispatches.saturating_add(1);
        }
    }

    command_buffer.commit();
    command_buffer.waitUntilCompleted();
    let timing = HogbomMetalCommandTiming::from_command_buffer(&command_buffer);
    if command_buffer.status() == MTLCommandBufferStatus::Error {
        let message = command_buffer
            .error()
            .map(|error| format!("{error:?}"))
            .unwrap_or_else(|| "unknown Metal command buffer error".to_string());
        return Err(ImagingError::Unsupported(format!(
            "Hogbom minor-cycle backend 'metal' resident command failed: {message}"
        )));
    }
    let final_state = unsafe {
        *std::slice::from_raw_parts(
            state_buffer
                .contents()
                .as_ptr()
                .cast::<HogbomMetalCycleState>(),
            1,
        )
        .first()
        .expect("one Hogbom Metal cycle state")
    };
    Ok((
        final_state,
        timing,
        peak_dispatches,
        reduce_dispatches,
        select_dispatches,
        subtract_peak_dispatches,
    ))
}

#[cfg(all(target_os = "macos", not(coverage)))]
#[allow(clippy::too_many_arguments)]
fn hogbom_metal_encode_reduce_plan(
    command_buffer: &objc2::runtime::ProtocolObject<dyn objc2_metal::MTLCommandBuffer>,
    reduce_pipeline: &objc2::runtime::ProtocolObject<dyn objc2_metal::MTLComputePipelineState>,
    candidate_a: &objc2::runtime::ProtocolObject<dyn objc2_metal::MTLBuffer>,
    candidate_b: &objc2::runtime::ProtocolObject<dyn objc2_metal::MTLBuffer>,
    reduce_param_buffers: &[HogbomMetalBuffer],
    reduce_plan: &[(bool, usize, usize)],
    state_buffer: &objc2::runtime::ProtocolObject<dyn objc2_metal::MTLBuffer>,
) -> Result<usize, ImagingError> {
    use objc2_metal::{MTLCommandBuffer, MTLCommandEncoder, MTLComputeCommandEncoder, MTLSize};

    let mut dispatches = 0usize;
    for (reduce_index, (input_a_for_reduce, output_count, reduce_threads_per_group)) in
        reduce_plan.iter().copied().enumerate()
    {
        let reduce_encoder = command_buffer.computeCommandEncoder().ok_or_else(|| {
            ImagingError::Unsupported(
                "Hogbom minor-cycle backend 'metal' could not create resident reduce encoder"
                    .to_string(),
            )
        })?;
        reduce_encoder.setComputePipelineState(reduce_pipeline);
        let (input_buffer, output_buffer) = if input_a_for_reduce {
            (candidate_a, candidate_b)
        } else {
            (candidate_b, candidate_a)
        };
        unsafe {
            reduce_encoder.setBuffer_offset_atIndex(Some(input_buffer), 0, 0);
            reduce_encoder.setBuffer_offset_atIndex(Some(output_buffer), 0, 1);
            reduce_encoder.setBuffer_offset_atIndex(
                Some(&reduce_param_buffers[reduce_index]),
                0,
                2,
            );
            reduce_encoder.setBuffer_offset_atIndex(Some(state_buffer), 0, 3);
        }
        reduce_encoder.dispatchThreadgroups_threadsPerThreadgroup(
            MTLSize {
                width: output_count,
                height: 1,
                depth: 1,
            },
            MTLSize {
                width: reduce_threads_per_group,
                height: 1,
                depth: 1,
            },
        );
        reduce_encoder.endEncoding();
        dispatches = dispatches.saturating_add(1);
    }
    Ok(dispatches)
}

#[cfg(all(target_os = "macos", not(coverage)))]
#[allow(clippy::too_many_arguments)]
fn hogbom_metal_encode_select_peak(
    command_buffer: &objc2::runtime::ProtocolObject<dyn objc2_metal::MTLCommandBuffer>,
    select_pipeline: &objc2::runtime::ProtocolObject<dyn objc2_metal::MTLComputePipelineState>,
    final_candidate_buffer: &objc2::runtime::ProtocolObject<dyn objc2_metal::MTLBuffer>,
    selected_peak_buffer: &objc2::runtime::ProtocolObject<dyn objc2_metal::MTLBuffer>,
    state_buffer: &objc2::runtime::ProtocolObject<dyn objc2_metal::MTLBuffer>,
    model_buffer: &objc2::runtime::ProtocolObject<dyn objc2_metal::MTLBuffer>,
    cycle_params_buffer: &objc2::runtime::ProtocolObject<dyn objc2_metal::MTLBuffer>,
    trace_buffer: &objc2::runtime::ProtocolObject<dyn objc2_metal::MTLBuffer>,
) -> Result<(), ImagingError> {
    use objc2_metal::{MTLCommandBuffer, MTLCommandEncoder, MTLComputeCommandEncoder, MTLSize};

    let select_encoder = command_buffer.computeCommandEncoder().ok_or_else(|| {
        ImagingError::Unsupported(
            "Hogbom minor-cycle backend 'metal' could not create resident peak-select encoder"
                .to_string(),
        )
    })?;
    select_encoder.setComputePipelineState(select_pipeline);
    unsafe {
        select_encoder.setBuffer_offset_atIndex(Some(final_candidate_buffer), 0, 0);
        select_encoder.setBuffer_offset_atIndex(Some(selected_peak_buffer), 0, 1);
        select_encoder.setBuffer_offset_atIndex(Some(state_buffer), 0, 2);
        select_encoder.setBuffer_offset_atIndex(Some(model_buffer), 0, 3);
        select_encoder.setBuffer_offset_atIndex(Some(cycle_params_buffer), 0, 4);
        select_encoder.setBuffer_offset_atIndex(Some(trace_buffer), 0, 5);
    }
    select_encoder.dispatchThreads_threadsPerThreadgroup(
        MTLSize {
            width: 1,
            height: 1,
            depth: 1,
        },
        MTLSize {
            width: 1,
            height: 1,
            depth: 1,
        },
    );
    select_encoder.endEncoding();
    Ok(())
}

#[cfg(all(target_os = "macos", not(coverage)))]
fn hogbom_metal_threads_per_group(
    pipeline: &objc2::runtime::ProtocolObject<dyn objc2_metal::MTLComputePipelineState>,
    thread_count: usize,
) -> usize {
    use objc2_metal::MTLComputePipelineState;

    let thread_width = pipeline.threadExecutionWidth().max(1);
    let max_threads = pipeline.maxTotalThreadsPerThreadgroup().max(1);
    let capped = HOGBOM_METAL_THREADS_PER_GROUP
        .min(thread_width.max(1).saturating_mul(32))
        .min(max_threads)
        .min(thread_count)
        .max(1);
    let mut power_of_two = 1usize;
    while power_of_two.saturating_mul(2) <= capped {
        power_of_two = power_of_two.saturating_mul(2);
    }
    power_of_two
}

#[cfg(all(target_os = "macos", not(coverage)))]
const MULTISCALE_MINOR_CYCLE_METAL_SHADER: &str = r#"
#include <metal_stdlib>
using namespace metal;
#pragma clang fp contract(off)

struct HogbomPeakCandidate {
    float abs_value;
    float value;
    uint flat_index;
    uint valid;
};

struct MultiscaleCycleParams {
    uint cell_count;
    uint nx;
    uint ny;
    uint scale_count;
    uint has_scale_masks;
    uint threads_per_group;
    uint reduce_threads_per_group;
    uint reduce_level_count;
    uint component_budget;
    float gain;
    float threshold_jy_per_beam;
    float cycle_threshold_jy_per_beam;
    float nsigma_threshold_jy_per_beam;
};

struct MultiscaleReduceParams {
    uint candidate_count;
    uint cell_count;
    uint nx;
    uint ny;
    uint scale_count;
    uint threads_per_group;
    uint2 _pad0;
};

struct MultiscaleCycleState {
    HogbomPeakCandidate peak;
    float component;
    uint updates;
    uint stopped;
    uint stop_reason;
    uint selected_scale_index;
    uint window_x0;
    uint window_y0;
    uint window_x1;
    uint window_y1;
    float initial_component_abs;
    uint2 _pad0;
};

struct MultiscaleDispatchArgs {
    uint threadgroups_per_grid[3];
};

struct MultiscaleWindowIndex {
    uint combined_index;
    uint scale_index;
    uint flat_index;
    uint x;
    uint y;
    uint valid;
};

static inline HogbomPeakCandidate multiscale_invalid_candidate() {
    HogbomPeakCandidate candidate;
    candidate.abs_value = 0.0f;
    candidate.value = 0.0f;
    candidate.flat_index = 0u;
    candidate.valid = 0u;
    return candidate;
}

static inline uint multiscale_order_key(uint combined_index, uint cell_count, uint nx, uint ny) {
    const uint scale_index = combined_index / cell_count;
    const uint flat_index = combined_index - scale_index * cell_count;
    const uint x = flat_index / ny;
    const uint y = flat_index - x * ny;
    return scale_index * cell_count + y * nx + x;
}

static inline bool multiscale_candidate_better(
    HogbomPeakCandidate candidate,
    HogbomPeakCandidate best,
    uint cell_count,
    uint nx,
    uint ny
) {
    if (candidate.valid == 0u) {
        return false;
    }
    if (best.valid == 0u) {
        return true;
    }
    if (candidate.abs_value > best.abs_value) {
        return true;
    }
    if (candidate.abs_value == best.abs_value) {
        return multiscale_order_key(candidate.flat_index, cell_count, nx, ny) <
               multiscale_order_key(best.flat_index, cell_count, nx, ny);
    }
    return false;
}

static inline uint multiscale_stop_reason(float component_abs, constant MultiscaleCycleParams &params) {
    const bool threshold_floor_active =
        params.threshold_jy_per_beam > 0.0f &&
        (0.01f * params.threshold_jy_per_beam) < 2.0e-8f &&
        params.cycle_threshold_jy_per_beam <= params.threshold_jy_per_beam;
    if (component_abs < params.threshold_jy_per_beam ||
        (threshold_floor_active &&
         (component_abs <= params.threshold_jy_per_beam ||
          fabs(component_abs - params.threshold_jy_per_beam) <= max(0.01f * params.threshold_jy_per_beam, 2.0e-8f)))) {
        return 1u;
    }
    if (params.nsigma_threshold_jy_per_beam > params.threshold_jy_per_beam &&
        component_abs < params.nsigma_threshold_jy_per_beam) {
        return 2u;
    }
    if (component_abs < params.cycle_threshold_jy_per_beam) {
        return 3u;
    }
    return 0u;
}

static inline uint multiscale_div_ceil(uint value, uint divisor) {
    return (value + divisor - 1u) / divisor;
}

static inline uint multiscale_window_width(device const MultiscaleCycleState *state) {
    return state->window_x1 >= state->window_x0 ? state->window_x1 - state->window_x0 + 1u : 0u;
}

static inline uint multiscale_window_height(device const MultiscaleCycleState *state) {
    return state->window_y1 >= state->window_y0 ? state->window_y1 - state->window_y0 + 1u : 0u;
}

static inline uint multiscale_window_candidate_count(
    constant MultiscaleCycleParams &params,
    device const MultiscaleCycleState *state
) {
    if (state->stopped != 0u) {
        return 0u;
    }
    return multiscale_window_width(state) * multiscale_window_height(state) * params.scale_count;
}

static inline void multiscale_prepare_window_dispatch_args(
    device const MultiscaleCycleState *state,
    constant MultiscaleCycleParams &params,
    device MultiscaleReduceParams *reduce_params,
    device MultiscaleDispatchArgs *dispatch_args,
    device ulong *dispatch_stats
) {
    const uint active_candidates = multiscale_window_candidate_count(params, state);
    dispatch_stats[0] += ulong(active_candidates);
    if (state->updates > 0u) {
        dispatch_stats[1] += ulong(active_candidates);
    }
    uint current_count = max(1u, multiscale_div_ceil(max(1u, active_candidates), params.threads_per_group));
    dispatch_args[0].threadgroups_per_grid[0] = current_count;
    dispatch_args[0].threadgroups_per_grid[1] = 1u;
    dispatch_args[0].threadgroups_per_grid[2] = 1u;
    for (uint level = 0u; level < params.reduce_level_count; ++level) {
        reduce_params[level].candidate_count = current_count;
        reduce_params[level].cell_count = params.cell_count;
        reduce_params[level].nx = params.nx;
        reduce_params[level].ny = params.ny;
        reduce_params[level].scale_count = params.scale_count;
        reduce_params[level].threads_per_group = params.reduce_threads_per_group;
        reduce_params[level]._pad0 = uint2(0u, 0u);
        current_count = max(1u, multiscale_div_ceil(max(1u, current_count), params.reduce_threads_per_group));
        dispatch_args[level + 1u].threadgroups_per_grid[0] = current_count;
        dispatch_args[level + 1u].threadgroups_per_grid[1] = 1u;
        dispatch_args[level + 1u].threadgroups_per_grid[2] = 1u;
    }
}

static inline MultiscaleWindowIndex multiscale_window_index(
    uint window_index,
    constant MultiscaleCycleParams &params,
    device const MultiscaleCycleState *state
) {
    MultiscaleWindowIndex mapped;
    mapped.combined_index = 0u;
    mapped.scale_index = 0u;
    mapped.flat_index = 0u;
    mapped.x = 0u;
    mapped.y = 0u;
    mapped.valid = 0u;
    const uint width = multiscale_window_width(state);
    const uint height = multiscale_window_height(state);
    const uint window_pixels = width * height;
    if (window_pixels == 0u || window_index >= window_pixels * params.scale_count) {
        return mapped;
    }
    mapped.scale_index = window_index / window_pixels;
    const uint window_flat = window_index - mapped.scale_index * window_pixels;
    mapped.x = state->window_x0 + window_flat / height;
    mapped.y = state->window_y0 + window_flat - (mapped.x - state->window_x0) * height;
    if (mapped.x >= params.nx || mapped.y >= params.ny) {
        return mapped;
    }
    mapped.flat_index = mapped.x * params.ny + mapped.y;
    mapped.combined_index = mapped.scale_index * params.cell_count + mapped.flat_index;
    mapped.valid = 1u;
    return mapped;
}

kernel void multiscale_prepare_window_dispatch(
    device const MultiscaleCycleState *state [[buffer(0)]],
    constant MultiscaleCycleParams &params [[buffer(1)]],
    device MultiscaleReduceParams *reduce_params [[buffer(2)]],
    device MultiscaleDispatchArgs *dispatch_args [[buffer(3)]],
    device ulong *dispatch_stats [[buffer(4)]],
    uint thread_index [[thread_position_in_grid]]
) {
    if (thread_index != 0u) {
        return;
    }
    multiscale_prepare_window_dispatch_args(
        state, params, reduce_params, dispatch_args, dispatch_stats);
}

static inline HogbomPeakCandidate multiscale_make_candidate(
    device const float *dirty_scales,
    device const uint *scale_masks,
    device const float *peak_psf,
    device const float *scale_bias,
    uint window_index,
    constant MultiscaleCycleParams &params,
    device const MultiscaleCycleState *state
) {
    HogbomPeakCandidate candidate = multiscale_invalid_candidate();
    if (state->stopped != 0u) {
        return candidate;
    }
    const MultiscaleWindowIndex mapped = multiscale_window_index(window_index, params, state);
    if (mapped.valid == 0u) {
        return candidate;
    }
    if (params.has_scale_masks != 0u && scale_masks[mapped.combined_index] == 0u) {
        return candidate;
    }
    const float peak = peak_psf[mapped.scale_index];
    const float value = dirty_scales[mapped.combined_index];
    if (peak <= 0.0f || value == 0.0f) {
        return candidate;
    }
    const float strength = value / peak;
    const float score = scale_bias[mapped.scale_index] * value * strength;
    candidate.abs_value = fabs(score);
    candidate.value = value;
    candidate.flat_index = mapped.combined_index;
    candidate.valid = 1u;
    return candidate;
}

kernel void multiscale_peak_reduce(
    device const float *dirty_scales [[buffer(0)]],
    device const uint *scale_masks [[buffer(1)]],
    device const float *peak_psf [[buffer(2)]],
    device const float *scale_bias [[buffer(3)]],
    device HogbomPeakCandidate *candidates [[buffer(4)]],
    constant MultiscaleCycleParams &params [[buffer(5)]],
    device const MultiscaleCycleState *state [[buffer(6)]],
    uint thread_index [[thread_position_in_grid]],
    uint local_index [[thread_index_in_threadgroup]],
    uint group_index [[threadgroup_position_in_grid]]
) {
    threadgroup HogbomPeakCandidate local_candidates[1024];
    HogbomPeakCandidate candidate = multiscale_make_candidate(
        dirty_scales, scale_masks, peak_psf, scale_bias, thread_index, params, state);
    local_candidates[local_index] = candidate;
    threadgroup_barrier(mem_flags::mem_threadgroup);

    for (uint stride = params.threads_per_group >> 1; stride > 0u; stride >>= 1) {
        if (local_index < stride) {
            const HogbomPeakCandidate other = local_candidates[local_index + stride];
            const HogbomPeakCandidate best = local_candidates[local_index];
            if (multiscale_candidate_better(other, best, params.cell_count, params.nx, params.ny)) {
                local_candidates[local_index] = other;
            }
        }
        threadgroup_barrier(mem_flags::mem_threadgroup);
    }
    if (local_index == 0u) {
        candidates[group_index] = local_candidates[0];
    }
}

kernel void multiscale_reduce_candidates(
    device const HogbomPeakCandidate *input [[buffer(0)]],
    device HogbomPeakCandidate *output [[buffer(1)]],
    constant MultiscaleReduceParams &params [[buffer(2)]],
    device const MultiscaleCycleState *state [[buffer(3)]],
    uint thread_index [[thread_position_in_grid]],
    uint local_index [[thread_index_in_threadgroup]],
    uint group_index [[threadgroup_position_in_grid]]
) {
    threadgroup HogbomPeakCandidate local_candidates[1024];
    HogbomPeakCandidate candidate = multiscale_invalid_candidate();
    if (state->stopped == 0u && thread_index < params.candidate_count) {
        candidate = input[thread_index];
    }
    local_candidates[local_index] = candidate;
    threadgroup_barrier(mem_flags::mem_threadgroup);

    for (uint stride = params.threads_per_group >> 1; stride > 0u; stride >>= 1) {
        if (local_index < stride) {
            const HogbomPeakCandidate other = local_candidates[local_index + stride];
            const HogbomPeakCandidate best = local_candidates[local_index];
            if (multiscale_candidate_better(other, best, params.cell_count, params.nx, params.ny)) {
                local_candidates[local_index] = other;
            }
        }
        threadgroup_barrier(mem_flags::mem_threadgroup);
    }
    if (local_index == 0u) {
        output[group_index] = local_candidates[0];
    }
}

kernel void multiscale_select_component(
    device const HogbomPeakCandidate *peak_candidate [[buffer(0)]],
    device HogbomPeakCandidate *selected_peak [[buffer(1)]],
    device MultiscaleCycleState *state [[buffer(2)]],
    device float *model [[buffer(3)]],
    device const float *scale_kernels [[buffer(4)]],
    device uint *scale_counts [[buffer(5)]],
    constant MultiscaleCycleParams &params [[buffer(6)]],
    device const float *peak_psf [[buffer(7)]],
    uint thread_index [[thread_position_in_grid]]
) {
    if (thread_index != 0u || state->stopped != 0u) {
        return;
    }
    const HogbomPeakCandidate peak = peak_candidate[0];
    selected_peak[0] = peak;
    state->peak = peak;
    if (peak.valid == 0u) {
        state->stopped = 1u;
        state->stop_reason = 6u;
        return;
    }
    const uint scale_index = peak.flat_index / params.cell_count;
    const uint flat_index = peak.flat_index - scale_index * params.cell_count;
    const float scale_peak_psf = max(1.0e-20f, peak_psf[scale_index]);
    const float strength = peak.value / scale_peak_psf;
    const float component_abs = fabs(strength);
    state->selected_scale_index = scale_index;
    const uint reason = multiscale_stop_reason(component_abs, params);
    if (reason != 0u) {
        state->stopped = 1u;
        state->stop_reason = reason;
        return;
    }
    if (state->updates > 0u && component_abs > state->initial_component_abs * 1.5f) {
        state->stopped = 1u;
        state->stop_reason = 7u;
        return;
    }
    if (state->updates == 0u) {
        state->initial_component_abs = component_abs;
    }
    state->component = params.gain * strength;
    state->updates += 1u;
    scale_counts[scale_index] += 1u;
    const uint peak_x = flat_index / params.ny;
    const uint peak_y = flat_index - peak_x * params.ny;
    const uint half_x = params.nx / 2u;
    const uint half_y = params.ny / 2u;
    state->window_x0 = peak_x > half_x ? peak_x - half_x : 0u;
    state->window_y0 = peak_y > half_y ? peak_y - half_y : 0u;
    state->window_x1 = min(params.nx - 1u, peak_x + half_x - 1u);
    state->window_y1 = min(params.ny - 1u, peak_y + half_y - 1u);
}

kernel void multiscale_subtract_and_find_next(
    device const HogbomPeakCandidate *selected_peak [[buffer(0)]],
    device float *dirty_scales [[buffer(1)]],
    device const float *psf_scales [[buffer(2)]],
    device const float *scale_kernels [[buffer(3)]],
    device const uint *scale_masks [[buffer(4)]],
    device const float *peak_psf [[buffer(5)]],
    device const float *scale_bias [[buffer(6)]],
    device HogbomPeakCandidate *candidates [[buffer(7)]],
    device float *model [[buffer(8)]],
    constant MultiscaleCycleParams &params [[buffer(9)]],
    device const MultiscaleCycleState *state [[buffer(10)]],
    uint thread_index [[thread_position_in_grid]],
    uint local_index [[thread_index_in_threadgroup]],
    uint group_index [[threadgroup_position_in_grid]]
) {
    threadgroup HogbomPeakCandidate local_candidates[1024];
    const MultiscaleWindowIndex mapped = multiscale_window_index(thread_index, params, state);
    if (state->stopped == 0u && mapped.valid != 0u) {
        const HogbomPeakCandidate peak = selected_peak[0];
        const uint selected_scale = state->selected_scale_index;
        const uint peak_flat = peak.flat_index - selected_scale * params.cell_count;
        const uint peak_x = peak_flat / params.ny;
        const uint peak_y = peak_flat - peak_x * params.ny;
        const int kernel_x = int(mapped.x) - int(peak_x) + int(params.nx / 2u);
        const int kernel_y = int(mapped.y) - int(peak_y) + int(params.ny / 2u);
        if (kernel_x >= 0 && kernel_y >= 0 &&
            kernel_x < int(params.nx) && kernel_y < int(params.ny)) {
            const uint kernel_index = uint(kernel_x) * params.ny + uint(kernel_y);
            if (mapped.scale_index == 0u) {
                const float model_delta =
                    state->component * scale_kernels[selected_scale * params.cell_count + kernel_index];
                model[mapped.flat_index] = model[mapped.flat_index] + model_delta;
            }
            const uint psf_index =
                ((mapped.scale_index * params.scale_count + selected_scale) * params.cell_count) +
                kernel_index;
            const float dirty_delta = state->component * psf_scales[psf_index];
            dirty_scales[mapped.combined_index] = dirty_scales[mapped.combined_index] - dirty_delta;
        }
    }

    HogbomPeakCandidate candidate = multiscale_make_candidate(
        dirty_scales, scale_masks, peak_psf, scale_bias, thread_index, params, state);
    local_candidates[local_index] = candidate;
    threadgroup_barrier(mem_flags::mem_threadgroup);

    for (uint stride = params.threads_per_group >> 1; stride > 0u; stride >>= 1) {
        if (local_index < stride) {
            const HogbomPeakCandidate other = local_candidates[local_index + stride];
            const HogbomPeakCandidate best = local_candidates[local_index];
            if (multiscale_candidate_better(other, best, params.cell_count, params.nx, params.ny)) {
                local_candidates[local_index] = other;
            }
        }
        threadgroup_barrier(mem_flags::mem_threadgroup);
    }
    if (local_index == 0u) {
        candidates[group_index] = local_candidates[0];
    }
}
"#;

#[cfg(all(target_os = "macos", not(coverage)))]
const HOGBOM_MINOR_CYCLE_METAL_SHADER: &str = r#"
#include <metal_stdlib>
using namespace metal;
#pragma clang fp contract(off)

struct HogbomPeakCandidate {
    float abs_value;
    float value;
    uint flat_index;
    uint valid;
};

struct HogbomReduceParams {
    uint candidate_count;
    uint nx;
    uint ny;
    uint threads_per_group;
};

struct HogbomCycleParams {
    uint cell_count;
    uint nx;
    uint ny;
    uint has_mask;
    uint peak_threads_per_group;
    uint component_budget;
    float gain;
    float threshold_jy_per_beam;
    float cycle_threshold_jy_per_beam;
    float nsigma_threshold_jy_per_beam;
    uint trace_components;
    uint _pad0;
};

struct HogbomCycleState {
    HogbomPeakCandidate peak;
    float component;
    uint updates;
    uint stopped;
    uint stop_reason;
};

struct HogbomComponentTrace {
    float value;
    float component;
    uint flat_index;
    uint update_index;
};

static inline uint hogbom_order_key(uint flat_index, uint ny, uint nx) {
    const uint x = flat_index / ny;
    const uint y = flat_index - x * ny;
    return y * nx + x;
}

static inline HogbomPeakCandidate hogbom_invalid_candidate() {
    HogbomPeakCandidate candidate;
    candidate.abs_value = 0.0f;
    candidate.value = 0.0f;
    candidate.flat_index = 0u;
    candidate.valid = 0u;
    return candidate;
}

static inline bool hogbom_candidate_better(
    HogbomPeakCandidate candidate,
    HogbomPeakCandidate best,
    uint ny,
    uint nx
) {
    if (candidate.valid == 0u) {
        return false;
    }
    if (best.valid == 0u) {
        return true;
    }
    if (candidate.abs_value > best.abs_value) {
        return true;
    }
    if (candidate.abs_value == best.abs_value) {
        return hogbom_order_key(candidate.flat_index, ny, nx) <
               hogbom_order_key(best.flat_index, ny, nx);
    }
    return false;
}

static inline bool hogbom_threshold_reached_with_tolerance(float peak_abs, float threshold) {
    if (threshold <= 0.0f) {
        return peak_abs <= threshold;
    }
    const float tolerance = max(0.01f * threshold, 2.0e-8f);
    return peak_abs <= threshold || fabs(peak_abs - threshold) <= tolerance;
}

static inline uint hogbom_stop_reason(float peak_abs, constant HogbomCycleParams &params) {
    const bool threshold_floor_active =
        params.threshold_jy_per_beam > 0.0f &&
        (0.01f * params.threshold_jy_per_beam) < 2.0e-8f &&
        params.cycle_threshold_jy_per_beam <= params.threshold_jy_per_beam;
    if (peak_abs < params.threshold_jy_per_beam ||
        (threshold_floor_active &&
         hogbom_threshold_reached_with_tolerance(peak_abs, params.threshold_jy_per_beam))) {
        return 1u;
    }
    if (params.nsigma_threshold_jy_per_beam > params.threshold_jy_per_beam &&
        peak_abs < params.nsigma_threshold_jy_per_beam) {
        return 2u;
    }
    if (peak_abs < params.cycle_threshold_jy_per_beam) {
        return 3u;
    }
    return 0u;
}

kernel void hogbom_peak_reduce_pixels(
    device const float *residual [[buffer(0)]],
    device const uint *mask [[buffer(1)]],
    device HogbomPeakCandidate *candidates [[buffer(2)]],
    constant HogbomCycleParams &params [[buffer(3)]],
    device const HogbomCycleState *state [[buffer(4)]],
    uint thread_index [[thread_position_in_grid]],
    uint local_index [[thread_index_in_threadgroup]],
    uint group_index [[threadgroup_position_in_grid]]
) {
    threadgroup HogbomPeakCandidate local_candidates[1024];
    HogbomPeakCandidate candidate = hogbom_invalid_candidate();
    if (state->stopped == 0u &&
        thread_index < params.cell_count &&
        (params.has_mask == 0u || mask[thread_index] != 0u)) {
        const float value = residual[thread_index];
        candidate.abs_value = fabs(value);
        candidate.value = value;
        candidate.flat_index = thread_index;
        candidate.valid = 1u;
    }
    local_candidates[local_index] = candidate;
    threadgroup_barrier(mem_flags::mem_threadgroup);

    for (uint stride = params.peak_threads_per_group >> 1; stride > 0u; stride >>= 1) {
        if (local_index < stride) {
            const HogbomPeakCandidate other = local_candidates[local_index + stride];
            const HogbomPeakCandidate best = local_candidates[local_index];
            if (hogbom_candidate_better(other, best, params.ny, params.nx)) {
                local_candidates[local_index] = other;
            }
        }
        threadgroup_barrier(mem_flags::mem_threadgroup);
    }
    if (local_index == 0u) {
        candidates[group_index] = local_candidates[0];
    }
}

kernel void hogbom_reduce_candidates(
    device const HogbomPeakCandidate *input [[buffer(0)]],
    device HogbomPeakCandidate *output [[buffer(1)]],
    constant HogbomReduceParams &params [[buffer(2)]],
    device const HogbomCycleState *state [[buffer(3)]],
    uint thread_index [[thread_position_in_grid]],
    uint local_index [[thread_index_in_threadgroup]],
    uint group_index [[threadgroup_position_in_grid]]
) {
    threadgroup HogbomPeakCandidate local_candidates[1024];
    HogbomPeakCandidate candidate = hogbom_invalid_candidate();
    if (state->stopped == 0u && thread_index < params.candidate_count) {
        candidate = input[thread_index];
    }
    local_candidates[local_index] = candidate;
    threadgroup_barrier(mem_flags::mem_threadgroup);

    for (uint stride = params.threads_per_group >> 1; stride > 0u; stride >>= 1) {
        if (local_index < stride) {
            const HogbomPeakCandidate other = local_candidates[local_index + stride];
            const HogbomPeakCandidate best = local_candidates[local_index];
            if (hogbom_candidate_better(other, best, params.ny, params.nx)) {
                local_candidates[local_index] = other;
            }
        }
        threadgroup_barrier(mem_flags::mem_threadgroup);
    }
    if (local_index == 0u) {
        output[group_index] = local_candidates[0];
    }
}

kernel void hogbom_select_peak_from_candidate(
    device const HogbomPeakCandidate *peak_candidate [[buffer(0)]],
    device HogbomPeakCandidate *selected_peak [[buffer(1)]],
    device HogbomCycleState *state [[buffer(2)]],
    device float *model [[buffer(3)]],
    constant HogbomCycleParams &params [[buffer(4)]],
    device HogbomComponentTrace *component_trace [[buffer(5)]],
    uint thread_index [[thread_position_in_grid]]
) {
    if (thread_index != 0u || state->stopped != 0u) {
        return;
    }
    const HogbomPeakCandidate peak = peak_candidate[0];
    selected_peak[0] = peak;
    state->peak = peak;
    if (peak.valid == 0u) {
        state->stopped = 1u;
        state->stop_reason = 6u;
        return;
    }
    const uint reason = hogbom_stop_reason(peak.abs_value, params);
    if (reason != 0u) {
        state->stopped = 1u;
        state->stop_reason = reason;
        return;
    }
    const float component = params.gain * peak.value;
    state->component = component;
    const uint update_index = state->updates;
    if (params.trace_components != 0u && update_index < params.component_budget) {
        component_trace[update_index].value = peak.value;
        component_trace[update_index].component = component;
        component_trace[update_index].flat_index = peak.flat_index;
        component_trace[update_index].update_index = update_index;
    }
    state->updates = update_index + 1u;
    model[peak.flat_index] += component;
}

kernel void hogbom_subtract_psf_and_find_next_peak(
    device const HogbomPeakCandidate *selected_peak [[buffer(0)]],
    device float *residual [[buffer(1)]],
    device const float *psf [[buffer(2)]],
    device const uint *mask [[buffer(3)]],
    device HogbomPeakCandidate *candidates [[buffer(4)]],
    constant HogbomCycleParams &params [[buffer(5)]],
    device const HogbomCycleState *state [[buffer(6)]],
    uint thread_index [[thread_position_in_grid]],
    uint local_index [[thread_index_in_threadgroup]],
    uint group_index [[threadgroup_position_in_grid]]
) {
    threadgroup HogbomPeakCandidate local_candidates[1024];
    HogbomPeakCandidate candidate = hogbom_invalid_candidate();
    if (state->stopped == 0u && thread_index < params.cell_count) {
        const HogbomPeakCandidate peak = selected_peak[0];
        if (peak.valid != 0u) {
            const uint x = thread_index / params.ny;
            const uint y = thread_index - x * params.ny;
            const uint peak_x = peak.flat_index / params.ny;
            const uint peak_y = peak.flat_index - peak_x * params.ny;
            const int kernel_x = int(x) - int(peak_x) + int(params.nx / 2u);
            const int kernel_y = int(y) - int(peak_y) + int(params.ny / 2u);
            if (kernel_x >= 0 && kernel_y >= 0 &&
                kernel_x < int(params.nx) && kernel_y < int(params.ny)) {
                const uint kernel_index = uint(kernel_x) * params.ny + uint(kernel_y);
                float delta = state->component * psf[kernel_index];
                float updated = residual[thread_index] - delta;
                residual[thread_index] = updated;
            }
        }
        if (params.has_mask == 0u || mask[thread_index] != 0u) {
            const float value = residual[thread_index];
            candidate.abs_value = fabs(value);
            candidate.value = value;
            candidate.flat_index = thread_index;
            candidate.valid = 1u;
        }
    }
    local_candidates[local_index] = candidate;
    threadgroup_barrier(mem_flags::mem_threadgroup);

    for (uint stride = params.peak_threads_per_group >> 1; stride > 0u; stride >>= 1) {
        if (local_index < stride) {
            const HogbomPeakCandidate other = local_candidates[local_index + stride];
            const HogbomPeakCandidate best = local_candidates[local_index];
            if (hogbom_candidate_better(other, best, params.ny, params.nx)) {
                local_candidates[local_index] = other;
            }
        }
        threadgroup_barrier(mem_flags::mem_threadgroup);
    }
    if (local_index == 0u) {
        candidates[group_index] = local_candidates[0];
    }
}
"#;

#[cfg(all(target_os = "macos", not(coverage)))]
const CLARK_MINOR_CYCLE_METAL_SHADER: &str = r#"
#include <metal_stdlib>
using namespace metal;
#pragma clang fp contract(off)

struct ClarkPeakCandidate {
    float abs_value;
    float value;
    uint flat_index;
    uint valid;
};

struct ClarkReduceParams {
    uint candidate_count;
    uint nx;
    uint ny;
    uint threads_per_group;
};

struct ClarkSubcycleParams {
    uint active_count;
    uint nx;
    uint ny;
    uint patch_nx;
    uint patch_ny;
    uint patch_radius_x;
    uint patch_radius_y;
    uint threads_per_group;
    uint component_budget;
    uint cycle_update_start;
    float gain;
    float threshold_jy_per_beam;
    float cycle_threshold_jy_per_beam;
    float nsigma_threshold_jy_per_beam;
    float flux_limit;
    float iter_flux_limit;
    float fac;
    uint _pad0;
};

struct ClarkSubcycleState {
    ClarkPeakCandidate peak;
    float component;
    uint updates;
    uint stopped;
    uint stop_reason;
    float fmn;
    float iter_flux_limit;
};

static inline ClarkPeakCandidate clark_invalid_candidate() {
    ClarkPeakCandidate candidate;
    candidate.abs_value = 0.0f;
    candidate.value = 0.0f;
    candidate.flat_index = 0u;
    candidate.valid = 0u;
    return candidate;
}

static inline bool clark_candidate_better(ClarkPeakCandidate candidate, ClarkPeakCandidate best) {
    if (candidate.valid == 0u) {
        return false;
    }
    if (best.valid == 0u) {
        return true;
    }
    if (candidate.abs_value > best.abs_value) {
        return true;
    }
    if (candidate.abs_value == best.abs_value) {
        return candidate.flat_index < best.flat_index;
    }
    return false;
}

static inline bool clark_threshold_reached_with_tolerance(float peak_abs, float threshold) {
    if (threshold <= 0.0f) {
        return peak_abs <= threshold;
    }
    const float tolerance = max(0.01f * threshold, 2.0e-8f);
    return peak_abs <= threshold || fabs(peak_abs - threshold) <= tolerance;
}

static inline uint clark_stop_reason(float peak_abs, float iter_flux_limit, constant ClarkSubcycleParams &params) {
    const bool threshold_floor_active =
        params.threshold_jy_per_beam > 0.0f &&
        (0.01f * params.threshold_jy_per_beam) < 2.0e-8f &&
        iter_flux_limit <= params.threshold_jy_per_beam;
    if (peak_abs < params.threshold_jy_per_beam ||
        (threshold_floor_active &&
         clark_threshold_reached_with_tolerance(peak_abs, params.threshold_jy_per_beam))) {
        return 1u;
    }
    if (params.nsigma_threshold_jy_per_beam > params.threshold_jy_per_beam &&
        peak_abs < params.nsigma_threshold_jy_per_beam) {
        return 2u;
    }
    if (peak_abs < iter_flux_limit) {
        return 3u;
    }
    return 0u;
}

kernel void clark_peak_active(
    device const float *active_values [[buffer(0)]],
    device ClarkPeakCandidate *candidates [[buffer(1)]],
    constant ClarkSubcycleParams &params [[buffer(2)]],
    device const ClarkSubcycleState *state [[buffer(3)]],
    uint thread_index [[thread_position_in_grid]],
    uint local_index [[thread_index_in_threadgroup]],
    uint group_index [[threadgroup_position_in_grid]]
) {
    threadgroup ClarkPeakCandidate local_candidates[1024];
    ClarkPeakCandidate candidate = clark_invalid_candidate();
    if (state->stopped == 0u && thread_index < params.active_count) {
        const float value = active_values[thread_index];
        candidate.abs_value = fabs(value);
        candidate.value = value;
        candidate.flat_index = thread_index;
        candidate.valid = 1u;
    }
    local_candidates[local_index] = candidate;
    threadgroup_barrier(mem_flags::mem_threadgroup);
    for (uint stride = params.threads_per_group >> 1; stride > 0u; stride >>= 1) {
        if (local_index < stride) {
            const ClarkPeakCandidate other = local_candidates[local_index + stride];
            const ClarkPeakCandidate best = local_candidates[local_index];
            if (clark_candidate_better(other, best)) {
                local_candidates[local_index] = other;
            }
        }
        threadgroup_barrier(mem_flags::mem_threadgroup);
    }
    if (local_index == 0u) {
        candidates[group_index] = local_candidates[0];
    }
}

kernel void clark_reduce_candidates(
    device const ClarkPeakCandidate *input [[buffer(0)]],
    device ClarkPeakCandidate *output [[buffer(1)]],
    constant ClarkReduceParams &params [[buffer(2)]],
    device const ClarkSubcycleState *state [[buffer(3)]],
    uint thread_index [[thread_position_in_grid]],
    uint local_index [[thread_index_in_threadgroup]],
    uint group_index [[threadgroup_position_in_grid]]
) {
    threadgroup ClarkPeakCandidate local_candidates[1024];
    ClarkPeakCandidate candidate = clark_invalid_candidate();
    if (state->stopped == 0u && thread_index < params.candidate_count) {
        candidate = input[thread_index];
    }
    local_candidates[local_index] = candidate;
    threadgroup_barrier(mem_flags::mem_threadgroup);
    for (uint stride = params.threads_per_group >> 1; stride > 0u; stride >>= 1) {
        if (local_index < stride) {
            const ClarkPeakCandidate other = local_candidates[local_index + stride];
            const ClarkPeakCandidate best = local_candidates[local_index];
            if (clark_candidate_better(other, best)) {
                local_candidates[local_index] = other;
            }
        }
        threadgroup_barrier(mem_flags::mem_threadgroup);
    }
    if (local_index == 0u) {
        output[group_index] = local_candidates[0];
    }
}

kernel void clark_select_peak(
    device const ClarkPeakCandidate *peak_candidate [[buffer(0)]],
    device ClarkPeakCandidate *selected_peak [[buffer(1)]],
    device ClarkSubcycleState *state [[buffer(2)]],
    device float *model [[buffer(3)]],
    device float *delta_model [[buffer(4)]],
    constant ClarkSubcycleParams &params [[buffer(5)]],
    device const uint *active_indices [[buffer(6)]],
    uint thread_index [[thread_position_in_grid]]
) {
    if (thread_index != 0u || state->stopped != 0u) {
        return;
    }
    const ClarkPeakCandidate peak = peak_candidate[0];
    selected_peak[0] = peak;
    state->peak = peak;
    if (peak.valid == 0u) {
        state->stopped = 1u;
        state->stop_reason = 6u;
        return;
    }
    const uint reason = clark_stop_reason(peak.abs_value, state->iter_flux_limit, params);
    if (reason != 0u) {
        state->stopped = 1u;
        state->stop_reason = reason;
        return;
    }
    const float component = params.gain * peak.value;
    const uint active_index = peak.flat_index;
    const uint image_index = active_indices[active_index];
    state->component = component;
    state->updates += 1u;
    model[image_index] += component;
    delta_model[image_index] += component;
    const uint total_updates = params.cycle_update_start + state->updates;
    if (total_updates > 0u) {
        state->fmn += params.fac / float(total_updates);
    }
    state->iter_flux_limit = max(params.flux_limit * state->fmn, params.cycle_threshold_jy_per_beam);
}

kernel void clark_subtract_active_and_find_next_peak(
    device const ClarkPeakCandidate *selected_peak [[buffer(0)]],
    device float *active_values [[buffer(1)]],
    device const uint *active_indices [[buffer(2)]],
    device const float *patch [[buffer(3)]],
    device ClarkPeakCandidate *candidates [[buffer(4)]],
    constant ClarkSubcycleParams &params [[buffer(5)]],
    device const ClarkSubcycleState *state [[buffer(6)]],
    uint thread_index [[thread_position_in_grid]],
    uint local_index [[thread_index_in_threadgroup]],
    uint group_index [[threadgroup_position_in_grid]]
) {
    threadgroup ClarkPeakCandidate local_candidates[1024];
    ClarkPeakCandidate candidate = clark_invalid_candidate();
    if (state->stopped == 0u && thread_index < params.active_count) {
        const ClarkPeakCandidate peak = selected_peak[0];
        if (peak.valid != 0u) {
            const uint active_index = thread_index;
            const uint image_index = active_indices[active_index];
            const uint peak_image_index = active_indices[peak.flat_index];
            const uint x = image_index / params.ny;
            const uint y = image_index - x * params.ny;
            const uint peak_x = peak_image_index / params.ny;
            const uint peak_y = peak_image_index - peak_x * params.ny;
            const int patch_x = int(x) - int(peak_x) + int(params.patch_radius_x);
            const int patch_y = int(y) - int(peak_y) + int(params.patch_radius_y);
            if (patch_x >= 0 && patch_y >= 0 &&
                patch_x < int(params.patch_nx) && patch_y < int(params.patch_ny)) {
                const uint patch_index = uint(patch_x) * params.patch_ny + uint(patch_y);
                const float active_delta = state->component * patch[patch_index];
                active_values[active_index] = active_values[active_index] - active_delta;
            }
            const float value = active_values[active_index];
            candidate.abs_value = fabs(value);
            candidate.value = value;
            candidate.flat_index = active_index;
            candidate.valid = 1u;
        }
    }
    local_candidates[local_index] = candidate;
    threadgroup_barrier(mem_flags::mem_threadgroup);
    for (uint stride = params.threads_per_group >> 1; stride > 0u; stride >>= 1) {
        if (local_index < stride) {
            const ClarkPeakCandidate other = local_candidates[local_index + stride];
            const ClarkPeakCandidate best = local_candidates[local_index];
            if (clark_candidate_better(other, best)) {
                local_candidates[local_index] = other;
            }
        }
        threadgroup_barrier(mem_flags::mem_threadgroup);
    }
    if (local_index == 0u) {
        candidates[group_index] = local_candidates[0];
    }
}

kernel void clark_store_peak_only(
    device const ClarkPeakCandidate *peak_candidate [[buffer(0)]],
    device ClarkSubcycleState *state [[buffer(1)]],
    uint thread_index [[thread_position_in_grid]]
) {
    if (thread_index != 0u || state->stopped != 0u) {
        return;
    }
    state->peak = peak_candidate[0];
}
"#;

#[allow(clippy::too_many_arguments)]
fn run_clark_minor_cycle(
    request: &ImagingRequest,
    model: &mut Array2<f32>,
    residual: &mut Array2<f32>,
    psf: &Array2<f32>,
    cycle_reported_niter: usize,
    cycle_threshold_jy_per_beam: f32,
    nsigma_threshold_jy_per_beam: f32,
    psf_patch: &ClarkPsfPatch,
    minor_cycle_backend: StandardMfsMinorCycleBackend,
    stage_timings: &mut ImagingStageTimings,
    minor_progress: &mut StandardMfsMinorCycleProgressReporter<'_>,
) -> Result<HogbomMinorCycleOutcome, ImagingError> {
    match minor_cycle_backend {
        StandardMfsMinorCycleBackend::Cpu => Ok(run_clark_minor_cycle_cpu(
            request,
            model,
            residual,
            psf,
            cycle_reported_niter,
            cycle_threshold_jy_per_beam,
            nsigma_threshold_jy_per_beam,
            psf_patch,
            stage_timings,
            minor_progress,
        )),
        StandardMfsMinorCycleBackend::Metal => run_clark_minor_cycle_metal(
            request,
            model,
            residual,
            psf,
            cycle_reported_niter,
            cycle_threshold_jy_per_beam,
            nsigma_threshold_jy_per_beam,
            psf_patch,
            stage_timings,
            minor_progress,
        ),
    }
}

#[allow(clippy::too_many_arguments)]
fn run_clark_minor_cycle_cpu(
    request: &ImagingRequest,
    model: &mut Array2<f32>,
    residual: &mut Array2<f32>,
    psf: &Array2<f32>,
    cycle_reported_niter: usize,
    cycle_threshold_jy_per_beam: f32,
    nsigma_threshold_jy_per_beam: f32,
    psf_patch: &ClarkPsfPatch,
    stage_timings: &mut ImagingStageTimings,
    minor_progress: &mut StandardMfsMinorCycleProgressReporter<'_>,
) -> HogbomMinorCycleOutcome {
    let mut cycle_component_updates = 0usize;
    let mut updated_model = false;
    let mut stop_reason = None;
    let minor_started = Instant::now();
    let image_pixels = residual.len();
    let mut peak_search_elapsed = Duration::ZERO;
    let mut active_set_build_elapsed = Duration::ZERO;
    let mut model_update_elapsed = Duration::ZERO;
    let mut subtract_elapsed = Duration::ZERO;
    let mut peak_searches = 0usize;
    let mut model_updates = 0usize;
    let mut subtract_updates = 0usize;
    let mut pixels_searched = 0usize;
    let mut pixels_touched = 0usize;
    let mut approximate_peak = peak_abs_value_masked(residual, request.clean_mask.as_ref());
    let mut previous_approximate_peak = approximate_peak;
    let mut factor = 1.5f32 / 4.5f32;
    let mut warn_flag = false;
    let mut max_minor_iterations = cycle_reported_niter;
    if psf_patch.max_exterior_abs > 0.5 {
        max_minor_iterations = max_minor_iterations.min(5);
    } else if psf_patch.max_exterior_abs > 0.35 {
        max_minor_iterations = max_minor_iterations.min(50);
    }
    let mut subcycle = 0usize;
    while cycle_component_updates < cycle_reported_niter && subcycle < CASA_CLARK_MAX_MAJOR_CYCLES {
        if let Some(reason) = minor_cycle_stop_reason(
            approximate_peak,
            request.clean.threshold_jy_per_beam,
            cycle_threshold_jy_per_beam,
            nsigma_threshold_jy_per_beam,
        ) {
            stop_reason = Some(reason);
            break;
        }

        let mut flux_limit = approximate_peak * psf_patch.max_exterior_abs * factor;
        if factor > 1.0 {
            flux_limit = flux_limit.min(0.95 * approximate_peak);
        }
        let selection_limit = flux_limit.max(cycle_threshold_jy_per_beam);
        let active_set_started = Instant::now();
        let mut active_pixels =
            collect_clark_active_pixels(residual, request.clean_mask.as_ref(), selection_limit);
        active_set_build_elapsed += active_set_started.elapsed();
        pixels_searched = pixels_searched.saturating_add(image_pixels);
        let (patch_nx, patch_ny) = psf_patch.patch.dim();
        append_clark_trace(format!(
            "{{\"event\":\"subcycle_start\",\"subcycle\":{},\"cycle_update_start\":{},\"reffreq_hz\":{:.17e},\"selected_frequency_min_hz\":{:.17e},\"selected_frequency_max_hz\":{:.17e},\"cycle_peak_abs\":{:.17e},\"max_exterior_abs\":{:.17e},\"factor\":{:.17e},\"flux_limit\":{:.17e},\"cycle_threshold\":{:.17e},\"selection_limit\":{:.17e},\"active_pixels\":{},\"cycle_reported_niter\":{},\"psf_patch_nx\":{},\"psf_patch_ny\":{},\"psf_patch_radius_x\":{},\"psf_patch_radius_y\":{},\"algorithm\":\"casa_clark_lat_solve\"}}",
            subcycle,
            cycle_component_updates,
            request.reffreq_hz,
            request.selected_frequency_range_hz[0],
            request.selected_frequency_range_hz[1],
            approximate_peak,
            psf_patch.max_exterior_abs,
            factor,
            flux_limit,
            cycle_threshold_jy_per_beam,
            selection_limit,
            active_pixels.len(),
            cycle_reported_niter,
            patch_nx,
            patch_ny,
            psf_patch.radius_x,
            psf_patch.radius_y,
        ));
        if active_pixels.is_empty() {
            if warn_flag {
                stop_reason = Some(CleanStopReason::NoCleanablePixels);
                break;
            }
            factor *= 1.2;
            warn_flag = true;
            subcycle = subcycle.saturating_add(1);
            continue;
        }

        let subcycle_limit =
            (cycle_reported_niter - cycle_component_updates).min(max_minor_iterations);
        let mut subcycle_updates = 0usize;
        let mut subcycle_delta_model = Array2::<f32>::zeros(model.dim());
        let mut fmn = 0.0f32;
        let mut iter_flux_limit = selection_limit;
        let subcycle_initial_peak = peak_clark_active_pixel(&active_pixels)
            .map(|(_, pixel)| pixel.value.abs())
            .unwrap_or(0.0);
        let fac = if flux_limit > 0.0 && subcycle_initial_peak > 0.0 {
            subcycle_initial_peak / flux_limit
        } else {
            1.0
        };
        while subcycle_updates < subcycle_limit {
            let active_len = active_pixels.len();
            let active_peak_started = Instant::now();
            let active_peak = peak_clark_active_pixel(&active_pixels);
            peak_search_elapsed += active_peak_started.elapsed();
            peak_searches = peak_searches.saturating_add(1);
            pixels_searched = pixels_searched.saturating_add(active_len);
            let Some((_, peak_pixel)) = active_peak else {
                break;
            };
            let peak_abs = peak_pixel.value.abs();
            if let Some(reason) = minor_cycle_stop_reason(
                peak_abs,
                request.clean.threshold_jy_per_beam,
                iter_flux_limit,
                nsigma_threshold_jy_per_beam,
            ) {
                stop_reason = Some(reason);
                append_clark_trace(format!(
                    "{{\"event\":\"stop\",\"subcycle\":{},\"cycle_update\":{},\"subcycle_update\":{},\"reffreq_hz\":{:.17e},\"reason\":\"{:?}\",\"peak_abs\":{:.17e},\"iter_flux_limit\":{:.17e}}}",
                    subcycle,
                    cycle_component_updates,
                    subcycle_updates,
                    request.reffreq_hz,
                    reason,
                    peak_abs,
                    iter_flux_limit
                ));
                break;
            }
            let component = request.clean.gain * peak_pixel.value;
            append_clark_trace(format!(
                "{{\"event\":\"component\",\"subcycle\":{},\"cycle_update\":{},\"subcycle_update\":{},\"reffreq_hz\":{:.17e},\"x\":{},\"y\":{},\"peak\":{:.17e},\"component\":{:.17e},\"iter_flux_limit\":{:.17e},\"fmn\":{:.17e}}}",
                subcycle,
                cycle_component_updates,
                subcycle_updates,
                request.reffreq_hz,
                peak_pixel.x,
                peak_pixel.y,
                peak_pixel.value,
                component,
                iter_flux_limit,
                fmn
            ));
            let model_update_started = Instant::now();
            model[(peak_pixel.x, peak_pixel.y)] += component;
            subcycle_delta_model[(peak_pixel.x, peak_pixel.y)] += component;
            model_update_elapsed += model_update_started.elapsed();
            let subtract_started = Instant::now();
            subtract_clark_component_from_active(
                &mut active_pixels,
                peak_pixel.x,
                peak_pixel.y,
                component,
                psf_patch,
            );
            subtract_elapsed += subtract_started.elapsed();
            subtract_updates = subtract_updates.saturating_add(1);
            pixels_touched = pixels_touched.saturating_add(active_len);
            cycle_component_updates += 1;
            subcycle_updates += 1;
            model_updates = model_updates.saturating_add(1);
            updated_model = true;
            fmn += fac / cycle_component_updates as f32;
            iter_flux_limit = (flux_limit * fmn).max(cycle_threshold_jy_per_beam);
            minor_progress.emit(cycle_component_updates, Some(peak_abs));
        }

        approximate_peak = peak_clark_active_pixel(&active_pixels)
            .map(|(_, pixel)| pixel.value.abs())
            .unwrap_or(0.0);
        if subcycle_updates > 0 {
            *residual = &*residual - &fft_convolve_real(psf, &subcycle_delta_model);
        }
        if approximate_peak > previous_approximate_peak {
            factor *= 3.0;
            max_minor_iterations = max_minor_iterations.min(10);
            warn_flag = true;
        }
        previous_approximate_peak = approximate_peak;
        if subcycle_updates == 0 {
            break;
        }
        if stop_reason.is_some() && cycle_component_updates < cycle_reported_niter {
            stop_reason = None;
        }
        subcycle = subcycle.saturating_add(1);
    }
    if !updated_model && stop_reason.is_none() {
        stop_reason = Some(CleanStopReason::NoCleanablePixels);
    }
    let minor_elapsed = minor_started.elapsed();
    stage_timings.minor_cycle += minor_elapsed;
    stage_timings.minor_cycle_solve += minor_elapsed;
    stage_timings.deconvolver_peak_search += peak_search_elapsed;
    stage_timings.deconvolver_active_set_build += active_set_build_elapsed;
    stage_timings.deconvolver_model_update += model_update_elapsed;
    stage_timings.deconvolver_psf_subtract += subtract_elapsed;
    stage_timings.deconvolver_peak_searches = stage_timings
        .deconvolver_peak_searches
        .saturating_add(peak_searches as u64);
    stage_timings.deconvolver_model_updates = stage_timings
        .deconvolver_model_updates
        .saturating_add(model_updates as u64);
    stage_timings.deconvolver_subtract_updates = stage_timings
        .deconvolver_subtract_updates
        .saturating_add(subtract_updates as u64);
    stage_timings.deconvolver_pixels_searched = stage_timings
        .deconvolver_pixels_searched
        .saturating_add(pixels_searched as u64);
    stage_timings.deconvolver_pixels_touched = stage_timings
        .deconvolver_pixels_touched
        .saturating_add(pixels_touched as u64);
    HogbomMinorCycleOutcome {
        updated_model,
        actual_updates: cycle_component_updates,
        reported_updates: cycle_component_updates,
        stop_reason,
        final_cycle_threshold_jy_per_beam: cycle_threshold_jy_per_beam,
        final_nsigma_threshold_jy_per_beam: nsigma_threshold_jy_per_beam,
    }
}

#[allow(clippy::too_many_arguments)]
#[cfg(any(not(target_os = "macos"), coverage))]
fn run_clark_minor_cycle_metal(
    _request: &ImagingRequest,
    _model: &mut Array2<f32>,
    _residual: &mut Array2<f32>,
    _psf: &Array2<f32>,
    _cycle_reported_niter: usize,
    _cycle_threshold_jy_per_beam: f32,
    _nsigma_threshold_jy_per_beam: f32,
    _psf_patch: &ClarkPsfPatch,
    _stage_timings: &mut ImagingStageTimings,
    _minor_progress: &mut StandardMfsMinorCycleProgressReporter<'_>,
) -> Result<HogbomMinorCycleOutcome, ImagingError> {
    Err(ImagingError::Unsupported(
        "Clark minor-cycle backend 'metal' requires macOS Metal".to_string(),
    ))
}

#[allow(clippy::too_many_arguments)]
#[cfg(all(target_os = "macos", not(coverage)))]
fn run_clark_minor_cycle_metal(
    request: &ImagingRequest,
    model: &mut Array2<f32>,
    residual: &mut Array2<f32>,
    psf: &Array2<f32>,
    cycle_reported_niter: usize,
    cycle_threshold_jy_per_beam: f32,
    nsigma_threshold_jy_per_beam: f32,
    psf_patch: &ClarkPsfPatch,
    stage_timings: &mut ImagingStageTimings,
    minor_progress: &mut StandardMfsMinorCycleProgressReporter<'_>,
) -> Result<HogbomMinorCycleOutcome, ImagingError> {
    use std::slice;

    use objc2_metal::{MTLBuffer, MTLCreateSystemDefaultDevice, MTLDevice, MTLResourceOptions};

    let (nx, ny) = residual.dim();
    if nx == 0 || ny == 0 {
        return Ok(HogbomMinorCycleOutcome {
            updated_model: false,
            actual_updates: 0,
            reported_updates: 0,
            stop_reason: Some(CleanStopReason::NoCleanablePixels),
            final_cycle_threshold_jy_per_beam: cycle_threshold_jy_per_beam,
            final_nsigma_threshold_jy_per_beam: nsigma_threshold_jy_per_beam,
        });
    }
    if model.dim() != (nx, ny) || psf.dim() != (nx, ny) {
        return Err(ImagingError::InvalidRequest(
            "Clark Metal minor cycle requires model, residual, and PSF shapes to match".to_string(),
        ));
    }
    let cell_count = nx
        .checked_mul(ny)
        .ok_or_else(|| ImagingError::InvalidRequest("Clark image is too large".to_string()))?;
    let cell_count_u32 = u32::try_from(cell_count).map_err(|_| {
        ImagingError::InvalidRequest("Clark Metal image cell count exceeds u32".to_string())
    })?;
    let nx_u32 = u32::try_from(nx).map_err(|_| {
        ImagingError::InvalidRequest("Clark Metal image width exceeds u32".to_string())
    })?;
    let ny_u32 = u32::try_from(ny).map_err(|_| {
        ImagingError::InvalidRequest("Clark Metal image height exceeds u32".to_string())
    })?;
    let (patch_nx, patch_ny) = psf_patch.patch.dim();
    let patch_nx_u32 = u32::try_from(patch_nx).map_err(|_| {
        ImagingError::InvalidRequest("Clark Metal PSF patch width exceeds u32".to_string())
    })?;
    let patch_ny_u32 = u32::try_from(patch_ny).map_err(|_| {
        ImagingError::InvalidRequest("Clark Metal PSF patch height exceeds u32".to_string())
    })?;
    let patch_radius_x_u32 = u32::try_from(psf_patch.radius_x).map_err(|_| {
        ImagingError::InvalidRequest("Clark Metal PSF patch x radius exceeds u32".to_string())
    })?;
    let patch_radius_y_u32 = u32::try_from(psf_patch.radius_y).map_err(|_| {
        ImagingError::InvalidRequest("Clark Metal PSF patch y radius exceeds u32".to_string())
    })?;

    let total_started = Instant::now();
    let collect_profile = profile::standard_mfs_profile_detail_enabled();
    let setup_started = Instant::now();
    let device = MTLCreateSystemDefaultDevice().ok_or_else(|| {
        ImagingError::Unsupported(
            "Clark minor-cycle backend 'metal' could not find a default Metal device".to_string(),
        )
    })?;
    let queue = device.newCommandQueue().ok_or_else(|| {
        ImagingError::Unsupported(
            "Clark minor-cycle backend 'metal' could not create a Metal command queue".to_string(),
        )
    })?;
    let source = objc2_foundation::NSString::from_str(CLARK_MINOR_CYCLE_METAL_SHADER);
    let library = device
        .newLibraryWithSource_options_error(&source, None)
        .map_err(|error| {
            ImagingError::Unsupported(format!(
                "Clark minor-cycle backend 'metal' failed to compile shader: {error:?}"
            ))
        })?;
    let active_peak_pipeline = hogbom_metal_pipeline(&device, &library, "clark_peak_active")?;
    let reduce_pipeline = hogbom_metal_pipeline(&device, &library, "clark_reduce_candidates")?;
    let select_pipeline = hogbom_metal_pipeline(&device, &library, "clark_select_peak")?;
    let subtract_peak_pipeline = hogbom_metal_pipeline(
        &device,
        &library,
        "clark_subtract_active_and_find_next_peak",
    )?;
    let store_peak_pipeline = hogbom_metal_pipeline(&device, &library, "clark_store_peak_only")?;
    let storage_options = MTLResourceOptions::StorageModeShared;
    let model_values = hogbom_flatten_array2_x_major(model);
    let model_buffer =
        hogbom_metal_buffer_from_slice(&device, model_values.as_slice(), storage_options, "model")?;
    let patch_values = hogbom_flatten_array2_x_major(&psf_patch.patch);
    let patch_buffer =
        hogbom_metal_buffer_from_slice(&device, patch_values.as_slice(), storage_options, "patch")?;
    let setup_elapsed = setup_started.elapsed();

    let mut cycle_component_updates = 0usize;
    let mut updated_model = false;
    let mut stop_reason = None;
    let mut peak_search_elapsed = Duration::ZERO;
    let mut active_set_build_elapsed = Duration::ZERO;
    let mut model_update_elapsed = Duration::ZERO;
    let mut subtract_elapsed = Duration::ZERO;
    let mut peak_searches = 0usize;
    let mut model_updates = 0usize;
    let mut subtract_updates = 0usize;
    let mut pixels_searched = 0usize;
    let mut pixels_touched = 0usize;
    let mut approximate_peak = peak_abs_value_masked(residual, request.clean_mask.as_ref());
    let mut previous_approximate_peak = approximate_peak;
    let mut factor = 1.5f32 / 4.5f32;
    let mut warn_flag = false;
    let mut max_minor_iterations = cycle_reported_niter;
    if psf_patch.max_exterior_abs > 0.5 {
        max_minor_iterations = max_minor_iterations.min(5);
    } else if psf_patch.max_exterior_abs > 0.35 {
        max_minor_iterations = max_minor_iterations.min(50);
    }
    let mut subcycle = 0usize;
    let mut command_kernel_elapsed = Duration::ZERO;
    let mut command_wall_elapsed = Duration::ZERO;
    let mut readback_elapsed = Duration::ZERO;

    while cycle_component_updates < cycle_reported_niter && subcycle < CASA_CLARK_MAX_MAJOR_CYCLES {
        if let Some(reason) = minor_cycle_stop_reason(
            approximate_peak,
            request.clean.threshold_jy_per_beam,
            cycle_threshold_jy_per_beam,
            nsigma_threshold_jy_per_beam,
        ) {
            stop_reason = Some(reason);
            break;
        }

        let mut flux_limit = approximate_peak * psf_patch.max_exterior_abs * factor;
        if factor > 1.0 {
            flux_limit = flux_limit.min(0.95 * approximate_peak);
        }
        let selection_limit = flux_limit.max(cycle_threshold_jy_per_beam);
        let active_set_started = Instant::now();
        let active_pixels =
            collect_clark_active_pixels(residual, request.clean_mask.as_ref(), selection_limit);
        active_set_build_elapsed += active_set_started.elapsed();
        pixels_searched = pixels_searched.saturating_add(cell_count);
        if active_pixels.is_empty() {
            if warn_flag {
                stop_reason = Some(CleanStopReason::NoCleanablePixels);
                break;
            }
            factor *= 1.2;
            warn_flag = true;
            subcycle = subcycle.saturating_add(1);
            continue;
        }

        let subcycle_limit =
            (cycle_reported_niter - cycle_component_updates).min(max_minor_iterations);
        let subcycle_initial_peak = peak_clark_active_pixel(&active_pixels)
            .map(|(_, pixel)| pixel.value.abs())
            .unwrap_or(0.0);
        let fac = if flux_limit > 0.0 && subcycle_initial_peak > 0.0 {
            subcycle_initial_peak / flux_limit
        } else {
            1.0
        };
        let subcycle_started = Instant::now();
        let subcycle_result = clark_metal_run_active_subcycle(
            &queue,
            &device,
            &active_peak_pipeline,
            &reduce_pipeline,
            &select_pipeline,
            &subtract_peak_pipeline,
            &store_peak_pipeline,
            &model_buffer,
            &patch_buffer,
            storage_options,
            &active_pixels,
            cell_count_u32,
            nx_u32,
            ny_u32,
            patch_nx_u32,
            patch_ny_u32,
            patch_radius_x_u32,
            patch_radius_y_u32,
            subcycle_limit,
            cycle_component_updates,
            request.clean.gain,
            request.clean.threshold_jy_per_beam,
            cycle_threshold_jy_per_beam,
            nsigma_threshold_jy_per_beam,
            flux_limit,
            selection_limit,
            fac,
            minor_progress,
        )?;
        command_kernel_elapsed += subcycle_result.command_timing.kernel_elapsed;
        command_wall_elapsed += subcycle_started.elapsed();
        readback_elapsed += subcycle_result.readback_elapsed;
        peak_search_elapsed += subcycle_result.command_timing.kernel_elapsed;
        peak_searches = peak_searches.saturating_add(subcycle_result.peak_searches);
        subtract_elapsed += subcycle_result.command_timing.kernel_elapsed;
        subtract_updates = subtract_updates.saturating_add(subcycle_result.actual_updates);
        pixels_searched = pixels_searched.saturating_add(
            subcycle_result
                .peak_searches
                .saturating_mul(active_pixels.len()),
        );
        pixels_touched = pixels_touched.saturating_add(
            subcycle_result
                .actual_updates
                .saturating_mul(active_pixels.len()),
        );
        model_updates = model_updates.saturating_add(subcycle_result.actual_updates);
        model_update_elapsed += Duration::ZERO;
        cycle_component_updates =
            cycle_component_updates.saturating_add(subcycle_result.actual_updates);
        updated_model |= subcycle_result.actual_updates > 0;
        approximate_peak = subcycle_result.final_peak_abs;

        if subcycle_result.actual_updates > 0 {
            let delta_model = Array2::from_shape_vec((nx, ny), subcycle_result.delta_model)
                .map_err(|error| {
                    ImagingError::InvalidRequest(format!(
                        "Clark Metal delta model shape mismatch: {error}"
                    ))
                })?;
            *residual = &*residual - &fft_convolve_real(psf, &delta_model);
        }
        if let Some(reason) = subcycle_result.stop_reason {
            stop_reason = Some(reason);
        }
        if approximate_peak > previous_approximate_peak {
            factor *= 3.0;
            max_minor_iterations = max_minor_iterations.min(10);
            warn_flag = true;
        }
        previous_approximate_peak = approximate_peak;
        if subcycle_result.actual_updates == 0 {
            break;
        }
        if stop_reason.is_some() && cycle_component_updates < cycle_reported_niter {
            stop_reason = None;
        }
        subcycle = subcycle.saturating_add(1);
    }

    if !updated_model && stop_reason.is_none() {
        stop_reason = Some(CleanStopReason::NoCleanablePixels);
    }
    let readback_started = Instant::now();
    let model_slice = unsafe {
        slice::from_raw_parts(model_buffer.contents().as_ptr().cast::<f32>(), cell_count)
    };
    copy_x_major_slice_to_array2(model, model_slice)?;
    readback_elapsed += readback_started.elapsed();

    let minor_elapsed = total_started.elapsed();
    if collect_profile {
        eprintln!(
            "standard_mfs_clark_minor_cycle_summary backend=metal_active_set updates={} reported_budget={} stop_reason={:?} image_pixels={} peak_searches={} subtract_updates={} setup_ms={:.3} command_wall_ms={:.3} command_gpu_ms={:.3} readback_ms={:.3} total_ms={:.3}",
            cycle_component_updates,
            cycle_reported_niter,
            stop_reason,
            cell_count,
            peak_searches,
            subtract_updates,
            profile::millis(setup_elapsed),
            profile::millis(command_wall_elapsed),
            profile::millis(command_kernel_elapsed),
            profile::millis(readback_elapsed),
            profile::millis(minor_elapsed),
        );
    }
    stage_timings.minor_cycle += minor_elapsed;
    stage_timings.minor_cycle_solve += minor_elapsed;
    stage_timings.deconvolver_peak_search += peak_search_elapsed;
    stage_timings.deconvolver_active_set_build += active_set_build_elapsed;
    stage_timings.deconvolver_model_update += model_update_elapsed;
    stage_timings.deconvolver_psf_subtract += subtract_elapsed;
    stage_timings.deconvolver_peak_searches = stage_timings
        .deconvolver_peak_searches
        .saturating_add(peak_searches as u64);
    stage_timings.deconvolver_model_updates = stage_timings
        .deconvolver_model_updates
        .saturating_add(model_updates as u64);
    stage_timings.deconvolver_subtract_updates = stage_timings
        .deconvolver_subtract_updates
        .saturating_add(subtract_updates as u64);
    stage_timings.deconvolver_pixels_searched = stage_timings
        .deconvolver_pixels_searched
        .saturating_add(pixels_searched as u64);
    stage_timings.deconvolver_pixels_touched = stage_timings
        .deconvolver_pixels_touched
        .saturating_add(pixels_touched as u64);

    Ok(HogbomMinorCycleOutcome {
        updated_model,
        actual_updates: cycle_component_updates,
        reported_updates: cycle_component_updates.min(cycle_reported_niter),
        stop_reason,
        final_cycle_threshold_jy_per_beam: cycle_threshold_jy_per_beam,
        final_nsigma_threshold_jy_per_beam: nsigma_threshold_jy_per_beam,
    })
}

#[cfg(all(target_os = "macos", not(coverage)))]
struct ClarkMetalSubcycleResult {
    actual_updates: usize,
    stop_reason: Option<CleanStopReason>,
    final_peak_abs: f32,
    peak_searches: usize,
    delta_model: Vec<f32>,
    command_timing: HogbomMetalCommandTiming,
    readback_elapsed: Duration,
}

#[cfg(all(target_os = "macos", not(coverage)))]
#[allow(clippy::too_many_arguments)]
fn clark_metal_run_active_subcycle(
    queue: &objc2::runtime::ProtocolObject<dyn objc2_metal::MTLCommandQueue>,
    device: &objc2::runtime::ProtocolObject<dyn objc2_metal::MTLDevice>,
    active_peak_pipeline: &objc2::runtime::ProtocolObject<dyn objc2_metal::MTLComputePipelineState>,
    reduce_pipeline: &objc2::runtime::ProtocolObject<dyn objc2_metal::MTLComputePipelineState>,
    select_pipeline: &objc2::runtime::ProtocolObject<dyn objc2_metal::MTLComputePipelineState>,
    subtract_peak_pipeline: &objc2::runtime::ProtocolObject<
        dyn objc2_metal::MTLComputePipelineState,
    >,
    store_peak_pipeline: &objc2::runtime::ProtocolObject<dyn objc2_metal::MTLComputePipelineState>,
    model_buffer: &objc2::runtime::ProtocolObject<dyn objc2_metal::MTLBuffer>,
    patch_buffer: &objc2::runtime::ProtocolObject<dyn objc2_metal::MTLBuffer>,
    storage_options: objc2_metal::MTLResourceOptions,
    active_pixels: &ClarkActiveSet,
    cell_count: u32,
    nx: u32,
    ny: u32,
    patch_nx: u32,
    patch_ny: u32,
    patch_radius_x: u32,
    patch_radius_y: u32,
    component_budget: usize,
    cycle_update_start: usize,
    gain: f32,
    threshold_jy_per_beam: f32,
    cycle_threshold_jy_per_beam: f32,
    nsigma_threshold_jy_per_beam: f32,
    flux_limit: f32,
    iter_flux_limit: f32,
    fac: f32,
    minor_progress: &mut StandardMfsMinorCycleProgressReporter<'_>,
) -> Result<ClarkMetalSubcycleResult, ImagingError> {
    use std::slice;

    use objc2_metal::{
        MTLBuffer, MTLCommandBuffer, MTLCommandBufferStatus, MTLCommandEncoder, MTLCommandQueue,
        MTLComputeCommandEncoder, MTLDevice, MTLSize,
    };

    let active_count = active_pixels.len();
    if active_count == 0 || component_budget == 0 {
        return Ok(ClarkMetalSubcycleResult {
            actual_updates: 0,
            stop_reason: Some(CleanStopReason::NoCleanablePixels),
            final_peak_abs: 0.0,
            peak_searches: 0,
            delta_model: vec![0.0; usize::try_from(cell_count).unwrap_or(0)],
            command_timing: HogbomMetalCommandTiming::default(),
            readback_elapsed: Duration::ZERO,
        });
    }
    let active_count_u32 = u32::try_from(active_count).map_err(|_| {
        ImagingError::InvalidRequest("Clark Metal active set exceeds u32".to_string())
    })?;
    let component_budget_u32 = u32::try_from(component_budget).map_err(|_| {
        ImagingError::InvalidRequest("Clark Metal component budget exceeds u32".to_string())
    })?;
    let cycle_update_start_u32 = u32::try_from(cycle_update_start).map_err(|_| {
        ImagingError::InvalidRequest("Clark Metal cycle update count exceeds u32".to_string())
    })?;
    let active_values = active_pixels
        .pixels
        .iter()
        .map(|pixel| pixel.value)
        .collect::<Vec<_>>();
    let active_indices = active_pixels
        .pixels
        .iter()
        .map(|pixel| {
            let flat = pixel
                .x
                .saturating_mul(active_pixels.image_ny)
                .saturating_add(pixel.y);
            u32::try_from(flat).map_err(|_| {
                ImagingError::InvalidRequest(
                    "Clark Metal active pixel index exceeds u32".to_string(),
                )
            })
        })
        .collect::<Result<Vec<_>, _>>()?;
    let cell_count_usize = usize::try_from(cell_count).map_err(|_| {
        ImagingError::InvalidRequest("Clark Metal cell count overflowed".to_string())
    })?;
    let zero_delta = vec![0.0f32; cell_count_usize];
    let active_values_buffer = hogbom_metal_buffer_from_slice(
        device,
        active_values.as_slice(),
        storage_options,
        "active",
    )?;
    let active_indices_buffer = hogbom_metal_buffer_from_slice(
        device,
        active_indices.as_slice(),
        storage_options,
        "active indices",
    )?;
    let delta_model_buffer =
        hogbom_metal_buffer_from_slice(device, zero_delta.as_slice(), storage_options, "delta")?;

    let active_threads_per_group =
        hogbom_metal_threads_per_group(active_peak_pipeline, active_count);
    let first_candidate_count = active_count.div_ceil(active_threads_per_group);
    let candidate_bytes = first_candidate_count
        .max(1)
        .checked_mul(std::mem::size_of::<HogbomMetalPeakCandidate>())
        .ok_or_else(|| {
            ImagingError::InvalidRequest("Clark Metal candidate buffer is too large".to_string())
        })?;
    let candidate_a = device
        .newBufferWithLength_options(candidate_bytes, storage_options)
        .ok_or_else(|| {
            ImagingError::Unsupported(
                "Clark minor-cycle backend 'metal' could not allocate candidate buffer".to_string(),
            )
        })?;
    let candidate_b = device
        .newBufferWithLength_options(candidate_bytes, storage_options)
        .ok_or_else(|| {
            ImagingError::Unsupported(
                "Clark minor-cycle backend 'metal' could not allocate reduction buffer".to_string(),
            )
        })?;
    let selected_peak_buffer = hogbom_metal_buffer_from_slice(
        device,
        &[HogbomMetalPeakCandidate::default()],
        storage_options,
        "selected peak",
    )?;
    let params = ClarkMetalSubcycleParams {
        active_count: active_count_u32,
        nx,
        ny,
        patch_nx,
        patch_ny,
        patch_radius_x,
        patch_radius_y,
        threads_per_group: u32::try_from(active_threads_per_group).map_err(|_| {
            ImagingError::InvalidRequest(
                "Clark Metal active threadgroup width exceeds u32".to_string(),
            )
        })?,
        component_budget: component_budget_u32,
        cycle_update_start: cycle_update_start_u32,
        gain,
        threshold_jy_per_beam,
        cycle_threshold_jy_per_beam,
        nsigma_threshold_jy_per_beam,
        flux_limit,
        iter_flux_limit,
        fac,
        _pad0: 0,
    };
    let params_buffer =
        hogbom_metal_params_buffer(device, &params, storage_options, "Clark subcycle params")?;
    let initial_state = ClarkMetalSubcycleState {
        iter_flux_limit,
        ..Default::default()
    };
    let state_buffer =
        hogbom_metal_buffer_from_slice(device, &[initial_state], storage_options, "Clark state")?;

    let mut reduce_param_buffers = Vec::new();
    let mut reduce_plan = Vec::new();
    let mut input_a = true;
    let mut current_count = first_candidate_count.max(1);
    while current_count > 1 {
        let reduce_threads_per_group =
            hogbom_metal_threads_per_group(reduce_pipeline, current_count);
        let output_count = current_count.div_ceil(reduce_threads_per_group);
        let reduce_params = HogbomMetalReduceParams {
            candidate_count: u32::try_from(current_count).map_err(|_| {
                ImagingError::InvalidRequest("Clark Metal candidate count exceeds u32".to_string())
            })?,
            nx,
            ny,
            threads_per_group: u32::try_from(reduce_threads_per_group).map_err(|_| {
                ImagingError::InvalidRequest(
                    "Clark Metal reduce threadgroup width exceeds u32".to_string(),
                )
            })?,
        };
        let reduce_params_buffer = hogbom_metal_params_buffer(
            device,
            &reduce_params,
            storage_options,
            "Clark reduce params",
        )?;
        reduce_param_buffers.push(reduce_params_buffer);
        reduce_plan.push((input_a, output_count, reduce_threads_per_group));
        input_a = !input_a;
        current_count = output_count.max(1);
    }
    let final_candidate_from_a = input_a;
    let final_candidate_buffer = if final_candidate_from_a {
        &candidate_a
    } else {
        &candidate_b
    };

    let active_group_count = active_count.div_ceil(active_threads_per_group);
    let command_component_budget = component_budget.min(64);
    let mut command_timing = HogbomMetalCommandTiming::default();
    let mut peak_searches = 0usize;
    let mut candidate_ready = false;
    let mut final_state = initial_state;
    while usize::try_from(final_state.updates).unwrap_or(usize::MAX) < component_budget
        && final_state.stopped == 0
    {
        let updates_done = usize::try_from(final_state.updates).map_err(|_| {
            ImagingError::InvalidRequest("Clark Metal update count overflowed".to_string())
        })?;
        let updates_remaining = component_budget.saturating_sub(updates_done);
        if updates_remaining == 0 {
            break;
        }
        let chunk_updates = updates_remaining.min(command_component_budget);
        let command_buffer = queue.commandBuffer().ok_or_else(|| {
            ImagingError::Unsupported(
                "Clark minor-cycle backend 'metal' could not create command buffer".to_string(),
            )
        })?;
        if !candidate_ready {
            let active_encoder = command_buffer.computeCommandEncoder().ok_or_else(|| {
                ImagingError::Unsupported(
                    "Clark minor-cycle backend 'metal' could not create active peak encoder"
                        .to_string(),
                )
            })?;
            active_encoder.setComputePipelineState(active_peak_pipeline);
            unsafe {
                active_encoder.setBuffer_offset_atIndex(Some(&active_values_buffer), 0, 0);
                active_encoder.setBuffer_offset_atIndex(Some(&candidate_a), 0, 1);
                active_encoder.setBuffer_offset_atIndex(Some(&params_buffer), 0, 2);
                active_encoder.setBuffer_offset_atIndex(Some(&state_buffer), 0, 3);
            }
            active_encoder.dispatchThreadgroups_threadsPerThreadgroup(
                MTLSize {
                    width: active_group_count,
                    height: 1,
                    depth: 1,
                },
                MTLSize {
                    width: active_threads_per_group,
                    height: 1,
                    depth: 1,
                },
            );
            active_encoder.endEncoding();
            peak_searches = peak_searches.saturating_add(1);
            hogbom_metal_encode_reduce_plan(
                &command_buffer,
                reduce_pipeline,
                &candidate_a,
                &candidate_b,
                &reduce_param_buffers,
                &reduce_plan,
                &state_buffer,
            )?;
        }
        clark_metal_encode_select_peak(
            &command_buffer,
            select_pipeline,
            final_candidate_buffer,
            &selected_peak_buffer,
            &state_buffer,
            model_buffer,
            &delta_model_buffer,
            &params_buffer,
            &active_indices_buffer,
        )?;

        for component_index in 0..chunk_updates {
            let subtract_encoder = command_buffer.computeCommandEncoder().ok_or_else(|| {
                ImagingError::Unsupported(
                    "Clark minor-cycle backend 'metal' could not create subtract encoder"
                        .to_string(),
                )
            })?;
            subtract_encoder.setComputePipelineState(subtract_peak_pipeline);
            unsafe {
                subtract_encoder.setBuffer_offset_atIndex(Some(&selected_peak_buffer), 0, 0);
                subtract_encoder.setBuffer_offset_atIndex(Some(&active_values_buffer), 0, 1);
                subtract_encoder.setBuffer_offset_atIndex(Some(&active_indices_buffer), 0, 2);
                subtract_encoder.setBuffer_offset_atIndex(Some(patch_buffer), 0, 3);
                subtract_encoder.setBuffer_offset_atIndex(Some(&candidate_a), 0, 4);
                subtract_encoder.setBuffer_offset_atIndex(Some(&params_buffer), 0, 5);
                subtract_encoder.setBuffer_offset_atIndex(Some(&state_buffer), 0, 6);
            }
            subtract_encoder.dispatchThreadgroups_threadsPerThreadgroup(
                MTLSize {
                    width: active_group_count,
                    height: 1,
                    depth: 1,
                },
                MTLSize {
                    width: active_threads_per_group,
                    height: 1,
                    depth: 1,
                },
            );
            subtract_encoder.endEncoding();
            peak_searches = peak_searches.saturating_add(1);

            hogbom_metal_encode_reduce_plan(
                &command_buffer,
                reduce_pipeline,
                &candidate_a,
                &candidate_b,
                &reduce_param_buffers,
                &reduce_plan,
                &state_buffer,
            )?;
            if component_index + 1 == chunk_updates {
                clark_metal_encode_store_peak(
                    &command_buffer,
                    store_peak_pipeline,
                    final_candidate_buffer,
                    &state_buffer,
                )?;
                break;
            }
            clark_metal_encode_select_peak(
                &command_buffer,
                select_pipeline,
                final_candidate_buffer,
                &selected_peak_buffer,
                &state_buffer,
                model_buffer,
                &delta_model_buffer,
                &params_buffer,
                &active_indices_buffer,
            )?;
        }

        command_buffer.commit();
        command_buffer.waitUntilCompleted();
        command_timing.kernel_elapsed +=
            HogbomMetalCommandTiming::from_command_buffer(&command_buffer).kernel_elapsed;
        if command_buffer.status() == MTLCommandBufferStatus::Error {
            let message = command_buffer
                .error()
                .map(|error| format!("{error:?}"))
                .unwrap_or_else(|| "unknown Metal command buffer error".to_string());
            return Err(ImagingError::Unsupported(format!(
                "Clark minor-cycle backend 'metal' command failed: {message}"
            )));
        }
        final_state = unsafe {
            *slice::from_raw_parts(
                state_buffer
                    .contents()
                    .as_ptr()
                    .cast::<ClarkMetalSubcycleState>(),
                1,
            )
            .first()
            .expect("one Clark Metal state")
        };
        minor_progress.emit(
            cycle_update_start.saturating_add(usize::try_from(final_state.updates).map_err(
                |_| ImagingError::InvalidRequest("Clark Metal update count overflowed".to_string()),
            )?),
            Some(final_state.peak.abs_value),
        );
        candidate_ready = true;
    }

    let readback_started = Instant::now();
    let delta_slice = unsafe {
        slice::from_raw_parts(
            delta_model_buffer.contents().as_ptr().cast::<f32>(),
            zero_delta.len(),
        )
    };
    let delta_model = delta_slice.to_vec();
    let readback_elapsed = readback_started.elapsed();
    let actual_updates = usize::try_from(final_state.updates).map_err(|_| {
        ImagingError::InvalidRequest("Clark Metal update count overflowed".to_string())
    })?;
    Ok(ClarkMetalSubcycleResult {
        actual_updates,
        stop_reason: hogbom_metal_stop_reason(final_state.stop_reason),
        final_peak_abs: final_state.peak.abs_value,
        peak_searches,
        delta_model,
        command_timing,
        readback_elapsed,
    })
}

#[cfg(all(target_os = "macos", not(coverage)))]
#[allow(clippy::too_many_arguments)]
fn clark_metal_encode_select_peak(
    command_buffer: &objc2::runtime::ProtocolObject<dyn objc2_metal::MTLCommandBuffer>,
    select_pipeline: &objc2::runtime::ProtocolObject<dyn objc2_metal::MTLComputePipelineState>,
    final_candidate_buffer: &objc2::runtime::ProtocolObject<dyn objc2_metal::MTLBuffer>,
    selected_peak_buffer: &objc2::runtime::ProtocolObject<dyn objc2_metal::MTLBuffer>,
    state_buffer: &objc2::runtime::ProtocolObject<dyn objc2_metal::MTLBuffer>,
    model_buffer: &objc2::runtime::ProtocolObject<dyn objc2_metal::MTLBuffer>,
    delta_model_buffer: &objc2::runtime::ProtocolObject<dyn objc2_metal::MTLBuffer>,
    params_buffer: &objc2::runtime::ProtocolObject<dyn objc2_metal::MTLBuffer>,
    active_indices_buffer: &objc2::runtime::ProtocolObject<dyn objc2_metal::MTLBuffer>,
) -> Result<(), ImagingError> {
    use objc2_metal::{MTLCommandBuffer, MTLCommandEncoder, MTLComputeCommandEncoder, MTLSize};

    let select_encoder = command_buffer.computeCommandEncoder().ok_or_else(|| {
        ImagingError::Unsupported(
            "Clark minor-cycle backend 'metal' could not create select encoder".to_string(),
        )
    })?;
    select_encoder.setComputePipelineState(select_pipeline);
    unsafe {
        select_encoder.setBuffer_offset_atIndex(Some(final_candidate_buffer), 0, 0);
        select_encoder.setBuffer_offset_atIndex(Some(selected_peak_buffer), 0, 1);
        select_encoder.setBuffer_offset_atIndex(Some(state_buffer), 0, 2);
        select_encoder.setBuffer_offset_atIndex(Some(model_buffer), 0, 3);
        select_encoder.setBuffer_offset_atIndex(Some(delta_model_buffer), 0, 4);
        select_encoder.setBuffer_offset_atIndex(Some(params_buffer), 0, 5);
        select_encoder.setBuffer_offset_atIndex(Some(active_indices_buffer), 0, 6);
    }
    select_encoder.dispatchThreads_threadsPerThreadgroup(
        MTLSize {
            width: 1,
            height: 1,
            depth: 1,
        },
        MTLSize {
            width: 1,
            height: 1,
            depth: 1,
        },
    );
    select_encoder.endEncoding();
    Ok(())
}

#[cfg(all(target_os = "macos", not(coverage)))]
fn clark_metal_encode_store_peak(
    command_buffer: &objc2::runtime::ProtocolObject<dyn objc2_metal::MTLCommandBuffer>,
    store_pipeline: &objc2::runtime::ProtocolObject<dyn objc2_metal::MTLComputePipelineState>,
    final_candidate_buffer: &objc2::runtime::ProtocolObject<dyn objc2_metal::MTLBuffer>,
    state_buffer: &objc2::runtime::ProtocolObject<dyn objc2_metal::MTLBuffer>,
) -> Result<(), ImagingError> {
    use objc2_metal::{MTLCommandBuffer, MTLCommandEncoder, MTLComputeCommandEncoder, MTLSize};

    let encoder = command_buffer.computeCommandEncoder().ok_or_else(|| {
        ImagingError::Unsupported(
            "Clark minor-cycle backend 'metal' could not create peak-store encoder".to_string(),
        )
    })?;
    encoder.setComputePipelineState(store_pipeline);
    unsafe {
        encoder.setBuffer_offset_atIndex(Some(final_candidate_buffer), 0, 0);
        encoder.setBuffer_offset_atIndex(Some(state_buffer), 0, 1);
    }
    encoder.dispatchThreads_threadsPerThreadgroup(
        MTLSize {
            width: 1,
            height: 1,
            depth: 1,
        },
        MTLSize {
            width: 1,
            height: 1,
            depth: 1,
        },
    );
    encoder.endEncoding();
    Ok(())
}

fn casa_clark_step_niter(cycle_reported_niter: usize) -> usize {
    if cycle_reported_niter < 5000 {
        cycle_reported_niter
    } else {
        2000
    }
}

const CASA_CLARK_MAX_MAJOR_CYCLES: usize = 10;

struct ClarkPsfPatch {
    patch: Array2<f32>,
    radius_x: usize,
    radius_y: usize,
    max_exterior_abs: f32,
}

struct MultiscaleState {
    scales: Vec<Array2<f32>>,
    scale_supports: Vec<Option<KernelSupport>>,
    dirty_conv_scales: Vec<Array2<f32>>,
    psf_conv_scales: Vec<Vec<Array2<f32>>>,
    peak_psf_conv_scales: Vec<f32>,
    scale_bias: Vec<f32>,
    scale_masks: Option<Vec<Array2<bool>>>,
}

#[derive(Debug, Clone, Copy)]
struct KernelSupport {
    x0: usize,
    y0: usize,
    x1: usize,
    y1: usize,
}

#[derive(Debug, Clone, Copy)]
struct ImageWindow {
    x0: usize,
    y0: usize,
    x1: usize,
    y1: usize,
}

impl ImageWindow {
    fn full(shape: (usize, usize)) -> Self {
        Self {
            x0: 0,
            y0: 0,
            x1: shape.0.saturating_sub(1),
            y1: shape.1.saturating_sub(1),
        }
    }

    fn from_casa_shifted_support(shape: (usize, usize), position: (usize, usize)) -> Self {
        let half_x = shape.0 / 2;
        let half_y = shape.1 / 2;
        Self {
            x0: position.0.saturating_sub(half_x),
            y0: position.1.saturating_sub(half_y),
            x1: position
                .0
                .saturating_add(half_x)
                .saturating_sub(1)
                .min(shape.0.saturating_sub(1)),
            y1: position
                .1
                .saturating_add(half_y)
                .saturating_sub(1)
                .min(shape.1.saturating_sub(1)),
        }
    }

    fn bounded_pixel_count(self, shape: (usize, usize)) -> usize {
        if shape.0 == 0 || shape.1 == 0 {
            return 0;
        }
        let x0 = self.x0.min(shape.0 - 1);
        let y0 = self.y0.min(shape.1 - 1);
        let x1 = self.x1.min(shape.0 - 1);
        let y1 = self.y1.min(shape.1 - 1);
        if x0 > x1 || y0 > y1 {
            return 0;
        }
        x1.saturating_sub(x0)
            .saturating_add(1)
            .saturating_mul(y1.saturating_sub(y0).saturating_add(1))
    }

    fn is_full(self, shape: (usize, usize)) -> bool {
        self.bounded_pixel_count(shape) == shape.0.saturating_mul(shape.1)
    }
}

fn refresh_multiscale_dirty_conv_scales(state: &mut MultiscaleState, residual: &Array2<f32>) {
    state.dirty_conv_scales = state
        .scales
        .iter()
        .map(|scale| fft_convolve_real(residual, scale))
        .collect::<Vec<_>>();
}

#[derive(Debug, Clone, Copy)]
struct ClarkActivePixel {
    x: usize,
    y: usize,
    value: f32,
}

struct ClarkActiveSet {
    pixels: Vec<ClarkActivePixel>,
    pixel_to_active_index: Vec<usize>,
    image_ny: usize,
}

impl ClarkActiveSet {
    const MISSING_INDEX: usize = usize::MAX;

    fn new(image_shape: (usize, usize)) -> Self {
        Self {
            pixels: Vec::new(),
            pixel_to_active_index: vec![Self::MISSING_INDEX; image_shape.0 * image_shape.1],
            image_ny: image_shape.1,
        }
    }

    fn len(&self) -> usize {
        self.pixels.len()
    }

    fn is_empty(&self) -> bool {
        self.pixels.is_empty()
    }

    fn push(&mut self, pixel: ClarkActivePixel) {
        let index = self.pixels.len();
        self.pixel_to_active_index[pixel.x * self.image_ny + pixel.y] = index;
        self.pixels.push(pixel);
    }

    fn active_index(&self, x: usize, y: usize) -> Option<usize> {
        let index = self.pixel_to_active_index[x * self.image_ny + y];
        (index != Self::MISSING_INDEX).then_some(index)
    }
}

#[allow(clippy::too_many_arguments)]
fn run_clark_cotton_schwab(
    request: &ImagingRequest,
    psf_state: &PsfState,
    stage_timings: &mut ImagingStageTimings,
    refresh_residual: &mut ResidualRefreshCallback<'_>,
    model: &mut Array2<f32>,
    mut residual: Array2<f32>,
    minor_cycle_backend: StandardMfsMinorCycleBackend,
    progress_callback: Option<&StandardMfsProgressCallback>,
    max_psf_sidelobe_level: f32,
    initial_peak: f32,
    cycle_threshold_override_jy_per_beam: Option<f32>,
    warnings: &mut Vec<String>,
) -> Result<CottonSchwabState, ImagingError> {
    let deconvolver_setup_started = Instant::now();
    let psf_patch = build_clark_psf_patch(
        &psf_state.psf,
        request.geometry.cell_size_rad,
        request.clean.psf_cutoff,
    );
    stage_timings.deconvolver_setup += deconvolver_setup_started.elapsed();
    let mut minor_iterations = 0usize;
    let mut reported_minor_iterations = 0usize;
    let mut major_cycles = 0usize;
    let mut clean_stop_reason = None::<CleanStopReason>;
    let mut minor_cycle_traces = Vec::<MinorCycleTrace>::new();
    let mut final_cycle_threshold_jy_per_beam = request.clean.threshold_jy_per_beam;
    let mut min_residual_peak_jy_per_beam = initial_peak;
    let mut divergence_warned = false;

    while reported_minor_iterations < request.clean.niter {
        if request
            .clean
            .major_cycle_limit
            .is_some_and(|limit| major_cycles >= limit)
        {
            clean_stop_reason = Some(CleanStopReason::MajorCycleLimitReached);
            break;
        }
        let cycle_setup_started = Instant::now();
        let Some((_, cycle_peak_value)) =
            peak_location_masked(&residual, request.clean_mask.as_ref())
        else {
            stage_timings.clean_cycle_setup += cycle_setup_started.elapsed();
            clean_stop_reason = Some(CleanStopReason::NoCleanablePixels);
            break;
        };
        let cycle_peak = cycle_peak_value.abs();
        let cycle_nsigma_threshold_jy_per_beam =
            nsigma_threshold_jy_per_beam(&residual, request.clean_mask.as_ref(), request.clean);
        if let Some(stop_reason) = tolerant_clean_stop_reason(
            cycle_peak,
            request.clean.threshold_jy_per_beam,
            cycle_nsigma_threshold_jy_per_beam,
        ) {
            stage_timings.clean_cycle_setup += cycle_setup_started.elapsed();
            clean_stop_reason = Some(stop_reason);
            break;
        }
        let remaining_reported = request.clean.niter - reported_minor_iterations;
        let cycle_reported_niter = remaining_reported.min(request.clean.minor_cycle_length);
        let casa_step_reported_niter = casa_clark_step_niter(cycle_reported_niter);
        let start_reported_iteration = reported_minor_iterations;
        final_cycle_threshold_jy_per_beam =
            cycle_threshold_override_jy_per_beam.unwrap_or_else(|| {
                clean_cycle_threshold(cycle_peak, max_psf_sidelobe_level, request.clean)
            });
        stage_timings.clean_cycle_setup += cycle_setup_started.elapsed();
        emit_standard_mfs_controller_progress(
            progress_callback,
            request,
            minor_cycle_backend,
            StandardMfsProgressPhase::MinorCycleStart,
            major_cycles,
            start_reported_iteration,
            casa_step_reported_niter,
            Some(cycle_peak),
            Some(final_cycle_threshold_jy_per_beam),
        );
        let mut minor_progress = StandardMfsMinorCycleProgressReporter::new(
            progress_callback,
            request,
            minor_cycle_backend,
            major_cycles,
            start_reported_iteration,
            casa_step_reported_niter,
            final_cycle_threshold_jy_per_beam,
        );
        let outcome = run_clark_minor_cycle(
            request,
            model,
            &mut residual,
            &psf_state.psf,
            casa_step_reported_niter,
            final_cycle_threshold_jy_per_beam,
            cycle_nsigma_threshold_jy_per_beam,
            &psf_patch,
            minor_cycle_backend,
            stage_timings,
            &mut minor_progress,
        )?;
        let reported_after_outcome =
            reported_minor_iterations.saturating_add(outcome.reported_updates);
        let post_minor_peak = peak_abs_value_masked(&residual, request.clean_mask.as_ref());
        emit_standard_mfs_controller_progress(
            progress_callback,
            request,
            minor_cycle_backend,
            StandardMfsProgressPhase::MinorCycleEnd,
            major_cycles,
            reported_after_outcome,
            casa_step_reported_niter,
            Some(post_minor_peak),
            Some(outcome.final_cycle_threshold_jy_per_beam),
        );
        if outcome.updated_model {
            emit_standard_mfs_controller_progress(
                progress_callback,
                request,
                minor_cycle_backend,
                StandardMfsProgressPhase::ResidualRefreshStart,
                major_cycles,
                reported_after_outcome,
                casa_step_reported_niter,
                Some(post_minor_peak),
                Some(outcome.final_cycle_threshold_jy_per_beam),
            );
            residual = refresh_residual(
                model,
                stage_timings,
                Some(standard_mfs_progress_context(
                    request,
                    minor_cycle_backend,
                    major_cycles,
                    reported_after_outcome,
                    casa_step_reported_niter,
                    Some(post_minor_peak),
                    Some(outcome.final_cycle_threshold_jy_per_beam),
                )),
            )?;
            let refreshed_peak = peak_abs_value_masked(&residual, request.clean_mask.as_ref());
            if reported_after_outcome < request.clean.niter {
                major_cycles += 1;
            }
            emit_standard_mfs_controller_progress(
                progress_callback,
                request,
                minor_cycle_backend,
                StandardMfsProgressPhase::ResidualRefreshEnd,
                major_cycles,
                reported_after_outcome,
                casa_step_reported_niter,
                Some(refreshed_peak),
                Some(outcome.final_cycle_threshold_jy_per_beam),
            );
        }
        minor_cycle_traces.push(make_minor_cycle_trace(
            minor_cycle_traces.len(),
            start_reported_iteration,
            outcome,
            cycle_peak,
            &residual,
            model,
            MinorCycleProbe::default(),
        ));
        minor_iterations += outcome.actual_updates;
        reported_minor_iterations = reported_after_outcome;
        let mut stop_after_cycle = false;
        if let Some(reason) = outcome.stop_reason {
            if minor_cycle_stop_is_major_cycle_handoff(reason, outcome.updated_model) {
                // The residual was refreshed above; let the outer controller
                // decide whether that measured residual has globally stopped.
            } else if matches!(
                reason,
                CleanStopReason::CycleThresholdReached | CleanStopReason::NsigmaThresholdReached
            ) {
                clean_stop_reason = Some(reason);
            } else {
                clean_stop_reason = Some(reason);
                stop_after_cycle = true;
            }
        }
        if !outcome.updated_model {
            break;
        }
        if stop_after_cycle {
            break;
        }
        let minor_peak = peak_abs_value_masked(&residual, request.clean_mask.as_ref());
        if let Some(stop_reason) = update_divergence_state(
            warnings,
            &mut min_residual_peak_jy_per_beam,
            minor_peak,
            &mut divergence_warned,
        ) {
            clean_stop_reason = Some(stop_reason);
            break;
        }
        if clean_stop_reason.is_none() && reported_minor_iterations >= request.clean.niter {
            clean_stop_reason = Some(CleanStopReason::IterationLimitReached);
            break;
        }
        let refreshed_peak = peak_abs_value_masked(&residual, request.clean_mask.as_ref());
        let refreshed_nsigma_threshold_jy_per_beam =
            nsigma_threshold_jy_per_beam(&residual, request.clean_mask.as_ref(), request.clean);
        if let Some(stop_reason) = tolerant_clean_stop_reason(
            refreshed_peak,
            request.clean.threshold_jy_per_beam,
            refreshed_nsigma_threshold_jy_per_beam,
        ) {
            clean_stop_reason = Some(stop_reason);
            break;
        }
    }
    if request.clean.niter > 0 && clean_stop_reason.is_none() {
        clean_stop_reason = Some(CleanStopReason::IterationLimitReached);
    }

    Ok(CottonSchwabState {
        residual,
        major_cycles,
        minor_iterations,
        clean_stop_reason,
        minor_cycle_traces,
        final_cycle_threshold_jy_per_beam,
    })
}

#[allow(clippy::too_many_arguments)]
fn run_multiscale_cotton_schwab(
    request: &ImagingRequest,
    psf_state: &PsfState,
    stage_timings: &mut ImagingStageTimings,
    refresh_residual: &mut ResidualRefreshCallback<'_>,
    model: &mut Array2<f32>,
    mut residual: Array2<f32>,
    minor_cycle_backend: StandardMfsMinorCycleBackend,
    progress_callback: Option<&StandardMfsProgressCallback>,
    max_psf_sidelobe_level: f32,
    initial_peak: f32,
    cycle_threshold_override_jy_per_beam: Option<f32>,
    warnings: &mut Vec<String>,
) -> Result<CottonSchwabState, ImagingError> {
    if minor_cycle_backend == StandardMfsMinorCycleBackend::Metal {
        return run_multiscale_cotton_schwab_metal(
            request,
            psf_state,
            stage_timings,
            refresh_residual,
            model,
            residual,
            progress_callback,
            max_psf_sidelobe_level,
            initial_peak,
            cycle_threshold_override_jy_per_beam,
            warnings,
        );
    }
    let deconvolver_setup_started = Instant::now();
    let scales = effective_multiscale_scales(request);
    let mut multiscale_state = build_multiscale_state(
        &residual,
        &psf_state.psf,
        &scales,
        request.small_scale_bias,
        request.clean_mask.as_ref(),
    );
    stage_timings.deconvolver_setup += deconvolver_setup_started.elapsed();
    let mut minor_iterations = 0usize;
    let mut reported_minor_iterations = 0usize;
    let mut major_cycles = 0usize;
    let mut clean_stop_reason = None::<CleanStopReason>;
    let mut minor_cycle_traces = Vec::<MinorCycleTrace>::new();
    let mut final_cycle_threshold_jy_per_beam = request.clean.threshold_jy_per_beam;
    let mut min_residual_peak_jy_per_beam = initial_peak;
    let mut divergence_warned = false;
    let mut residual_needs_refresh = false;
    let multiscale_trace = multiscale_trace_sink();
    let scale_count = scales.len();
    let mut stats = MultiscaleMinorCycleStats::new(scale_count);
    let mut peak_search_elapsed = Duration::ZERO;
    let mut model_update_elapsed = Duration::ZERO;
    let mut subtract_elapsed = Duration::ZERO;
    let mut model_updates = 0usize;

    while reported_minor_iterations < request.clean.niter {
        if request
            .clean
            .major_cycle_limit
            .is_some_and(|limit| major_cycles >= limit)
        {
            clean_stop_reason = Some(CleanStopReason::MajorCycleLimitReached);
            break;
        }
        let cycle_setup_started = Instant::now();
        let full_window = ImageWindow::full(residual.dim());
        let cycle_candidate_started = Instant::now();
        let cycle_candidate = select_multiscale_candidate(
            &multiscale_state,
            request.clean_mask.as_ref(),
            full_window,
        );
        peak_search_elapsed += cycle_candidate_started.elapsed();
        stats.record_peak_search(full_window, residual.dim());
        let Some(cycle_candidate) = cycle_candidate else {
            stage_timings.clean_cycle_setup += cycle_setup_started.elapsed();
            clean_stop_reason = Some(CleanStopReason::NoCleanablePixels);
            break;
        };
        let cycle_peak = peak_abs_value_masked(
            &multiscale_state.dirty_conv_scales[0],
            request.clean_mask.as_ref(),
        );
        let cycle_nsigma_threshold_jy_per_beam =
            nsigma_threshold_jy_per_beam(&residual, request.clean_mask.as_ref(), request.clean);
        if let Some(stop_reason) = tolerant_clean_stop_reason(
            cycle_peak,
            request.clean.threshold_jy_per_beam,
            cycle_nsigma_threshold_jy_per_beam,
        ) {
            stage_timings.clean_cycle_setup += cycle_setup_started.elapsed();
            clean_stop_reason = Some(stop_reason);
            break;
        }
        let remaining_reported = request.clean.niter - reported_minor_iterations;
        let cycle_reported_niter = remaining_reported.min(request.clean.minor_cycle_length);
        let start_reported_iteration = reported_minor_iterations;
        final_cycle_threshold_jy_per_beam =
            cycle_threshold_override_jy_per_beam.unwrap_or_else(|| {
                clean_cycle_threshold(cycle_peak, max_psf_sidelobe_level, request.clean)
            });
        let probe = MinorCycleProbe {
            initial_scale_pixels: Some(scales[cycle_candidate.scale_index]),
            initial_candidate_strength_jy_per_beam: Some(cycle_candidate.strength),
            initial_candidate_position: Some([
                cycle_candidate.position.0,
                cycle_candidate.position.1,
            ]),
        };
        if let Some(trace) = &multiscale_trace {
            append_multiscale_trace(
                trace,
                format!(
                    "{{\"event\":\"cycle_start\",\"cycle_index\":{},\"start_reported_iteration\":{},\"cycle_reported_niter\":{},\"cycle_peak\":{:.17e},\"cycle_threshold\":{:.17e},\"nsigma_threshold\":{:.17e},\"initial_scale\":{:.17e},\"initial_x\":{},\"initial_y\":{},\"initial_strength\":{:.17e},\"initial_dirty_value\":{:.17e},\"initial_peak_psf\":{:.17e},\"model_flux\":{:.17e}}}",
                    minor_cycle_traces.len(),
                    start_reported_iteration,
                    cycle_reported_niter,
                    cycle_peak,
                    final_cycle_threshold_jy_per_beam,
                    cycle_nsigma_threshold_jy_per_beam,
                    scales[cycle_candidate.scale_index],
                    cycle_candidate.position.0,
                    cycle_candidate.position.1,
                    cycle_candidate.strength,
                    cycle_candidate.dirty_value,
                    cycle_candidate.peak_psf,
                    model.iter().copied().sum::<f32>(),
                ),
            );
        }
        let initial_cycle_component = cycle_candidate.strength.abs();
        let mut cycle_component_updates = 0usize;
        let mut updated_model = false;
        let mut cycle_stop_reason = None::<CleanStopReason>;
        stage_timings.clean_cycle_setup += cycle_setup_started.elapsed();
        let mut dirty_window = full_window;
        emit_standard_mfs_controller_progress(
            progress_callback,
            request,
            minor_cycle_backend,
            StandardMfsProgressPhase::MinorCycleStart,
            major_cycles,
            start_reported_iteration,
            cycle_reported_niter,
            Some(cycle_peak),
            Some(final_cycle_threshold_jy_per_beam),
        );
        let mut minor_progress = StandardMfsMinorCycleProgressReporter::new(
            progress_callback,
            request,
            minor_cycle_backend,
            major_cycles,
            start_reported_iteration,
            cycle_reported_niter,
            final_cycle_threshold_jy_per_beam,
        );
        let minor_started = Instant::now();
        while cycle_component_updates < cycle_reported_niter {
            let candidate_started = Instant::now();
            let candidate = select_multiscale_candidate(
                &multiscale_state,
                request.clean_mask.as_ref(),
                dirty_window,
            );
            peak_search_elapsed += candidate_started.elapsed();
            stats.record_peak_search(dirty_window, residual.dim());
            let Some(candidate) = candidate else {
                cycle_stop_reason = Some(CleanStopReason::NoCleanablePixels);
                break;
            };
            let component_abs = candidate.strength.abs();
            if let Some(stop_reason) = minor_cycle_stop_reason(
                component_abs,
                request.clean.threshold_jy_per_beam,
                final_cycle_threshold_jy_per_beam,
                cycle_nsigma_threshold_jy_per_beam,
            ) {
                cycle_stop_reason = Some(stop_reason);
                break;
            }
            if let Some(stop_reason) = casa_multiscale_divergence_stop_reason(
                candidate,
                multiscale_state.dirty_conv_scales.len(),
                initial_cycle_component,
                cycle_component_updates,
            ) {
                cycle_stop_reason = Some(stop_reason);
                break;
            }

            let component = request.clean.gain * candidate.strength;
            if let Some(trace) = &multiscale_trace {
                append_multiscale_trace(
                    trace,
                    format!(
                        "{{\"event\":\"component\",\"cycle_index\":{},\"cycle_update\":{},\"reported_iteration\":{},\"scale\":{:.17e},\"x\":{},\"y\":{},\"strength\":{:.17e},\"dirty_value\":{:.17e},\"peak_psf\":{:.17e},\"component\":{:.17e},\"component_abs\":{:.17e},\"cycle_threshold\":{:.17e}}}",
                        minor_cycle_traces.len(),
                        cycle_component_updates,
                        start_reported_iteration + cycle_component_updates,
                        scales[candidate.scale_index],
                        candidate.position.0,
                        candidate.position.1,
                        candidate.strength,
                        candidate.dirty_value,
                        candidate.peak_psf,
                        component,
                        component_abs,
                        final_cycle_threshold_jy_per_beam,
                    ),
                );
            }
            let model_update_started = Instant::now();
            add_shifted_kernel_with_support(
                model,
                &multiscale_state.scales[candidate.scale_index],
                multiscale_state.scale_supports[candidate.scale_index],
                candidate.position,
                component,
            );
            model_update_elapsed += model_update_started.elapsed();
            model_updates = model_updates.saturating_add(1);
            stats.record_component(
                candidate.scale_index,
                shifted_kernel_support_pixel_count(
                    residual.dim(),
                    &multiscale_state.scales[candidate.scale_index],
                    multiscale_state.scale_supports[candidate.scale_index],
                    candidate.position,
                ),
            );
            let component_window =
                ImageWindow::from_casa_shifted_support(residual.dim(), candidate.position);
            let subtract_started = Instant::now();
            subtract_multiscale_component(
                &mut multiscale_state,
                candidate.scale_index,
                candidate.position,
                component,
                component_window,
            );
            subtract_elapsed += subtract_started.elapsed();
            stats.record_subtract(component_window, residual.dim());
            dirty_window = component_window;
            cycle_component_updates += 1;
            minor_iterations += 1;
            updated_model = true;
            minor_progress.emit(cycle_component_updates, Some(component_abs));
        }
        let minor_elapsed = minor_started.elapsed();
        stage_timings.minor_cycle += minor_elapsed;
        stage_timings.minor_cycle_solve += minor_elapsed;
        let reported_updates =
            casa_multiscale_reported_updates(cycle_component_updates, cycle_reported_niter);
        let reported_after_outcome = reported_minor_iterations.saturating_add(reported_updates);
        emit_standard_mfs_controller_progress(
            progress_callback,
            request,
            minor_cycle_backend,
            StandardMfsProgressPhase::MinorCycleEnd,
            major_cycles,
            reported_after_outcome,
            cycle_reported_niter,
            Some(peak_abs_value_masked(
                &multiscale_state.dirty_conv_scales[0],
                request.clean_mask.as_ref(),
            )),
            Some(final_cycle_threshold_jy_per_beam),
        );
        if let Some(trace) = &multiscale_trace {
            let stop_reason = cycle_stop_reason
                .map(|reason| format!("{reason:?}"))
                .unwrap_or_else(|| "null".to_string());
            append_multiscale_trace(
                trace,
                format!(
                    "{{\"event\":\"cycle_end\",\"cycle_index\":{},\"actual_updates\":{},\"reported_updates\":{},\"stop_reason\":\"{}\",\"updated_model\":{},\"minor_iterations\":{},\"reported_minor_iterations_before\":{},\"model_flux\":{:.17e}}}",
                    minor_cycle_traces.len(),
                    cycle_component_updates,
                    reported_updates,
                    stop_reason,
                    updated_model,
                    minor_iterations,
                    reported_minor_iterations,
                    model.iter().copied().sum::<f32>(),
                ),
            );
        }
        let outcome = HogbomMinorCycleOutcome {
            updated_model,
            actual_updates: cycle_component_updates,
            reported_updates,
            stop_reason: cycle_stop_reason,
            final_cycle_threshold_jy_per_beam,
            final_nsigma_threshold_jy_per_beam: cycle_nsigma_threshold_jy_per_beam,
        };
        minor_cycle_traces.push(make_minor_cycle_trace(
            minor_cycle_traces.len(),
            start_reported_iteration,
            outcome,
            cycle_peak,
            &multiscale_state.dirty_conv_scales[0],
            model,
            probe,
        ));
        reported_minor_iterations = reported_after_outcome;
        if !updated_model {
            clean_stop_reason = cycle_stop_reason;
            break;
        }
        residual = multiscale_state.dirty_conv_scales[0].clone();
        residual_needs_refresh = true;
        let minor_peak = peak_abs_value_masked(&residual, request.clean_mask.as_ref());
        if let Some(stop_reason) = update_divergence_state(
            warnings,
            &mut min_residual_peak_jy_per_beam,
            minor_peak,
            &mut divergence_warned,
        ) {
            clean_stop_reason = Some(stop_reason);
            break;
        }
        if clean_stop_reason.is_none() && reported_minor_iterations >= request.clean.niter {
            clean_stop_reason = Some(CleanStopReason::IterationLimitReached);
            break;
        }
        emit_standard_mfs_controller_progress(
            progress_callback,
            request,
            minor_cycle_backend,
            StandardMfsProgressPhase::ResidualRefreshStart,
            major_cycles,
            reported_minor_iterations,
            cycle_reported_niter,
            Some(minor_peak),
            Some(final_cycle_threshold_jy_per_beam),
        );
        residual = refresh_residual(
            model,
            stage_timings,
            Some(standard_mfs_progress_context(
                request,
                minor_cycle_backend,
                major_cycles,
                reported_minor_iterations,
                cycle_reported_niter,
                Some(minor_peak),
                Some(final_cycle_threshold_jy_per_beam),
            )),
        )?;
        let multiscale_refresh_started = Instant::now();
        refresh_multiscale_dirty_conv_scales(&mut multiscale_state, &residual);
        stage_timings.multiscale_scale_refresh += multiscale_refresh_started.elapsed();
        major_cycles += 1;
        residual_needs_refresh = false;
        let refreshed_peak = peak_abs_value_masked(&residual, request.clean_mask.as_ref());
        refresh_latest_minor_cycle_trace_residual(&mut minor_cycle_traces, &residual);
        emit_standard_mfs_controller_progress(
            progress_callback,
            request,
            minor_cycle_backend,
            StandardMfsProgressPhase::ResidualRefreshEnd,
            major_cycles,
            reported_minor_iterations,
            cycle_reported_niter,
            Some(refreshed_peak),
            Some(final_cycle_threshold_jy_per_beam),
        );
        let refreshed_nsigma_threshold_jy_per_beam =
            nsigma_threshold_jy_per_beam(&residual, request.clean_mask.as_ref(), request.clean);
        if let Some(stop_reason) = tolerant_clean_stop_reason(
            refreshed_peak,
            request.clean.threshold_jy_per_beam,
            refreshed_nsigma_threshold_jy_per_beam,
        ) {
            clean_stop_reason = Some(stop_reason);
            break;
        }
    }
    if request.clean.niter > 0 && clean_stop_reason.is_none() {
        clean_stop_reason = Some(CleanStopReason::IterationLimitReached);
    }
    if residual_needs_refresh {
        emit_standard_mfs_controller_progress(
            progress_callback,
            request,
            minor_cycle_backend,
            StandardMfsProgressPhase::ResidualRefreshStart,
            major_cycles,
            reported_minor_iterations,
            request.clean.minor_cycle_length,
            Some(peak_abs_value_masked(
                &residual,
                request.clean_mask.as_ref(),
            )),
            Some(final_cycle_threshold_jy_per_beam),
        );
        residual = refresh_residual(
            model,
            stage_timings,
            Some(standard_mfs_progress_context(
                request,
                minor_cycle_backend,
                major_cycles,
                reported_minor_iterations,
                request.clean.minor_cycle_length,
                Some(peak_abs_value_masked(
                    &residual,
                    request.clean_mask.as_ref(),
                )),
                Some(final_cycle_threshold_jy_per_beam),
            )),
        )?;
        major_cycles += 1;
        refresh_latest_minor_cycle_trace_residual(&mut minor_cycle_traces, &residual);
        emit_standard_mfs_controller_progress(
            progress_callback,
            request,
            minor_cycle_backend,
            StandardMfsProgressPhase::ResidualRefreshEnd,
            major_cycles,
            reported_minor_iterations,
            request.clean.minor_cycle_length,
            Some(peak_abs_value_masked(
                &residual,
                request.clean_mask.as_ref(),
            )),
            Some(final_cycle_threshold_jy_per_beam),
        );
    }
    stage_timings.deconvolver_peak_search += peak_search_elapsed;
    stage_timings.deconvolver_model_update += model_update_elapsed;
    stage_timings.deconvolver_psf_subtract += subtract_elapsed;
    stage_timings.deconvolver_model_updates = stage_timings
        .deconvolver_model_updates
        .saturating_add(model_updates as u64);
    stats.add_to_stage_timings(stage_timings);
    log_standard_mfs_multiscale_minor_cycle_summary(
        "cpu",
        minor_iterations,
        request.clean.niter,
        clean_stop_reason,
        &stats,
        peak_search_elapsed,
        model_update_elapsed,
        subtract_elapsed,
        stage_timings.minor_cycle,
    );

    Ok(CottonSchwabState {
        residual,
        major_cycles,
        minor_iterations,
        clean_stop_reason,
        minor_cycle_traces,
        final_cycle_threshold_jy_per_beam,
    })
}

#[derive(Debug, Clone, Copy)]
struct MultiscaleCandidate {
    scale_index: usize,
    position: (usize, usize),
    strength: f32,
    dirty_value: f32,
    peak_psf: f32,
}

fn casa_multiscale_divergence_stop_reason(
    candidate: MultiscaleCandidate,
    _scale_count: usize,
    initial_cycle_component_abs: f32,
    cycle_component_updates: usize,
) -> Option<CleanStopReason> {
    if cycle_component_updates > 0
        && candidate.strength.abs() > initial_cycle_component_abs.abs() * 1.5
    {
        return Some(CleanStopReason::DivergenceDetected);
    }
    None
}

#[derive(Debug, Clone)]
struct MultiscaleMinorCycleStats {
    scale_component_counts: Vec<usize>,
    peak_searches: usize,
    full_window_peak_searches: usize,
    subtract_updates: usize,
    full_window_subtract_updates: usize,
    pixels_searched: usize,
    pixels_touched: usize,
    peak_search_window_pixels_max: usize,
    subtract_window_pixels_max: usize,
}

impl MultiscaleMinorCycleStats {
    fn new(scale_count: usize) -> Self {
        Self {
            scale_component_counts: vec![0; scale_count],
            peak_searches: 0,
            full_window_peak_searches: 0,
            subtract_updates: 0,
            full_window_subtract_updates: 0,
            pixels_searched: 0,
            pixels_touched: 0,
            peak_search_window_pixels_max: 0,
            subtract_window_pixels_max: 0,
        }
    }

    fn record_peak_search(&mut self, window: ImageWindow, shape: (usize, usize)) {
        let window_pixels = window.bounded_pixel_count(shape);
        self.peak_searches = self
            .peak_searches
            .saturating_add(self.scale_component_counts.len());
        self.pixels_searched = self.pixels_searched.saturating_add(
            self.scale_component_counts
                .len()
                .saturating_mul(window_pixels),
        );
        self.peak_search_window_pixels_max = self.peak_search_window_pixels_max.max(window_pixels);
        if window.is_full(shape) {
            self.full_window_peak_searches = self
                .full_window_peak_searches
                .saturating_add(self.scale_component_counts.len());
        }
    }

    fn record_component(&mut self, scale_index: usize, model_pixels_touched: usize) {
        if let Some(count) = self.scale_component_counts.get_mut(scale_index) {
            *count = count.saturating_add(1);
        }
        self.pixels_touched = self.pixels_touched.saturating_add(model_pixels_touched);
    }

    fn record_subtract(&mut self, window: ImageWindow, shape: (usize, usize)) {
        let window_pixels = window.bounded_pixel_count(shape);
        let scale_count = self.scale_component_counts.len();
        self.subtract_updates = self.subtract_updates.saturating_add(scale_count);
        self.pixels_touched = self
            .pixels_touched
            .saturating_add(scale_count.saturating_mul(window_pixels));
        self.subtract_window_pixels_max = self.subtract_window_pixels_max.max(window_pixels);
        if window.is_full(shape) {
            self.full_window_subtract_updates = self
                .full_window_subtract_updates
                .saturating_add(scale_count);
        }
    }

    fn add_to_stage_timings(&self, stage_timings: &mut ImagingStageTimings) {
        stage_timings.deconvolver_peak_searches = stage_timings
            .deconvolver_peak_searches
            .saturating_add(self.peak_searches as u64);
        stage_timings.deconvolver_subtract_updates = stage_timings
            .deconvolver_subtract_updates
            .saturating_add(self.subtract_updates as u64);
        stage_timings.deconvolver_pixels_searched = stage_timings
            .deconvolver_pixels_searched
            .saturating_add(self.pixels_searched as u64);
        stage_timings.deconvolver_pixels_touched = stage_timings
            .deconvolver_pixels_touched
            .saturating_add(self.pixels_touched as u64);
        stage_timings.deconvolver_full_window_peak_searches = stage_timings
            .deconvolver_full_window_peak_searches
            .saturating_add(self.full_window_peak_searches as u64);
        stage_timings.deconvolver_full_window_subtract_updates = stage_timings
            .deconvolver_full_window_subtract_updates
            .saturating_add(self.full_window_subtract_updates as u64);
        stage_timings.deconvolver_peak_search_window_pixels_max = stage_timings
            .deconvolver_peak_search_window_pixels_max
            .max(self.peak_search_window_pixels_max as u64);
        stage_timings.deconvolver_subtract_window_pixels_max = stage_timings
            .deconvolver_subtract_window_pixels_max
            .max(self.subtract_window_pixels_max as u64);
    }

    fn scale_counts_label(&self) -> String {
        self.scale_component_counts
            .iter()
            .enumerate()
            .map(|(scale_index, count)| format!("{scale_index}:{count}"))
            .collect::<Vec<_>>()
            .join(",")
    }
}

#[allow(clippy::too_many_arguments)]
fn log_standard_mfs_multiscale_minor_cycle_summary(
    backend: &str,
    updates: usize,
    reported_budget: usize,
    stop_reason: Option<CleanStopReason>,
    stats: &MultiscaleMinorCycleStats,
    peak_search_elapsed: Duration,
    model_update_elapsed: Duration,
    subtract_elapsed: Duration,
    total_elapsed: Duration,
) {
    eprintln!(
        "standard_mfs_multiscale_minor_cycle_summary backend={} updates={} reported_budget={} stop_reason={:?} scale_component_counts={} peak_searches={} full_window_peak_searches={} subtract_updates={} full_window_subtract_updates={} pixels_searched={} pixels_touched={} peak_search_window_pixels_max={} subtract_window_pixels_max={} peak_search_ms={:.3} model_update_ms={:.3} subtract_ms={:.3} total_ms={:.3}",
        backend,
        updates,
        reported_budget,
        stop_reason,
        stats.scale_counts_label(),
        stats.peak_searches,
        stats.full_window_peak_searches,
        stats.subtract_updates,
        stats.full_window_subtract_updates,
        stats.pixels_searched,
        stats.pixels_touched,
        stats.peak_search_window_pixels_max,
        stats.subtract_window_pixels_max,
        peak_search_elapsed.as_secs_f64() * 1000.0,
        model_update_elapsed.as_secs_f64() * 1000.0,
        subtract_elapsed.as_secs_f64() * 1000.0,
        total_elapsed.as_secs_f64() * 1000.0,
    );
}

fn effective_multiscale_scales(request: &ImagingRequest) -> Vec<f32> {
    if request.multiscale_scales.is_empty() {
        vec![0.0]
    } else {
        request.multiscale_scales.clone()
    }
}

fn build_multiscale_state(
    residual: &Array2<f32>,
    psf: &Array2<f32>,
    scales: &[f32],
    small_scale_bias: f32,
    mask: Option<&Array2<bool>>,
) -> MultiscaleState {
    let scale_images = scales
        .iter()
        .map(|scale| make_multiscale_kernel(residual.dim(), *scale))
        .collect::<Vec<_>>();
    let scale_supports = scale_images
        .iter()
        .map(kernel_nonzero_support)
        .collect::<Vec<_>>();
    let dirty_conv_scales = scale_images
        .iter()
        .map(|scale| fft_convolve_real(residual, scale))
        .collect::<Vec<_>>();
    let psf_conv_scales = (0..scale_images.len())
        .map(|scale_index| {
            (0..scale_images.len())
                .map(|other_index| {
                    fft_convolve_real(
                        &fft_convolve_real(psf, &scale_images[scale_index]),
                        &scale_images[other_index],
                    )
                })
                .collect::<Vec<_>>()
        })
        .collect::<Vec<_>>();
    let peak_psf_conv_scales = (0..scale_images.len())
        .map(|scale_index| peak_abs_value(&psf_conv_scales[scale_index][scale_index]).max(1.0e-6))
        .collect::<Vec<_>>();
    let max_scale = scales.iter().copied().fold(0.0f32, f32::max);
    let scale_bias = if max_scale > 0.0 && scales.len() > 1 {
        scales
            .iter()
            .map(|scale| 1.0 - small_scale_bias * (*scale / max_scale))
            .collect::<Vec<_>>()
    } else {
        vec![1.0; scales.len()]
    };
    let scale_masks =
        mask.map(|clean_mask| build_multiscale_scale_masks(clean_mask, &scale_images, scales));

    MultiscaleState {
        scales: scale_images,
        scale_supports,
        dirty_conv_scales,
        psf_conv_scales,
        peak_psf_conv_scales,
        scale_bias,
        scale_masks,
    }
}

fn build_multiscale_scale_masks(
    mask: &Array2<bool>,
    scale_images: &[Array2<f32>],
    scale_sizes: &[f32],
) -> Vec<Array2<bool>> {
    let mask_values = mask.mapv(|cleanable| if cleanable { 1.0 } else { 0.0 });
    scale_images
        .iter()
        .zip(scale_sizes.iter().copied())
        .map(|(scale_image, scale_size)| {
            let convolved = fft_convolve_real(&mask_values, scale_image);
            let mut scale_mask = convolved.mapv(|value| value > 0.9);
            apply_casa_multiscale_edge_mask(&mut scale_mask, scale_size);
            scale_mask
        })
        .collect()
}

fn apply_casa_multiscale_edge_mask(mask: &mut Array2<bool>, scale_size: f32) {
    let (nx, ny) = mask.dim();
    let border = (scale_size * 1.5) as usize;
    for x in 0..nx {
        for y in 0..ny {
            if x <= border
                || y <= border
                || x >= nx.saturating_sub(border + 1)
                || y >= ny.saturating_sub(border + 1)
            {
                mask[(x, y)] = false;
            }
        }
    }
}

fn select_multiscale_candidate(
    state: &MultiscaleState,
    mask: Option<&Array2<bool>>,
    window: ImageWindow,
) -> Option<MultiscaleCandidate> {
    let mut best = None::<(MultiscaleCandidate, f32)>;
    for scale_index in 0..state.dirty_conv_scales.len() {
        let search_mask = state
            .scale_masks
            .as_ref()
            .map(|scale_masks| &scale_masks[scale_index])
            .or(mask);
        let Some((position, value)) = peak_location_masked_in_window(
            &state.dirty_conv_scales[scale_index],
            search_mask,
            window,
        ) else {
            continue;
        };
        let peak_psf = state.peak_psf_conv_scales[scale_index];
        if peak_psf <= 0.0 || value == 0.0 {
            continue;
        }
        let strength = value / peak_psf;
        let score = state.scale_bias[scale_index] * value * strength;
        if best
            .map(|(_, best_score)| score.abs() > best_score.abs())
            .unwrap_or(true)
        {
            best = Some((
                MultiscaleCandidate {
                    scale_index,
                    position,
                    strength,
                    dirty_value: value,
                    peak_psf,
                },
                score,
            ));
        }
    }
    best.map(|(candidate, _)| candidate)
}

fn subtract_multiscale_component(
    state: &mut MultiscaleState,
    optimum_scale: usize,
    position: (usize, usize),
    scale_factor: f32,
    window: ImageWindow,
) {
    for scale_index in 0..state.dirty_conv_scales.len() {
        subtract_shifted_kernel_in_window(
            &mut state.dirty_conv_scales[scale_index],
            &state.psf_conv_scales[scale_index][optimum_scale],
            position,
            scale_factor,
            window,
        );
    }
}

fn make_multiscale_kernel(shape: (usize, usize), scale_size: f32) -> Array2<f32> {
    let (nx, ny) = shape;
    let mut kernel = Array2::<f32>::zeros((nx, ny));
    // MatrixCleaner assigns the result of integer nx/2 and ny/2 to Double.
    let refi = (nx / 2) as f64;
    let refj = (ny / 2) as f64;
    if scale_size == 0.0 {
        kernel[(refi as usize, refj as usize)] = 1.0;
        return kernel;
    }

    let scale_size_f64 = f64::from(scale_size);
    let mini = ((refi - scale_size_f64) as isize).max(0) as usize;
    let maxi = ((refi + scale_size_f64) as usize).min(nx - 1);
    let minj = ((refj - scale_size_f64) as isize).max(0) as usize;
    let maxj = ((refj + scale_size_f64) as usize).min(ny - 1);
    let mut volume = 0.0f32;
    for j in minj..=maxj {
        let ypart = (((refj - j as f64) / scale_size_f64).powi(2)) as f32;
        for i in mini..=maxi {
            let rad2 = (f64::from(ypart) + ((refi - i as f64) / scale_size_f64).powi(2)) as f32;
            if rad2 < 1.0 {
                let rad = if rad2 <= 0.0 { 0.0 } else { rad2.sqrt() };
                // MatrixCleaner::makeScale spells the literal as `1.0`.
                // C++ therefore promotes the Float operands to Double for
                // this expression, then rounds once when assigning iscale.
                let value =
                    ((1.0f64 - f64::from(rad2)) * f64::from(multiscale_spheroidal(rad))) as f32;
                kernel[(i, j)] = value;
                volume += value;
            }
        }
    }
    if volume > 0.0 {
        kernel /= volume;
    }
    kernel
}

fn multiscale_spheroidal(nu: f32) -> f32 {
    if nu <= 0.0 {
        return 1.0;
    }
    if nu >= 1.0 {
        return 0.0;
    }

    let (p, q, nuend) = if nu < 0.75 {
        (
            [
                8.203343e-2,
                -3.644705e-1,
                6.278_66e-1,
                -5.335581e-1,
                2.312756e-1,
            ],
            [1.0, 8.212018e-1, 2.078043e-1],
            0.75f32,
        )
    } else {
        (
            [
                4.028559e-3,
                -3.697768e-2,
                1.021332e-1,
                -1.201436e-1,
                6.412774e-2,
            ],
            [1.0, 9.599102e-1, 2.918724e-1],
            1.0f32,
        )
    };
    // CASA 6.7.5.18 evaluates the powers, subtraction, and following
    // polynomial as separate Float operations despite the source literal.
    let delnusq = nu.powf(2.0) - nuend.powf(2.0);
    let mut numerator = p[0];
    for (power, coefficient) in p.iter().enumerate().skip(1) {
        numerator += coefficient * delnusq.powf(power as f32);
    }
    let mut denominator = q[0];
    for (power, coefficient) in q.iter().enumerate().skip(1) {
        denominator += coefficient * delnusq.powf(power as f32);
    }
    if denominator == 0.0 {
        0.0
    } else {
        numerator / denominator
    }
}

fn fft_convolve_real(lhs: &Array2<f32>, rhs: &Array2<f32>) -> Array2<f32> {
    let lhs_complex = lhs.mapv(|value| Complex32::new(value, 0.0));
    let rhs_complex = rhs.mapv(|value| Complex32::new(value, 0.0));
    let product = centered_fft2(&lhs_complex) * centered_fft2(&rhs_complex);
    centered_ifft2(&product).mapv(|value| value.re)
}

fn build_clark_psf_patch(
    psf: &Array2<f32>,
    cell_size_rad: [f64; 2],
    psf_cutoff: f32,
) -> ClarkPsfPatch {
    let BeamFitOutcome { beam, .. } = fit_beam_from_psf(psf, cell_size_rad, psf_cutoff);
    let (major_pixels, minor_pixels) = beam
        .map(|beam| {
            (
                (beam.major_fwhm_rad / cell_size_rad[0]).ceil().max(1.0) as usize,
                (beam.minor_fwhm_rad / cell_size_rad[1]).ceil().max(1.0) as usize,
            )
        })
        .unwrap_or((4, 4));
    let ncent = 4usize.max(major_pixels).max(minor_pixels);
    let patch_size_x = 3 * ncent + 1;
    let patch_size_y = 3 * ncent + 1;
    let center_x = psf.dim().0 / 2;
    let center_y = psf.dim().1 / 2;
    let radius_x = patch_size_x / 2;
    let radius_y = patch_size_y / 2;
    let x0 = center_x.saturating_sub(radius_x);
    let y0 = center_y.saturating_sub(radius_y);
    let x1 = (x0 + patch_size_x).min(psf.dim().0);
    let y1 = (y0 + patch_size_y).min(psf.dim().1);
    let patch = psf.slice(s![x0..x1, y0..y1]).to_owned();
    let max_exterior_abs = max_abs_outside_patch(psf, x0, x1, y0, y1);
    ClarkPsfPatch {
        patch,
        radius_x,
        radius_y,
        max_exterior_abs,
    }
}

fn max_abs_outside_patch(psf: &Array2<f32>, x0: usize, x1: usize, y0: usize, y1: usize) -> f32 {
    let mut max_abs = 0.0f32;
    for ((x, y), value) in psf.indexed_iter() {
        if x < x0 || x >= x1 || y < y0 || y >= y1 {
            max_abs = max_abs.max(value.abs());
        }
    }
    max_abs
}

fn collect_clark_active_pixels(
    residual: &Array2<f32>,
    mask: Option<&Array2<bool>>,
    flux_limit: f32,
) -> ClarkActiveSet {
    let mut active = ClarkActiveSet::new(residual.dim());
    for ((x, y), value) in residual.indexed_iter() {
        if value.abs() < flux_limit {
            continue;
        }
        if mask.is_some_and(|mask| !mask[(x, y)]) {
            continue;
        }
        active.push(ClarkActivePixel {
            x,
            y,
            value: *value,
        });
    }
    active
}

fn peak_clark_active_pixel(active_pixels: &ClarkActiveSet) -> Option<(usize, ClarkActivePixel)> {
    let mut best = None::<(usize, ClarkActivePixel)>;
    for (index, pixel) in active_pixels.pixels.iter().copied().enumerate() {
        match best {
            None => best = Some((index, pixel)),
            Some((_, current)) if pixel.value.abs() > current.value.abs() => {
                best = Some((index, pixel))
            }
            _ => {}
        }
    }
    best
}

fn subtract_clark_component_from_active(
    active_pixels: &mut ClarkActiveSet,
    peak_x: usize,
    peak_y: usize,
    component: f32,
    psf_patch: &ClarkPsfPatch,
) {
    let (patch_nx, patch_ny) = psf_patch.patch.dim();
    let image_nx = active_pixels.pixel_to_active_index.len() / active_pixels.image_ny;
    for patch_x in 0..patch_nx {
        let Some(pixel_x) = peak_x
            .checked_add(patch_x)
            .and_then(|value| value.checked_sub(psf_patch.radius_x))
        else {
            continue;
        };
        if pixel_x >= image_nx {
            continue;
        }
        for patch_y in 0..patch_ny {
            let Some(pixel_y) = peak_y
                .checked_add(patch_y)
                .and_then(|value| value.checked_sub(psf_patch.radius_y))
            else {
                continue;
            };
            if pixel_y >= active_pixels.image_ny {
                continue;
            }
            let Some(active_index) = active_pixels.active_index(pixel_x, pixel_y) else {
                continue;
            };
            active_pixels.pixels[active_index].value -=
                component * psf_patch.patch[(patch_x, patch_y)];
        }
    }
}

fn hogbom_component_budget(reported_cycle_niter: usize, clean: CleanConfig) -> usize {
    match clean.hogbom_iteration_mode {
        // CASA's `SDAlgorithmHogbomClean` passes `siter = 0` and
        // `cycleNiter` into casacore's Fortran `hclean`, whose
        // `do iter=siter,niter` loop is inclusive. The kernel can therefore
        // commit one more component than the reported `iterdone`, which is
        // clamped back to `cycleNiter` before returning.
        HogbomIterationMode::CasaInclusive => reported_cycle_niter.saturating_add(1),
        HogbomIterationMode::Strict => reported_cycle_niter,
    }
}

/// Control parameters for one Hogbom image-plane minor cycle.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct HogbomPlaneMinorCycleControl {
    clean: CleanConfig,
    cycle_limit: usize,
    cycle_threshold_jy_per_beam: f32,
    peak_relative_tolerance: f32,
}

impl HogbomPlaneMinorCycleControl {
    /// Build one Hogbom image-plane minor-cycle control block.
    pub fn new(
        clean: CleanConfig,
        cycle_limit: usize,
        cycle_threshold_jy_per_beam: f32,
        peak_relative_tolerance: f32,
    ) -> Self {
        Self {
            clean,
            cycle_limit,
            cycle_threshold_jy_per_beam,
            peak_relative_tolerance,
        }
    }
}

/// One component selected during a Hogbom image-plane minor cycle.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct HogbomPlaneComponent {
    position: (usize, usize),
    peak_value_jy_per_beam: f32,
    component_jy: f32,
}

impl HogbomPlaneComponent {
    /// Component position in image-pixel coordinates.
    pub fn position(&self) -> (usize, usize) {
        self.position
    }

    /// Peak residual value selected for this component.
    pub fn peak_value_jy_per_beam(&self) -> f32 {
        self.peak_value_jy_per_beam
    }

    /// Flux added to the model plane.
    pub fn component_jy(&self) -> f32 {
        self.component_jy
    }
}

/// Result of one Hogbom image-plane minor cycle.
#[derive(Debug, Clone, PartialEq)]
pub struct HogbomPlaneMinorCycleOutcome {
    actual_updates: usize,
    reported_updates: usize,
    components: Vec<HogbomPlaneComponent>,
}

impl HogbomPlaneMinorCycleOutcome {
    /// Number of model/residual updates actually applied.
    pub fn actual_updates(&self) -> usize {
        self.actual_updates
    }

    /// CASA-compatible iteration count reported to clean control.
    pub fn reported_updates(&self) -> usize {
        self.reported_updates
    }

    /// Components selected during this minor cycle.
    pub fn components(&self) -> &[HogbomPlaneComponent] {
        &self.components
    }
}

/// Run a finite masked Hogbom minor cycle on one image plane.
pub fn run_hogbom_plane_minor_cycle(
    model: &mut Array2<f32>,
    residual: &mut Array2<f32>,
    psf: &Array2<f32>,
    clean_mask: Option<&Array2<bool>>,
    control: HogbomPlaneMinorCycleControl,
) -> HogbomPlaneMinorCycleOutcome {
    let clean = control.clean;
    let cycle_component_budget = hogbom_component_budget(control.cycle_limit, clean);
    let mut components = Vec::new();
    while components.len() < cycle_component_budget {
        let Some(((peak_x, peak_y), peak_value)) =
            finite_peak_location_masked_with_relative_tolerance(
                residual,
                clean_mask,
                control.peak_relative_tolerance,
            )
        else {
            break;
        };
        let peak_abs = peak_value.abs();
        if peak_abs <= clean.threshold_jy_per_beam
            || peak_abs <= control.cycle_threshold_jy_per_beam
        {
            break;
        }
        let component = clean.gain * peak_value;
        model[(peak_x, peak_y)] += component;
        subtract_shifted_psf(residual, psf, (peak_x, peak_y), component);
        components.push(HogbomPlaneComponent {
            position: (peak_x, peak_y),
            peak_value_jy_per_beam: peak_value,
            component_jy: component,
        });
    }
    let actual_updates = components.len();
    let stopped_by_limit = actual_updates >= cycle_component_budget && cycle_component_budget > 0;
    let reported_updates =
        if clean.hogbom_iteration_mode == HogbomIterationMode::CasaInclusive && stopped_by_limit {
            actual_updates.min(control.cycle_limit)
        } else {
            actual_updates
        };
    HogbomPlaneMinorCycleOutcome {
        actual_updates,
        reported_updates,
        components,
    }
}

struct PsfState {
    psf: Array2<f32>,
    normalization_sumwt: f32,
    reported_sumwt: f32,
    psf_peak: f32,
    gridded_samples: usize,
    skipped_samples: usize,
}

struct MtmfsPsfState {
    psf_terms: Vec<Array2<f32>>,
    normalization_sumwt: f32,
    reported_sumwt_terms: Vec<f32>,
    psf_peak: f32,
    gridded_samples: usize,
    skipped_samples: usize,
}

#[derive(Debug)]
struct MtmfsPsfGridAccumulation {
    psf_grids: Vec<Array2<Complex32>>,
    normalization_sumwt: f64,
    reported_sumwt_terms: Vec<f64>,
    gridded_samples: usize,
    skipped_samples: usize,
}

#[derive(Debug)]
struct MtmfsResidualGridAccumulation {
    residual_grids: Vec<Array2<Complex32>>,
}

struct MtmfsAccelerationBackend<'a> {
    execution_config: StandardMfsExecutionPlan,
    #[cfg(all(target_os = "macos", not(coverage)))]
    metal: Option<StandardMfsMetalExecutor<'a>>,
    #[cfg(all(target_os = "macos", not(coverage)))]
    metal_input_cache: Option<MtmfsMetalInputCache>,
    _gridder_lifetime: std::marker::PhantomData<&'a StandardGridder>,
}

impl<'a> MtmfsAccelerationBackend<'a> {
    fn new(
        request: &MtmfsRequest,
        gridder: &'a StandardGridder,
        execution_config: &StandardMfsExecutionPlan,
    ) -> Result<Self, ImagingError> {
        let _ = gridder;
        if standard_mfs_mtmfs_metal_backend_enabled(execution_config)
            && request.w_term_mode != WTermMode::WProject
        {
            #[cfg(all(target_os = "macos", not(coverage)))]
            {
                return Ok(Self {
                    execution_config: execution_config.clone(),
                    metal: Some(StandardMfsMetalExecutor::new_with_resident_bytes(
                        gridder,
                        None,
                        execution_config,
                    )?),
                    metal_input_cache: None,
                    _gridder_lifetime: std::marker::PhantomData,
                });
            }
            #[cfg(any(not(target_os = "macos"), coverage))]
            {
                return Err(ImagingError::Unsupported(
                    "MTMFS Metal backend requires macOS Metal and is not available on this platform"
                        .to_string(),
                ));
            }
        }
        Ok(Self {
            execution_config: execution_config.clone(),
            #[cfg(all(target_os = "macos", not(coverage)))]
            metal: None,
            #[cfg(all(target_os = "macos", not(coverage)))]
            metal_input_cache: None,
            _gridder_lifetime: std::marker::PhantomData,
        })
    }

    fn prepare_weighted_batches(
        &mut self,
        request: &MtmfsRequest,
        batches: &[VisibilityBatch],
    ) -> Result<(), ImagingError> {
        #[cfg(all(target_os = "macos", not(coverage)))]
        {
            if let Some(metal) = self.metal.as_ref() {
                self.metal_input_cache = Some(metal.prepare_mtmfs_input_cache(
                    batches,
                    &request.sample_frequency_batches_hz,
                    request.reffreq_hz,
                    2 * request.nterms - 1,
                )?);
                if let Some(cache) = self.metal_input_cache.as_ref() {
                    eprintln!(
                        "mtmfs_runtime_plan backend=metal-sample-cache terms={} psf_terms={} samples={} cache_host_bytes={} gridded_samples={} skipped_samples={}",
                        request.nterms,
                        2 * request.nterms - 1,
                        cache.sample_count(),
                        cache.host_bytes(),
                        cache.gridded_samples,
                        cache.skipped_samples
                    );
                }
            }
        }
        let _ = (request, batches);
        Ok(())
    }

    fn worker_threads(&self, work_items: usize) -> usize {
        standard_mfs_grid_threads(&self.execution_config)
            .min(work_items.max(1))
            .max(1)
    }

    fn metal_enabled(&self) -> bool {
        standard_mfs_mtmfs_metal_backend_enabled(&self.execution_config)
    }

    #[cfg(all(target_os = "macos", not(coverage)))]
    fn metal(&self) -> Option<&StandardMfsMetalExecutor<'a>> {
        self.metal.as_ref()
    }

    #[cfg(all(target_os = "macos", not(coverage)))]
    fn metal_input_cache(&self) -> Option<&MtmfsMetalInputCache> {
        self.metal_input_cache.as_ref()
    }
}

#[derive(Debug, Clone, Copy, Default)]
struct PsfComputationTimings {
    grid: Duration,
    fft: Duration,
    normalize: Duration,
}

#[derive(Debug, Clone, Copy, Default)]
struct ResidualComputationTimings {
    model_fft: Duration,
    degrid_grid: Duration,
    fft: Duration,
    normalize: Duration,
}

fn fill_mtmfs_taylor_weights(
    weights: &mut Vec<f32>,
    frequency_hz: f64,
    reffreq_hz: f64,
    count: usize,
) {
    weights.clear();
    let scaled = mtmfs_casa_taylor_x(frequency_hz, reffreq_hz);
    for order in 0..count {
        weights.push(mtmfs_casa_taylor_power_x(scaled, order));
    }
}

pub(crate) fn mtmfs_casa_taylor_x(frequency_hz: f64, reffreq_hz: f64) -> f32 {
    let casa_frequency_hz = f64::from(frequency_hz as f32);
    ((casa_frequency_hz - reffreq_hz) / reffreq_hz) as f32
}

/// CASA's `modifyModelVis` evaluates `pow(Float, Int)` in Double, converts the
/// scalar result to Float for `Complex<Float>::operator*=`, and then performs
/// the Complex multiplication.
#[inline]
pub(crate) fn mtmfs_casa_taylor_power_x(taylor_x: f32, order: usize) -> f32 {
    f64::from(taylor_x).powi(order as i32) as f32
}

fn centered_ifft2_mtmfs_term_batch(
    grids: Vec<Array2<Complex32>>,
    dirty_product_fft_policy: DirtyProductFftPolicy,
) -> Result<(Vec<Array2<Complex32>>, Duration), ImagingError> {
    let started = Instant::now();
    let terms = execute_dirty_product_host_f32_batch(&grids, dirty_product_fft_policy)?;
    Ok((terms, started.elapsed()))
}

#[allow(clippy::needless_range_loop)]
fn compute_mtmfs_psf_terms(
    request: &MtmfsRequest,
    batches: &[VisibilityBatch],
    gridder: &StandardGridder,
    acceleration_backend: &MtmfsAccelerationBackend<'_>,
    dirty_product_fft_policy: DirtyProductFftPolicy,
    stage_timings: &mut ImagingStageTimings,
) -> Result<MtmfsPsfState, ImagingError> {
    let _ = acceleration_backend;
    if request.w_term_mode == WTermMode::WProject {
        return compute_mtmfs_psf_terms_w_project(
            request,
            batches,
            gridder,
            acceleration_backend.worker_threads(usize::MAX),
            dirty_product_fft_policy,
            stage_timings,
        );
    }
    let term_count = 2 * request.nterms - 1;
    let mut timings = PsfComputationTimings::default();

    let grid_started = Instant::now();
    let worker_threads = acceleration_backend.worker_threads(batches.len());
    let accumulation = if cfg!(all(target_os = "macos", not(coverage)))
        && acceleration_backend.metal_enabled()
    {
        #[cfg(all(target_os = "macos", not(coverage)))]
        {
            let executor = acceleration_backend.metal().ok_or_else(|| {
                ImagingError::Unsupported(
                    "MTMFS Metal backend was selected but no Metal executor was prepared"
                        .to_string(),
                )
            })?;
            let cache = acceleration_backend.metal_input_cache().ok_or_else(|| {
                ImagingError::Unsupported(
                    "MTMFS Metal backend was selected but no input cache was prepared".to_string(),
                )
            })?;
            let metal = executor.accumulate_mtmfs_psf_grids_from_cache(cache, term_count)?;
            MtmfsPsfGridAccumulation {
                psf_grids: metal.psf_grids,
                normalization_sumwt: metal.normalization_sumwt,
                reported_sumwt_terms: metal.reported_sumwt_terms,
                gridded_samples: metal.gridded_samples,
                skipped_samples: metal.skipped_samples,
            }
        }
        #[cfg(any(not(target_os = "macos"), coverage))]
        {
            return Err(ImagingError::Unsupported(
                "MTMFS Metal backend requires macOS Metal and is not available on this platform"
                    .to_string(),
            ));
        }
    } else if worker_threads > 1 {
        accumulate_mtmfs_psf_grids_parallel(request, batches, gridder, term_count, worker_threads)?
    } else {
        accumulate_mtmfs_psf_grid_range(request, batches, gridder, term_count, 0, batches.len())?
    };
    let MtmfsPsfGridAccumulation {
        psf_grids,
        normalization_sumwt,
        reported_sumwt_terms,
        gridded_samples,
        skipped_samples,
    } = accumulation;
    timings.grid = grid_started.elapsed();

    if normalization_sumwt <= 0.0
        || !reported_sumwt_terms[0].is_finite()
        || reported_sumwt_terms[0] <= 0.0
    {
        return Err(ImagingError::NoUsableSamples);
    }

    let (raw_terms, fft_duration) =
        centered_ifft2_mtmfs_term_batch(psf_grids, dirty_product_fft_policy)?;
    timings.fft = fft_duration;
    let normalize_started = Instant::now();
    let mut psf_terms = raw_terms
        .iter()
        .map(|raw| {
            let mut corrected = gridder.corrected_image_from_grid(raw);
            corrected.mapv_inplace(|value| value / normalization_sumwt as f32);
            corrected
        })
        .collect::<Vec<_>>();
    let psf_peak = peak_abs_value(&psf_terms[0]);
    if !(psf_peak.is_finite() && psf_peak > 0.0) {
        return Err(ImagingError::Normalization(
            "MTMFS PSF peak is non-finite or zero".to_string(),
        ));
    }
    for psf_term in &mut psf_terms {
        psf_term.mapv_inplace(|value| value / psf_peak);
    }
    timings.normalize = normalize_started.elapsed();
    stage_timings.psf_grid += timings.grid;
    stage_timings.psf_fft += timings.fft;
    stage_timings.psf_normalize += timings.normalize;

    Ok(MtmfsPsfState {
        psf_terms,
        normalization_sumwt: normalization_sumwt as f32,
        reported_sumwt_terms: reported_sumwt_terms
            .into_iter()
            .map(|value| value as f32)
            .collect(),
        psf_peak,
        gridded_samples,
        skipped_samples,
    })
}

fn accumulate_mtmfs_psf_grids_parallel(
    request: &MtmfsRequest,
    batches: &[VisibilityBatch],
    gridder: &StandardGridder,
    term_count: usize,
    worker_threads: usize,
) -> Result<MtmfsPsfGridAccumulation, ImagingError> {
    let chunk_size = batches.len().div_ceil(worker_threads);
    let partials = thread::scope(|scope| {
        let mut handles = Vec::new();
        for start in (0..batches.len()).step_by(chunk_size) {
            let end = (start + chunk_size).min(batches.len());
            handles.push(scope.spawn(move || {
                accumulate_mtmfs_psf_grid_range(request, batches, gridder, term_count, start, end)
            }));
        }
        handles
            .into_iter()
            .map(|handle| {
                handle.join().map_err(|_| {
                    ImagingError::InvalidRequest("MTMFS PSF worker thread panicked".to_string())
                })?
            })
            .collect::<Result<Vec<_>, _>>()
    })?;
    merge_mtmfs_psf_accumulations(partials, term_count, gridder.grid_shape())
}

fn accumulate_mtmfs_psf_grid_range(
    request: &MtmfsRequest,
    batches: &[VisibilityBatch],
    gridder: &StandardGridder,
    term_count: usize,
    start_batch: usize,
    end_batch: usize,
) -> Result<MtmfsPsfGridAccumulation, ImagingError> {
    let [nx, ny] = gridder.grid_shape();
    let mut psf_grids = (0..term_count)
        .map(|_| Array2::<Complex32>::zeros((nx, ny)))
        .collect::<Vec<_>>();
    let mut normalization_sumwt = 0.0f64;
    let mut reported_sumwt_terms = vec![0.0f64; term_count];
    let mut gridded_samples = 0usize;
    let mut skipped_samples = 0usize;

    for (batch_index, batch) in batches.iter().enumerate().take(end_batch).skip(start_batch) {
        let frequencies_hz = request
            .sample_frequency_batches_hz
            .get(batch_index)
            .ok_or_else(|| {
                ImagingError::InvalidRequest(format!(
                    "missing MTMFS sample-frequency batch for visibility batch {batch_index}"
                ))
            })?;
        for (index, &frequency_hz) in frequencies_hz.iter().enumerate().take(batch.len()) {
            if !batch.gridable[index] {
                skipped_samples += 1;
                continue;
            }
            let weight = batch.weight[index];
            let sumwt_factor = batch.sumwt_factor[index];
            if !(weight.is_finite()
                && weight > 0.0
                && sumwt_factor.is_finite()
                && sumwt_factor > 0.0
                && frequency_hz.is_finite()
                && frequency_hz > 0.0)
            {
                skipped_samples += 1;
                continue;
            }
            let Some(plan) = gridder.plan_sample(batch.u_lambda[index], batch.v_lambda[index])
            else {
                skipped_samples += 1;
                continue;
            };
            normalization_sumwt += 2.0 * f64::from(weight);
            for order in 0..term_count {
                let term_weight = mtmfs_casa_weighted_taylor_term(
                    weight,
                    frequency_hz,
                    request.reffreq_hz,
                    order,
                );
                let psf_weight = Complex32::new(term_weight, 0.0);
                gridder.grid_sample_product_planned(
                    &mut psf_grids[order],
                    &plan.positive,
                    psf_weight,
                );
                gridder.grid_sample_product_planned(
                    &mut psf_grids[order],
                    &plan.negative,
                    psf_weight,
                );
                reported_sumwt_terms[order] += f64::from(term_weight) * f64::from(sumwt_factor);
            }
            gridded_samples += 1;
        }
    }

    Ok(MtmfsPsfGridAccumulation {
        psf_grids,
        normalization_sumwt,
        reported_sumwt_terms,
        gridded_samples,
        skipped_samples,
    })
}

fn merge_mtmfs_psf_accumulations(
    partials: Vec<MtmfsPsfGridAccumulation>,
    term_count: usize,
    [nx, ny]: [usize; 2],
) -> Result<MtmfsPsfGridAccumulation, ImagingError> {
    let mut merged = MtmfsPsfGridAccumulation {
        psf_grids: (0..term_count)
            .map(|_| Array2::<Complex32>::zeros((nx, ny)))
            .collect(),
        normalization_sumwt: 0.0,
        reported_sumwt_terms: vec![0.0; term_count],
        gridded_samples: 0,
        skipped_samples: 0,
    };
    for partial in partials {
        if partial.psf_grids.len() != term_count || partial.reported_sumwt_terms.len() != term_count
        {
            return Err(ImagingError::InvalidRequest(
                "MTMFS PSF worker returned an unexpected Taylor-term count".to_string(),
            ));
        }
        for (target, source) in merged.psf_grids.iter_mut().zip(partial.psf_grids.iter()) {
            *target += source;
        }
        for (target, source) in merged
            .reported_sumwt_terms
            .iter_mut()
            .zip(partial.reported_sumwt_terms.iter())
        {
            *target += *source;
        }
        merged.normalization_sumwt += partial.normalization_sumwt;
        merged.gridded_samples += partial.gridded_samples;
        merged.skipped_samples += partial.skipped_samples;
    }
    Ok(merged)
}

#[allow(clippy::needless_range_loop)]
fn compute_mtmfs_psf_terms_w_project(
    request: &MtmfsRequest,
    batches: &[VisibilityBatch],
    gridder: &StandardGridder,
    requested_threads: usize,
    dirty_product_fft_policy: DirtyProductFftPolicy,
    stage_timings: &mut ImagingStageTimings,
) -> Result<MtmfsPsfState, ImagingError> {
    let prepare_started = Instant::now();
    let prepared = prepare_w_project_data(
        request.geometry,
        batches,
        gridder,
        request.w_project_planes,
        requested_threads,
    )?;
    let mut timings = PsfComputationTimings {
        grid: prepare_started.elapsed(),
        ..PsfComputationTimings::default()
    };
    let term_count = 2 * request.nterms - 1;
    let [nx, ny] = gridder.grid_shape();
    let mut psf_grids = (0..term_count)
        .map(|_| Array2::<Complex32>::zeros((nx, ny)))
        .collect::<Vec<_>>();
    let mut reported_sumwt_terms = vec![0.0f64; term_count];

    let grid_started = Instant::now();
    for sample in &prepared.samples {
        let frequency_hz =
            mtmfs_sample_frequency(request, sample.batch_index, sample.sample_index)?;
        for order in 0..term_count {
            let term_weight = mtmfs_casa_weighted_taylor_term(
                sample.weight,
                frequency_hz,
                request.reffreq_hz,
                order,
            );
            let psf_weight = Complex32::new(term_weight, 0.0);
            prepared.projector.grid_sample_planned(
                &mut psf_grids[order],
                &sample.positive_plan,
                psf_weight,
            );
            reported_sumwt_terms[order] += f64::from(term_weight) * f64::from(sample.sumwt_factor);
        }
    }
    timings.grid += grid_started.elapsed();

    if prepared.normalization_sumwt <= 0.0
        || !reported_sumwt_terms[0].is_finite()
        || reported_sumwt_terms[0] <= 0.0
    {
        return Err(ImagingError::NoUsableSamples);
    }

    let (raw_terms, fft_duration) =
        centered_ifft2_mtmfs_term_batch(psf_grids, dirty_product_fft_policy)?;
    timings.fft = fft_duration;
    let normalize_started = Instant::now();
    let mut psf_terms = raw_terms
        .iter()
        .map(|raw| {
            let mut corrected =
                gridder.corrected_w_project_image_from_grid(raw, prepared.projector.sampling());
            corrected.mapv_inplace(|value| 2.0 * value / prepared.normalization_sumwt);
            corrected
        })
        .collect::<Vec<_>>();
    let psf_peak = peak_abs_value(&psf_terms[0]);
    if !(psf_peak.is_finite() && psf_peak > 0.0) {
        return Err(ImagingError::Normalization(
            "MTMFS W-projection PSF peak is non-finite or zero".to_string(),
        ));
    }
    for psf_term in &mut psf_terms {
        psf_term.mapv_inplace(|value| value / psf_peak);
    }
    timings.normalize = normalize_started.elapsed();
    stage_timings.psf_grid += timings.grid;
    stage_timings.psf_fft += timings.fft;
    stage_timings.psf_normalize += timings.normalize;

    Ok(MtmfsPsfState {
        psf_terms,
        normalization_sumwt: prepared.normalization_sumwt,
        reported_sumwt_terms: reported_sumwt_terms
            .into_iter()
            .map(|value| value as f32)
            .collect(),
        psf_peak,
        gridded_samples: prepared.gridded_samples,
        skipped_samples: prepared.skipped_samples.len(),
    })
}

struct MtmfsResidualExecution<'a> {
    dirty_product_fft_policy: DirtyProductFftPolicy,
    stage_timings: &'a mut ImagingStageTimings,
}

#[allow(clippy::needless_range_loop)]
fn compute_mtmfs_residual_terms(
    request: &MtmfsRequest,
    batches: &[VisibilityBatch],
    gridder: &StandardGridder,
    acceleration_backend: &MtmfsAccelerationBackend<'_>,
    model_terms: &[Array2<f32>],
    psf_state: &MtmfsPsfState,
    execution: MtmfsResidualExecution<'_>,
) -> Result<Vec<Array2<f32>>, ImagingError> {
    #[cfg(any(not(target_os = "macos"), coverage))]
    let _ = acceleration_backend;
    let MtmfsResidualExecution {
        dirty_product_fft_policy,
        stage_timings,
    } = execution;
    if request.w_term_mode == WTermMode::WProject {
        return compute_mtmfs_residual_terms_w_project(
            request,
            batches,
            gridder,
            acceleration_backend.worker_threads(usize::MAX),
            model_terms,
            psf_state,
            dirty_product_fft_policy,
            stage_timings,
        );
    }
    let mut timings = ResidualComputationTimings::default();
    let model_grids = if model_terms
        .iter()
        .any(|term| term.iter().any(|value| value.abs() > 0.0))
    {
        let model_fft_started = Instant::now();
        let grids = model_terms
            .iter()
            .map(|model_term| centered_fft2(&gridder.apodize_model(model_term)))
            .collect::<Vec<_>>();
        timings.model_fft = model_fft_started.elapsed();
        Some(grids)
    } else {
        None
    };

    let degrid_grid_started = Instant::now();
    let worker_threads = acceleration_backend.worker_threads(batches.len());
    let residual_grids = if cfg!(all(target_os = "macos", not(coverage)))
        && acceleration_backend.metal_enabled()
    {
        #[cfg(all(target_os = "macos", not(coverage)))]
        {
            let executor = acceleration_backend.metal().ok_or_else(|| {
                ImagingError::Unsupported(
                    "MTMFS Metal backend was selected but no Metal executor was prepared"
                        .to_string(),
                )
            })?;
            let cache = acceleration_backend.metal_input_cache().ok_or_else(|| {
                ImagingError::Unsupported(
                    "MTMFS Metal backend was selected but no input cache was prepared".to_string(),
                )
            })?;
            executor
                .accumulate_mtmfs_residual_grids_from_cache(
                    cache,
                    request.nterms,
                    model_grids.as_deref(),
                )?
                .residual_grids
        }
        #[cfg(any(not(target_os = "macos"), coverage))]
        {
            return Err(ImagingError::Unsupported(
                "MTMFS Metal backend requires macOS Metal and is not available on this platform"
                    .to_string(),
            ));
        }
    } else if worker_threads > 1 {
        accumulate_mtmfs_residual_grids_parallel(
            request,
            batches,
            gridder,
            model_grids.as_deref(),
            worker_threads,
        )?
        .residual_grids
    } else {
        accumulate_mtmfs_residual_grid_range(
            request,
            batches,
            gridder,
            model_grids.as_deref(),
            0,
            batches.len(),
        )?
        .residual_grids
    };
    timings.degrid_grid = degrid_grid_started.elapsed();

    let (raw_terms, fft_duration) =
        centered_ifft2_mtmfs_term_batch(residual_grids, dirty_product_fft_policy)?;
    timings.fft = fft_duration;
    let normalize_started = Instant::now();
    let residual_terms = raw_terms
        .iter()
        .map(|raw| {
            let mut image = gridder.corrected_image_from_grid(raw);
            image.mapv_inplace(|value| value / psf_state.normalization_sumwt / psf_state.psf_peak);
            image
        })
        .collect::<Vec<_>>();
    timings.normalize = normalize_started.elapsed();
    stage_timings.model_fft += timings.model_fft;
    stage_timings.residual_degrid_grid += timings.degrid_grid;
    stage_timings.residual_fft += timings.fft;
    stage_timings.residual_normalize += timings.normalize;
    Ok(residual_terms)
}

#[allow(clippy::needless_range_loop, clippy::too_many_arguments)]
fn compute_mtmfs_residual_terms_w_project(
    request: &MtmfsRequest,
    batches: &[VisibilityBatch],
    gridder: &StandardGridder,
    requested_threads: usize,
    model_terms: &[Array2<f32>],
    psf_state: &MtmfsPsfState,
    dirty_product_fft_policy: DirtyProductFftPolicy,
    stage_timings: &mut ImagingStageTimings,
) -> Result<Vec<Array2<f32>>, ImagingError> {
    let prepare_started = Instant::now();
    let prepared = prepare_w_project_data(
        request.geometry,
        batches,
        gridder,
        request.w_project_planes,
        requested_threads,
    )?;
    let mut timings = ResidualComputationTimings {
        degrid_grid: prepare_started.elapsed(),
        ..ResidualComputationTimings::default()
    };
    let [nx, ny] = gridder.grid_shape();
    let mut residual_grids = (0..request.nterms)
        .map(|_| Array2::<Complex32>::zeros((nx, ny)))
        .collect::<Vec<_>>();
    let model_grids = if model_terms
        .iter()
        .any(|term| term.iter().any(|value| value.abs() > 0.0))
    {
        let model_fft_started = Instant::now();
        let grids = model_terms
            .iter()
            .map(|model_term| {
                centered_fft2(
                    &gridder.apodize_w_project_model(model_term, prepared.projector.sampling()),
                )
            })
            .collect::<Vec<_>>();
        timings.model_fft = model_fft_started.elapsed();
        Some(grids)
    } else {
        None
    };

    let degrid_started = Instant::now();
    let mut taylor_weights = Vec::<f32>::with_capacity(request.nterms);
    let mut predicted_visibility_terms = Vec::<Complex32>::with_capacity(request.nterms);
    for sample in &prepared.samples {
        let frequency_hz =
            mtmfs_sample_frequency(request, sample.batch_index, sample.sample_index)?;
        fill_mtmfs_taylor_weights(
            &mut taylor_weights,
            frequency_hz,
            request.reffreq_hz,
            request.nterms,
        );
        predicted_visibility_terms.clear();
        if let Some(model_grids) = model_grids.as_ref() {
            for grid in model_grids.iter().take(request.nterms) {
                predicted_visibility_terms.push(
                    prepared
                        .projector
                        .degrid_sample_planned(grid, &sample.positive_plan),
                );
            }
        }
        let predicted_visibility = predicted_visibility_terms
            .iter()
            .zip(&taylor_weights)
            .fold(Complex32::new(0.0, 0.0), |sum, (predicted, &factor)| {
                sum + *predicted * factor
            });
        let residual_visibility = sample.visibility - predicted_visibility;
        for (residual_order, residual_grid) in
            residual_grids.iter_mut().enumerate().take(request.nterms)
        {
            let term_weight = mtmfs_casa_weighted_taylor_term(
                sample.weight,
                frequency_hz,
                request.reffreq_hz,
                residual_order,
            );
            let residual = residual_visibility * term_weight;
            prepared
                .projector
                .grid_sample_planned(residual_grid, &sample.positive_plan, residual);
        }
    }
    timings.degrid_grid += degrid_started.elapsed();

    let (raw_terms, fft_duration) =
        centered_ifft2_mtmfs_term_batch(residual_grids, dirty_product_fft_policy)?;
    timings.fft = fft_duration;
    let normalize_started = Instant::now();
    let residual_terms = raw_terms
        .iter()
        .map(|raw| {
            let mut image =
                gridder.corrected_w_project_image_from_grid(raw, prepared.projector.sampling());
            image.mapv_inplace(|value| {
                2.0 * value / psf_state.normalization_sumwt / psf_state.psf_peak
            });
            image
        })
        .collect::<Vec<_>>();
    timings.normalize = normalize_started.elapsed();
    stage_timings.model_fft += timings.model_fft;
    stage_timings.residual_degrid_grid += timings.degrid_grid;
    stage_timings.residual_fft += timings.fft;
    stage_timings.residual_normalize += timings.normalize;
    Ok(residual_terms)
}

fn accumulate_mtmfs_residual_grids_parallel(
    request: &MtmfsRequest,
    batches: &[VisibilityBatch],
    gridder: &StandardGridder,
    model_grids: Option<&[Array2<Complex32>]>,
    worker_threads: usize,
) -> Result<MtmfsResidualGridAccumulation, ImagingError> {
    let chunk_size = batches.len().div_ceil(worker_threads);
    let partials = thread::scope(|scope| {
        let mut handles = Vec::new();
        for start in (0..batches.len()).step_by(chunk_size) {
            let end = (start + chunk_size).min(batches.len());
            handles.push(scope.spawn(move || {
                accumulate_mtmfs_residual_grid_range(
                    request,
                    batches,
                    gridder,
                    model_grids,
                    start,
                    end,
                )
            }));
        }
        handles
            .into_iter()
            .map(|handle| {
                handle.join().map_err(|_| {
                    ImagingError::InvalidRequest(
                        "MTMFS residual worker thread panicked".to_string(),
                    )
                })?
            })
            .collect::<Result<Vec<_>, _>>()
    })?;
    merge_mtmfs_residual_accumulations(partials, request.nterms, gridder.grid_shape())
}

fn accumulate_mtmfs_residual_grid_range(
    request: &MtmfsRequest,
    batches: &[VisibilityBatch],
    gridder: &StandardGridder,
    model_grids: Option<&[Array2<Complex32>]>,
    start_batch: usize,
    end_batch: usize,
) -> Result<MtmfsResidualGridAccumulation, ImagingError> {
    let [nx, ny] = gridder.grid_shape();
    let mut residual_grids = (0..request.nterms)
        .map(|_| Array2::<Complex32>::zeros((nx, ny)))
        .collect::<Vec<_>>();
    let mut taylor_weights = Vec::<f32>::with_capacity(request.nterms);
    let mut predicted_visibility_terms = Vec::<Complex32>::with_capacity(request.nterms);

    for (batch_index, batch) in batches.iter().enumerate().take(end_batch).skip(start_batch) {
        let frequencies_hz = request
            .sample_frequency_batches_hz
            .get(batch_index)
            .ok_or_else(|| {
                ImagingError::InvalidRequest(format!(
                    "missing MTMFS sample-frequency batch for visibility batch {batch_index}"
                ))
            })?;
        for (index, &frequency_hz) in frequencies_hz.iter().enumerate().take(batch.len()) {
            let weight = batch.weight[index];
            let observed_visibility = batch.visibility[index];
            let gridable = batch.gridable[index];
            let planned_sample = if gridable
                && weight.is_finite()
                && weight > 0.0
                && observed_visibility.re.is_finite()
                && observed_visibility.im.is_finite()
                && frequency_hz.is_finite()
                && frequency_hz > 0.0
            {
                gridder.plan_sample(batch.u_lambda[index], batch.v_lambda[index])
            } else {
                None
            };
            let Some(plan) = planned_sample.as_ref() else {
                continue;
            };
            fill_mtmfs_taylor_weights(
                &mut taylor_weights,
                frequency_hz,
                request.reffreq_hz,
                request.nterms,
            );
            predicted_visibility_terms.clear();
            if let Some(model_grids) = model_grids {
                for grid in model_grids.iter().take(request.nterms) {
                    predicted_visibility_terms.push(
                        gridder.degrid_sample_product_planned_normalized(grid, &plan.positive),
                    );
                }
            }
            let predicted_visibility = predicted_visibility_terms
                .iter()
                .zip(&taylor_weights)
                .fold(Complex32::new(0.0, 0.0), |sum, (predicted, &factor)| {
                    sum + *predicted * factor
                });
            let residual_visibility = observed_visibility - predicted_visibility;
            for (residual_order, residual_grid) in
                residual_grids.iter_mut().enumerate().take(request.nterms)
            {
                let term_weight = mtmfs_casa_weighted_taylor_term(
                    weight,
                    frequency_hz,
                    request.reffreq_hz,
                    residual_order,
                );
                let residual = residual_visibility * term_weight;
                gridder.grid_sample_product_planned(residual_grid, &plan.positive, residual);
                gridder.grid_sample_product_planned(residual_grid, &plan.negative, residual.conj());
            }
        }
    }

    Ok(MtmfsResidualGridAccumulation { residual_grids })
}

fn merge_mtmfs_residual_accumulations(
    partials: Vec<MtmfsResidualGridAccumulation>,
    term_count: usize,
    [nx, ny]: [usize; 2],
) -> Result<MtmfsResidualGridAccumulation, ImagingError> {
    let mut merged = MtmfsResidualGridAccumulation {
        residual_grids: (0..term_count)
            .map(|_| Array2::<Complex32>::zeros((nx, ny)))
            .collect(),
    };
    for partial in partials {
        if partial.residual_grids.len() != term_count {
            return Err(ImagingError::InvalidRequest(
                "MTMFS residual worker returned an unexpected Taylor-term count".to_string(),
            ));
        }
        for (target, source) in merged
            .residual_grids
            .iter_mut()
            .zip(partial.residual_grids.iter())
        {
            *target += source;
        }
    }
    Ok(merged)
}

fn mtmfs_sample_frequency(
    request: &MtmfsRequest,
    batch_index: usize,
    sample_index: usize,
) -> Result<f64, ImagingError> {
    let frequency_hz = request
        .sample_frequency_batches_hz
        .get(batch_index)
        .and_then(|batch| batch.get(sample_index))
        .copied()
        .ok_or_else(|| {
            ImagingError::InvalidRequest(format!(
                "missing MTMFS sample frequency for batch {batch_index} sample {sample_index}"
            ))
        })?;
    if !(frequency_hz.is_finite() && frequency_hz > 0.0) {
        return Err(ImagingError::InvalidRequest(format!(
            "MTMFS sample frequency for batch {batch_index} sample {sample_index} must be finite and > 0 Hz"
        )));
    }
    Ok(frequency_hz)
}

#[derive(Debug, Clone)]
struct MtmfsScaleHessian {
    scale_size: f32,
    hessian: Vec<Vec<f32>>,
    inverse: Vec<Vec<f32>>,
}

fn mtmfs_scale_hessians(
    psf_terms: &[Array2<f32>],
    nterms: usize,
    scale_sizes: &[f32],
) -> Result<Vec<MtmfsScaleHessian>, ImagingError> {
    if psf_terms.len() < 2 * nterms - 1 {
        return Err(ImagingError::InvalidRequest(format!(
            "MTMFS PSF stack length {} is smaller than required {}",
            psf_terms.len(),
            2 * nterms - 1
        )));
    }
    if scale_sizes.is_empty() {
        return Err(ImagingError::InvalidRequest(
            "MTMFS requires at least one effective deconvolution scale".to_string(),
        ));
    }
    let expected_shape = psf_terms[0].dim();
    if psf_terms.iter().any(|term| term.dim() != expected_shape) {
        return Err(ImagingError::InvalidRequest(
            "MTMFS PSF Taylor terms must share one image shape".to_string(),
        ));
    }
    let psf_peak_position = casa_mtmfs_psf_peak_position(
        &psf_terms[0],
        scale_sizes.iter().copied().fold(0.0, f32::max),
    );

    scale_sizes
        .iter()
        .copied()
        .map(|scale_size| {
            let hessian = (0..nterms)
                .map(|row| {
                    (0..nterms)
                        .map(|col| {
                            mtmfs_scale_hessian_peak(
                                &psf_terms[row + col],
                                scale_size,
                                psf_peak_position,
                            )
                        })
                        .collect::<Vec<_>>()
                })
                .collect::<Vec<_>>();
            let inverse = invert_symmetric_definite(&hessian)?;
            Ok(MtmfsScaleHessian {
                scale_size,
                hessian,
                inverse,
            })
        })
        .collect()
}

fn mtmfs_scale_hessians_from_basis(
    basis: &MtmfsMultiscaleBasis,
    nterms: usize,
) -> Result<Vec<MtmfsScaleHessian>, ImagingError> {
    basis
        .scale_sizes
        .iter()
        .enumerate()
        .map(|(scale_index, &scale_size)| {
            let patch = basis.psf_pair_patch(scale_index, scale_index, 0);
            let center = (patch.dim().0 / 2, patch.dim().1 / 2);
            let hessian = (0..nterms)
                .map(|row| {
                    (0..nterms)
                        .map(|col| {
                            basis.psf_pair_patch(scale_index, scale_index, row + col)[center]
                        })
                        .collect::<Vec<_>>()
                })
                .collect::<Vec<_>>();
            let inverse = invert_symmetric_definite(&hessian)?;
            Ok(MtmfsScaleHessian {
                scale_size,
                hessian,
                inverse,
            })
        })
        .collect()
}

fn mtmfs_scale_hessians_for_clean(
    psf_terms: &[Array2<f32>],
    nterms: usize,
    scale_sizes: &[f32],
    niter: usize,
    warnings: &mut Vec<String>,
) -> Result<Vec<MtmfsScaleHessian>, ImagingError> {
    match mtmfs_scale_hessians(psf_terms, nterms, scale_sizes) {
        Ok(hessians) => Ok(hessians),
        Err(ImagingError::Unsupported(reason)) if niter == 0 => {
            // CASA's `computeprincipalsolution()` also tries to construct the
            // Hessian for niter=0. When that solve reports a singular matrix,
            // `mtrestore()` ignores the false return and restores the raw
            // residual Taylor terms. An identity principal transform
            // reproduces that behavior while retaining the dirty products.
            warnings.push(format!(
                "CASA MT-MFS niter=0 principal solution was skipped: {reason}"
            ));
            let identity = (0..nterms)
                .map(|row| {
                    (0..nterms)
                        .map(|col| if row == col { 1.0 } else { 0.0 })
                        .collect::<Vec<_>>()
                })
                .collect::<Vec<_>>();
            Ok(scale_sizes
                .iter()
                .copied()
                .map(|scale_size| MtmfsScaleHessian {
                    scale_size,
                    hessian: identity.clone(),
                    inverse: identity.clone(),
                })
                .collect())
        }
        Err(error) => Err(error),
    }
}

fn casa_mtmfs_psf_peak_position(psf: &Array2<f32>, max_scale_size: f32) -> (usize, usize) {
    let (nx, ny) = psf.dim();
    let mut support = ((4.0f32 * 4.0 + max_scale_size * max_scale_size).sqrt() * 20.0) as usize;
    support = support.max(80).min(nx).min(ny);
    if support % 2 != 0 {
        support -= 1;
    }
    let x0 = if nx > support {
        nx / 2 - support / 2
    } else {
        0
    };
    let y0 = if ny > support {
        ny / 2 - support / 2
    } else {
        0
    };
    let x1 = if nx > support {
        nx / 2 + support / 2
    } else {
        nx - 1
    };
    let y1 = if ny > support {
        ny / 2 + support / 2
    } else {
        ny - 1
    };
    let mut peak_position = (0, 0);
    let mut peak_abs = 0.0f32;
    for y in y0..y1 {
        for x in x0..x1 {
            let value_abs = psf[(x, y)].abs();
            if value_abs > peak_abs {
                peak_abs = value_abs;
                peak_position = (x, y);
            }
        }
    }
    peak_position
}

fn mtmfs_scale_hessian_peak(
    psf: &Array2<f32>,
    scale_size: f32,
    psf_peak_position: (usize, usize),
) -> f32 {
    let (nx, ny) = psf.dim();
    if scale_size == 0.0 {
        return psf[psf_peak_position];
    }

    // MultiTermMatrixCleaner forms PSF_t * scale_s * scale_s and samples its
    // central peak. The scale has compact support, so evaluating that one
    // circular-convolution sample directly avoids materializing CASA's
    // full-image scale FFTs while retaining the same Hessian semantics.
    let radius = scale_size.ceil() as usize;
    let kernel = make_multiscale_kernel((2 * radius + 1, 2 * radius + 1), scale_size);
    let kernel_center = (radius as isize, radius as isize);
    let mut peak = 0.0f32;
    for ((left_x, left_y), left) in kernel.indexed_iter() {
        if *left == 0.0 {
            continue;
        }
        let left_dx = left_x as isize - kernel_center.0;
        let left_dy = left_y as isize - kernel_center.1;
        for ((right_x, right_y), right) in kernel.indexed_iter() {
            if *right == 0.0 {
                continue;
            }
            let offset_x = left_dx + right_x as isize - kernel_center.0;
            let offset_y = left_dy + right_y as isize - kernel_center.1;
            let psf_x = (psf_peak_position.0 as isize - offset_x).rem_euclid(nx as isize) as usize;
            let psf_y = (psf_peak_position.1 as isize - offset_y).rem_euclid(ny as isize) as usize;
            peak += psf[(psf_x, psf_y)] * *left * *right;
        }
    }
    peak
}

fn invert_symmetric_definite(matrix: &[Vec<f32>]) -> Result<Vec<Vec<f32>>, ImagingError> {
    let n = matrix.len();
    if n == 0 || matrix.iter().any(|row| row.len() != n) {
        return Err(ImagingError::InvalidRequest(
            "MTMFS Hessian must be a non-empty square matrix".to_string(),
        ));
    }
    let values = matrix
        .iter()
        .flat_map(|row| row.iter().map(|value| f64::from(*value)))
        .collect::<Vec<_>>();
    // Production PSFs have a positive main lobe. Tiny cache-validation images
    // can place that lobe outside the image and leave a negative alias peak.
    // The normal equations are then negative definite but remain invertible;
    // orient them for Cholesky and restore the inverse sign afterward.
    let orientation = if values[0] < 0.0 { -1.0 } else { 1.0 };
    let oriented_rows = matrix
        .iter()
        .map(|row| {
            row.iter()
                .map(|value| orientation * f64::from(*value))
                .collect::<Vec<_>>()
        })
        .collect::<Vec<_>>();
    let inverse = invert_symmetric_positive_definite_casacore(&oriented_rows).ok_or_else(|| {
        ImagingError::Unsupported(format!(
            "MTMFS Hessian is not symmetric definite at the CASA PSF peak: {values:?}"
        ))
    })?;
    Ok(inverse
        .into_iter()
        .map(|row| {
            row.into_iter()
                .map(|value| (orientation * value) as f32)
                .collect::<Vec<_>>()
        })
        .collect())
}

fn solve_mtmfs_coefficients(rhs: &[f32], inv_hessian: &[Vec<f32>]) -> Vec<f32> {
    inv_hessian
        .iter()
        .map(|row| {
            row.iter()
                .zip(rhs.iter())
                .map(|(left, right)| *left * *right)
                .sum()
        })
        .collect()
}

fn principal_solution_terms(
    residual_terms: &[Array2<f32>],
    inv_hessian: &[Vec<f32>],
) -> Vec<Array2<f32>> {
    let nterms = residual_terms.len();
    let shape = residual_terms[0].raw_dim();
    let mut principal_terms = (0..nterms)
        .map(|_| Array2::<f32>::zeros(shape))
        .collect::<Vec<_>>();
    for x in 0..shape[0] {
        for y in 0..shape[1] {
            let rhs = residual_terms
                .iter()
                .map(|term| term[(x, y)])
                .collect::<Vec<_>>();
            let coeffs = solve_mtmfs_coefficients(&rhs, inv_hessian);
            for (term, coeff) in coeffs.into_iter().enumerate() {
                principal_terms[term][(x, y)] = coeff;
            }
        }
    }
    principal_terms
}

fn find_mtmfs_component(
    residual_terms: &[Array2<f32>],
    hessian: &[Vec<f32>],
    inv_hessian: &[Vec<f32>],
    clean_mask: Option<&Array2<bool>>,
    requested_threads: usize,
) -> Option<((usize, usize), Vec<f32>, f32)> {
    let (nx, ny) = residual_terms.first()?.dim();
    let worker_threads = requested_threads.min(nx.max(1)).max(1);
    if worker_threads <= 1 {
        return find_mtmfs_component_range(
            residual_terms,
            hessian,
            inv_hessian,
            clean_mask,
            0,
            nx,
            ny,
        );
    }
    let chunk_size = nx.div_ceil(worker_threads);
    thread::scope(|scope| {
        let mut handles = Vec::new();
        for start_x in (0..nx).step_by(chunk_size) {
            let end_x = (start_x + chunk_size).min(nx);
            handles.push(scope.spawn(move || {
                find_mtmfs_component_range(
                    residual_terms,
                    hessian,
                    inv_hessian,
                    clean_mask,
                    start_x,
                    end_x,
                    ny,
                )
            }));
        }
        handles
            .into_iter()
            .filter_map(|handle| handle.join().ok().flatten())
            .max_by(|left, right| left.2.total_cmp(&right.2))
    })
}

fn find_mtmfs_component_range(
    residual_terms: &[Array2<f32>],
    hessian: &[Vec<f32>],
    inv_hessian: &[Vec<f32>],
    clean_mask: Option<&Array2<bool>>,
    start_x: usize,
    end_x: usize,
    ny: usize,
) -> Option<((usize, usize), Vec<f32>, f32)> {
    let mut best = None::<((usize, usize), Vec<f32>, f32)>;
    let mut best_penalty = -1.0f32;
    for x in start_x..end_x {
        for y in 0..ny {
            if clean_mask.is_some_and(|mask| !mask[(x, y)]) {
                continue;
            }
            let rhs = residual_terms
                .iter()
                .map(|term| term[(x, y)])
                .collect::<Vec<_>>();
            let coeffs = solve_mtmfs_coefficients(&rhs, inv_hessian);
            let mut penalty = 0.0f32;
            for row in 0..coeffs.len() {
                penalty += 2.0 * coeffs[row] * rhs[row];
                for col in 0..coeffs.len() {
                    penalty -= coeffs[row] * coeffs[col] * hessian[row][col];
                }
            }
            let penalty_abs = penalty.abs();
            if penalty_abs > best_penalty {
                best_penalty = penalty_abs;
                best = Some(((x, y), coeffs, penalty_abs));
            }
        }
    }
    best
}

#[allow(clippy::too_many_arguments)]
fn run_mtmfs_minor_cycle(
    request: &MtmfsRequest,
    psf_terms: &[Array2<f32>],
    scale_hessians: &[MtmfsScaleHessian],
    multiscale_basis: Option<&MtmfsMultiscaleBasis>,
    model_terms: &mut [Array2<f32>],
    residual_terms: &mut [Array2<f32>],
    cycle_reported_niter: usize,
    cycle_threshold_jy_per_beam: f32,
    nsigma_threshold_jy_per_beam: f32,
    stage_timings: &mut ImagingStageTimings,
    requested_threads: usize,
    mut model_support_positions: Option<&mut BTreeSet<(usize, usize)>>,
) -> (HogbomMinorCycleOutcome, MinorCycleProbe) {
    if !request.multiscale_scales.is_empty() {
        return run_mtmfs_multiscale_minor_cycle(
            request,
            scale_hessians,
            multiscale_basis.expect("MT-MFS multiscale requests must prepare a scale basis"),
            model_terms,
            residual_terms,
            cycle_reported_niter,
            cycle_threshold_jy_per_beam,
            nsigma_threshold_jy_per_beam,
            stage_timings,
            model_support_positions.as_deref_mut(),
        );
    }
    let principal_hessian = &scale_hessians[0];
    let cycle_component_budget = hogbom_component_budget(cycle_reported_niter, request.clean);
    let mut cycle_component_updates = 0usize;
    let mut updated_model = false;
    let mut stop_reason = None;
    let mut probe = MinorCycleProbe::default();
    let minor_started = Instant::now();
    while cycle_component_updates < cycle_component_budget {
        let peak_abs = peak_abs_value_masked(&residual_terms[0], request.clean_mask.as_ref());
        if let Some(reason) = minor_cycle_stop_reason(
            peak_abs,
            request.clean.threshold_jy_per_beam,
            cycle_threshold_jy_per_beam,
            nsigma_threshold_jy_per_beam,
        ) {
            stop_reason = Some(reason);
            break;
        }
        let Some(((peak_x, peak_y), coeffs, candidate_strength)) = find_mtmfs_component(
            residual_terms,
            &principal_hessian.hessian,
            &principal_hessian.inverse,
            request.clean_mask.as_ref(),
            requested_threads,
        ) else {
            stop_reason = Some(CleanStopReason::NoCleanablePixels);
            break;
        };
        if cycle_component_updates == 0 {
            probe = MinorCycleProbe {
                initial_scale_pixels: Some(0.0),
                initial_candidate_strength_jy_per_beam: Some(candidate_strength),
                initial_candidate_position: Some([peak_x, peak_y]),
            };
        }
        for (term_index, coefficient) in coeffs.iter().enumerate() {
            let component = request.clean.gain * *coefficient;
            model_terms[term_index][(peak_x, peak_y)] += component;
        }
        if let Some(positions) = model_support_positions.as_deref_mut() {
            positions.insert((peak_x, peak_y));
        }
        for residual_order in 0..request.nterms {
            for model_order in 0..request.nterms {
                let component = request.clean.gain * coeffs[model_order];
                subtract_shifted_kernel(
                    &mut residual_terms[residual_order],
                    &psf_terms[residual_order + model_order],
                    (peak_x, peak_y),
                    component,
                );
            }
        }
        cycle_component_updates += 1;
        updated_model = true;
    }
    let minor_elapsed = minor_started.elapsed();
    stage_timings.minor_cycle += minor_elapsed;
    stage_timings.minor_cycle_solve += minor_elapsed;
    (
        HogbomMinorCycleOutcome {
            updated_model,
            actual_updates: cycle_component_updates,
            reported_updates: cycle_component_updates.min(cycle_reported_niter),
            stop_reason,
            final_cycle_threshold_jy_per_beam: cycle_threshold_jy_per_beam,
            final_nsigma_threshold_jy_per_beam: nsigma_threshold_jy_per_beam,
        },
        probe,
    )
}

#[allow(clippy::too_many_arguments)]
fn run_mtmfs_multiscale_minor_cycle(
    request: &MtmfsRequest,
    scale_hessians: &[MtmfsScaleHessian],
    basis: &MtmfsMultiscaleBasis,
    model_terms: &mut [Array2<f32>],
    residual_terms: &mut [Array2<f32>],
    cycle_reported_niter: usize,
    cycle_threshold_jy_per_beam: f32,
    nsigma_threshold_jy_per_beam: f32,
    stage_timings: &mut ImagingStageTimings,
    mut model_support_positions: Option<&mut BTreeSet<(usize, usize)>>,
) -> (HogbomMinorCycleOutcome, MinorCycleProbe) {
    let scale_sizes = effective_mtmfs_multiscale_scales(request);
    debug_assert_eq!(scale_sizes.len(), scale_hessians.len());
    debug_assert_eq!(scale_sizes, basis.scale_sizes);
    debug_assert!(
        scale_sizes
            .iter()
            .zip(scale_hessians)
            .all(|(size, hessian)| *size == hessian.scale_size)
    );
    let minor_started = Instant::now();
    let rhs_prepare_started = Instant::now();
    let mut scale_rhs_terms = basis.convolve_residual_terms(residual_terms);
    let rhs_prepare_elapsed = rhs_prepare_started.elapsed();
    let mut candidate_search_elapsed = Duration::ZERO;
    let mut model_update_elapsed = Duration::ZERO;
    let mut rhs_subtract_elapsed = Duration::ZERO;
    let mut residual_writeback_elapsed = Duration::ZERO;
    let component_trace_limit = env::var("CASA_RS_MTMFS_COMPONENT_TRACE_LIMIT")
        .ok()
        .and_then(|value| value.parse::<usize>().ok())
        .unwrap_or(0);
    let first_candidate_started = Instant::now();
    let first_candidate = find_mtmfs_multiscale_component(
        &scale_rhs_terms,
        basis,
        scale_hessians,
        (component_trace_limit > 0).then_some(0),
    );
    candidate_search_elapsed += first_candidate_started.elapsed();
    let Some(first_candidate) = first_candidate else {
        let minor_elapsed = minor_started.elapsed();
        stage_timings.minor_cycle += minor_elapsed;
        stage_timings.minor_cycle_solve += minor_elapsed;
        return (
            HogbomMinorCycleOutcome {
                updated_model: false,
                actual_updates: 0,
                reported_updates: 0,
                stop_reason: Some(CleanStopReason::NoCleanablePixels),
                final_cycle_threshold_jy_per_beam: cycle_threshold_jy_per_beam,
                final_nsigma_threshold_jy_per_beam: nsigma_threshold_jy_per_beam,
            },
            MinorCycleProbe::default(),
        );
    };
    let probe = MinorCycleProbe {
        initial_scale_pixels: Some(scale_sizes[first_candidate.scale_index]),
        initial_candidate_strength_jy_per_beam: first_candidate
            .coefficients
            .first()
            .copied()
            .map(f32::abs),
        initial_candidate_position: Some([first_candidate.position.0, first_candidate.position.1]),
    };
    let principal_hessian_peak = scale_hessians[0].hessian[0][0];
    let initial_cycle_peak =
        basis.peak_abs_scale_zero(&scale_rhs_terms[0]) / principal_hessian_peak;
    if let Some(reason) = minor_cycle_stop_reason(
        initial_cycle_peak,
        request.clean.threshold_jy_per_beam,
        cycle_threshold_jy_per_beam,
        nsigma_threshold_jy_per_beam,
    ) {
        let minor_elapsed = minor_started.elapsed();
        stage_timings.minor_cycle += minor_elapsed;
        stage_timings.minor_cycle_solve += minor_elapsed;
        return (
            HogbomMinorCycleOutcome {
                updated_model: false,
                actual_updates: 0,
                reported_updates: 0,
                stop_reason: Some(reason),
                final_cycle_threshold_jy_per_beam: cycle_threshold_jy_per_beam,
                final_nsigma_threshold_jy_per_beam: nsigma_threshold_jy_per_beam,
            },
            probe,
        );
    }

    let cycle_component_budget = hogbom_component_budget(cycle_reported_niter, request.clean);
    let mut cycle_component_updates = 0usize;
    let mut updated_model = false;
    let mut stop_reason = None;
    let mut next_candidate = Some(first_candidate);
    while cycle_component_updates < cycle_component_budget {
        let candidate_search_started = Instant::now();
        let candidate = next_candidate.take().or_else(|| {
            find_mtmfs_multiscale_component(
                &scale_rhs_terms,
                basis,
                scale_hessians,
                (cycle_component_updates < component_trace_limit)
                    .then_some(cycle_component_updates),
            )
        });
        candidate_search_elapsed += candidate_search_started.elapsed();
        let Some(candidate) = candidate else {
            stop_reason = Some(CleanStopReason::NoCleanablePixels);
            break;
        };
        let peak_abs = basis.peak_abs_scale_zero(&scale_rhs_terms[0]) / principal_hessian_peak;
        if let Some(reason) = minor_cycle_stop_reason(
            peak_abs,
            request.clean.threshold_jy_per_beam,
            cycle_threshold_jy_per_beam,
            nsigma_threshold_jy_per_beam,
        ) {
            stop_reason = Some(reason);
            break;
        }
        if cycle_component_updates > 0 && peak_abs > initial_cycle_peak * 1.5 {
            stop_reason = Some(CleanStopReason::DivergenceDetected);
            break;
        }

        if cycle_component_updates < component_trace_limit {
            eprintln!(
                "mtmfs_component_trace local_iteration={} scale_index={} scale_pixels={} x={} y={} signed_score={} biased_signed_score={} coefficients={:?} rhs={:?} scale_zero_peak={} cycle_threshold={} nsigma_threshold={}",
                cycle_component_updates,
                candidate.scale_index,
                scale_sizes[candidate.scale_index],
                candidate.position.0,
                candidate.position.1,
                candidate.signed_score,
                candidate.biased_signed_score,
                candidate.coefficients,
                candidate.rhs_values,
                peak_abs,
                cycle_threshold_jy_per_beam,
                nsigma_threshold_jy_per_beam,
            );
        }
        let coeffs = candidate.coefficients;
        let model_update_started = Instant::now();
        if let Some(positions) = model_support_positions.as_deref_mut() {
            record_shifted_kernel_support_positions(
                positions,
                model_terms[0].dim(),
                &basis.compact_scale_kernels[candidate.scale_index],
                candidate.position,
            );
        }
        for (term_index, coefficient) in coeffs.iter().enumerate().take(request.nterms) {
            add_shifted_kernel_casa_mtmfs_model(
                &mut model_terms[term_index],
                &basis.compact_scale_kernels[candidate.scale_index],
                candidate.position,
                request.clean.gain,
                *coefficient,
            );
        }
        model_update_elapsed += model_update_started.elapsed();
        let rhs_subtract_started = Instant::now();
        basis.subtract_rhs_component(
            &mut scale_rhs_terms,
            candidate.scale_index,
            candidate.position,
            request.clean.gain,
            &coeffs,
        );
        rhs_subtract_elapsed += rhs_subtract_started.elapsed();
        cycle_component_updates += 1;
        updated_model = true;
    }
    if updated_model {
        let residual_writeback_started = Instant::now();
        basis.write_scale_zero_rhs(&mut scale_rhs_terms[0], residual_terms);
        residual_writeback_elapsed += residual_writeback_started.elapsed();
    }
    let minor_elapsed = minor_started.elapsed();
    stage_timings.minor_cycle += minor_elapsed;
    stage_timings.minor_cycle_solve += minor_elapsed;
    let reported_updates =
        casa_multiscale_reported_updates(cycle_component_updates, cycle_reported_niter);
    if profile::standard_mfs_profile_detail_enabled() {
        let candidate_positions = basis
            .scale_search_positions
            .iter()
            .map(|positions| positions.as_ref().map_or(0, Vec::len))
            .collect::<Vec<_>>();
        eprintln!(
            "mtmfs_multiscale_minor_cycle_profile storage={} updates={} reported_updates={} candidate_positions={candidate_positions:?} rhs_prepare_ms={:.3} candidate_search_ms={:.3} model_update_ms={:.3} rhs_subtract_ms={:.3} residual_writeback_ms={:.3} total_ms={:.3}",
            if basis.sparse_rhs {
                "sparse-positions"
            } else {
                "dense-images"
            },
            cycle_component_updates,
            reported_updates,
            profile::millis(rhs_prepare_elapsed),
            profile::millis(candidate_search_elapsed),
            profile::millis(model_update_elapsed),
            profile::millis(rhs_subtract_elapsed),
            profile::millis(residual_writeback_elapsed),
            profile::millis(minor_elapsed),
        );
    }
    (
        HogbomMinorCycleOutcome {
            updated_model,
            actual_updates: cycle_component_updates,
            reported_updates,
            stop_reason,
            final_cycle_threshold_jy_per_beam: cycle_threshold_jy_per_beam,
            final_nsigma_threshold_jy_per_beam: nsigma_threshold_jy_per_beam,
        },
        probe,
    )
}

struct MtmfsMultiscaleCandidate {
    scale_index: usize,
    position: (usize, usize),
    coefficients: Vec<f32>,
    rhs_values: Vec<f32>,
    signed_score: f32,
    biased_signed_score: f32,
}

#[derive(Clone)]
enum MtmfsScaleRhs {
    Dense(Vec<Array2<f32>>),
    Sparse(Vec<Vec<f32>>),
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum MtmfsScaleFftBackend {
    RustFft,
    FftwF32,
    CasaFft0F32 { threads: usize },
}

impl MtmfsScaleFftBackend {
    fn from_policy(policy: DirtyProductFftPolicy) -> Self {
        if env::var_os("CASA_RS_EXPERIMENTAL_MT_MFS_CASA_FFT0").is_some() {
            assert!(
                policy.backend == FftBackendChoice::Fftw && crate::fftw_local::configured_f32(),
                "CASA_RS_EXPERIMENTAL_MT_MFS_CASA_FFT0 requires the configured FFTW f32 backend"
            );
            let threads = env::var("CASA_RS_EXPERIMENTAL_MT_MFS_CASA_FFT0_THREADS")
                .ok()
                .and_then(|value| value.parse::<usize>().ok())
                .filter(|value| *value > 0)
                .unwrap_or_else(|| {
                    thread::available_parallelism().map_or(1, std::num::NonZeroUsize::get)
                });
            return Self::CasaFft0F32 { threads };
        }
        if policy.backend == FftBackendChoice::Fftw && crate::fftw_local::configured_f32() {
            Self::FftwF32
        } else {
            Self::RustFft
        }
    }
}

fn mtmfs_use_full_fft_basis() -> bool {
    env::var_os("CASA_RS_EXPERIMENTAL_MT_MFS_FULL_FFT_BASIS").is_some()
        || env::var_os("CASA_RS_EXPERIMENTAL_MT_MFS_CASA_FFT0").is_some()
}

struct MtmfsMultiscaleBasis {
    scale_sizes: Vec<f32>,
    compact_scale_kernels: Vec<Array2<f32>>,
    scale_bias: Vec<f32>,
    scale_masks: Option<Vec<Array2<bool>>>,
    scale_search_positions: Vec<Option<Vec<(usize, usize)>>>,
    psf_pair_patches: Vec<Vec<Array2<f32>>>,
    sparse_rhs: bool,
    sparse_rhs_fft_seed: bool,
    scale_fft_backend: MtmfsScaleFftBackend,
}

impl MtmfsMultiscaleBasis {
    fn new(
        request: &MtmfsRequest,
        psf_terms: &[Array2<f32>],
        scale_sizes: &[f32],
        fft_policy: DirtyProductFftPolicy,
    ) -> Self {
        Self::new_with_sparse(
            request,
            psf_terms,
            scale_sizes,
            env::var_os("CASA_RS_EXPERIMENTAL_MT_MFS_SPARSE_RHS").is_some(),
            fft_policy,
        )
    }

    fn new_with_sparse(
        request: &MtmfsRequest,
        psf_terms: &[Array2<f32>],
        scale_sizes: &[f32],
        sparse_experiment: bool,
        fft_policy: DirtyProductFftPolicy,
    ) -> Self {
        let scale_fft_backend = MtmfsScaleFftBackend::from_policy(fft_policy);
        let casa_fft0 = matches!(scale_fft_backend, MtmfsScaleFftBackend::CasaFft0F32 { .. });
        let compact_scale_kernels = scale_sizes
            .iter()
            .map(|scale| make_compact_multiscale_kernel(*scale))
            .collect::<Vec<_>>();
        let max_scale = scale_sizes.iter().copied().fold(0.0f32, f32::max);
        let scale_bias = if max_scale > 0.0 && scale_sizes.len() > 1 {
            scale_sizes
                .iter()
                // MultiTermMatrixCleaner evaluates the Float expression as
                // `(small_scale_bias * scale) / maximum_scale` before the
                // subtraction. Preserve that grouping because the biased
                // cross-scale score can differ by one ULP.
                .map(|scale| 1.0 - (request.small_scale_bias * *scale) / max_scale)
                .collect::<Vec<_>>()
        } else {
            vec![1.0; scale_sizes.len()]
        };
        let image_pixels =
            request.geometry.image_shape[0].saturating_mul(request.geometry.image_shape[1]);
        let sparse_scale_search_positions = (sparse_experiment && !casa_fft0)
            .then(|| {
                request.clean_mask.as_ref().and_then(|mask| {
                    build_sparse_mtmfs_scale_search_positions(
                        mask,
                        &compact_scale_kernels,
                        scale_sizes,
                    )
                })
            })
            .flatten();
        let (scale_masks, scale_search_positions) = if let Some(positions) =
            sparse_scale_search_positions
        {
            (
                None,
                positions
                    .into_iter()
                    .map(Some)
                    .collect::<Vec<Option<Vec<(usize, usize)>>>>(),
            )
        } else {
            let mut scale_masks = request.clean_mask.as_ref().map(|mask| {
                build_mtmfs_scale_masks_with_backend(
                    mask,
                    &compact_scale_kernels,
                    scale_sizes,
                    scale_fft_backend,
                )
            });
            let scale_search_positions = scale_masks
                .as_ref()
                .map(|masks| mtmfs_scale_search_positions_from_masks(masks, image_pixels))
                .unwrap_or_else(|| vec![None; scale_sizes.len()]);
            if casa_fft0 && sparse_experiment && scale_search_positions.iter().all(Option::is_some)
            {
                // CASA obtains these positions from the exact Float
                // FFTServer mask convolution. Once the ordered positions have
                // been retained, the dense masks no longer have a next use.
                scale_masks = None;
            }
            (scale_masks, scale_search_positions)
        };
        let sparse_rhs = sparse_experiment
            && request.clean_mask.is_some()
            && scale_search_positions.iter().all(Option::is_some)
            && scale_masks.is_none();
        let sparse_rhs_fft_seed = sparse_rhs
            && (casa_fft0
                || env::var_os("CASA_RS_EXPERIMENTAL_MT_MFS_SPARSE_RHS_FFT_SEED").is_some());
        if sparse_experiment {
            let position_counts = scale_search_positions
                .iter()
                .map(|positions| positions.as_ref().map_or(image_pixels, Vec::len))
                .collect::<Vec<_>>();
            let rhs_bytes = position_counts
                .iter()
                .copied()
                .sum::<usize>()
                .saturating_mul(request.nterms)
                .saturating_mul(std::mem::size_of::<f32>());
            eprintln!(
                "mtmfs_multiscale_rhs_experiment storage={} seeder={} image_pixels={} clean_mask_pixels={} scale_position_counts={position_counts:?} rhs_bytes={rhs_bytes}",
                if sparse_rhs {
                    "sparse-positions"
                } else {
                    "dense-fallback"
                },
                if sparse_rhs_fft_seed {
                    "full-fft-sampled"
                } else if sparse_rhs {
                    "direct-candidate-convolution"
                } else {
                    "dense-images"
                },
                image_pixels,
                request.clean_mask.as_ref().map_or(image_pixels, |mask| mask
                    .iter()
                    .filter(|value| **value)
                    .count()),
            );
        }

        let psf_peak_position =
            casa_mtmfs_psf_peak_position(psf_terms.first().expect("PSF term"), max_scale);
        let psf_support = casa_mtmfs_psf_patch_support(psf_terms[0].dim(), max_scale);
        let full_fft_basis = mtmfs_use_full_fft_basis();
        let psf_pair_patches = if full_fft_basis {
            match scale_fft_backend {
                MtmfsScaleFftBackend::CasaFft0F32 { threads } => mtmfs_psf_pair_patches_casa_fft0(
                    psf_terms,
                    &compact_scale_kernels,
                    psf_peak_position,
                    psf_support,
                    threads,
                ),
                _ => mtmfs_psf_pair_patches_fft(
                    psf_terms,
                    &compact_scale_kernels,
                    psf_peak_position,
                    psf_support,
                    scale_fft_backend,
                ),
            }
        } else {
            let mut patches = Vec::with_capacity(scale_sizes.len() * (scale_sizes.len() + 1) / 2);
            for high_scale in 0..scale_sizes.len() {
                for low_scale in 0..=high_scale {
                    let combined_kernel = convolve_compact_scale_kernels(
                        &compact_scale_kernels[high_scale],
                        &compact_scale_kernels[low_scale],
                    );
                    patches.push(
                        psf_terms
                            .iter()
                            .map(|psf| {
                                bounded_circular_convolution_patch(
                                    psf,
                                    &combined_kernel,
                                    psf_peak_position,
                                    psf_support,
                                )
                            })
                            .collect(),
                    );
                }
            }
            patches
        };
        if profile::standard_mfs_profile_detail_enabled() {
            eprintln!(
                "mtmfs_multiscale_basis route={} fft_backend={:?} psf_support={psf_support}",
                if full_fft_basis {
                    "full-float-fft"
                } else {
                    "direct-compact-convolution"
                },
                scale_fft_backend,
            );
        }

        Self {
            scale_sizes: scale_sizes.to_vec(),
            compact_scale_kernels,
            scale_bias,
            scale_masks,
            scale_search_positions,
            psf_pair_patches,
            sparse_rhs,
            sparse_rhs_fft_seed,
            scale_fft_backend,
        }
    }

    fn convolve_residual_terms(&self, residual_terms: &[Array2<f32>]) -> Vec<MtmfsScaleRhs> {
        self.convolve_residual_terms_with_sparse_seed(
            residual_terms,
            self.sparse_rhs,
            self.sparse_rhs_fft_seed,
        )
    }

    #[cfg(test)]
    fn convolve_residual_terms_with_sparse(
        &self,
        residual_terms: &[Array2<f32>],
        sparse_enabled: bool,
    ) -> Vec<MtmfsScaleRhs> {
        self.convolve_residual_terms_with_sparse_seed(residual_terms, sparse_enabled, false)
    }

    fn convolve_residual_terms_with_sparse_seed(
        &self,
        residual_terms: &[Array2<f32>],
        sparse_enabled: bool,
        fft_seed: bool,
    ) -> Vec<MtmfsScaleRhs> {
        self.compact_scale_kernels
            .iter()
            .zip(&self.scale_search_positions)
            .map(|(kernel, positions)| {
                if sparse_enabled && let Some(positions) = positions {
                    if fft_seed {
                        let dense_terms = convolve_mtmfs_terms_for_scale(
                            residual_terms,
                            kernel,
                            self.scale_fft_backend,
                        );
                        return MtmfsScaleRhs::Sparse(sample_dense_mtmfs_terms(
                            &dense_terms,
                            positions,
                        ));
                    }
                    return MtmfsScaleRhs::Sparse(sample_mtmfs_terms_for_scale(
                        residual_terms,
                        kernel,
                        positions,
                    ));
                }
                MtmfsScaleRhs::Dense(convolve_mtmfs_terms_for_scale(
                    residual_terms,
                    kernel,
                    self.scale_fft_backend,
                ))
            })
            .collect()
    }

    fn peak_abs_scale_zero(&self, rhs: &MtmfsScaleRhs) -> f32 {
        match rhs {
            MtmfsScaleRhs::Sparse(terms) => {
                terms[0].iter().copied().map(f32::abs).fold(0.0, f32::max)
            }
            MtmfsScaleRhs::Dense(terms) => {
                let image = &terms[0];
                if let Some(positions) = &self.scale_search_positions[0] {
                    return positions
                        .iter()
                        .map(|position| image[*position].abs())
                        .fold(0.0f32, f32::max);
                }
                peak_abs_value_masked(
                    image,
                    self.scale_masks.as_ref().map(|scale_masks| &scale_masks[0]),
                )
            }
        }
    }

    fn write_scale_zero_rhs(
        &self,
        scale_zero_rhs: &mut MtmfsScaleRhs,
        residual_terms: &mut [Array2<f32>],
    ) {
        match scale_zero_rhs {
            MtmfsScaleRhs::Dense(rhs_terms) => {
                for (residual_term, rhs_term) in residual_terms.iter_mut().zip(rhs_terms.iter_mut())
                {
                    std::mem::swap(residual_term, rhs_term);
                }
            }
            MtmfsScaleRhs::Sparse(rhs_terms) => {
                let positions = self.scale_search_positions[0]
                    .as_ref()
                    .expect("sparse scale-zero RHS requires sparse search positions");
                for (residual_term, rhs_values) in residual_terms.iter_mut().zip(rhs_terms) {
                    for (&position, &value) in positions.iter().zip(rhs_values.iter()) {
                        residual_term[position] = value;
                    }
                }
            }
        }
    }

    fn psf_pair_patch(
        &self,
        left_scale: usize,
        right_scale: usize,
        psf_order: usize,
    ) -> &Array2<f32> {
        let high = left_scale.max(right_scale);
        let low = left_scale.min(right_scale);
        &self.psf_pair_patches[high * (high + 1) / 2 + low][psf_order]
    }

    fn subtract_rhs_component(
        &self,
        scale_rhs_terms: &mut [MtmfsScaleRhs],
        selected_scale: usize,
        position: (usize, usize),
        gain: f32,
        coefficients: &[f32],
    ) {
        let nterms = coefficients.len();
        for (target_scale, rhs) in scale_rhs_terms.iter_mut().enumerate() {
            match rhs {
                MtmfsScaleRhs::Dense(rhs_terms) => {
                    for (residual_order, rhs_term) in rhs_terms.iter_mut().enumerate() {
                        for (model_order, coefficient) in coefficients.iter().copied().enumerate() {
                            let psf_order = residual_order + model_order;
                            debug_assert!(psf_order < 2 * nterms - 1);
                            subtract_shifted_kernel_casa_mtmfs_rhs(
                                rhs_term,
                                self.psf_pair_patch(target_scale, selected_scale, psf_order),
                                position,
                                gain,
                                coefficient,
                            );
                        }
                    }
                }
                MtmfsScaleRhs::Sparse(rhs_terms) => {
                    let positions = self.scale_search_positions[target_scale]
                        .as_ref()
                        .expect("sparse RHS requires sparse search positions");
                    for (residual_order, rhs_values) in rhs_terms.iter_mut().enumerate() {
                        for (model_order, coefficient) in coefficients.iter().copied().enumerate() {
                            let psf_order = residual_order + model_order;
                            debug_assert!(psf_order < 2 * nterms - 1);
                            subtract_shifted_kernel_at_positions_casa_mtmfs_rhs(
                                rhs_values,
                                positions,
                                self.psf_pair_patch(target_scale, selected_scale, psf_order),
                                position,
                                gain,
                                coefficient,
                            );
                        }
                    }
                }
            }
        }
    }
}

fn make_compact_multiscale_kernel(scale_size: f32) -> Array2<f32> {
    let radius = scale_size.ceil().max(0.0) as usize;
    make_multiscale_kernel((2 * radius + 1, 2 * radius + 1), scale_size)
}

fn convolve_compact_scale_kernels(left: &Array2<f32>, right: &Array2<f32>) -> Array2<f32> {
    let output_shape = (
        left.dim().0 + right.dim().0 - 1,
        left.dim().1 + right.dim().1 - 1,
    );
    let mut output = Array2::<f32>::zeros(output_shape);
    for ((left_x, left_y), left_value) in left.indexed_iter() {
        if *left_value == 0.0 {
            continue;
        }
        for ((right_x, right_y), right_value) in right.indexed_iter() {
            if *right_value != 0.0 {
                output[(left_x + right_x, left_y + right_y)] += *left_value * *right_value;
            }
        }
    }
    output
}

fn casa_mtmfs_psf_patch_support(image_shape: (usize, usize), max_scale_size: f32) -> usize {
    let mut support = ((4.0f32 * 4.0 + max_scale_size * max_scale_size).sqrt() * 20.0) as usize;
    support = support.max(80).min(image_shape.0).min(image_shape.1);
    if support % 2 != 0 {
        support -= 1;
    }
    support
}

fn bounded_circular_convolution_patch(
    image: &Array2<f32>,
    compact_kernel: &Array2<f32>,
    center: (usize, usize),
    support: usize,
) -> Array2<f32> {
    let (nx, ny) = image.dim();
    let patch_center = support / 2;
    let kernel_center = (compact_kernel.dim().0 / 2, compact_kernel.dim().1 / 2);
    let taps = compact_kernel
        .indexed_iter()
        .filter_map(|((x, y), value)| {
            (*value != 0.0).then_some((
                x as isize - kernel_center.0 as isize,
                y as isize - kernel_center.1 as isize,
                *value,
            ))
        })
        .collect::<Vec<_>>();
    let mut patch = Array2::<f32>::zeros((support, support));
    for (offset_x, offset_y, value) in taps {
        for patch_x in 0..support {
            let image_x = (center.0 as isize + patch_x as isize - patch_center as isize - offset_x)
                .rem_euclid(nx as isize) as usize;
            for patch_y in 0..support {
                let image_y =
                    (center.1 as isize + patch_y as isize - patch_center as isize - offset_y)
                        .rem_euclid(ny as isize) as usize;
                patch[(patch_x, patch_y)] += value * image[(image_x, image_y)];
            }
        }
    }
    patch
}

fn materialize_centered_compact_kernel(
    image_shape: (usize, usize),
    compact_kernel: &Array2<f32>,
) -> Array2<Complex32> {
    let mut image = Array2::<Complex32>::zeros(image_shape);
    let image_center = (image_shape.0 / 2, image_shape.1 / 2);
    let kernel_center = (compact_kernel.dim().0 / 2, compact_kernel.dim().1 / 2);
    for ((kernel_x, kernel_y), value) in compact_kernel.indexed_iter() {
        let image_x = image_center.0 as isize + kernel_x as isize - kernel_center.0 as isize;
        let image_y = image_center.1 as isize + kernel_y as isize - kernel_center.1 as isize;
        if image_x >= 0
            && image_y >= 0
            && image_x < image_shape.0 as isize
            && image_y < image_shape.1 as isize
        {
            image[(image_x as usize, image_y as usize)] = Complex32::new(*value, 0.0);
        }
    }
    image
}

fn materialize_centered_compact_kernel_real(
    image_shape: (usize, usize),
    compact_kernel: &Array2<f32>,
) -> Array2<f32> {
    let mut image = Array2::<f32>::zeros(image_shape);
    let image_center = (image_shape.0 / 2, image_shape.1 / 2);
    let kernel_center = (compact_kernel.dim().0 / 2, compact_kernel.dim().1 / 2);
    for ((kernel_x, kernel_y), value) in compact_kernel.indexed_iter() {
        let image_x = image_center.0 as isize + kernel_x as isize - kernel_center.0 as isize;
        let image_y = image_center.1 as isize + kernel_y as isize - kernel_center.1 as isize;
        if image_x >= 0
            && image_y >= 0
            && image_x < image_shape.0 as isize
            && image_y < image_shape.1 as isize
        {
            image[(image_x as usize, image_y as usize)] = *value;
        }
    }
    image
}

fn compact_kernel_is_unit_impulse(compact_kernel: &Array2<f32>) -> bool {
    compact_kernel.dim() == (1, 1) && compact_kernel[(0, 0)] == 1.0
}

fn mtmfs_scale_fft(
    input: Array2<Complex32>,
    direction: FftDirection,
    backend: MtmfsScaleFftBackend,
) -> Array2<Complex32> {
    match backend {
        MtmfsScaleFftBackend::RustFft => match direction {
            FftDirection::Forward => centered_fft2_owned(input),
            FftDirection::Inverse => centered_ifft2_owned(input),
        },
        MtmfsScaleFftBackend::FftwF32 => {
            let (output, timing) = crate::fftw_local::centered_transform_f32_owned(
                input,
                direction,
                FftUseCase::Benchmark,
            )
            .expect("configured single-precision FFTW MT-MFS scale transform must run");
            if profile::standard_mfs_profile_detail_enabled() {
                eprintln!(
                    "mtmfs_multiscale_rhs_fft backend=fftwf direction={} threads={} plan_ms={:.3} pack_ms={:.3} exec_ms={:.3} total_ms={:.3}",
                    match direction {
                        FftDirection::Forward => "forward",
                        FftDirection::Inverse => "inverse",
                    },
                    env::var("CASA_RS_FFTW_THREADS")
                        .ok()
                        .and_then(|value| value.parse::<usize>().ok())
                        .unwrap_or_else(|| {
                            thread::available_parallelism().map_or(1, |value| value.get())
                        }),
                    profile::millis(timing.plan),
                    profile::millis(timing.pack),
                    profile::millis(timing.exec),
                    profile::millis(timing.total),
                );
            }
            output
        }
        MtmfsScaleFftBackend::CasaFft0F32 { .. } => {
            unreachable!("CASA FFTServer-compatible real transforms use the dedicated R2C path")
        }
    }
}

fn mtmfs_casa_fft0_product(
    left: &crate::fftw_local::FftwRealHalfSpectrumF32,
    right: &crate::fftw_local::FftwRealHalfSpectrumF32,
) -> crate::fftw_local::FftwRealHalfSpectrumF32 {
    assert_eq!(
        left.logical_shape(),
        right.logical_shape(),
        "CASA MT-MFS FFT0 products require matching logical shapes"
    );
    let mut product = left.clone();
    Zip::from(product.values_mut())
        .and(right.values())
        .for_each(|value, right| *value *= *right);
    product
}

fn casa_fftserver_flip_real(input: &Array2<f32>) -> Array2<f32> {
    let (nx, ny) = input.dim();
    let shift_x = nx.div_ceil(2);
    let shift_y = ny.div_ceil(2);
    let mut output = Array2::<f32>::zeros((nx, ny).f());
    for y in 0..ny {
        let source_y = (y + shift_y) % ny;
        for x in 0..nx {
            let source_x = (x + shift_x) % nx;
            output[(x, y)] = input[(source_x, source_y)];
        }
    }
    output
}

fn mtmfs_psf_pair_patches_casa_fft0(
    psf_terms: &[Array2<f32>],
    compact_scale_kernels: &[Array2<f32>],
    psf_peak_position: (usize, usize),
    psf_support: usize,
    threads: usize,
) -> Vec<Vec<Array2<f32>>> {
    let image_shape = psf_terms[0].dim();
    let psf_spectra = psf_terms
        .iter()
        .map(|psf| {
            crate::fftw_local::fft0_r2c_f32_casacore_layout(psf, threads)
                .expect("configured CASA-compatible MT-MFS PSF R2C transform must run")
        })
        .collect::<Vec<_>>();
    let scale_spectra = compact_scale_kernels
        .iter()
        .map(|kernel| {
            let full_kernel = materialize_centered_compact_kernel_real(image_shape, kernel);
            crate::fftw_local::fft0_r2c_f32_casacore_layout(&full_kernel, threads)
                .expect("configured CASA-compatible MT-MFS scale R2C transform must run")
        })
        .collect::<Vec<_>>();
    let patch_center = psf_support / 2;
    let x0 = psf_peak_position
        .0
        .checked_sub(patch_center)
        .expect("CASA MT-MFS PSF patch must fit before the PSF peak");
    let y0 = psf_peak_position
        .1
        .checked_sub(patch_center)
        .expect("CASA MT-MFS PSF patch must fit before the PSF peak");
    let x1 = x0 + psf_support;
    let y1 = y0 + psf_support;
    assert!(
        x1 <= image_shape.0 && y1 <= image_shape.1,
        "CASA MT-MFS PSF patch must fit within the image"
    );

    let mut patches =
        Vec::with_capacity(compact_scale_kernels.len() * (compact_scale_kernels.len() + 1) / 2);
    for high_scale in 0..compact_scale_kernels.len() {
        for low_scale in 0..=high_scale {
            patches.push(
                psf_spectra
                    .iter()
                    .map(|psf_spectrum| {
                        // Preserve CASA's left-associated
                        // `psfFT * scaleFT[high] * scaleFT[low]` Float
                        // complex arithmetic.
                        let high_product =
                            mtmfs_casa_fft0_product(psf_spectrum, &scale_spectra[high_scale]);
                        let product =
                            mtmfs_casa_fft0_product(&high_product, &scale_spectra[low_scale]);
                        let convolved =
                            crate::fftw_local::fft0_c2r_f32_casacore_layout(&product, threads)
                                .expect(
                                    "configured CASA-compatible MT-MFS PSF C2R transform must run",
                                );
                        convolved.slice(s![x0..x1, y0..y1]).to_owned()
                    })
                    .collect(),
            );
        }
    }
    patches
}

fn mtmfs_psf_pair_patches_fft(
    psf_terms: &[Array2<f32>],
    compact_scale_kernels: &[Array2<f32>],
    psf_peak_position: (usize, usize),
    psf_support: usize,
    fft_backend: MtmfsScaleFftBackend,
) -> Vec<Vec<Array2<f32>>> {
    let image_shape = psf_terms[0].dim();
    let psf_spectra = psf_terms
        .iter()
        .map(|psf| {
            mtmfs_scale_fft(
                psf.mapv(|value| Complex32::new(value, 0.0)),
                FftDirection::Forward,
                fft_backend,
            )
        })
        .collect::<Vec<_>>();
    let scale_spectra = compact_scale_kernels
        .iter()
        .map(|kernel| {
            mtmfs_scale_fft(
                materialize_centered_compact_kernel(image_shape, kernel),
                FftDirection::Forward,
                fft_backend,
            )
        })
        .collect::<Vec<_>>();
    let patch_center = psf_support / 2;
    let x0 = psf_peak_position
        .0
        .checked_sub(patch_center)
        .expect("CASA MT-MFS PSF patch must fit before the PSF peak");
    let y0 = psf_peak_position
        .1
        .checked_sub(patch_center)
        .expect("CASA MT-MFS PSF patch must fit before the PSF peak");
    let x1 = x0 + psf_support;
    let y1 = y0 + psf_support;
    assert!(
        x1 <= image_shape.0 && y1 <= image_shape.1,
        "CASA MT-MFS PSF patch must fit within the image"
    );

    let mut patches =
        Vec::with_capacity(compact_scale_kernels.len() * (compact_scale_kernels.len() + 1) / 2);
    for high_scale in 0..compact_scale_kernels.len() {
        for low_scale in 0..=high_scale {
            patches.push(
                psf_spectra
                    .iter()
                    .map(|psf_spectrum| {
                        // MultiTermMatrixCleaner evaluates
                        // `psfFT * scaleFT[high] * scaleFT[low]` in this
                        // left-associated Complex<Float> order.
                        let mut work = psf_spectrum.clone();
                        Zip::from(&mut work)
                            .and(&scale_spectra[high_scale])
                            .for_each(|value, scale| *value *= *scale);
                        Zip::from(&mut work)
                            .and(&scale_spectra[low_scale])
                            .for_each(|value, scale| *value *= *scale);
                        let convolved = mtmfs_scale_fft(work, FftDirection::Inverse, fft_backend);
                        convolved.slice(s![x0..x1, y0..y1]).mapv(|value| value.re)
                    })
                    .collect(),
            );
        }
    }
    patches
}

fn convolve_mtmfs_terms_for_scale(
    terms: &[Array2<f32>],
    compact_kernel: &Array2<f32>,
    fft_backend: MtmfsScaleFftBackend,
) -> Vec<Array2<f32>> {
    if let MtmfsScaleFftBackend::CasaFft0F32 { threads } = fft_backend {
        let shape = terms[0].dim();
        let full_kernel = materialize_centered_compact_kernel_real(shape, compact_kernel);
        let kernel_spectrum =
            crate::fftw_local::fft0_r2c_f32_casacore_layout(&full_kernel, threads)
                .expect("configured CASA-compatible MT-MFS scale R2C transform must run");
        return terms
            .iter()
            .map(|term| {
                let term_spectrum = crate::fftw_local::fft0_r2c_f32_casacore_layout(term, threads)
                    .expect("configured CASA-compatible MT-MFS RHS R2C transform must run");
                let product = mtmfs_casa_fft0_product(&term_spectrum, &kernel_spectrum);
                let convolved = crate::fftw_local::fft0_c2r_f32_casacore_layout(&product, threads)
                    .expect("configured CASA-compatible MT-MFS RHS C2R transform must run");
                // MultiTermMatrixCleaner::computeRHS and setupUserMask call
                // FFTServer::flip(..., false, false) after the uncentered
                // inverse transform. Scale-zero deliberately follows this
                // path too; CASA does not bypass the FFT round trip.
                casa_fftserver_flip_real(&convolved)
            })
            .collect();
    }
    if compact_kernel_is_unit_impulse(compact_kernel)
        && env::var_os("CASA_RS_EXPERIMENTAL_MT_MFS_FORCE_UNIT_SCALE_FFT").is_none()
    {
        return terms.to_vec();
    }
    let shape = terms[0].dim();
    let kernel_spectrum = mtmfs_scale_fft(
        materialize_centered_compact_kernel(shape, compact_kernel),
        FftDirection::Forward,
        fft_backend,
    );
    terms
        .iter()
        .map(|term| {
            let mut work = mtmfs_scale_fft(
                term.mapv(|value| Complex32::new(value, 0.0)),
                FftDirection::Forward,
                fft_backend,
            );
            Zip::from(&mut work)
                .and(&kernel_spectrum)
                .for_each(|value, kernel| *value *= *kernel);
            mtmfs_scale_fft(work, FftDirection::Inverse, fft_backend).mapv(|value| value.re)
        })
        .collect()
}

fn sample_mtmfs_terms_for_scale(
    terms: &[Array2<f32>],
    compact_kernel: &Array2<f32>,
    positions: &[(usize, usize)],
) -> Vec<Vec<f32>> {
    if compact_kernel_is_unit_impulse(compact_kernel) {
        return terms
            .iter()
            .map(|term| positions.iter().map(|position| term[*position]).collect())
            .collect();
    }
    let (nx, ny) = terms[0].dim();
    let kernel_center = (compact_kernel.dim().0 / 2, compact_kernel.dim().1 / 2);
    let taps = compact_kernel
        .indexed_iter()
        .filter_map(|((x, y), value)| {
            (*value != 0.0).then_some((
                x as isize - kernel_center.0 as isize,
                y as isize - kernel_center.1 as isize,
                *value,
            ))
        })
        .collect::<Vec<_>>();
    terms
        .iter()
        .map(|term| {
            positions
                .iter()
                .map(|&(x, y)| {
                    taps.iter()
                        .fold(0.0f32, |sum, &(offset_x, offset_y, value)| {
                            let source_x = (x as isize - offset_x).rem_euclid(nx as isize) as usize;
                            let source_y = (y as isize - offset_y).rem_euclid(ny as isize) as usize;
                            sum + value * term[(source_x, source_y)]
                        })
                })
                .collect()
        })
        .collect()
}

fn sample_dense_mtmfs_terms(terms: &[Array2<f32>], positions: &[(usize, usize)]) -> Vec<Vec<f32>> {
    terms
        .iter()
        .map(|term| positions.iter().map(|position| term[*position]).collect())
        .collect()
}

#[cfg(test)]
fn subtract_shifted_kernel_at_positions(
    values: &mut [f32],
    positions: &[(usize, usize)],
    kernel: &Array2<f32>,
    peak_index: (usize, usize),
    scale_factor: f32,
) {
    debug_assert_eq!(values.len(), positions.len());
    let kernel_center = (kernel.dim().0 / 2, kernel.dim().1 / 2);
    let kernel_x_min = peak_index.0 as isize - kernel_center.0 as isize;
    let kernel_y_min = peak_index.1 as isize - kernel_center.1 as isize;
    for (value, &(x, y)) in values.iter_mut().zip(positions) {
        let kernel_x = x as isize - kernel_x_min;
        let kernel_y = y as isize - kernel_y_min;
        if kernel_x >= 0
            && kernel_y >= 0
            && kernel_x < kernel.dim().0 as isize
            && kernel_y < kernel.dim().1 as isize
        {
            *value -= scale_factor * kernel[(kernel_x as usize, kernel_y as usize)];
        }
    }
}

fn subtract_shifted_kernel_at_positions_casa_mtmfs_rhs(
    values: &mut [f32],
    positions: &[(usize, usize)],
    kernel: &Array2<f32>,
    peak_index: (usize, usize),
    gain: f32,
    coefficient: f32,
) {
    debug_assert_eq!(values.len(), positions.len());
    let kernel_center = (kernel.dim().0 / 2, kernel.dim().1 / 2);
    let kernel_x_min = peak_index.0 as isize - kernel_center.0 as isize;
    let kernel_y_min = peak_index.1 as isize - kernel_center.1 as isize;
    for (value, &(x, y)) in values.iter_mut().zip(positions) {
        let kernel_x = x as isize - kernel_x_min;
        let kernel_y = y as isize - kernel_y_min;
        if kernel_x >= 0
            && kernel_y >= 0
            && kernel_x < kernel.dim().0 as isize
            && kernel_y < kernel.dim().1 as isize
        {
            *value -= casa_mtmfs_scaled_kernel_value(
                kernel[(kernel_x as usize, kernel_y as usize)],
                gain,
                coefficient,
            );
        }
    }
}

#[cfg(test)]
fn fft_convolve_real_compact(image: &Array2<f32>, compact_kernel: &Array2<f32>) -> Array2<f32> {
    convolve_mtmfs_terms_for_scale(
        std::slice::from_ref(image),
        compact_kernel,
        MtmfsScaleFftBackend::RustFft,
    )
    .pop()
    .expect("one compact convolution input should produce one output")
}

fn build_sparse_mtmfs_scale_search_positions(
    mask: &Array2<bool>,
    compact_kernels: &[Array2<f32>],
    scale_sizes: &[f32],
) -> Option<Vec<Vec<(usize, usize)>>> {
    let (nx, ny) = mask.dim();
    let image_pixels = nx.saturating_mul(ny);
    let mut source_positions = mask
        .indexed_iter()
        .filter_map(|(position, cleanable)| cleanable.then_some(position))
        .collect::<Vec<_>>();
    source_positions.sort_unstable_by_key(|&(x, y)| (y, x));
    let maximum_kernel_taps = compact_kernels
        .iter()
        .map(|kernel| kernel.iter().filter(|value| **value != 0.0).count())
        .max()
        .unwrap_or(1);
    if source_positions.len().saturating_mul(8) > image_pixels
        || source_positions.len().saturating_mul(maximum_kernel_taps) > image_pixels
    {
        return None;
    }
    let mut scale_positions = Vec::with_capacity(compact_kernels.len());
    for (scale_index, (kernel, scale_size)) in compact_kernels
        .iter()
        .zip(scale_sizes.iter().copied())
        .enumerate()
    {
        if compact_kernel_is_unit_impulse(kernel) {
            scale_positions.push(source_positions.clone());
            continue;
        }
        let kernel_center = (kernel.dim().0 / 2, kernel.dim().1 / 2);
        let taps = kernel
            .indexed_iter()
            .filter_map(|((x, y), value)| {
                (*value != 0.0).then_some((
                    x as isize - kernel_center.0 as isize,
                    y as isize - kernel_center.1 as isize,
                    *value,
                ))
            })
            .collect::<Vec<_>>();
        let mut candidates =
            HashSet::with_capacity(source_positions.len().saturating_mul(taps.len().min(8)));
        for &(source_x, source_y) in &source_positions {
            for &(offset_x, offset_y, _) in &taps {
                candidates.insert((
                    (source_x as isize + offset_x).rem_euclid(nx as isize) as usize,
                    (source_y as isize + offset_y).rem_euclid(ny as isize) as usize,
                ));
            }
        }
        let border = (scale_size * 1.5) as usize;
        let mut positions = candidates
            .into_iter()
            .filter(|&(x, y)| {
                if scale_index > 0
                    && (x <= border
                        || y <= border
                        || x >= nx.saturating_sub(border + 1)
                        || y >= ny.saturating_sub(border + 1))
                {
                    return false;
                }
                let convolved = taps
                    .iter()
                    .fold(0.0f32, |sum, &(offset_x, offset_y, value)| {
                        let source_x = (x as isize - offset_x).rem_euclid(nx as isize) as usize;
                        let source_y = (y as isize - offset_y).rem_euclid(ny as isize) as usize;
                        sum + value * if mask[(source_x, source_y)] { 1.0 } else { 0.0 }
                    });
                convolved > 0.1
            })
            .collect::<Vec<_>>();
        // casacore arrays keep x contiguous, so findMaxAbsMask traverses x
        // inside y. Preserve that order for deterministic equal-score ties.
        positions.sort_unstable_by_key(|&(x, y)| (y, x));
        if positions.len().saturating_mul(8) > image_pixels {
            return None;
        }
        scale_positions.push(positions);
    }
    Some(scale_positions)
}

#[cfg(test)]
fn build_mtmfs_scale_masks(
    mask: &Array2<bool>,
    compact_kernels: &[Array2<f32>],
    scale_sizes: &[f32],
) -> Vec<Array2<bool>> {
    build_mtmfs_scale_masks_with_backend(
        mask,
        compact_kernels,
        scale_sizes,
        MtmfsScaleFftBackend::RustFft,
    )
}

fn build_mtmfs_scale_masks_with_backend(
    mask: &Array2<bool>,
    compact_kernels: &[Array2<f32>],
    scale_sizes: &[f32],
    fft_backend: MtmfsScaleFftBackend,
) -> Vec<Array2<bool>> {
    let mask_values = mask.mapv(|cleanable| if cleanable { 1.0 } else { 0.0 });
    compact_kernels
        .iter()
        .zip(scale_sizes.iter().copied())
        .enumerate()
        .map(|(scale_index, (compact_kernel, scale_size))| {
            let convolved = convolve_mtmfs_terms_for_scale(
                std::slice::from_ref(&mask_values),
                compact_kernel,
                fft_backend,
            )
            .pop()
            .expect("one MT-MFS scale-mask input should produce one output");
            // MultiTermMatrixCleaner::setupUserMask uses a fixed 0.1
            // threshold here (independent of MatrixCleaner's 0.9 default).
            let mut scale_mask = convolved.mapv(|value| value > 0.1);
            if scale_index > 0 {
                apply_casa_multiscale_edge_mask(&mut scale_mask, scale_size);
            }
            scale_mask
        })
        .collect()
}

fn mtmfs_scale_search_positions_from_masks(
    masks: &[Array2<bool>],
    image_pixels: usize,
) -> Vec<Option<Vec<(usize, usize)>>> {
    masks
        .iter()
        .map(|mask| {
            let (nx, ny) = mask.dim();
            let mut positions = Vec::new();
            // casacore stores x contiguously and findMaxAbsMask traverses x
            // inside y. Keep this order independent of ndarray layout.
            for y in 0..ny {
                for x in 0..nx {
                    if mask[(x, y)] {
                        positions.push((x, y));
                    }
                }
            }
            (positions.len().saturating_mul(8) <= image_pixels).then_some(positions)
        })
        .collect()
}

fn find_mtmfs_multiscale_component(
    scale_rhs_terms: &[MtmfsScaleRhs],
    basis: &MtmfsMultiscaleBasis,
    scale_hessians: &[MtmfsScaleHessian],
    trace_iteration: Option<usize>,
) -> Option<MtmfsMultiscaleCandidate> {
    let mut best = None::<MtmfsMultiscaleCandidate>;
    let mut legacy_abs_best = None::<(usize, f32, f32, (usize, usize))>;
    for (scale_index, (rhs, scale_hessian)) in
        scale_rhs_terms.iter().zip(scale_hessians).enumerate()
    {
        let mut scale_min = None::<(f32, (usize, usize), Vec<f32>, Vec<f32>)>;
        let mut scale_max = None::<(f32, (usize, usize), Vec<f32>, Vec<f32>)>;
        let mut consider_values = |position: (usize, usize), rhs_values: Vec<f32>| {
            let coefficients = solve_mtmfs_coefficients(&rhs_values, &scale_hessian.inverse);
            let score = coefficients
                .iter()
                .zip(rhs_values.iter())
                .map(|(coefficient, value)| coefficient * value)
                .sum::<f32>();
            if scale_min
                .as_ref()
                .is_none_or(|(minimum, _, _, _)| score < *minimum)
            {
                scale_min = Some((score, position, coefficients.clone(), rhs_values.clone()));
            }
            if scale_max
                .as_ref()
                .is_none_or(|(maximum, _, _, _)| score > *maximum)
            {
                scale_max = Some((score, position, coefficients, rhs_values));
            }
        };
        match rhs {
            MtmfsScaleRhs::Sparse(rhs_terms) => {
                let positions = basis.scale_search_positions[scale_index]
                    .as_ref()
                    .expect("sparse RHS requires sparse search positions");
                for (position_index, &position) in positions.iter().enumerate() {
                    consider_values(
                        position,
                        rhs_terms.iter().map(|term| term[position_index]).collect(),
                    );
                }
            }
            MtmfsScaleRhs::Dense(rhs_terms) => {
                let (nx, ny) = rhs_terms.first()?.dim();
                let mut consider_position = |position: (usize, usize)| {
                    consider_values(
                        position,
                        rhs_terms.iter().map(|term| term[position]).collect(),
                    );
                };
                if let Some(positions) = &basis.scale_search_positions[scale_index] {
                    for &position in positions {
                        consider_position(position);
                    }
                } else {
                    let search_mask = basis.scale_masks.as_ref().map(|masks| &masks[scale_index]);
                    // CASA's first logical (x) axis is contiguous.
                    for y in 0..ny {
                        for x in 0..nx {
                            if search_mask.is_none_or(|mask| mask[(x, y)]) {
                                consider_position((x, y));
                            }
                        }
                    }
                }
            }
        }
        let (Some(minimum), Some(maximum)) = (scale_min, scale_max) else {
            continue;
        };
        // CASA first chooses the largest-magnitude signed score within each
        // scale (with the positive maximum winning an exact magnitude tie),
        // then compares the resulting scale winners by signed biased score.
        let selected = if minimum.0.abs() > maximum.0.abs() {
            minimum
        } else {
            maximum
        };
        let biased_signed_score = selected.0 * basis.scale_bias[scale_index];
        let candidate = MtmfsMultiscaleCandidate {
            scale_index,
            position: selected.1,
            coefficients: selected.2,
            rhs_values: selected.3,
            signed_score: selected.0,
            biased_signed_score,
        };
        if trace_iteration.is_some() {
            let biased_abs_score = candidate.signed_score.abs() * basis.scale_bias[scale_index];
            if legacy_abs_best
                .as_ref()
                .is_none_or(|(_, best_score, _, _)| biased_abs_score > *best_score)
            {
                legacy_abs_best = Some((
                    scale_index,
                    biased_abs_score,
                    candidate.signed_score,
                    candidate.position,
                ));
            }
        }
        if let Some(iteration) = trace_iteration {
            eprintln!(
                "mtmfs_scale_selection_trace local_iteration={} scale_index={} scale_pixels={} signed_score={} biased_signed_score={} x={} y={} coefficients={:?} rhs={:?}",
                iteration,
                scale_index,
                basis.scale_sizes[scale_index],
                candidate.signed_score,
                candidate.biased_signed_score,
                candidate.position.0,
                candidate.position.1,
                candidate.coefficients,
                candidate.rhs_values,
            );
        }
        if best
            .as_ref()
            .is_none_or(|best| candidate.biased_signed_score > best.biased_signed_score)
        {
            best = Some(candidate);
        }
    }
    if let (Some(iteration), Some(selected), Some(legacy)) =
        (trace_iteration, best.as_ref(), legacy_abs_best)
    {
        eprintln!(
            "mtmfs_cross_scale_selection_trace local_iteration={} selected_scale_index={} selected_biased_signed_score={} selected_signed_score={} selected_x={} selected_y={} legacy_abs_scale_index={} legacy_biased_abs_score={} legacy_signed_score={} legacy_x={} legacy_y={}",
            iteration,
            selected.scale_index,
            selected.biased_signed_score,
            selected.signed_score,
            selected.position.0,
            selected.position.1,
            legacy.0,
            legacy.1,
            legacy.2,
            legacy.3.0,
            legacy.3.1,
        );
    }
    best
}

#[cfg(test)]
fn subtract_mtmfs_multiscale_component(
    residual_terms: &mut [Array2<f32>],
    psf_terms: &[Array2<f32>],
    compact_scale_kernel: &Array2<f32>,
    position: (usize, usize),
    gain: f32,
    coefficients: &[f32],
) {
    let nterms = residual_terms.len();
    for (psf_order, psf_term) in psf_terms.iter().enumerate() {
        if compact_kernel_is_unit_impulse(compact_scale_kernel) {
            for (residual_order, residual_term) in residual_terms.iter_mut().enumerate() {
                let Some(model_order) = psf_order.checked_sub(residual_order) else {
                    continue;
                };
                if model_order < nterms {
                    subtract_shifted_kernel(
                        residual_term,
                        psf_term,
                        position,
                        gain * coefficients[model_order],
                    );
                }
            }
            continue;
        }

        let convolved_psf = fft_convolve_real_compact(psf_term, compact_scale_kernel);
        for (residual_order, residual_term) in residual_terms.iter_mut().enumerate() {
            let Some(model_order) = psf_order.checked_sub(residual_order) else {
                continue;
            };
            if model_order < nterms {
                subtract_shifted_kernel(
                    residual_term,
                    &convolved_psf,
                    position,
                    gain * coefficients[model_order],
                );
            }
        }
    }
}

fn effective_mtmfs_multiscale_scales(request: &MtmfsRequest) -> Vec<f32> {
    if request.multiscale_scales.is_empty() {
        vec![0.0]
    } else {
        request.multiscale_scales.clone()
    }
}

type MtmfsAlphaProducts = (
    Option<Array2<f32>>,
    Option<Array2<f32>>,
    Option<Array2<bool>>,
);

fn compute_mtmfs_alpha_products(
    image_terms: &[Array2<f32>],
    principal_residual_terms: &[Array2<f32>],
) -> MtmfsAlphaProducts {
    if image_terms.len() < 2 || principal_residual_terms.len() < 2 {
        return (None, None, None);
    }
    let tt0 = &image_terms[0];
    let tt1 = &image_terms[1];
    let residual0 = &principal_residual_terms[0];
    let residual1 = &principal_residual_terms[1];
    // SDAlgorithmMSMFS temporarily overwrites the residual images with the
    // Hessian principal solution before restore/calculateAlphaBeta, then puts
    // the original Taylor residual products back. The threshold is the
    // positive maximum of that temporary term zero, not its absolute maximum.
    let specthreshold = residual0.iter().copied().fold(f32::NEG_INFINITY, f32::max) / 10.0;
    let (nx, ny) = tt0.dim();
    let mut alpha = Array2::<f32>::zeros((nx, ny));
    let mut alpha_error = Array2::<f32>::zeros((nx, ny));
    let mut alpha_mask = Array2::<bool>::from_elem((nx, ny), false);
    for x in 0..nx {
        for y in 0..ny {
            let image0 = tt0[(x, y)];
            if image0 <= specthreshold {
                continue;
            }
            alpha_mask[(x, y)] = true;
            let image1 = tt1[(x, y)];
            if image0 == 0.0 || image1 == 0.0 {
                continue;
            }
            let alpha_value = image1 / image0;
            alpha[(x, y)] = alpha_value;
            let term0 = residual0[(x, y)] / image0;
            let term1 = residual1[(x, y)] / image1;
            alpha_error[(x, y)] = alpha_value.abs() * (term0 * term0 + term1 * term1).sqrt();
        }
    }
    if profile::standard_mfs_profile_detail_enabled()
        && let Some(((x, y), alpha_value)) = alpha
            .indexed_iter()
            .max_by(|(_, left), (_, right)| left.abs().total_cmp(&right.abs()))
    {
        eprintln!(
            "mtmfs_alpha_probe x={} y={} threshold={} image_tt0={} image_tt1={} temporary_residual_tt0={} temporary_residual_tt1={} alpha={} alpha_error={} mask={}",
            x,
            y,
            specthreshold,
            tt0[(x, y)],
            tt1[(x, y)],
            residual0[(x, y)],
            residual1[(x, y)],
            alpha_value,
            alpha_error[(x, y)],
            alpha_mask[(x, y)],
        );
    }
    (Some(alpha), Some(alpha_error), Some(alpha_mask))
}

fn compute_psf(
    request: &ImagingRequest,
    batches: &[VisibilityBatch],
    gridder: &StandardGridder,
    execution: &ImagingExecutionPlan,
    stage_timings: &mut ImagingStageTimings,
) -> Result<PsfState, ImagingError> {
    compute_psf_with_policy(
        request,
        batches,
        gridder,
        &execution.standard_mfs,
        execution.fft.dirty_products,
        stage_timings,
    )
}

fn compute_psf_with_policy(
    request: &ImagingRequest,
    batches: &[VisibilityBatch],
    gridder: &StandardGridder,
    execution_config: &StandardMfsExecutionPlan,
    dirty_product_fft_policy: DirtyProductFftPolicy,
    stage_timings: &mut ImagingStageTimings,
) -> Result<PsfState, ImagingError> {
    match request.w_term_mode {
        WTermMode::Direct => {
            return compute_psf_direct(request.geometry, batches, stage_timings);
        }
        WTermMode::WProject => {
            return compute_psf_w_project(
                request.geometry,
                batches,
                gridder,
                request.w_project_planes,
                execution_config,
                dirty_product_fft_policy,
                stage_timings,
            );
        }
        WTermMode::None => {}
    }
    if standard_mfs_fixed_tile_backend_enabled(execution_config) {
        return compute_psf_standard_tiled(
            batches,
            gridder,
            execution_config.clone(),
            dirty_product_fft_policy,
            stage_timings,
        );
    }
    if standard_mfs_metal_backend_enabled(execution_config) {
        return compute_psf_standard_metal(
            batches,
            gridder,
            execution_config.clone(),
            dirty_product_fft_policy,
            stage_timings,
        );
    }
    if !standard_mfs_materialized_plan_fits(
        standard_mfs_sample_count(batches),
        Some(
            execution_config
                .resolved
                .caches
                .materialized_sample_plan_bytes,
        ),
    ) {
        return compute_psf_standard_streaming(
            batches,
            gridder,
            dirty_product_fft_policy,
            stage_timings,
        );
    }
    let executor_build_started = Instant::now();
    let mut executor = StandardMfsCpuExecutor::new(gridder, batches)?;
    let executor_build_elapsed = executor_build_started.elapsed();
    stage_timings.executor_build += executor_build_elapsed;
    if profile::standard_mfs_profile_detail_enabled() {
        eprintln!(
            "standard_mfs_executor_build caller=compute_psf samples={} elapsed_ms={:.3}",
            standard_mfs_sample_count(batches),
            profile::millis(executor_build_elapsed),
        );
    }
    compute_psf_standard(&mut executor, dirty_product_fft_policy, stage_timings)
}

fn compute_psf_standard(
    executor: &mut StandardMfsCpuExecutor<'_>,
    dirty_product_fft_policy: DirtyProductFftPolicy,
    stage_timings: &mut ImagingStageTimings,
) -> Result<PsfState, ImagingError> {
    let mut timings = PsfComputationTimings::default();
    let (gridder, plan, workspace) = executor.parts_mut();
    let psf_grid = workspace.clear_psf_grid();

    let grid_started = Instant::now();
    for sample in plan.samples() {
        gridder.grid_sample_taps_real_planned_f64(
            psf_grid,
            &sample.positive_taps,
            sample.grid_weight_f64(),
        );
    }
    timings.grid = grid_started.elapsed();

    let normalization_sumwt = plan.normalization_sumwt();
    let reported_sumwt = plan.reported_sumwt();
    if normalization_sumwt <= 0.0 || reported_sumwt <= 0.0 {
        return Err(ImagingError::NoUsableSamples);
    }

    let fft_started = Instant::now();
    let (mut raw_grids, _) =
        execute_dirty_product_host_f64_batch(&[psf_grid], dirty_product_fft_policy)?;
    let raw_psf = raw_grids.pop().expect("standard PSF FFT");
    timings.fft = fft_started.elapsed();
    let normalize_started = Instant::now();
    let mut psf = gridder.corrected_image_from_grid_f64(&raw_psf);
    psf.mapv_inplace(|value| value / normalization_sumwt as f32);
    let psf_peak = peak_abs_value(&psf);
    if !(psf_peak.is_finite() && psf_peak > 0.0) {
        return Err(ImagingError::Normalization(
            "PSF peak is non-finite or zero".to_string(),
        ));
    }
    psf.mapv_inplace(|value| value / psf_peak);
    timings.normalize = normalize_started.elapsed();
    stage_timings.psf_grid += timings.grid;
    stage_timings.psf_fft += timings.fft;
    stage_timings.psf_normalize += timings.normalize;

    Ok(PsfState {
        psf,
        normalization_sumwt: normalization_sumwt as f32,
        reported_sumwt: reported_sumwt as f32,
        psf_peak,
        gridded_samples: plan.gridded_samples(),
        skipped_samples: plan.skipped_samples(),
    })
}

fn compute_psf_standard_streaming(
    batches: &[VisibilityBatch],
    gridder: &StandardGridder,
    dirty_product_fft_policy: DirtyProductFftPolicy,
    stage_timings: &mut ImagingStageTimings,
) -> Result<PsfState, ImagingError> {
    let mut timings = PsfComputationTimings::default();
    let [nx, ny] = gridder.grid_shape();
    let mut psf_grid = Array2::<Complex64>::zeros((nx, ny));
    let mut normalization_sumwt = 0.0f64;
    let mut reported_sumwt = 0.0f64;
    let mut gridded_samples = 0usize;
    let mut skipped_samples = 0usize;

    let grid_started = Instant::now();
    for batch in batches {
        for sample_index in 0..batch.len() {
            if !batch.gridable[sample_index] {
                skipped_samples += 1;
                continue;
            }
            let weight = batch.weight[sample_index];
            let sumwt_factor = batch.sumwt_factor[sample_index];
            if !(weight.is_finite()
                && weight > 0.0
                && sumwt_factor.is_finite()
                && sumwt_factor > 0.0)
            {
                skipped_samples += 1;
                continue;
            }
            let Some(plan) = gridder
                .plan_positive_taps(batch.u_lambda[sample_index], batch.v_lambda[sample_index])
            else {
                skipped_samples += 1;
                continue;
            };
            let grid_weight = f64::from(weight * sumwt_factor);
            normalization_sumwt += grid_weight;
            reported_sumwt += grid_weight;
            gridded_samples += 1;
            gridder.grid_sample_taps_real_planned_f64(&mut psf_grid, &plan, grid_weight);
        }
    }
    timings.grid = grid_started.elapsed();

    if normalization_sumwt <= 0.0 || reported_sumwt <= 0.0 {
        return Err(ImagingError::NoUsableSamples);
    }

    let fft_started = Instant::now();
    let (mut raw_grids, _) =
        execute_dirty_product_host_f64_batch(&[&psf_grid], dirty_product_fft_policy)?;
    let raw_psf = raw_grids.pop().expect("streaming standard PSF FFT");
    timings.fft = fft_started.elapsed();
    let normalize_started = Instant::now();
    let mut psf = gridder.corrected_image_from_grid_f64(&raw_psf);
    psf.mapv_inplace(|value| value / normalization_sumwt as f32);
    let psf_peak = peak_abs_value(&psf);
    if !(psf_peak.is_finite() && psf_peak > 0.0) {
        return Err(ImagingError::Normalization(
            "PSF peak is non-finite or zero".to_string(),
        ));
    }
    psf.mapv_inplace(|value| value / psf_peak);
    timings.normalize = normalize_started.elapsed();
    stage_timings.psf_grid += timings.grid;
    stage_timings.psf_fft += timings.fft;
    stage_timings.psf_normalize += timings.normalize;

    Ok(PsfState {
        psf,
        normalization_sumwt: normalization_sumwt as f32,
        reported_sumwt: reported_sumwt as f32,
        psf_peak,
        gridded_samples,
        skipped_samples,
    })
}

fn compute_psf_standard_tiled(
    batches: &[VisibilityBatch],
    gridder: &StandardGridder,
    execution_config: StandardMfsExecutionPlan,
    dirty_product_fft_policy: DirtyProductFftPolicy,
    stage_timings: &mut ImagingStageTimings,
) -> Result<PsfState, ImagingError> {
    let mut timings = PsfComputationTimings::default();
    let [nx, ny] = gridder.grid_shape();
    let mut psf_grid = Array2::<Complex64>::zeros((nx, ny));
    let executor =
        StandardMfsTiledCpuExecutor::new_with_execution_config(gridder, execution_config)?;

    let grid_started = Instant::now();
    let accumulation = executor.accumulate_psf_grid(batches, &mut psf_grid)?;
    timings.grid = grid_started.elapsed();

    if accumulation.normalization_sumwt <= 0.0 || accumulation.reported_sumwt <= 0.0 {
        return Err(ImagingError::NoUsableSamples);
    }

    let fft_started = Instant::now();
    let (mut raw_grids, _) =
        execute_dirty_product_host_f64_batch(&[&psf_grid], dirty_product_fft_policy)?;
    let raw_psf = raw_grids.pop().expect("tiled standard PSF FFT");
    timings.fft = fft_started.elapsed();
    let normalize_started = Instant::now();
    let mut psf = gridder.corrected_image_from_grid_f64(&raw_psf);
    psf.mapv_inplace(|value| value / accumulation.normalization_sumwt as f32);
    let psf_peak = peak_abs_value(&psf);
    if !(psf_peak.is_finite() && psf_peak > 0.0) {
        return Err(ImagingError::Normalization(
            "PSF peak is non-finite or zero".to_string(),
        ));
    }
    psf.mapv_inplace(|value| value / psf_peak);
    timings.normalize = normalize_started.elapsed();
    stage_timings.psf_grid += timings.grid;
    stage_timings.psf_fft += timings.fft;
    stage_timings.psf_normalize += timings.normalize;

    Ok(PsfState {
        psf,
        normalization_sumwt: accumulation.normalization_sumwt as f32,
        reported_sumwt: accumulation.reported_sumwt as f32,
        psf_peak,
        gridded_samples: accumulation.gridded_samples,
        skipped_samples: accumulation.skipped_samples,
    })
}

fn compute_psf_standard_metal(
    batches: &[VisibilityBatch],
    gridder: &StandardGridder,
    execution_config: StandardMfsExecutionPlan,
    dirty_product_fft_policy: DirtyProductFftPolicy,
    stage_timings: &mut ImagingStageTimings,
) -> Result<PsfState, ImagingError> {
    #[cfg(all(target_os = "macos", not(coverage)))]
    {
        let mut timings = PsfComputationTimings::default();
        let [nx, ny] = gridder.grid_shape();
        let mut psf_grid = Array2::<Complex64>::zeros((nx, ny));
        let executor = StandardMfsMetalExecutor::new_with_resident_bytes(
            gridder,
            Some(execution_config.resolved.tile.resident_bytes),
            &execution_config,
        )?;

        let grid_started = Instant::now();
        let accumulation = executor.accumulate_psf_grid(batches, &mut psf_grid)?;
        timings.grid = grid_started.elapsed();

        if accumulation.normalization_sumwt <= 0.0 || accumulation.reported_sumwt <= 0.0 {
            return Err(ImagingError::NoUsableSamples);
        }

        let fft_started = Instant::now();
        let (mut raw_grids, _) =
            execute_dirty_product_host_f64_batch(&[&psf_grid], dirty_product_fft_policy)?;
        let raw_psf = raw_grids.pop().expect("Metal-grid standard PSF FFT");
        timings.fft = fft_started.elapsed();
        let normalize_started = Instant::now();
        let mut psf = gridder.corrected_image_from_grid_f64(&raw_psf);
        psf.mapv_inplace(|value| value / accumulation.normalization_sumwt as f32);
        let psf_peak = peak_abs_value(&psf);
        if !(psf_peak.is_finite() && psf_peak > 0.0) {
            return Err(ImagingError::Normalization(
                "PSF peak is non-finite or zero".to_string(),
            ));
        }
        psf.mapv_inplace(|value| value / psf_peak);
        timings.normalize = normalize_started.elapsed();
        stage_timings.psf_grid += timings.grid;
        stage_timings.psf_fft += timings.fft;
        stage_timings.psf_normalize += timings.normalize;

        Ok(PsfState {
            psf,
            normalization_sumwt: accumulation.normalization_sumwt as f32,
            reported_sumwt: accumulation.reported_sumwt as f32,
            psf_peak,
            gridded_samples: accumulation.gridded_samples,
            skipped_samples: accumulation.skipped_samples,
        })
    }
    #[cfg(any(not(target_os = "macos"), coverage))]
    {
        let _ = (
            batches,
            gridder,
            execution_config,
            dirty_product_fft_policy,
            stage_timings,
        );
        Err(ImagingError::Unsupported(
            "standard MFS backend 'metal' requires macOS Metal and is not available on this platform"
                .to_string(),
        ))
    }
}

#[cfg(test)]
fn compute_dirty_psf_and_residual_standard(
    batches: &[VisibilityBatch],
    gridder: &StandardGridder,
    stage_timings: &mut ImagingStageTimings,
) -> Result<(PsfState, Array2<f32>), ImagingError> {
    let mut executor = StandardMfsCpuExecutor::new(gridder, batches)?;
    compute_dirty_psf_and_residual_standard_with_executor(
        &mut executor,
        DirtyProductFftPolicy::correctness_first(),
        stage_timings,
    )
}

fn compute_dirty_psf_and_residual_standard_with_executor(
    executor: &mut StandardMfsCpuExecutor<'_>,
    dirty_product_fft_policy: DirtyProductFftPolicy,
    stage_timings: &mut ImagingStageTimings,
) -> Result<(PsfState, Array2<f32>), ImagingError> {
    let (gridder, plan, workspace) = executor.parts_mut();
    let (psf_grid, residual_grid) = workspace.clear_dirty_grids();

    let grid_started = Instant::now();
    for sample in plan.samples() {
        let grid_weight = sample.grid_weight_f64();
        gridder.grid_sample_taps_real_planned_f64(psf_grid, &sample.positive_taps, grid_weight);

        let observed_visibility = sample.visibility;
        if finite_visibility(observed_visibility) {
            let residual = Complex64::new(
                f64::from(observed_visibility.re) * grid_weight,
                f64::from(observed_visibility.im) * grid_weight,
            );
            gridder.grid_sample_taps_planned_f64(residual_grid, &sample.positive_taps, residual);
        }
    }
    let grid_elapsed = grid_started.elapsed();
    let split_grid_elapsed = Duration::from_secs_f64(grid_elapsed.as_secs_f64() * 0.5);
    stage_timings.psf_grid += split_grid_elapsed;
    stage_timings.residual_degrid_grid += grid_elapsed.saturating_sub(split_grid_elapsed);

    let normalization_sumwt = plan.normalization_sumwt();
    let reported_sumwt = plan.reported_sumwt();
    if normalization_sumwt <= 0.0 || reported_sumwt <= 0.0 {
        return Err(ImagingError::NoUsableSamples);
    }

    let accumulation = StandardMfsDirtyAccumulation {
        normalization_sumwt,
        reported_sumwt,
        gridded_samples: plan.gridded_samples(),
        skipped_samples: plan.skipped_samples(),
        max_abs_w_lambda: 0.0,
    };
    dirty_grids_to_psf_and_residual_owned(
        gridder,
        psf_grid.clone(),
        residual_grid.clone(),
        accumulation,
        dirty_product_fft_policy,
        stage_timings,
    )
}

