#[cfg(all(target_os = "macos", not(coverage)))]
fn accumulate_w_project_grid_metal_samples(
    projector: &WProjector,
    samples: &[WProjectMetalSample],
    sample_pack_elapsed: Duration,
    model_grid: Option<&Array2<Complex32>>,
    psf_grid: &mut Array2<Complex32>,
    residual_grid: &mut Array2<Complex32>,
    mode: u32,
) -> Result<(), ImagingError> {
    use std::{ffi::c_void, mem, ptr, ptr::NonNull, slice};

    use objc2_metal::{
        MTLBuffer, MTLCommandBuffer, MTLCommandBufferStatus, MTLCommandEncoder, MTLCommandQueue,
        MTLComputeCommandEncoder, MTLComputePipelineState, MTLCreateSystemDefaultDevice, MTLDevice,
        MTLLibrary, MTLResourceOptions, MTLSize,
    };

    let profile_detail = profile::standard_mfs_profile_detail_enabled();
    let total_started = Instant::now();
    let [grid_width, grid_height] = projector.grid_shape();
    let cell_count = grid_width.checked_mul(grid_height).ok_or_else(|| {
        ImagingError::InvalidRequest("wproject Metal grid is too large".to_string())
    })?;
    if samples.is_empty() {
        return Err(ImagingError::NoUsableSamples);
    }
    let sample_buffer_bytes = mem::size_of_val(samples);
    let kernel_pack_started = Instant::now();
    let kernel_weights = w_project_metal_kernel_weights(projector);
    let kernel_pack_elapsed = kernel_pack_started.elapsed();
    let kernel_buffer_bytes = mem::size_of_val(kernel_weights.as_slice());
    let kernel_width = projector.kernel_weight_width();
    let model_pack_started = Instant::now();
    let model_values = if let Some(model_grid) = model_grid {
        model_grid
            .iter()
            .map(|value| WProjectMetalComplex {
                re: value.re,
                im: value.im,
            })
            .collect::<Vec<_>>()
    } else {
        vec![WProjectMetalComplex { re: 0.0, im: 0.0 }]
    };
    let model_pack_elapsed = model_pack_started.elapsed();
    let model_buffer_bytes = mem::size_of_val(model_values.as_slice());
    let device_queue_started = Instant::now();
    let device = MTLCreateSystemDefaultDevice().ok_or_else(|| {
        ImagingError::Unsupported(
            "wproject backend 'metal' could not find a default Metal device".to_string(),
        )
    })?;
    let output_bytes = cell_count
        .checked_mul(mem::size_of::<u32>())
        .ok_or_else(|| {
            ImagingError::InvalidRequest("wproject Metal output grid is too large".to_string())
        })?;
    let fixed_dispatch_bytes = sample_buffer_bytes
        .saturating_add(kernel_buffer_bytes)
        .saturating_add(model_buffer_bytes)
        .saturating_add(mem::size_of::<WProjectMetalParams>())
        .saturating_add(output_bytes.saturating_mul(4));
    let recommended_working_set_bytes = device.recommendedMaxWorkingSetSize();
    let current_allocated_bytes = device.currentAllocatedSize();
    let partial_grid_budget_bytes = metal_dispatch_temporary_budget(
        recommended_working_set_bytes,
        current_allocated_bytes,
        fixed_dispatch_bytes,
    );
    let kernel_span = samples
        .iter()
        .map(|sample| {
            usize::from(sample.support())
                .saturating_mul(2)
                .saturating_add(1)
        })
        .max()
        .unwrap_or(1);
    let desired_partial_grid_plan = plan_metal_partial_grids(
        samples.len(),
        cell_count,
        kernel_span.saturating_mul(kernel_span),
        4,
        usize::MAX,
    );
    let (partial_grid_plan, _partial_grid_reservation) =
        reserve_metal_partial_grids(desired_partial_grid_plan, partial_grid_budget_bytes);
    let partial_grid_count = partial_grid_plan.count;
    let partial_chunk_len = samples.len().div_ceil(partial_grid_count);
    let params = WProjectMetalParams {
        sample_count: u32::try_from(samples.len()).map_err(|_| {
            ImagingError::InvalidRequest("wproject Metal sample count exceeds u32".to_string())
        })?,
        grid_width: u32::try_from(grid_width).map_err(|_| {
            ImagingError::InvalidRequest("wproject Metal grid width exceeds u32".to_string())
        })?,
        grid_height: u32::try_from(grid_height).map_err(|_| {
            ImagingError::InvalidRequest("wproject Metal grid height exceeds u32".to_string())
        })?,
        kernel_width: u32::try_from(kernel_width).map_err(|_| {
            ImagingError::InvalidRequest("wproject Metal kernel width exceeds u32".to_string())
        })?,
        sampling: u32::try_from(projector.sampling()).map_err(|_| {
            ImagingError::InvalidRequest("wproject Metal sampling exceeds u32".to_string())
        })?,
        mode,
        model_present: u32::from(model_grid.is_some()),
        partial_grid_count: u32::try_from(partial_grid_count).map_err(|_| {
            ImagingError::InvalidRequest(
                "wproject Metal partial grid count exceeds u32".to_string(),
            )
        })?,
        partial_chunk_len: u32::try_from(partial_chunk_len).map_err(|_| {
            ImagingError::InvalidRequest(
                "wproject Metal partial grid chunk length exceeds u32".to_string(),
            )
        })?,
        _pad0: 0,
    };

    let queue = device.newCommandQueue().ok_or_else(|| {
        ImagingError::Unsupported(
            "wproject backend 'metal' could not create a Metal command queue".to_string(),
        )
    })?;
    let device_queue_elapsed = device_queue_started.elapsed();
    let shader_compile_started = Instant::now();
    let source = objc2_foundation::NSString::from_str(W_PROJECT_METAL_SHADER);
    let library = device
        .newLibraryWithSource_options_error(&source, None)
        .map_err(|error| {
            ImagingError::Unsupported(format!(
                "wproject backend 'metal' failed to compile shader: {error:?}"
            ))
        })?;
    let shader_compile_elapsed = shader_compile_started.elapsed();
    let pipeline_started = Instant::now();
    let use_partial_grids = partial_grid_count > 1;
    let entry_point = match (mode, use_partial_grids) {
        (_, true) => "wproject_grid_chunked_samples",
        (W_PROJECT_METAL_MODE_DIRTY, false) => "wproject_grid_dirty_samples",
        _ => "wproject_grid_samples",
    };
    let function_name = objc2_foundation::NSString::from_str(entry_point);
    let function = library.newFunctionWithName(&function_name).ok_or_else(|| {
        ImagingError::Unsupported(
            "wproject backend 'metal' shader entry point was not found".to_string(),
        )
    })?;
    let pipeline = device
        .newComputePipelineStateWithFunction_error(&function)
        .map_err(|error| {
            ImagingError::Unsupported(format!(
                "wproject backend 'metal' failed to create pipeline: {error:?}"
            ))
        })?;
    let pipeline_elapsed = pipeline_started.elapsed();
    let reduce_pipeline = if use_partial_grids {
        let reduce_function_name =
            objc2_foundation::NSString::from_str("wproject_reduce_chunked_grids");
        let reduce_function = library
            .newFunctionWithName(&reduce_function_name)
            .ok_or_else(|| {
                ImagingError::Unsupported(
                    "wproject backend 'metal' reduction shader entry point was not found"
                        .to_string(),
                )
            })?;
        Some(
            device
                .newComputePipelineStateWithFunction_error(&reduce_function)
                .map_err(|error| {
                    ImagingError::Unsupported(format!(
                        "wproject backend 'metal' failed to create reduction pipeline: {error:?}"
                    ))
                })?,
        )
    } else {
        None
    };
    let storage_options = MTLResourceOptions::StorageModeShared;

    let buffer_alloc_started = Instant::now();
    let sample_buffer = unsafe {
        let pointer =
            NonNull::new(samples.as_ptr().cast::<c_void>() as *mut c_void).ok_or_else(|| {
                ImagingError::InvalidRequest("wproject Metal sample pointer was null".to_string())
            })?;
        device
            .newBufferWithBytesNoCopy_length_options_deallocator(
                pointer,
                sample_buffer_bytes,
                storage_options,
                None,
            )
            .ok_or_else(|| {
                ImagingError::Unsupported(
                    "wproject backend 'metal' could not wrap sample buffer without copying"
                        .to_string(),
                )
            })?
    };
    let kernel_buffer = unsafe {
        let pointer = NonNull::new(kernel_weights.as_ptr().cast::<c_void>() as *mut c_void)
            .ok_or_else(|| {
                ImagingError::InvalidRequest("wproject Metal kernel pointer was null".to_string())
            })?;
        device
            .newBufferWithBytesNoCopy_length_options_deallocator(
                pointer,
                kernel_buffer_bytes,
                storage_options,
                None,
            )
            .ok_or_else(|| {
                ImagingError::Unsupported(
                    "wproject backend 'metal' could not wrap kernel buffer without copying"
                        .to_string(),
                )
            })?
    };
    let params_buffer = unsafe {
        let params_slice = slice::from_ref(&params);
        let byte_len = mem::size_of_val(params_slice);
        let pointer = NonNull::new(params_slice.as_ptr().cast::<c_void>() as *mut c_void)
            .ok_or_else(|| {
                ImagingError::InvalidRequest("wproject Metal params pointer was null".to_string())
            })?;
        device
            .newBufferWithBytes_length_options(pointer, byte_len, storage_options)
            .ok_or_else(|| {
                ImagingError::Unsupported(
                    "wproject backend 'metal' could not allocate params buffer".to_string(),
                )
            })?
    };
    let buffer_alloc_pre_model_elapsed = buffer_alloc_started.elapsed();
    let model_buffer_started = Instant::now();
    let model_buffer = unsafe {
        let pointer = NonNull::new(model_values.as_ptr().cast::<c_void>() as *mut c_void)
            .ok_or_else(|| {
                ImagingError::InvalidRequest("wproject Metal model pointer was null".to_string())
            })?;
        device
            .newBufferWithBytesNoCopy_length_options_deallocator(
                pointer,
                model_buffer_bytes,
                storage_options,
                None,
            )
            .ok_or_else(|| {
                ImagingError::Unsupported(
                    "wproject backend 'metal' could not wrap model buffer without copying"
                        .to_string(),
                )
            })?
    };
    let model_buffer_elapsed = model_buffer_started.elapsed();
    let partial_output_bytes = output_bytes
        .checked_mul(partial_grid_count)
        .ok_or_else(|| {
            ImagingError::InvalidRequest(
                "wproject Metal partial output grid is too large".to_string(),
            )
        })?;
    let output_alloc_started = Instant::now();
    let psf_re = device
        .newBufferWithLength_options(output_bytes, storage_options)
        .ok_or_else(|| {
            ImagingError::Unsupported(
                "wproject backend 'metal' could not allocate PSF real buffer".to_string(),
            )
        })?;
    let psf_im = device
        .newBufferWithLength_options(output_bytes, storage_options)
        .ok_or_else(|| {
            ImagingError::Unsupported(
                "wproject backend 'metal' could not allocate PSF imag buffer".to_string(),
            )
        })?;
    let residual_re = device
        .newBufferWithLength_options(output_bytes, storage_options)
        .ok_or_else(|| {
            ImagingError::Unsupported(
                "wproject backend 'metal' could not allocate residual real buffer".to_string(),
            )
        })?;
    let residual_im = device
        .newBufferWithLength_options(output_bytes, storage_options)
        .ok_or_else(|| {
            ImagingError::Unsupported(
                "wproject backend 'metal' could not allocate residual imag buffer".to_string(),
            )
        })?;
    let partial_psf_re = if use_partial_grids {
        Some(
            device
                .newBufferWithLength_options(partial_output_bytes, storage_options)
                .ok_or_else(|| {
                    ImagingError::Unsupported(
                        "wproject backend 'metal' could not allocate partial PSF real buffer"
                            .to_string(),
                    )
                })?,
        )
    } else {
        None
    };
    let partial_psf_im = if use_partial_grids {
        Some(
            device
                .newBufferWithLength_options(partial_output_bytes, storage_options)
                .ok_or_else(|| {
                    ImagingError::Unsupported(
                        "wproject backend 'metal' could not allocate partial PSF imag buffer"
                            .to_string(),
                    )
                })?,
        )
    } else {
        None
    };
    let partial_residual_re = if use_partial_grids {
        Some(
            device
                .newBufferWithLength_options(partial_output_bytes, storage_options)
                .ok_or_else(|| {
                    ImagingError::Unsupported(
                        "wproject backend 'metal' could not allocate partial residual real buffer"
                            .to_string(),
                    )
                })?,
        )
    } else {
        None
    };
    let partial_residual_im = if use_partial_grids {
        Some(
            device
                .newBufferWithLength_options(partial_output_bytes, storage_options)
                .ok_or_else(|| {
                    ImagingError::Unsupported(
                        "wproject backend 'metal' could not allocate partial residual imag buffer"
                            .to_string(),
                    )
                })?,
        )
    } else {
        None
    };
    let output_alloc_elapsed = output_alloc_started.elapsed();
    let accum_psf_re = partial_psf_re.as_ref().unwrap_or(&psf_re);
    let accum_psf_im = partial_psf_im.as_ref().unwrap_or(&psf_im);
    let accum_residual_re = partial_residual_re.as_ref().unwrap_or(&residual_re);
    let accum_residual_im = partial_residual_im.as_ref().unwrap_or(&residual_im);
    let accum_output_bytes = if use_partial_grids {
        partial_output_bytes
    } else {
        output_bytes
    };
    let zero_outputs_started = Instant::now();
    unsafe {
        ptr::write_bytes(
            accum_psf_re.contents().as_ptr().cast::<u8>(),
            0,
            accum_output_bytes,
        );
        ptr::write_bytes(
            accum_psf_im.contents().as_ptr().cast::<u8>(),
            0,
            accum_output_bytes,
        );
        ptr::write_bytes(
            accum_residual_re.contents().as_ptr().cast::<u8>(),
            0,
            accum_output_bytes,
        );
        ptr::write_bytes(
            accum_residual_im.contents().as_ptr().cast::<u8>(),
            0,
            accum_output_bytes,
        );
    }
    let zero_outputs_elapsed = zero_outputs_started.elapsed();

    let encode_started = Instant::now();
    let command_buffer = queue.commandBuffer().ok_or_else(|| {
        ImagingError::Unsupported(
            "wproject backend 'metal' could not create a command buffer".to_string(),
        )
    })?;
    let encoder = command_buffer.computeCommandEncoder().ok_or_else(|| {
        ImagingError::Unsupported(
            "wproject backend 'metal' could not create a compute encoder".to_string(),
        )
    })?;
    encoder.setComputePipelineState(&pipeline);
    unsafe {
        encoder.setBuffer_offset_atIndex(Some(&sample_buffer), 0, 0);
        encoder.setBuffer_offset_atIndex(Some(&kernel_buffer), 0, 1);
        encoder.setBuffer_offset_atIndex(Some(&model_buffer), 0, 2);
        encoder.setBuffer_offset_atIndex(Some(accum_psf_re), 0, 3);
        encoder.setBuffer_offset_atIndex(Some(accum_psf_im), 0, 4);
        encoder.setBuffer_offset_atIndex(Some(accum_residual_re), 0, 5);
        encoder.setBuffer_offset_atIndex(Some(accum_residual_im), 0, 6);
        encoder.setBuffer_offset_atIndex(Some(&params_buffer), 0, 7);
    }
    let thread_count = samples.len();
    let thread_width = pipeline.threadExecutionWidth().max(1);
    let max_threads = pipeline.maxTotalThreadsPerThreadgroup().max(1);
    let threads_per_group = thread_width.min(max_threads).min(thread_count).max(1);
    encoder.dispatchThreads_threadsPerThreadgroup(
        MTLSize {
            width: thread_count,
            height: 1,
            depth: 1,
        },
        MTLSize {
            width: threads_per_group,
            height: 1,
            depth: 1,
        },
    );
    encoder.endEncoding();
    let encode_elapsed = encode_started.elapsed();
    let dispatch_wait_started = Instant::now();
    command_buffer.commit();
    command_buffer.waitUntilCompleted();
    let dispatch_wait_elapsed = dispatch_wait_started.elapsed();
    if command_buffer.status() == MTLCommandBufferStatus::Error {
        let message = command_buffer
            .error()
            .map(|error| format!("{error:?}"))
            .unwrap_or_else(|| "unknown Metal command buffer error".to_string());
        return Err(ImagingError::Unsupported(format!(
            "wproject backend 'metal' command failed: {message}"
        )));
    }
    let mut reduce_wait_elapsed = Duration::ZERO;
    if use_partial_grids {
        let reduce_started = Instant::now();
        let reduce_command_buffer = queue.commandBuffer().ok_or_else(|| {
            ImagingError::Unsupported(
                "wproject backend 'metal' could not create a reduction command buffer".to_string(),
            )
        })?;
        let reduce_encoder = reduce_command_buffer
            .computeCommandEncoder()
            .ok_or_else(|| {
                ImagingError::Unsupported(
                    "wproject backend 'metal' could not create a reduction compute encoder"
                        .to_string(),
                )
            })?;
        reduce_encoder
            .setComputePipelineState(reduce_pipeline.as_ref().expect("reduction pipeline"));
        unsafe {
            reduce_encoder.setBuffer_offset_atIndex(Some(accum_psf_re), 0, 0);
            reduce_encoder.setBuffer_offset_atIndex(Some(accum_psf_im), 0, 1);
            reduce_encoder.setBuffer_offset_atIndex(Some(accum_residual_re), 0, 2);
            reduce_encoder.setBuffer_offset_atIndex(Some(accum_residual_im), 0, 3);
            reduce_encoder.setBuffer_offset_atIndex(Some(&psf_re), 0, 4);
            reduce_encoder.setBuffer_offset_atIndex(Some(&psf_im), 0, 5);
            reduce_encoder.setBuffer_offset_atIndex(Some(&residual_re), 0, 6);
            reduce_encoder.setBuffer_offset_atIndex(Some(&residual_im), 0, 7);
            reduce_encoder.setBuffer_offset_atIndex(Some(&params_buffer), 0, 8);
        }
        let reduce_thread_count = cell_count;
        let reduce_thread_width = reduce_pipeline
            .as_ref()
            .expect("reduction pipeline")
            .threadExecutionWidth()
            .max(1);
        let reduce_max_threads = reduce_pipeline
            .as_ref()
            .expect("reduction pipeline")
            .maxTotalThreadsPerThreadgroup()
            .max(1);
        let reduce_threads_per_group = reduce_thread_width
            .min(reduce_max_threads)
            .min(reduce_thread_count)
            .max(1);
        reduce_encoder.dispatchThreads_threadsPerThreadgroup(
            MTLSize {
                width: reduce_thread_count,
                height: 1,
                depth: 1,
            },
            MTLSize {
                width: reduce_threads_per_group,
                height: 1,
                depth: 1,
            },
        );
        reduce_encoder.endEncoding();
        reduce_command_buffer.commit();
        reduce_command_buffer.waitUntilCompleted();
        reduce_wait_elapsed = reduce_started.elapsed();
        if reduce_command_buffer.status() == MTLCommandBufferStatus::Error {
            let message = reduce_command_buffer
                .error()
                .map(|error| format!("{error:?}"))
                .unwrap_or_else(|| "unknown Metal command buffer error".to_string());
            return Err(ImagingError::Unsupported(format!(
                "wproject backend 'metal' reduction command failed: {message}"
            )));
        }
    }

    let readback_started = Instant::now();
    let psf_re_values =
        unsafe { slice::from_raw_parts(psf_re.contents().as_ptr().cast::<f32>(), cell_count) };
    let psf_im_values =
        unsafe { slice::from_raw_parts(psf_im.contents().as_ptr().cast::<f32>(), cell_count) };
    let residual_re_values =
        unsafe { slice::from_raw_parts(residual_re.contents().as_ptr().cast::<f32>(), cell_count) };
    let residual_im_values =
        unsafe { slice::from_raw_parts(residual_im.contents().as_ptr().cast::<f32>(), cell_count) };
    for (
        (((psf_cell, &psf_re_value), &psf_im_value), residual_cell),
        (&residual_re_value, &residual_im_value),
    ) in psf_grid
        .as_slice_memory_order_mut()
        .expect("wproject PSF grid should be contiguous")
        .iter_mut()
        .zip(psf_re_values)
        .zip(psf_im_values)
        .zip(
            residual_grid
                .as_slice_memory_order_mut()
                .expect("wproject residual grid should be contiguous")
                .iter_mut(),
        )
        .zip(residual_re_values.iter().zip(residual_im_values))
    {
        *psf_cell = Complex32::new(psf_re_value, psf_im_value);
        *residual_cell = Complex32::new(residual_re_value, residual_im_value);
    }
    let readback_elapsed = readback_started.elapsed();

    if profile_detail {
        let buffer_alloc_copy_elapsed =
            buffer_alloc_pre_model_elapsed + model_buffer_elapsed + output_alloc_elapsed;
        eprintln!(
            "wproject_metal_grid mode={} entry={} samples={} grid={}x{} planes={} kernel_width={} sampling={} desired_partial_grids={} partial_grids={} partial_grid_reserved_bytes={} partial_chunk_len={} recommended_working_set_bytes={} current_allocated_bytes={} fixed_dispatch_bytes={} partial_grid_budget_bytes={} sample_bytes={} kernel_bytes={} model_bytes={} output_bytes={} partial_output_bytes={} thread_width={} max_threads={} threads_per_group={} sample_pack_ms={:.3} kernel_pack_ms={:.3} device_queue_ms={:.3} shader_compile_ms={:.3} pipeline_ms={:.3} buffer_alloc_copy_ms={:.3} model_pack_ms={:.3} zero_outputs_ms={:.3} encode_ms={:.3} dispatch_wait_ms={:.3} reduce_wait_ms={:.3} readback_ms={:.3} total_ms={:.3}",
            mode,
            entry_point,
            samples.len(),
            grid_width,
            grid_height,
            projector.plane_count(),
            kernel_width,
            projector.sampling(),
            desired_partial_grid_plan.count,
            partial_grid_count,
            partial_grid_plan.reserved_bytes,
            partial_chunk_len,
            recommended_working_set_bytes,
            current_allocated_bytes,
            fixed_dispatch_bytes,
            partial_grid_budget_bytes,
            sample_buffer_bytes,
            kernel_buffer_bytes,
            model_buffer_bytes,
            output_bytes * 4,
            if use_partial_grids {
                partial_output_bytes * 4
            } else {
                0
            },
            thread_width,
            max_threads,
            threads_per_group,
            profile::millis(sample_pack_elapsed),
            profile::millis(kernel_pack_elapsed),
            profile::millis(device_queue_elapsed),
            profile::millis(shader_compile_elapsed),
            profile::millis(pipeline_elapsed),
            profile::millis(buffer_alloc_copy_elapsed),
            profile::millis(model_pack_elapsed),
            profile::millis(zero_outputs_elapsed),
            profile::millis(encode_elapsed),
            profile::millis(dispatch_wait_elapsed),
            profile::millis(reduce_wait_elapsed),
            profile::millis(readback_elapsed),
            profile::millis(total_started.elapsed()),
        );
    }
    Ok(())
}

#[cfg(any(not(target_os = "macos"), coverage))]
fn accumulate_w_project_grid_metal_streaming_replay<F>(
    _projector: &WProjector,
    _model_grid: Option<&Array2<Complex32>>,
    _psf_grid: &mut Array2<Complex32>,
    _residual_grid: &mut Array2<Complex32>,
    _mode: u32,
    _replay_weighted_batches: &mut F,
) -> Result<WProjectGridAccumulation, ImagingError>
where
    F: FnMut(
        &mut dyn FnMut(Vec<VisibilityBatch>) -> Result<(), ImagingError>,
    ) -> Result<(), ImagingError>,
{
    Err(ImagingError::Unsupported(
        "wproject backend 'metal' requires macOS Metal and is not available on this platform"
            .to_string(),
    ))
}

#[cfg(all(target_os = "macos", not(coverage)))]
fn accumulate_w_project_grid_metal_streaming_replay<F>(
    projector: &WProjector,
    model_grid: Option<&Array2<Complex32>>,
    psf_grid: &mut Array2<Complex32>,
    residual_grid: &mut Array2<Complex32>,
    mode: u32,
    replay_weighted_batches: &mut F,
) -> Result<WProjectGridAccumulation, ImagingError>
where
    F: FnMut(
        &mut dyn FnMut(Vec<VisibilityBatch>) -> Result<(), ImagingError>,
    ) -> Result<(), ImagingError>,
{
    let total_started = Instant::now();
    let profile_detail = profile::standard_mfs_profile_detail_enabled();
    let [grid_width, grid_height] = projector.grid_shape();
    let cell_count = grid_width.checked_mul(grid_height).ok_or_else(|| {
        ImagingError::InvalidRequest("wproject Metal grid is too large".to_string())
    })?;
    let mut psf_accumulator = vec![Complex64::new(0.0, 0.0); cell_count];
    let mut residual_accumulator = vec![Complex64::new(0.0, 0.0); cell_count];
    let mut accumulation = WProjectGridAccumulation::default();
    let mut stats = WProjectMetalStreamingStats::default();

    replay_weighted_batches(&mut |batches| {
        let chunk = prepare_w_project_metal_streaming_chunk(projector, &batches)?;
        stats.prepare_elapsed += chunk.prepare_elapsed;
        stats.skipped_samples += chunk.skipped_samples;
        stats.gridded_samples += chunk.gridded_samples;
        stats.max_support = stats.max_support.max(chunk.max_support);
        stats.tap_visits += chunk.tap_visits;
        stats.boundary_merges += chunk.boundary_merges;
        accumulation.normalization_sumwt += chunk.normalization_sumwt;
        accumulation.reported_sumwt += chunk.reported_sumwt;
        accumulation.gridded_samples += chunk.gridded_samples;
        accumulation.skipped_samples += chunk.skipped_samples;
        if chunk.samples.is_empty() {
            return Ok(());
        }

        stats.chunk_count += 1;
        stats.sample_count += chunk.samples.len();
        stats.sample_buffer_bytes += std::mem::size_of_val(chunk.samples.as_slice());
        let mut chunk_psf_grid = Array2::<Complex32>::zeros((grid_width, grid_height));
        let mut chunk_residual_grid = Array2::<Complex32>::zeros((grid_width, grid_height));
        let dispatch_started = Instant::now();
        accumulate_w_project_grid_metal_samples(
            projector,
            &chunk.samples,
            chunk.prepare_elapsed,
            model_grid,
            &mut chunk_psf_grid,
            &mut chunk_residual_grid,
            mode,
        )?;
        stats.dispatch_elapsed += dispatch_started.elapsed();

        let host_reduce_started = Instant::now();
        for (accumulated, value) in psf_accumulator.iter_mut().zip(chunk_psf_grid.iter()) {
            accumulated.re += f64::from(value.re);
            accumulated.im += f64::from(value.im);
        }
        for (accumulated, value) in residual_accumulator
            .iter_mut()
            .zip(chunk_residual_grid.iter())
        {
            accumulated.re += f64::from(value.re);
            accumulated.im += f64::from(value.im);
        }
        stats.host_reduce_elapsed += host_reduce_started.elapsed();
        Ok(())
    })?;

    if stats.sample_count == 0 || accumulation.normalization_sumwt <= 0.0 {
        return Err(ImagingError::NoUsableSamples);
    }

    for (output, accumulated) in psf_grid
        .as_slice_memory_order_mut()
        .expect("wproject PSF grid should be contiguous")
        .iter_mut()
        .zip(psf_accumulator)
    {
        *output = Complex32::new(accumulated.re as f32, accumulated.im as f32);
    }
    for (output, accumulated) in residual_grid
        .as_slice_memory_order_mut()
        .expect("wproject residual grid should be contiguous")
        .iter_mut()
        .zip(residual_accumulator)
    {
        *output = Complex32::new(accumulated.re as f32, accumulated.im as f32);
    }

    if profile_detail {
        let avg_taps_per_sample = stats.tap_visits as f64 / stats.sample_count.max(1) as f64;
        let grouped_sample_ratio = stats.sample_count as f64 / stats.gridded_samples.max(1) as f64;
        eprintln!(
            "wproject_metal_streaming_grid mode={} chunks={} samples={} gridded_samples={} grouped_sample_ratio={:.6} skipped={} grid={}x{} planes={} kernel_width={} sampling={} max_support={} avg_taps_per_sample={:.3} tap_visits={} boundary_merges={} sample_bytes_total={} reduction=shared_partial_grid_host_f64 prepare_ms={:.3} dispatch_ms={:.3} host_reduce_ms={:.3} total_ms={:.3}",
            mode,
            stats.chunk_count,
            stats.sample_count,
            stats.gridded_samples,
            grouped_sample_ratio,
            stats.skipped_samples,
            grid_width,
            grid_height,
            projector.plane_count(),
            projector.kernel_weight_width(),
            projector.sampling(),
            stats.max_support,
            avg_taps_per_sample,
            stats.tap_visits,
            stats.boundary_merges,
            stats.sample_buffer_bytes,
            profile::millis(stats.prepare_elapsed),
            profile::millis(stats.dispatch_elapsed),
            profile::millis(stats.host_reduce_elapsed),
            profile::millis(total_started.elapsed()),
        );
    }
    Ok(accumulation)
}
#[cfg(all(target_os = "macos", not(coverage)))]
const W_PROJECT_METAL_SHADER: &str = r#"
#include <metal_stdlib>
using namespace metal;

struct WProjectSample {
    uint loc;
    uint plane_support_offsets;
    float weight;
    float visibility_re;
    float visibility_im;
};

struct WProjectParams {
    uint sample_count;
    uint grid_width;
    uint grid_height;
    uint kernel_width;
    uint sampling;
    uint mode;
    uint model_present;
    uint partial_grid_count;
    uint partial_chunk_len;
    uint _pad0;
};

static inline void atomic_add_float(device atomic_float *address, float value) {
    atomic_fetch_add_explicit(address, value, memory_order_relaxed);
}

static inline uint sample_loc_x(WProjectSample sample) {
    return sample.loc & 0xffffu;
}

static inline uint sample_loc_y(WProjectSample sample) {
    return sample.loc >> 16;
}

static inline uint sample_plane_index(WProjectSample sample) {
    return sample.plane_support_offsets & 0x3ffu;
}

static inline int sample_support(WProjectSample sample) {
    return int((sample.plane_support_offsets >> 10) & 0x1fu);
}

static inline int sample_off_x(WProjectSample sample) {
    return int((sample.plane_support_offsets >> 16) & 0xffu) - 128;
}

static inline int sample_off_y(WProjectSample sample) {
    return int((sample.plane_support_offsets >> 24) & 0xffu) - 128;
}

static inline bool sample_conjugate_kernel(WProjectSample sample) {
    return (sample.plane_support_offsets & (1u << 15)) != 0u;
}

kernel void wproject_grid_samples(
    device const WProjectSample *samples [[buffer(0)]],
    device const float2 *kernels [[buffer(1)]],
    device const float2 *model [[buffer(2)]],
    device atomic_float *psf_re [[buffer(3)]],
    device atomic_float *psf_im [[buffer(4)]],
    device atomic_float *residual_re [[buffer(5)]],
    device atomic_float *residual_im [[buffer(6)]],
    constant WProjectParams &params [[buffer(7)]],
    uint sample_index [[thread_position_in_grid]]
) {
    if (sample_index >= params.sample_count) {
        return;
    }
    const WProjectSample sample = samples[sample_index];
    const int support = sample_support(sample);
    const uint plane_offset =
        sample_plane_index(sample) * params.kernel_width * params.kernel_width;

    float predicted_re = 0.0f;
    float predicted_im = 0.0f;
    const bool needs_model = params.mode == 2u && params.model_present != 0u;
    if (needs_model) {
        for (int iy = -support; iy <= support; ++iy) {
            const uint kernel_y = uint(abs(iy * int(params.sampling) + sample_off_y(sample)));
            const uint grid_y = uint(int(sample_loc_y(sample)) + iy);
            for (int ix = -support; ix <= support; ++ix) {
                const uint kernel_x = uint(abs(ix * int(params.sampling) + sample_off_x(sample)));
                const uint grid_x = uint(int(sample_loc_x(sample)) + ix);
                float2 cwt = kernels[plane_offset + kernel_x * params.kernel_width + kernel_y];
                if (sample_conjugate_kernel(sample)) {
                    cwt.y = -cwt.y;
                }
                const float2 cell = model[grid_x * params.grid_height + grid_y];
                predicted_re += cwt.x * cell.x + cwt.y * cell.y;
                predicted_im += cwt.x * cell.y - cwt.y * cell.x;
            }
        }
    }

    const bool write_psf = params.mode == 0u || params.mode == 1u;
    const bool write_residual = params.mode == 1u || params.mode == 2u;
    const float residual_value_re = sample.visibility_re - predicted_re;
    const float residual_value_im = sample.visibility_im - predicted_im;
    for (int iy = -support; iy <= support; ++iy) {
        const uint kernel_y = uint(abs(iy * int(params.sampling) + sample_off_y(sample)));
        const uint grid_y = uint(int(sample_loc_y(sample)) + iy);
        for (int ix = -support; ix <= support; ++ix) {
            const uint kernel_x = uint(abs(ix * int(params.sampling) + sample_off_x(sample)));
            const uint grid_x = uint(int(sample_loc_x(sample)) + ix);
            float2 cwt = kernels[plane_offset + kernel_x * params.kernel_width + kernel_y];
            if (sample_conjugate_kernel(sample)) {
                cwt.y = -cwt.y;
            }
            const uint cell = grid_x * params.grid_height + grid_y;
            if (write_psf) {
                atomic_add_float(&psf_re[cell], sample.weight * cwt.x);
                atomic_add_float(&psf_im[cell], sample.weight * cwt.y);
            }
            if (write_residual) {
                const float weighted_re =
                    sample.weight * (residual_value_re * cwt.x - residual_value_im * cwt.y);
                const float weighted_im =
                    sample.weight * (residual_value_re * cwt.y + residual_value_im * cwt.x);
                atomic_add_float(&residual_re[cell], weighted_re);
                atomic_add_float(&residual_im[cell], weighted_im);
            }
        }
    }
}

kernel void wproject_grid_dirty_samples(
    device const WProjectSample *samples [[buffer(0)]],
    device const float2 *kernels [[buffer(1)]],
    device atomic_float *psf_re [[buffer(3)]],
    device atomic_float *psf_im [[buffer(4)]],
    device atomic_float *residual_re [[buffer(5)]],
    device atomic_float *residual_im [[buffer(6)]],
    constant WProjectParams &params [[buffer(7)]],
    uint sample_index [[thread_position_in_grid]]
) {
    if (sample_index >= params.sample_count) {
        return;
    }
    const WProjectSample sample = samples[sample_index];
    const int support = sample_support(sample);
    const uint plane_offset =
        sample_plane_index(sample) * params.kernel_width * params.kernel_width;
    for (int iy = -support; iy <= support; ++iy) {
        const uint kernel_y = uint(abs(iy * int(params.sampling) + sample_off_y(sample)));
        const uint grid_y = uint(int(sample_loc_y(sample)) + iy);
        for (int ix = -support; ix <= support; ++ix) {
            const uint kernel_x = uint(abs(ix * int(params.sampling) + sample_off_x(sample)));
            const uint grid_x = uint(int(sample_loc_x(sample)) + ix);
            float2 cwt = kernels[plane_offset + kernel_x * params.kernel_width + kernel_y];
            if (sample_conjugate_kernel(sample)) {
                cwt.y = -cwt.y;
            }
            const uint cell = grid_x * params.grid_height + grid_y;
            atomic_add_float(&psf_re[cell], sample.weight * cwt.x);
            atomic_add_float(&psf_im[cell], sample.weight * cwt.y);
            atomic_add_float(
                &residual_re[cell],
                sample.weight * (sample.visibility_re * cwt.x - sample.visibility_im * cwt.y)
            );
            atomic_add_float(
                &residual_im[cell],
                sample.weight * (sample.visibility_re * cwt.y + sample.visibility_im * cwt.x)
            );
        }
    }
}

kernel void wproject_grid_chunked_samples(
    device const WProjectSample *samples [[buffer(0)]],
    device const float2 *kernels [[buffer(1)]],
    device const float2 *model [[buffer(2)]],
    device atomic_float *psf_re [[buffer(3)]],
    device atomic_float *psf_im [[buffer(4)]],
    device atomic_float *residual_re [[buffer(5)]],
    device atomic_float *residual_im [[buffer(6)]],
    constant WProjectParams &params [[buffer(7)]],
    uint sample_index [[thread_position_in_grid]]
) {
    if (sample_index >= params.sample_count) {
        return;
    }
    const WProjectSample sample = samples[sample_index];
    const int support = sample_support(sample);
    const uint plane_offset =
        sample_plane_index(sample) * params.kernel_width * params.kernel_width;
    const uint partial_grid_index = min(
        sample_index / max(params.partial_chunk_len, 1u),
        params.partial_grid_count - 1u
    );
    const uint partial_grid_offset = partial_grid_index * params.grid_width * params.grid_height;

    float predicted_re = 0.0f;
    float predicted_im = 0.0f;
    const bool needs_model = params.mode == 2u && params.model_present != 0u;
    if (needs_model) {
        for (int iy = -support; iy <= support; ++iy) {
            const uint kernel_y = uint(abs(iy * int(params.sampling) + sample_off_y(sample)));
            const uint grid_y = uint(int(sample_loc_y(sample)) + iy);
            for (int ix = -support; ix <= support; ++ix) {
                const uint kernel_x = uint(abs(ix * int(params.sampling) + sample_off_x(sample)));
                const uint grid_x = uint(int(sample_loc_x(sample)) + ix);
                float2 cwt = kernels[plane_offset + kernel_x * params.kernel_width + kernel_y];
                if (sample_conjugate_kernel(sample)) {
                    cwt.y = -cwt.y;
                }
                const float2 cell = model[grid_x * params.grid_height + grid_y];
                predicted_re += cwt.x * cell.x + cwt.y * cell.y;
                predicted_im += cwt.x * cell.y - cwt.y * cell.x;
            }
        }
    }

    const bool write_psf = params.mode == 0u || params.mode == 1u;
    const bool write_residual = params.mode == 1u || params.mode == 2u;
    const float residual_value_re = sample.visibility_re - predicted_re;
    const float residual_value_im = sample.visibility_im - predicted_im;
    for (int iy = -support; iy <= support; ++iy) {
        const uint kernel_y = uint(abs(iy * int(params.sampling) + sample_off_y(sample)));
        const uint grid_y = uint(int(sample_loc_y(sample)) + iy);
        for (int ix = -support; ix <= support; ++ix) {
            const uint kernel_x = uint(abs(ix * int(params.sampling) + sample_off_x(sample)));
            const uint grid_x = uint(int(sample_loc_x(sample)) + ix);
            float2 cwt = kernels[plane_offset + kernel_x * params.kernel_width + kernel_y];
            if (sample_conjugate_kernel(sample)) {
                cwt.y = -cwt.y;
            }
            const uint cell = partial_grid_offset + grid_x * params.grid_height + grid_y;
            if (write_psf) {
                atomic_add_float(&psf_re[cell], sample.weight * cwt.x);
                atomic_add_float(&psf_im[cell], sample.weight * cwt.y);
            }
            if (write_residual) {
                const float weighted_re =
                    sample.weight * (residual_value_re * cwt.x - residual_value_im * cwt.y);
                const float weighted_im =
                    sample.weight * (residual_value_re * cwt.y + residual_value_im * cwt.x);
                atomic_add_float(&residual_re[cell], weighted_re);
                atomic_add_float(&residual_im[cell], weighted_im);
            }
        }
    }
}

kernel void wproject_reduce_chunked_grids(
    device const float *partial_psf_re [[buffer(0)]],
    device const float *partial_psf_im [[buffer(1)]],
    device const float *partial_residual_re [[buffer(2)]],
    device const float *partial_residual_im [[buffer(3)]],
    device float *psf_re [[buffer(4)]],
    device float *psf_im [[buffer(5)]],
    device float *residual_re [[buffer(6)]],
    device float *residual_im [[buffer(7)]],
    constant WProjectParams &params [[buffer(8)]],
    uint cell [[thread_position_in_grid]]
) {
    const uint cell_count = params.grid_width * params.grid_height;
    if (cell >= cell_count) {
        return;
    }

    float sum_psf_re = 0.0f;
    float sum_psf_im = 0.0f;
    float sum_residual_re = 0.0f;
    float sum_residual_im = 0.0f;
    for (uint partial = 0; partial < params.partial_grid_count; ++partial) {
        const uint index = partial * cell_count + cell;
        sum_psf_re += partial_psf_re[index];
        sum_psf_im += partial_psf_im[index];
        sum_residual_re += partial_residual_re[index];
        sum_residual_im += partial_residual_im[index];
    }
    psf_re[cell] = sum_psf_re;
    psf_im[cell] = sum_psf_im;
    residual_re[cell] = sum_residual_re;
    residual_im[cell] = sum_residual_im;
}
"#;

fn prepare_w_project_data(
    geometry: ImageGeometry,
    batches: &[VisibilityBatch],
    gridder: &StandardGridder,
    w_project_planes: Option<usize>,
    requested_threads: usize,
) -> Result<WProjectPreparedData, ImagingError> {
    let input_sample_count: usize = batches.iter().map(VisibilityBatch::len).sum();
    let (raw_sample_count, max_abs_w_lambda) = w_project_raw_sample_summary(batches);
    if raw_sample_count == 0 {
        return Err(ImagingError::NoUsableSamples);
    }
    let projector = WProjector::new(geometry, gridder, max_abs_w_lambda, w_project_planes)?;
    let thread_count = w_project_grid_threads(input_sample_count, requested_threads);
    if w_project_parallel_prepare_profitable(
        input_sample_count,
        raw_sample_count,
        batches.len(),
        thread_count,
    ) {
        return prepare_w_project_data_parallel(
            w_project_planes,
            max_abs_w_lambda,
            projector,
            batches,
            raw_sample_count,
            input_sample_count,
            thread_count,
        );
    }
    prepare_w_project_data_serial(
        w_project_planes,
        max_abs_w_lambda,
        projector,
        batches,
        raw_sample_count,
    )
}

fn prepare_w_project_metal_data(
    geometry: ImageGeometry,
    batches: &[VisibilityBatch],
    gridder: &StandardGridder,
    w_project_planes: Option<usize>,
    requested_threads: usize,
) -> Result<WProjectMetalPreparedData, ImagingError> {
    let input_sample_count: usize = batches.iter().map(VisibilityBatch::len).sum();
    let (raw_sample_count, max_abs_w_lambda) = w_project_raw_sample_summary(batches);
    if raw_sample_count == 0 {
        return Err(ImagingError::NoUsableSamples);
    }
    let projector = WProjector::new(geometry, gridder, max_abs_w_lambda, w_project_planes)?;
    let thread_count = w_project_grid_threads(input_sample_count, requested_threads);
    if w_project_parallel_prepare_profitable(
        input_sample_count,
        raw_sample_count,
        batches.len(),
        thread_count,
    ) {
        return prepare_w_project_metal_data_parallel(
            w_project_planes,
            max_abs_w_lambda,
            projector,
            batches,
            raw_sample_count,
            input_sample_count,
            thread_count,
        );
    }
    prepare_w_project_metal_data_serial(
        w_project_planes,
        max_abs_w_lambda,
        projector,
        batches,
        raw_sample_count,
    )
}

fn w_project_parallel_prepare_profitable(
    input_sample_count: usize,
    raw_sample_count: usize,
    batch_count: usize,
    thread_count: usize,
) -> bool {
    if thread_count <= 1 || raw_sample_count < thread_count {
        return false;
    }
    let samples_per_worker = input_sample_count.div_ceil(thread_count);
    samples_per_worker > batch_count
}

fn prepare_w_project_metal_data_serial(
    w_project_planes: Option<usize>,
    max_abs_w_lambda: f64,
    projector: WProjector,
    batches: &[VisibilityBatch],
    raw_sample_count: usize,
) -> Result<WProjectMetalPreparedData, ImagingError> {
    let mut samples = Vec::with_capacity(raw_sample_count);
    let mut skipped_samples = 0usize;
    let mut normalization_sumwt = 0.0f64;
    let mut reported_sumwt = 0.0f64;
    let mut gridded_samples = 0usize;
    let mut max_support = 0u16;
    let mut tap_visits = 0usize;

    for (batch_index, batch) in batches.iter().enumerate() {
        for sample_index in 0..batch.len() {
            accumulate_w_project_metal_prepared_sample(
                &projector,
                batch,
                batch_index,
                sample_index,
                &mut samples,
                &mut skipped_samples,
                &mut normalization_sumwt,
                &mut reported_sumwt,
                &mut gridded_samples,
                &mut max_support,
                &mut tap_visits,
            )?;
        }
    }

    finish_w_project_metal_prepared_data(
        w_project_planes,
        max_abs_w_lambda,
        projector,
        samples,
        skipped_samples,
        normalization_sumwt,
        reported_sumwt,
        gridded_samples,
        max_support,
        tap_visits,
    )
}

fn prepare_w_project_metal_data_parallel(
    w_project_planes: Option<usize>,
    max_abs_w_lambda: f64,
    projector: WProjector,
    batches: &[VisibilityBatch],
    raw_sample_count: usize,
    input_sample_count: usize,
    thread_count: usize,
) -> Result<WProjectMetalPreparedData, ImagingError> {
    let chunk_len = input_sample_count.div_ceil(thread_count);
    let mut local_results = Vec::with_capacity(thread_count);
    thread::scope(|scope| {
        let mut handles = Vec::with_capacity(thread_count);
        for chunk_index in 0..thread_count {
            let sample_start = chunk_index * chunk_len;
            let sample_end = ((chunk_index + 1) * chunk_len).min(input_sample_count);
            if sample_start >= sample_end {
                continue;
            }
            let projector = &projector;
            handles.push(scope.spawn(move || {
                let worker_started = Instant::now();
                let mut samples =
                    Vec::<WProjectMetalSample>::with_capacity(sample_end - sample_start);
                let mut skipped_samples = 0usize;
                let mut normalization_sumwt = 0.0f64;
                let mut reported_sumwt = 0.0f64;
                let mut gridded_samples = 0usize;
                let mut max_support = 0u16;
                let mut tap_visits = 0usize;
                let mut global_sample_offset = 0usize;
                for (batch_index, batch) in batches.iter().enumerate() {
                    let batch_start = global_sample_offset;
                    let batch_end = batch_start + batch.len();
                    global_sample_offset = batch_end;
                    if batch_end <= sample_start {
                        continue;
                    }
                    if batch_start >= sample_end {
                        break;
                    }
                    let local_start = sample_start.saturating_sub(batch_start);
                    let local_end = (sample_end - batch_start).min(batch.len());
                    for sample_index in local_start..local_end {
                        accumulate_w_project_metal_prepared_sample(
                            projector,
                            batch,
                            batch_index,
                            sample_index,
                            &mut samples,
                            &mut skipped_samples,
                            &mut normalization_sumwt,
                            &mut reported_sumwt,
                            &mut gridded_samples,
                            &mut max_support,
                            &mut tap_visits,
                        )?;
                    }
                }
                Ok::<_, ImagingError>(WProjectMetalPreparedLocal {
                    sample_start,
                    samples,
                    skipped_samples,
                    normalization_sumwt,
                    reported_sumwt,
                    gridded_samples,
                    max_support,
                    tap_visits,
                    worker_elapsed: worker_started.elapsed(),
                })
            }));
        }
        for handle in handles {
            local_results.push(handle.join().map_err(|_| {
                ImagingError::Unsupported(
                    "wproject Metal sample planning worker panicked".to_string(),
                )
            })??);
        }
        Ok::<(), ImagingError>(())
    })?;
    local_results.sort_by_key(|local| local.sample_start);

    let local_sample_count = local_results
        .iter()
        .map(|local| local.samples.len())
        .sum::<usize>();
    let merge_started = Instant::now();
    let mut samples = Vec::<WProjectMetalSample>::with_capacity(local_sample_count);
    let mut skipped_samples = 0usize;
    let mut normalization_sumwt = 0.0f64;
    let mut reported_sumwt = 0.0f64;
    let mut gridded_samples = 0usize;
    let mut max_support = 0u16;
    let mut tap_visits = 0usize;
    let mut boundary_merges = 0usize;
    let mut worker_elapsed = Vec::with_capacity(local_results.len());
    for mut local in local_results {
        worker_elapsed.push(local.worker_elapsed);
        skipped_samples += local.skipped_samples;
        normalization_sumwt += local.normalization_sumwt;
        reported_sumwt += local.reported_sumwt;
        gridded_samples += local.gridded_samples;
        max_support = max_support.max(local.max_support);
        tap_visits += local.tap_visits;
        if local.samples.is_empty() {
            continue;
        }
        if let Some(last) = samples.last_mut()
            && last.merge_weighted_visibility(local.samples[0])
        {
            let axis = usize::from(local.samples[0].support()) * 2 + 1;
            tap_visits = tap_visits.saturating_sub(axis * axis);
            boundary_merges += 1;
            samples.extend_from_slice(&local.samples[1..]);
            continue;
        }
        samples.append(&mut local.samples);
    }
    let merge_elapsed = merge_started.elapsed();
    if profile::standard_mfs_profile_detail_enabled() {
        worker_elapsed.sort();
        let worker_min = worker_elapsed.first().copied().unwrap_or(Duration::ZERO);
        let worker_p50 = worker_elapsed
            .get(worker_elapsed.len().saturating_sub(1) / 2)
            .copied()
            .unwrap_or(Duration::ZERO);
        let worker_max = worker_elapsed.last().copied().unwrap_or(Duration::ZERO);
        eprintln!(
            "wproject_metal_prepare_parallel requested_threads={} actual_threads={} chunk_len={} input_samples={} raw_samples={} local_grouped_samples={} final_grouped_samples={} boundary_merges={} final_capacity={} worker_compute_min_ms={:.3} worker_compute_p50_ms={:.3} worker_compute_max_ms={:.3} merge_ms={:.3}",
            thread_count,
            worker_elapsed.len(),
            chunk_len,
            input_sample_count,
            raw_sample_count,
            local_sample_count,
            samples.len(),
            boundary_merges,
            samples.capacity(),
            profile::millis(worker_min),
            profile::millis(worker_p50),
            profile::millis(worker_max),
            profile::millis(merge_elapsed),
        );
    }

    finish_w_project_metal_prepared_data(
        w_project_planes,
        max_abs_w_lambda,
        projector,
        samples,
        skipped_samples,
        normalization_sumwt,
        reported_sumwt,
        gridded_samples,
        max_support,
        tap_visits,
    )
}

#[cfg_attr(any(not(target_os = "macos"), coverage), allow(dead_code))]
fn prepare_w_project_metal_streaming_chunk(
    projector: &WProjector,
    batches: &[VisibilityBatch],
) -> Result<WProjectMetalStreamingChunk, ImagingError> {
    let prepare_started = Instant::now();
    let input_sample_count: usize = batches.iter().map(VisibilityBatch::len).sum();
    if input_sample_count == 0 {
        return Ok(WProjectMetalStreamingChunk {
            prepare_elapsed: prepare_started.elapsed(),
            ..WProjectMetalStreamingChunk::default()
        });
    }

    let thread_count = w_project_grid_threads(input_sample_count, 1);
    if thread_count <= 1 || input_sample_count < 10_000 {
        let mut chunk = WProjectMetalStreamingChunk {
            samples: Vec::with_capacity(input_sample_count),
            ..WProjectMetalStreamingChunk::default()
        };
        for (batch_index, batch) in batches.iter().enumerate() {
            for sample_index in 0..batch.len() {
                accumulate_w_project_metal_prepared_sample(
                    projector,
                    batch,
                    batch_index,
                    sample_index,
                    &mut chunk.samples,
                    &mut chunk.skipped_samples,
                    &mut chunk.normalization_sumwt,
                    &mut chunk.reported_sumwt,
                    &mut chunk.gridded_samples,
                    &mut chunk.max_support,
                    &mut chunk.tap_visits,
                )?;
            }
        }
        chunk.prepare_elapsed = prepare_started.elapsed();
        return Ok(chunk);
    }

    let chunk_len = input_sample_count.div_ceil(thread_count);
    let mut local_results = Vec::with_capacity(thread_count);
    thread::scope(|scope| {
        let mut handles = Vec::with_capacity(thread_count);
        for chunk_index in 0..thread_count {
            let sample_start = chunk_index * chunk_len;
            let sample_end = ((chunk_index + 1) * chunk_len).min(input_sample_count);
            if sample_start >= sample_end {
                continue;
            }
            handles.push(scope.spawn(move || {
                let worker_started = Instant::now();
                let mut samples =
                    Vec::<WProjectMetalSample>::with_capacity(sample_end - sample_start);
                let mut skipped_samples = 0usize;
                let mut normalization_sumwt = 0.0f64;
                let mut reported_sumwt = 0.0f64;
                let mut gridded_samples = 0usize;
                let mut max_support = 0u16;
                let mut tap_visits = 0usize;
                let mut global_sample_offset = 0usize;
                for (batch_index, batch) in batches.iter().enumerate() {
                    let batch_start = global_sample_offset;
                    let batch_end = batch_start + batch.len();
                    global_sample_offset = batch_end;
                    if batch_end <= sample_start {
                        continue;
                    }
                    if batch_start >= sample_end {
                        break;
                    }
                    let local_start = sample_start.saturating_sub(batch_start);
                    let local_end = (sample_end - batch_start).min(batch.len());
                    for sample_index in local_start..local_end {
                        accumulate_w_project_metal_prepared_sample(
                            projector,
                            batch,
                            batch_index,
                            sample_index,
                            &mut samples,
                            &mut skipped_samples,
                            &mut normalization_sumwt,
                            &mut reported_sumwt,
                            &mut gridded_samples,
                            &mut max_support,
                            &mut tap_visits,
                        )?;
                    }
                }
                Ok::<_, ImagingError>(WProjectMetalPreparedLocal {
                    sample_start,
                    samples,
                    skipped_samples,
                    normalization_sumwt,
                    reported_sumwt,
                    gridded_samples,
                    max_support,
                    tap_visits,
                    worker_elapsed: worker_started.elapsed(),
                })
            }));
        }
        for handle in handles {
            local_results.push(handle.join().map_err(|_| {
                ImagingError::Unsupported(
                    "wproject Metal streaming sample planning worker panicked".to_string(),
                )
            })??);
        }
        Ok::<(), ImagingError>(())
    })?;
    local_results.sort_by_key(|local| local.sample_start);

    let local_sample_count = local_results
        .iter()
        .map(|local| local.samples.len())
        .sum::<usize>();
    let mut chunk = WProjectMetalStreamingChunk {
        samples: Vec::with_capacity(local_sample_count),
        ..WProjectMetalStreamingChunk::default()
    };
    for mut local in local_results {
        chunk.skipped_samples += local.skipped_samples;
        chunk.normalization_sumwt += local.normalization_sumwt;
        chunk.reported_sumwt += local.reported_sumwt;
        chunk.gridded_samples += local.gridded_samples;
        chunk.max_support = chunk.max_support.max(local.max_support);
        chunk.tap_visits += local.tap_visits;
        if local.samples.is_empty() {
            continue;
        }
        if let Some(last) = chunk.samples.last_mut()
            && last.merge_weighted_visibility(local.samples[0])
        {
            let axis = usize::from(local.samples[0].support()) * 2 + 1;
            chunk.tap_visits = chunk.tap_visits.saturating_sub(axis * axis);
            chunk.boundary_merges += 1;
            chunk.samples.extend_from_slice(&local.samples[1..]);
            continue;
        }
        chunk.samples.append(&mut local.samples);
    }
    chunk.prepare_elapsed = prepare_started.elapsed();
    Ok(chunk)
}

fn prepare_w_project_data_serial(
    w_project_planes: Option<usize>,
    max_abs_w_lambda: f64,
    projector: WProjector,
    batches: &[VisibilityBatch],
    raw_sample_count: usize,
) -> Result<WProjectPreparedData, ImagingError> {
    let mut samples = Vec::with_capacity(raw_sample_count);
    let mut skipped_samples = Vec::<WProjectSkippedSample>::new();
    let mut normalization_sumwt = 0.0f64;
    let mut reported_sumwt = 0.0f64;
    let mut gridded_samples = 0usize;

    for (batch_index, batch) in batches.iter().enumerate() {
        for sample_index in 0..batch.len() {
            accumulate_w_project_prepared_sample(
                &projector,
                batch,
                batch_index,
                sample_index,
                &mut samples,
                &mut skipped_samples,
                &mut normalization_sumwt,
                &mut reported_sumwt,
                &mut gridded_samples,
            );
        }
    }

    finish_w_project_prepared_data(
        w_project_planes,
        max_abs_w_lambda,
        projector,
        samples,
        skipped_samples,
        normalization_sumwt,
        reported_sumwt,
        gridded_samples,
    )
}

fn prepare_w_project_data_parallel(
    w_project_planes: Option<usize>,
    max_abs_w_lambda: f64,
    projector: WProjector,
    batches: &[VisibilityBatch],
    raw_sample_count: usize,
    input_sample_count: usize,
    thread_count: usize,
) -> Result<WProjectPreparedData, ImagingError> {
    let chunk_len = input_sample_count.div_ceil(thread_count);
    let mut local_results = Vec::with_capacity(thread_count);
    thread::scope(|scope| {
        let mut handles = Vec::with_capacity(thread_count);
        for chunk_index in 0..thread_count {
            let sample_start = chunk_index * chunk_len;
            let sample_end = ((chunk_index + 1) * chunk_len).min(input_sample_count);
            if sample_start >= sample_end {
                continue;
            }
            let projector = &projector;
            handles.push(scope.spawn(move || {
                let mut samples = Vec::<WProjectPreparedSample>::new();
                let mut skipped_samples = Vec::<WProjectSkippedSample>::new();
                let mut normalization_sumwt = 0.0f64;
                let mut reported_sumwt = 0.0f64;
                let mut gridded_samples = 0usize;
                let mut global_sample_offset = 0usize;
                for (batch_index, batch) in batches.iter().enumerate() {
                    let batch_start = global_sample_offset;
                    let batch_end = batch_start + batch.len();
                    global_sample_offset = batch_end;
                    if batch_end <= sample_start {
                        continue;
                    }
                    if batch_start >= sample_end {
                        break;
                    }
                    let local_start = sample_start.saturating_sub(batch_start);
                    let local_end = (sample_end - batch_start).min(batch.len());
                    for sample_index in local_start..local_end {
                        accumulate_w_project_prepared_sample(
                            projector,
                            batch,
                            batch_index,
                            sample_index,
                            &mut samples,
                            &mut skipped_samples,
                            &mut normalization_sumwt,
                            &mut reported_sumwt,
                            &mut gridded_samples,
                        );
                    }
                }
                (
                    sample_start,
                    samples,
                    skipped_samples,
                    normalization_sumwt,
                    reported_sumwt,
                    gridded_samples,
                )
            }));
        }
        for handle in handles {
            local_results.push(handle.join().map_err(|_| {
                ImagingError::Unsupported("wproject sample planning worker panicked".to_string())
            })?);
        }
        Ok::<(), ImagingError>(())
    })?;
    local_results.sort_by_key(|(batch_offset, _, _, _, _, _)| *batch_offset);

    let mut samples = Vec::with_capacity(raw_sample_count);
    let mut skipped_samples = Vec::<WProjectSkippedSample>::new();
    let mut normalization_sumwt = 0.0f64;
    let mut reported_sumwt = 0.0f64;
    let mut gridded_samples = 0usize;
    for (
        _,
        mut local_samples,
        mut local_skipped,
        local_normalization,
        local_reported,
        local_gridded,
    ) in local_results
    {
        samples.append(&mut local_samples);
        skipped_samples.append(&mut local_skipped);
        normalization_sumwt += local_normalization;
        reported_sumwt += local_reported;
        gridded_samples += local_gridded;
    }

    finish_w_project_prepared_data(
        w_project_planes,
        max_abs_w_lambda,
        projector,
        samples,
        skipped_samples,
        normalization_sumwt,
        reported_sumwt,
        gridded_samples,
    )
}

#[allow(clippy::too_many_arguments)]
fn accumulate_w_project_prepared_sample(
    projector: &WProjector,
    batch: &VisibilityBatch,
    batch_index: usize,
    sample_index: usize,
    samples: &mut Vec<WProjectPreparedSample>,
    skipped_samples: &mut Vec<WProjectSkippedSample>,
    normalization_sumwt: &mut f64,
    reported_sumwt: &mut f64,
    gridded_samples: &mut usize,
) {
    let sample = RawWProjectSample {
        batch_index,
        sample_index,
        u_lambda: batch.u_lambda[sample_index],
        v_lambda: batch.v_lambda[sample_index],
        w_lambda: batch.w_lambda[sample_index],
        weight: batch.weight[sample_index],
        visibility: batch.visibility[sample_index],
        sumwt_factor: batch.sumwt_factor[sample_index],
    };
    if !batch.gridable[sample_index] {
        skipped_samples.push(w_project_skipped_sample(
            sample,
            WProjectSkipReason::NotGridable,
        ));
        return;
    }
    if !raw_w_project_sample_is_valid(sample) {
        skipped_samples.push(w_project_skipped_sample(
            sample,
            WProjectSkipReason::InvalidInput,
        ));
        return;
    }
    let Some(positive_plan) =
        projector.plan_sample(sample.u_lambda, sample.v_lambda, sample.w_lambda)
    else {
        skipped_samples.push(w_project_skipped_sample(
            sample,
            WProjectSkipReason::OutsideGrid,
        ));
        return;
    };
    *normalization_sumwt += 2.0 * f64::from(sample.weight) * f64::from(positive_plan.normalization);
    *reported_sumwt += f64::from(sample.weight) * f64::from(sample.sumwt_factor);
    *gridded_samples += 1;
    samples.push(WProjectPreparedSample {
        batch_index: sample.batch_index,
        sample_index: sample.sample_index,
        u_lambda: sample.u_lambda,
        v_lambda: sample.v_lambda,
        w_lambda: sample.w_lambda,
        sumwt_factor: sample.sumwt_factor,
        positive_plan,
        weight: sample.weight,
        visibility: sample.visibility,
    });
}

#[allow(clippy::too_many_arguments)]
fn accumulate_w_project_metal_prepared_sample(
    projector: &WProjector,
    batch: &VisibilityBatch,
    batch_index: usize,
    sample_index: usize,
    samples: &mut Vec<WProjectMetalSample>,
    skipped_samples: &mut usize,
    normalization_sumwt: &mut f64,
    reported_sumwt: &mut f64,
    gridded_samples: &mut usize,
    max_support: &mut u16,
    tap_visits: &mut usize,
) -> Result<(), ImagingError> {
    let sample = RawWProjectSample {
        batch_index,
        sample_index,
        u_lambda: batch.u_lambda[sample_index],
        v_lambda: batch.v_lambda[sample_index],
        w_lambda: batch.w_lambda[sample_index],
        weight: batch.weight[sample_index],
        visibility: batch.visibility[sample_index],
        sumwt_factor: batch.sumwt_factor[sample_index],
    };
    if !batch.gridable[sample_index] || !raw_w_project_sample_is_valid(sample) {
        *skipped_samples += 1;
        return Ok(());
    }
    let Some(positive_plan) =
        projector.plan_sample(sample.u_lambda, sample.v_lambda, sample.w_lambda)
    else {
        *skipped_samples += 1;
        return Ok(());
    };
    *normalization_sumwt += 2.0 * f64::from(sample.weight) * f64::from(positive_plan.normalization);
    *reported_sumwt += f64::from(sample.weight) * f64::from(sample.sumwt_factor);
    *gridded_samples += 1;
    let metal_sample = w_project_metal_sample_from_plan(
        projector,
        &positive_plan,
        sample.weight,
        sample.visibility,
    )?;
    *max_support = (*max_support).max(metal_sample.support());
    if push_w_project_metal_sample(samples, metal_sample) {
        let axis = usize::from(metal_sample.support()) * 2 + 1;
        *tap_visits += axis * axis;
    }
    Ok(())
}

#[allow(clippy::too_many_arguments)]
fn finish_w_project_prepared_data(
    w_project_planes: Option<usize>,
    max_abs_w_lambda: f64,
    projector: WProjector,
    samples: Vec<WProjectPreparedSample>,
    mut skipped_samples: Vec<WProjectSkippedSample>,
    normalization_sumwt: f64,
    reported_sumwt: f64,
    gridded_samples: usize,
) -> Result<WProjectPreparedData, ImagingError> {
    if samples.is_empty() || normalization_sumwt <= 0.0 || reported_sumwt <= 0.0 {
        return Err(ImagingError::NoUsableSamples);
    }

    skipped_samples.sort_by_key(|sample| (sample.batch_index, sample.sample_index));
    Ok(WProjectPreparedData {
        requested_plane_count: w_project_planes,
        max_abs_w_lambda,
        projector,
        samples,
        skipped_samples,
        normalization_sumwt: normalization_sumwt as f32,
        reported_sumwt: reported_sumwt as f32,
        gridded_samples,
    })
}

#[allow(clippy::too_many_arguments)]
fn finish_w_project_metal_prepared_data(
    w_project_planes: Option<usize>,
    max_abs_w_lambda: f64,
    projector: WProjector,
    samples: Vec<WProjectMetalSample>,
    skipped_samples: usize,
    normalization_sumwt: f64,
    reported_sumwt: f64,
    gridded_samples: usize,
    max_support: u16,
    tap_visits: usize,
) -> Result<WProjectMetalPreparedData, ImagingError> {
    if samples.is_empty() || normalization_sumwt <= 0.0 || reported_sumwt <= 0.0 {
        return Err(ImagingError::NoUsableSamples);
    }

    Ok(WProjectMetalPreparedData {
        requested_plane_count: w_project_planes,
        max_abs_w_lambda,
        projector,
        samples,
        skipped_samples,
        max_support,
        tap_visits,
        normalization_sumwt: normalization_sumwt as f32,
        reported_sumwt: reported_sumwt as f32,
        gridded_samples,
    })
}

fn w_project_raw_sample_summary(batches: &[VisibilityBatch]) -> (usize, f64) {
    let mut raw_sample_count = 0usize;
    let mut max_abs_w_lambda = 0.0f64;
    for batch in batches {
        for sample_index in 0..batch.len() {
            let sample = RawWProjectSample {
                batch_index: 0,
                sample_index,
                u_lambda: batch.u_lambda[sample_index],
                v_lambda: batch.v_lambda[sample_index],
                w_lambda: batch.w_lambda[sample_index],
                weight: batch.weight[sample_index],
                visibility: batch.visibility[sample_index],
                sumwt_factor: batch.sumwt_factor[sample_index],
            };
            if batch.gridable[sample_index] && raw_w_project_sample_is_valid(sample) {
                raw_sample_count += 1;
                max_abs_w_lambda = max_abs_w_lambda.max(sample.w_lambda.abs());
            }
        }
    }
    (raw_sample_count, max_abs_w_lambda)
}

fn raw_w_project_sample_is_valid(sample: RawWProjectSample) -> bool {
    sample.weight.is_finite()
        && sample.weight > 0.0
        && sample.sumwt_factor.is_finite()
        && sample.sumwt_factor > 0.0
        && sample.visibility.re.is_finite()
        && sample.visibility.im.is_finite()
        && sample.u_lambda.is_finite()
        && sample.v_lambda.is_finite()
        && sample.w_lambda.is_finite()
}

fn w_project_skipped_sample(
    sample: RawWProjectSample,
    reason: WProjectSkipReason,
) -> WProjectSkippedSample {
    WProjectSkippedSample {
        batch_index: sample.batch_index,
        sample_index: sample.sample_index,
        u_lambda: sample.u_lambda,
        v_lambda: sample.v_lambda,
        w_lambda: sample.w_lambda,
        weight: sample.weight,
        sumwt_factor: sample.sumwt_factor,
        reason,
    }
}

#[derive(Debug, Clone, Copy)]
struct DirectPixelCoordinate {
    l: f64,
    m: f64,
    n_minus_one: f64,
}

#[derive(Debug, Clone, Copy)]
struct DirectComponent {
    value: f32,
    l: f64,
    m: f64,
    n_minus_one: f64,
}

fn compute_psf_direct(
    geometry: ImageGeometry,
    batches: &[VisibilityBatch],
    stage_timings: &mut ImagingStageTimings,
) -> Result<PsfState, ImagingError> {
    let [nx, ny] = geometry.image_shape;
    let pixels = build_direct_pixel_coordinates(geometry);
    let mut psf = Array2::<f32>::zeros((nx, ny));
    let mut normalization_sumwt = 0.0f64;
    let mut reported_sumwt = 0.0f64;
    let mut gridded_samples = 0usize;
    let mut skipped_samples = 0usize;

    let accumulate_started = Instant::now();
    for batch in batches {
        for index in 0..batch.len() {
            if !batch.gridable[index] {
                skipped_samples += 1;
                continue;
            }
            let weight = batch.weight[index];
            let sumwt_factor = batch.sumwt_factor[index];
            if !(weight.is_finite()
                && weight > 0.0
                && sumwt_factor.is_finite()
                && sumwt_factor > 0.0)
            {
                skipped_samples += 1;
                continue;
            }
            normalization_sumwt += 2.0 * f64::from(weight);
            reported_sumwt += f64::from(weight) * f64::from(sumwt_factor);
            gridded_samples += 1;
            accumulate_direct_adjoint(
                &mut psf,
                &pixels,
                ny,
                batch.u_lambda[index],
                batch.v_lambda[index],
                batch.w_lambda[index],
                Complex32::new(weight, 0.0),
            );
        }
    }
    stage_timings.psf_grid += accumulate_started.elapsed();

    if normalization_sumwt <= 0.0 || reported_sumwt <= 0.0 {
        return Err(ImagingError::NoUsableSamples);
    }

    let normalize_started = Instant::now();
    psf.mapv_inplace(|value| value / normalization_sumwt as f32);
    let psf_peak = peak_abs_value(&psf);
    if !(psf_peak.is_finite() && psf_peak > 0.0) {
        return Err(ImagingError::Normalization(
            "PSF peak is non-finite or zero".to_string(),
        ));
    }
    psf.mapv_inplace(|value| value / psf_peak);
    stage_timings.psf_normalize += normalize_started.elapsed();

    Ok(PsfState {
        psf,
        normalization_sumwt: normalization_sumwt as f32,
        reported_sumwt: reported_sumwt as f32,
        psf_peak,
        gridded_samples,
        skipped_samples,
    })
}

fn compute_residual_direct(
    geometry: ImageGeometry,
    batches: &[VisibilityBatch],
    model: &Array2<f32>,
    psf_state: &PsfState,
    stage_timings: &mut ImagingStageTimings,
) -> Result<Array2<f32>, ImagingError> {
    let [nx, ny] = geometry.image_shape;
    let pixels = build_direct_pixel_coordinates(geometry);
    let components = build_direct_components(model, &pixels, ny);
    let mut image = Array2::<f32>::zeros((nx, ny));

    let accumulate_started = Instant::now();
    for batch in batches {
        for index in 0..batch.len() {
            if !batch.gridable[index] {
                continue;
            }
            let weight = batch.weight[index];
            let sample = batch.visibility[index];
            if !(weight.is_finite()
                && weight > 0.0
                && sample.re.is_finite()
                && sample.im.is_finite())
            {
                continue;
            }
            let predicted = if components.is_empty() {
                Complex32::new(0.0, 0.0)
            } else {
                direct_predict_visibility(
                    &components,
                    batch.u_lambda[index],
                    batch.v_lambda[index],
                    batch.w_lambda[index],
                )
            };
            let residual = (sample - predicted) * weight;
            accumulate_direct_adjoint(
                &mut image,
                &pixels,
                ny,
                batch.u_lambda[index],
                batch.v_lambda[index],
                batch.w_lambda[index],
                residual,
            );
        }
    }
    stage_timings.residual_degrid_grid += accumulate_started.elapsed();

    let normalize_started = Instant::now();
    image.mapv_inplace(|value| value / psf_state.normalization_sumwt / psf_state.psf_peak);
    stage_timings.residual_normalize += normalize_started.elapsed();
    Ok(image)
}

fn build_direct_pixel_coordinates(geometry: ImageGeometry) -> Vec<DirectPixelCoordinate> {
    let [nx, ny] = geometry.image_shape;
    let center_x = nx as f64 / 2.0;
    let center_y = ny as f64 / 2.0;
    let mut pixels = Vec::with_capacity(nx * ny);
    for x in 0..nx {
        for y in 0..ny {
            let l = (x as f64 - center_x) * geometry.cell_size_rad[0];
            // Match CASA GridFT's effective Dec-axis convention. The C++
            // gridder negates UVW's first two axes before locating samples on
            // the padded grid, which maps positive m to lower array indices.
            let m = (center_y - y as f64) * geometry.cell_size_rad[1];
            let radius_sq = l * l + m * m;
            let n_minus_one = if radius_sq < 1.0 {
                (1.0 - radius_sq).sqrt() - 1.0
            } else {
                -1.0
            };
            pixels.push(DirectPixelCoordinate { l, m, n_minus_one });
        }
    }
    pixels
}

fn build_direct_components(
    model: &Array2<f32>,
    pixels: &[DirectPixelCoordinate],
    ny: usize,
) -> Vec<DirectComponent> {
    model
        .indexed_iter()
        .filter_map(|((x, y), value)| {
            if value.abs() <= 0.0 {
                return None;
            }
            let pixel = pixels[x * ny + y];
            Some(DirectComponent {
                value: *value,
                l: pixel.l,
                m: pixel.m,
                n_minus_one: pixel.n_minus_one,
            })
        })
        .collect()
}

fn direct_predict_visibility(
    components: &[DirectComponent],
    u_lambda: f64,
    v_lambda: f64,
    w_lambda: f64,
) -> Complex32 {
    let mut predicted = Complex32::new(0.0, 0.0);
    for component in components {
        let phase = std::f64::consts::TAU
            * (u_lambda * component.l + v_lambda * component.m + w_lambda * component.n_minus_one);
        predicted.re += component.value * phase.cos() as f32;
        predicted.im -= component.value * phase.sin() as f32;
    }
    predicted
}

fn accumulate_direct_adjoint(
    image: &mut Array2<f32>,
    pixels: &[DirectPixelCoordinate],
    ny: usize,
    u_lambda: f64,
    v_lambda: f64,
    w_lambda: f64,
    value: Complex32,
) {
    for (index, pixel) in pixels.iter().enumerate() {
        let phase = std::f64::consts::TAU
            * (u_lambda * pixel.l + v_lambda * pixel.m + w_lambda * pixel.n_minus_one);
        let contribution = 2.0 * (value.re * phase.cos() as f32 - value.im * phase.sin() as f32);
        image[(index / ny, index % ny)] += contribution;
    }
}

fn peak_abs_value_masked(image: &Array2<f32>, mask: Option<&Array2<bool>>) -> f32 {
    peak_location_masked(image, mask)
        .map(|(_, value)| value.abs())
        .unwrap_or(0.0)
}

fn peak_location_masked(
    image: &Array2<f32>,
    mask: Option<&Array2<bool>>,
) -> Option<((usize, usize), f32)> {
    peak_location_masked_with_relative_tolerance(image, mask, 0.0)
}

fn masked_positions_in_casa_peak_order(mask: &Array2<bool>) -> Vec<(usize, usize)> {
    let (nx, ny) = mask.dim();
    let mut positions = Vec::with_capacity(mask.iter().filter(|&&value| value).count());
    for y in 0..ny {
        for x in 0..nx {
            if mask[(x, y)] {
                positions.push((x, y));
            }
        }
    }
    positions
}

fn peak_location_at_positions(
    image: &Array2<f32>,
    positions: &[(usize, usize)],
) -> Option<((usize, usize), f32)> {
    let (nx, ny) = image.dim();
    let mut best = None::<((usize, usize), f32)>;
    for &(x, y) in positions {
        debug_assert!(x < nx && y < ny);
        let value = image[(x, y)];
        match best {
            None => best = Some(((x, y), value)),
            Some((_, best_value)) if value.abs() > best_value.abs() => {
                best = Some(((x, y), value));
            }
            _ => {}
        }
    }
    best
}

fn peak_location_masked_in_window(
    image: &Array2<f32>,
    mask: Option<&Array2<bool>>,
    window: ImageWindow,
) -> Option<((usize, usize), f32)> {
    let (nx, ny) = image.dim();
    if nx == 0 || ny == 0 {
        return None;
    }
    let x0 = window.x0.min(nx - 1);
    let y0 = window.y0.min(ny - 1);
    let x1 = window.x1.min(nx - 1);
    let y1 = window.y1.min(ny - 1);
    if x0 > x1 || y0 > y1 {
        return None;
    }

    peak_location_masked_in_bounds_zero_tolerance(image, mask, x0, y0, x1, y1)
}

fn hclean_peak_location_masked(
    image: &Array2<f32>,
    mask: Option<&Array2<bool>>,
) -> Option<((usize, usize), f32)> {
    peak_location_masked_with_relative_tolerance(image, mask, 0.0)
}

/// Return the finite masked peak location using a relative tie tolerance.
pub fn clean_peak_location_masked_with_relative_tolerance(
    image: &Array2<f32>,
    mask: Option<&Array2<bool>>,
    relative_tolerance: f32,
) -> Option<((usize, usize), f32)> {
    finite_peak_location_masked_with_relative_tolerance(image, mask, relative_tolerance)
}

fn finite_peak_location_masked_with_relative_tolerance(
    image: &Array2<f32>,
    mask: Option<&Array2<bool>>,
    relative_tolerance: f32,
) -> Option<((usize, usize), f32)> {
    let (nx, ny) = image.dim();
    let mut best = None;
    for y in 0..ny {
        for x in 0..nx {
            if mask.is_some_and(|current| !current[(x, y)]) {
                continue;
            }
            let value = image[(x, y)];
            if !value.is_finite() {
                continue;
            }
            match best {
                None => best = Some(((x, y), value)),
                Some((_, best_value))
                    if value.abs() > best_value.abs() * (1.0 + relative_tolerance) =>
                {
                    best = Some(((x, y), value));
                }
                _ => {}
            }
        }
    }
    best
}

fn peak_location_masked_with_relative_tolerance(
    image: &Array2<f32>,
    mask: Option<&Array2<bool>>,
    relative_tolerance: f32,
) -> Option<((usize, usize), f32)> {
    let (nx, ny) = image.dim();
    if relative_tolerance == 0.0 {
        if nx == 0 || ny == 0 {
            return None;
        }
        return peak_location_masked_in_bounds_zero_tolerance(image, mask, 0, 0, nx - 1, ny - 1);
    }

    let mut best = None;
    // Match casacore's `hclean` search order: y-major, with an optional
    // tolerance to keep near-tied peaks stable against gridding roundoff.
    for y in 0..ny {
        for x in 0..nx {
            if mask.is_some_and(|current| !current[(x, y)]) {
                continue;
            }
            let value = image[(x, y)];
            match best {
                None => best = Some(((x, y), value)),
                Some((_, best_value))
                    if value.abs() > best_value.abs() * (1.0 + relative_tolerance) =>
                {
                    best = Some(((x, y), value));
                }
                _ => {}
            }
        }
    }
    best
}

fn peak_location_masked_in_bounds_zero_tolerance(
    image: &Array2<f32>,
    mask: Option<&Array2<bool>>,
    x0: usize,
    y0: usize,
    x1: usize,
    y1: usize,
) -> Option<((usize, usize), f32)> {
    let (nx, _) = image.dim();
    let mut best = None::<((usize, usize), f32, usize)>;
    match mask {
        Some(mask) => {
            for x in x0..=x1 {
                for y in y0..=y1 {
                    if !mask[(x, y)] {
                        continue;
                    }
                    let value = image[(x, y)];
                    let order_key = y.saturating_mul(nx).saturating_add(x);
                    match best {
                        None => best = Some(((x, y), value, order_key)),
                        Some((_, best_value, best_key))
                            if value.abs() > best_value.abs()
                                || (value.abs() == best_value.abs() && order_key < best_key) =>
                        {
                            best = Some(((x, y), value, order_key));
                        }
                        _ => {}
                    }
                }
            }
        }
        None => {
            for x in x0..=x1 {
                for y in y0..=y1 {
                    let value = image[(x, y)];
                    let order_key = y.saturating_mul(nx).saturating_add(x);
                    match best {
                        None => best = Some(((x, y), value, order_key)),
                        Some((_, best_value, best_key))
                            if value.abs() > best_value.abs()
                                || (value.abs() == best_value.abs() && order_key < best_key) =>
                        {
                            best = Some(((x, y), value, order_key));
                        }
                        _ => {}
                    }
                }
            }
        }
    }
    best.map(|(position, value, _)| (position, value))
}

/// Compute the Cotton-Schwab minor-cycle threshold from the current peak and
/// PSF sidelobe estimate.
pub fn clean_cycle_threshold(
    peak_residual_jy_per_beam: f32,
    max_psf_sidelobe_level: f32,
    clean: CleanConfig,
) -> f32 {
    let psf_fraction = (max_psf_sidelobe_level * clean.cyclefactor)
        .clamp(clean.min_psf_fraction, clean.max_psf_fraction);
    (peak_residual_jy_per_beam * psf_fraction).max(clean.threshold_jy_per_beam)
}

fn robust_rms_jy_per_beam(residual: &Array2<f32>, clean_mask: Option<&Array2<bool>>) -> f32 {
    let full_mask = clean_mask
        .map(|mask| mask.iter().all(|value| *value))
        .unwrap_or(true);
    if !full_mask
        && env::var_os("CASA_RS_EXPERIMENTAL_RADIX_MADFM").is_some()
        && let Some(mask) = clean_mask
    {
        let started = Instant::now();
        let madfm = radix_madfm_f32(residual, mask);
        if profile::standard_mfs_profile_detail_enabled() {
            eprintln!(
                "robust_rms_order_statistic algorithm=exact-radix-histogram elapsed_ms={:.3}",
                profile::millis(started.elapsed()),
            );
        }
        return (madfm as f32) * 1.4826;
    }
    let mut values = residual_noise_values(residual, clean_mask, full_mask);
    if values.is_empty() {
        return 0.0;
    }
    if full_mask {
        apply_chauvenet_clipping(&mut values, -1.0, 5);
    }
    if values.is_empty() {
        return 0.0;
    }
    let madfm = if env::var_os("CASA_RS_EXPERIMENTAL_KEYED_MADFM").is_some() {
        let started = Instant::now();
        let value = keyed_madfm_f32(&values);
        if profile::standard_mfs_profile_detail_enabled() {
            eprintln!(
                "robust_rms_order_statistic algorithm=keyed-integer-selection elapsed_ms={:.3}",
                profile::millis(started.elapsed()),
            );
        }
        value
    } else if env::var_os("CASA_RS_EXPERIMENTAL_LINEAR_MADFM").is_some() {
        let started = Instant::now();
        let value = linear_madfm_f32(values);
        if profile::standard_mfs_profile_detail_enabled() {
            eprintln!(
                "robust_rms_order_statistic algorithm=linear-selection elapsed_ms={:.3}",
                profile::millis(started.elapsed()),
            );
        }
        value
    } else {
        let clipped = ndarray::Array1::from_vec(values).into_dyn();
        array_madfm(&clipped)
    };
    (madfm as f32) * 1.4826
}

#[derive(Clone, Copy)]
struct RadixRankTarget {
    prefix: u64,
    prefix_bits: u32,
    rank: usize,
}

fn radix_madfm_f32(residual: &Array2<f32>, clean_mask: &Array2<bool>) -> f64 {
    let values = residual
        .as_slice_memory_order()
        .expect("imaging residuals use contiguous native storage");
    let mask = clean_mask
        .as_slice_memory_order()
        .expect("imaging masks use contiguous native storage");
    let (lower_key, upper_key, _) = radix_select_middle_pair_by_key(values, mask, 32, |value| {
        value
            .is_finite()
            .then(|| u64::from(f32_total_order_key(value)))
    });
    let median = (f64::from(f32_from_total_order_key(lower_key as u32))
        + f64::from(f32_from_total_order_key(upper_key as u32)))
        / 2.0;
    let (lower_deviation, upper_deviation, _) =
        radix_select_middle_pair_by_key(values, mask, 64, |value| {
            value
                .is_finite()
                .then(|| (f64::from(value) - median).abs().to_bits())
        });
    (f64::from_bits(lower_deviation) + f64::from_bits(upper_deviation)) / 2.0
}

fn radix_select_middle_pair_by_key<K>(
    values: &[f32],
    mask: &[bool],
    total_bits: u32,
    key: K,
) -> (u64, u64, usize)
where
    K: Fn(f32) -> Option<u64> + Copy + Send + Sync,
{
    assert_eq!(values.len(), mask.len());
    assert!(matches!(total_bits, 32 | 64));
    let first_shift = total_bits - 16;
    let first_histogram = radix_histogram_by_key(values, mask, total_bits, 0, 0, first_shift, key);
    let count = first_histogram
        .iter()
        .copied()
        .map(|value| value as usize)
        .sum::<usize>();
    if count == 0 {
        return (0, 0, 0);
    }
    let lower_rank = (count - 1) / 2;
    let upper_rank = count / 2;
    let (lower_digit, lower_remainder) = radix_histogram_rank(&first_histogram, lower_rank);
    let (upper_digit, upper_remainder) = radix_histogram_rank(&first_histogram, upper_rank);
    let mut targets = [
        RadixRankTarget {
            prefix: u64::from(lower_digit),
            prefix_bits: 16,
            rank: lower_remainder,
        },
        RadixRankTarget {
            prefix: u64::from(upper_digit),
            prefix_bits: 16,
            rank: upper_remainder,
        },
    ];

    while targets[0].prefix_bits < total_bits {
        let shift = total_bits - targets[0].prefix_bits - 16;
        if targets[0].prefix == targets[1].prefix
            && targets[0].prefix_bits == targets[1].prefix_bits
        {
            let histogram = radix_histogram_by_key(
                values,
                mask,
                total_bits,
                targets[0].prefix,
                targets[0].prefix_bits,
                shift,
                key,
            );
            for target in &mut targets {
                radix_advance_target(target, &histogram);
            }
        } else {
            for target in &mut targets {
                let histogram = radix_histogram_by_key(
                    values,
                    mask,
                    total_bits,
                    target.prefix,
                    target.prefix_bits,
                    shift,
                    key,
                );
                radix_advance_target(target, &histogram);
            }
        }
    }
    (targets[0].prefix, targets[1].prefix, count)
}

fn radix_histogram_by_key<K>(
    values: &[f32],
    mask: &[bool],
    total_bits: u32,
    prefix: u64,
    prefix_bits: u32,
    shift: u32,
    key: K,
) -> Vec<u32>
where
    K: Fn(f32) -> Option<u64> + Copy + Send + Sync,
{
    const RADIX_BINS: usize = 1 << 16;
    const CHUNK_VALUES: usize = 262_144;
    values
        .par_chunks(CHUNK_VALUES)
        .zip(mask.par_chunks(CHUNK_VALUES))
        .fold(
            || vec![0_u32; RADIX_BINS],
            |mut histogram, (value_chunk, mask_chunk)| {
                for (&value, &masked) in value_chunk.iter().zip(mask_chunk) {
                    if masked {
                        continue;
                    }
                    let Some(key) = key(value) else {
                        continue;
                    };
                    let key_prefix = if prefix_bits == 0 {
                        0
                    } else {
                        key >> (total_bits - prefix_bits)
                    };
                    if key_prefix == prefix {
                        let digit = ((key >> shift) & 0xffff) as usize;
                        histogram[digit] = histogram[digit].saturating_add(1);
                    }
                }
                histogram
            },
        )
        .reduce(
            || vec![0_u32; RADIX_BINS],
            |mut left, right| {
                for (left_count, right_count) in left.iter_mut().zip(right) {
                    *left_count = left_count.saturating_add(right_count);
                }
                left
            },
        )
}

fn radix_histogram_rank(histogram: &[u32], rank: usize) -> (u16, usize) {
    let mut preceding = 0usize;
    for (digit, &count) in histogram.iter().enumerate() {
        let next = preceding.saturating_add(count as usize);
        if rank < next {
            return (digit as u16, rank - preceding);
        }
        preceding = next;
    }
    panic!("radix rank {rank} exceeds histogram population {preceding}");
}

fn radix_advance_target(target: &mut RadixRankTarget, histogram: &[u32]) {
    let (digit, remainder) = radix_histogram_rank(histogram, target.rank);
    target.prefix = (target.prefix << 16) | u64::from(digit);
    target.prefix_bits += 16;
    target.rank = remainder;
}

fn keyed_madfm_f32(values: &[f32]) -> f64 {
    let mut ordered_values = values
        .par_iter()
        .map(|value| f32_total_order_key(*value))
        .collect::<Vec<_>>();
    let median = median_ordered_f32_keys_as_f64(&mut ordered_values);
    let mut deviation_bits = values
        .par_iter()
        .map(|value| (f64::from(*value) - median).abs().to_bits())
        .collect::<Vec<_>>();
    median_nonnegative_f64_bits(&mut deviation_bits)
}

#[inline]
fn f32_total_order_key(value: f32) -> u32 {
    let bits = value.to_bits();
    if bits & 0x8000_0000 == 0 {
        bits ^ 0x8000_0000
    } else {
        !bits
    }
}

#[inline]
fn f32_from_total_order_key(key: u32) -> f32 {
    let bits = if key & 0x8000_0000 == 0 {
        !key
    } else {
        key ^ 0x8000_0000
    };
    f32::from_bits(bits)
}

fn median_ordered_f32_keys_as_f64(keys: &mut [u32]) -> f64 {
    if keys.is_empty() {
        return 0.0;
    }
    let length = keys.len();
    let middle = length / 2;
    let (lower, upper, _) = keys.select_nth_unstable(middle);
    let upper_middle = f64::from(f32_from_total_order_key(*upper));
    if length % 2 == 1 {
        return upper_middle;
    }
    let lower_middle = lower
        .iter()
        .copied()
        .max()
        .map(f32_from_total_order_key)
        .expect("an even non-empty key slice has a lower middle value");
    (f64::from(lower_middle) + upper_middle) / 2.0
}

fn median_nonnegative_f64_bits(bits: &mut [u64]) -> f64 {
    if bits.is_empty() {
        return 0.0;
    }
    let length = bits.len();
    let middle = length / 2;
    let (lower, upper, _) = bits.select_nth_unstable(middle);
    let upper_middle = f64::from_bits(*upper);
    if length % 2 == 1 {
        return upper_middle;
    }
    let lower_middle = lower
        .iter()
        .copied()
        .max()
        .map(f64::from_bits)
        .expect("an even non-empty deviation slice has a lower middle value");
    (lower_middle + upper_middle) / 2.0
}

fn linear_madfm_f32(mut values: Vec<f32>) -> f64 {
    let median = median_f32_values_as_f64(&mut values);
    median_by_f64_key_in_place(&mut values, |value| (f64::from(*value) - median).abs())
}

fn median_f32_values_as_f64(values: &mut [f32]) -> f64 {
    if values.is_empty() {
        return 0.0;
    }
    let middle = values.len() / 2;
    if values.len() % 2 == 1 {
        return f64::from(*values.select_nth_unstable_by(middle, f32::total_cmp).1);
    }
    let (lower, upper, _) = values.select_nth_unstable_by(middle, f32::total_cmp);
    let lower_middle = lower
        .iter()
        .copied()
        .max_by(f32::total_cmp)
        .expect("an even non-empty slice has a lower middle value");
    (f64::from(lower_middle) + f64::from(*upper)) / 2.0
}

fn median_by_f64_key_in_place<T>(values: &mut [T], mut key: impl FnMut(&T) -> f64 + Copy) -> f64 {
    if values.is_empty() {
        return 0.0;
    }
    let length = values.len();
    let middle = length / 2;
    let (lower, upper, _) =
        values.select_nth_unstable_by(middle, |left, right| key(left).total_cmp(&key(right)));
    let upper_middle = key(upper);
    if length % 2 == 1 {
        return upper_middle;
    }
    let lower_middle = lower
        .iter()
        .map(key)
        .max_by(f64::total_cmp)
        .expect("an even non-empty slice has a lower middle value");
    (lower_middle + upper_middle) / 2.0
}

fn nsigma_threshold_jy_per_beam(
    residual: &Array2<f32>,
    clean_mask: Option<&Array2<bool>>,
    clean: CleanConfig,
) -> f32 {
    if clean.nsigma > 0.0 {
        clean.nsigma * robust_rms_jy_per_beam(residual, clean_mask)
    } else {
        0.0
    }
}

fn residual_noise_values(
    residual: &Array2<f32>,
    clean_mask: Option<&Array2<bool>>,
    full_mask: bool,
) -> Vec<f32> {
    residual
        .iter()
        .zip(
            clean_mask
                .into_iter()
                .flat_map(|mask| mask.iter())
                .chain(std::iter::repeat(&false)),
        )
        .filter_map(|(value, masked)| {
            if !value.is_finite() {
                return None;
            }
            if !full_mask && *masked {
                None
            } else {
                Some(*value)
            }
        })
        .collect()
}

fn apply_chauvenet_clipping(values: &mut Vec<f32>, zscore: f64, max_iterations: i32) {
    if values.is_empty() {
        return;
    }
    let max_i = if max_iterations >= 0 {
        max_iterations as usize
    } else {
        1000usize
    };
    let mut prev_npts = 0usize;
    let mut iteration = 0usize;
    while iteration <= max_i && !values.is_empty() {
        let current_npts = values.len();
        if iteration > 0 && current_npts == prev_npts {
            break;
        }
        let (mean, stddev) = mean_stddev(values);
        if !mean.is_finite() || !stddev.is_finite() || stddev <= 0.0 {
            break;
        }
        let z = if zscore >= 0.0 {
            zscore
        } else {
            chauvenet_max_zscore(current_npts as u64)
        };
        let low = mean - z * stddev;
        let high = mean + z * stddev;
        values.retain(|value| {
            let value = *value as f64;
            value >= low && value <= high
        });
        prev_npts = current_npts;
        iteration += 1;
    }
}

fn mean_stddev(values: &[f32]) -> (f64, f64) {
    let n = values.len() as f64;
    let mean = values.iter().map(|value| *value as f64).sum::<f64>() / n;
    let sumsq = values
        .iter()
        .map(|value| {
            let diff = *value as f64 - mean;
            diff * diff
        })
        .sum::<f64>();
    let variance = if values.len() > 1 {
        sumsq / (n - 1.0)
    } else {
        0.0
    };
    (mean, variance.sqrt())
}

fn chauvenet_max_zscore(npts: u64) -> f64 {
    const NPTS_TO_MAX_ZSCORE: &[(u64, f64)] = &[
        (0, 0.5),
        (1, 1.0),
        (3, 1.5),
        (10, 2.0),
        (40, 2.5),
        (185, 3.0),
        (1074, 3.5),
        (7893, 4.0),
        (73579, 4.5),
        (872138, 5.0),
        (13165126, 5.5),
        (253398672, 6.0),
        (6225098696, 6.5),
        (195341107722, 7.0),
    ];
    if let Some((_, zscore)) = NPTS_TO_MAX_ZSCORE.iter().find(|(count, _)| *count == npts) {
        return *zscore;
    }
    let mut low_index = 0usize;
    let mut high_index = 1usize;
    if npts > NPTS_TO_MAX_ZSCORE[NPTS_TO_MAX_ZSCORE.len() - 1].0 {
        let mut z = NPTS_TO_MAX_ZSCORE[NPTS_TO_MAX_ZSCORE.len() - 1].1 + 0.5;
        loop {
            let npts_min = chauvenet_zscore_to_npts(z);
            if npts_min >= npts {
                low_index = NPTS_TO_MAX_ZSCORE.len() - 2;
                high_index = NPTS_TO_MAX_ZSCORE.len() - 1;
                break;
            }
            z += 0.5;
        }
    } else {
        while high_index < NPTS_TO_MAX_ZSCORE.len() && NPTS_TO_MAX_ZSCORE[high_index].0 < npts {
            low_index += 1;
            high_index += 1;
        }
    }
    let (mut low_z, mut high_z) = (
        NPTS_TO_MAX_ZSCORE[low_index].1,
        NPTS_TO_MAX_ZSCORE[high_index].1,
    );
    let mut z = (low_z + high_z) / 2.0;
    loop {
        let npts_min = chauvenet_zscore_to_npts(z);
        if npts_min == npts || (high_z - low_z).abs() <= 1e-12 {
            return z;
        }
        if npts_min > npts {
            high_z = z;
        } else {
            low_z = z;
        }
        z = (low_z + high_z) / 2.0;
    }
}

fn chauvenet_zscore_to_npts(zscore: f64) -> u64 {
    (0.5 / erfc(zscore / std::f64::consts::SQRT_2)) as u64
}

fn threshold_reached_with_tolerance(peak_abs_jy_per_beam: f32, threshold_jy_per_beam: f32) -> bool {
    if threshold_jy_per_beam <= 0.0 {
        return peak_abs_jy_per_beam <= threshold_jy_per_beam;
    }
    let tolerance_jy_per_beam = (0.01 * threshold_jy_per_beam).max(2.0e-8);
    peak_abs_jy_per_beam <= threshold_jy_per_beam
        || (peak_abs_jy_per_beam - threshold_jy_per_beam).abs() <= tolerance_jy_per_beam
}

fn tolerant_clean_stop_reason(
    peak_abs_jy_per_beam: f32,
    threshold_jy_per_beam: f32,
    nsigma_threshold_jy_per_beam: f32,
) -> Option<CleanStopReason> {
    if threshold_reached_with_tolerance(peak_abs_jy_per_beam, threshold_jy_per_beam) {
        Some(CleanStopReason::GlobalThresholdReached)
    } else if nsigma_threshold_jy_per_beam > threshold_jy_per_beam
        && threshold_reached_with_tolerance(peak_abs_jy_per_beam, nsigma_threshold_jy_per_beam)
    {
        Some(CleanStopReason::NsigmaThresholdReached)
    } else {
        None
    }
}

fn minor_cycle_stop_reason(
    peak_abs_jy_per_beam: f32,
    threshold_jy_per_beam: f32,
    cycle_threshold_jy_per_beam: f32,
    nsigma_threshold_jy_per_beam: f32,
) -> Option<CleanStopReason> {
    let threshold_floor_active = threshold_jy_per_beam > 0.0
        && (0.01 * threshold_jy_per_beam) < 2.0e-8
        && cycle_threshold_jy_per_beam <= threshold_jy_per_beam;
    if peak_abs_jy_per_beam < threshold_jy_per_beam
        || (threshold_floor_active
            && threshold_reached_with_tolerance(peak_abs_jy_per_beam, threshold_jy_per_beam))
    {
        Some(CleanStopReason::GlobalThresholdReached)
    } else if cycle_threshold_jy_per_beam >= nsigma_threshold_jy_per_beam {
        (peak_abs_jy_per_beam < cycle_threshold_jy_per_beam)
            .then_some(CleanStopReason::CycleThresholdReached)
    } else if nsigma_threshold_jy_per_beam > threshold_jy_per_beam {
        (peak_abs_jy_per_beam < nsigma_threshold_jy_per_beam)
            .then_some(CleanStopReason::NsigmaThresholdReached)
    } else {
        None
    }
}

fn minor_cycle_stop_is_major_cycle_handoff(reason: CleanStopReason, updated_model: bool) -> bool {
    updated_model
        && matches!(
            reason,
            CleanStopReason::CycleThresholdReached | CleanStopReason::NsigmaThresholdReached
        )
}

// CASA's single-term Cotton-Schwab controllers retain this cross-cycle
// divergence guard. MT-MFS must not use it: its approximate residual normally
// follows a sawtooth across measured major-cycle refreshes, while MT-MFS
// divergence is decided inside the current minor-cycle solve.
fn update_divergence_state(
    warnings: &mut Vec<String>,
    min_residual_peak_jy_per_beam: &mut f32,
    current_peak: f32,
    divergence_warned: &mut bool,
) -> Option<CleanStopReason> {
    if current_peak < *min_residual_peak_jy_per_beam {
        *min_residual_peak_jy_per_beam = current_peak;
        return None;
    } else if *min_residual_peak_jy_per_beam > 0.0
        && (current_peak - *min_residual_peak_jy_per_beam) / *min_residual_peak_jy_per_beam > 0.1
    {
        if !*divergence_warned {
            warnings.push(format!(
                "minor-cycle divergence detected: residual peak {:.6} Jy/beam exceeded prior minimum {:.6} Jy/beam by more than 10%",
                current_peak, *min_residual_peak_jy_per_beam
            ));
            *divergence_warned = true;
        }
        return Some(CleanStopReason::DivergenceDetected);
    }
    None
}

fn subtract_shifted_psf(
    residual: &mut Array2<f32>,
    psf: &Array2<f32>,
    peak_index: (usize, usize),
    component: f32,
) {
    subtract_shifted_kernel(residual, psf, peak_index, component);
}

fn subtract_shifted_kernel(
    image: &mut Array2<f32>,
    kernel: &Array2<f32>,
    peak_index: (usize, usize),
    scale_factor: f32,
) {
    subtract_shifted_kernel_in_window(
        image,
        kernel,
        peak_index,
        scale_factor,
        ImageWindow::full(image.dim()),
    );
}

fn subtract_shifted_kernel_casa_mtmfs_rhs(
    image: &mut Array2<f32>,
    kernel: &Array2<f32>,
    peak_index: (usize, usize),
    gain: f32,
    coefficient: f32,
) {
    let support = KernelSupport {
        x0: 0,
        y0: 0,
        x1: kernel.dim().0.saturating_sub(1),
        y1: kernel.dim().1.saturating_sub(1),
    };
    let Some((x0, x1, y0, y1)) =
        shifted_kernel_image_bounds(image.dim(), kernel, support, peak_index)
    else {
        return;
    };
    let kernel_center = (kernel.dim().0 / 2, kernel.dim().1 / 2);
    let image_ny = image.dim().1;

    if image.is_standard_layout()
        && kernel.is_standard_layout()
        && let (Some(image_values), Some(kernel_values)) = (
            image.as_slice_memory_order_mut(),
            kernel.as_slice_memory_order(),
        )
    {
        let kernel_ny = kernel.dim().1;
        for x in x0..=x1 {
            let image_row_offset = x * image_ny;
            let kernel_x = x as isize - peak_index.0 as isize + kernel_center.0 as isize;
            let kernel_row_offset = kernel_x as usize * kernel_ny;
            for y in y0..=y1 {
                let kernel_y = y as isize - peak_index.1 as isize + kernel_center.1 as isize;
                image_values[image_row_offset + y] -= casa_mtmfs_scaled_kernel_value(
                    kernel_values[kernel_row_offset + kernel_y as usize],
                    gain,
                    coefficient,
                );
            }
        }
        return;
    }

    for x in x0..=x1 {
        for y in y0..=y1 {
            let kernel_x = x as isize - peak_index.0 as isize + kernel_center.0 as isize;
            let kernel_y = y as isize - peak_index.1 as isize + kernel_center.1 as isize;
            image[(x, y)] -= casa_mtmfs_scaled_kernel_value(
                kernel[(kernel_x as usize, kernel_y as usize)],
                gain,
                coefficient,
            );
        }
    }
}

#[inline]
fn casa_mtmfs_scaled_kernel_value(kernel_value: f32, gain: f32, coefficient: f32) -> f32 {
    // MultiTermMatrixCleaner::updateModelAndRHS evaluates both
    // `scaleSub * loopgain * coeffs[taylor]` and
    // `smoothSub * loopgain * coeffs[taylor2]` in this Float32 order.
    let scaled_kernel = kernel_value * gain;
    scaled_kernel * coefficient
}

fn subtract_shifted_kernel_in_window(
    image: &mut Array2<f32>,
    kernel: &Array2<f32>,
    peak_index: (usize, usize),
    scale_factor: f32,
    window: ImageWindow,
) {
    let kernel_center = (kernel.shape()[0] / 2, kernel.shape()[1] / 2);
    let (nx, ny) = image.dim();
    if nx == 0 || ny == 0 {
        return;
    }
    let x0 = window.x0.min(nx - 1);
    let y0 = window.y0.min(ny - 1);
    let x1 = window.x1.min(nx - 1);
    let y1 = window.y1.min(ny - 1);
    if x0 > x1 || y0 > y1 {
        return;
    }

    let kernel_x_min_image = peak_index.0 as isize - kernel_center.0 as isize;
    let kernel_y_min_image = peak_index.1 as isize - kernel_center.1 as isize;
    let kernel_x_max_image = kernel_x_min_image + kernel.shape()[0] as isize - 1;
    let kernel_y_max_image = kernel_y_min_image + kernel.shape()[1] as isize - 1;
    if kernel_x_max_image < 0
        || kernel_y_max_image < 0
        || kernel_x_min_image > nx as isize - 1
        || kernel_y_min_image > ny as isize - 1
    {
        return;
    }
    let x0 = x0.max(kernel_x_min_image.max(0) as usize);
    let y0 = y0.max(kernel_y_min_image.max(0) as usize);
    let x1 = x1.min(kernel_x_max_image.min(nx as isize - 1) as usize);
    let y1 = y1.min(kernel_y_max_image.min(ny as isize - 1) as usize);
    if x0 > x1 || y0 > y1 {
        return;
    }

    if image.is_standard_layout()
        && kernel.is_standard_layout()
        && let (Some(image_values), Some(kernel_values)) = (
            image.as_slice_memory_order_mut(),
            kernel.as_slice_memory_order(),
        )
    {
        let kernel_ny = kernel.shape()[1];
        for x in x0..=x1 {
            let image_row_offset = x * ny;
            let kernel_x = (x as isize - kernel_x_min_image) as usize;
            let kernel_row_offset = kernel_x * kernel_ny;
            for y in y0..=y1 {
                let kernel_y = (y as isize - kernel_y_min_image) as usize;
                image_values[image_row_offset + y] -=
                    scale_factor * kernel_values[kernel_row_offset + kernel_y];
            }
        }
        return;
    }

    for x in x0..=x1 {
        let kernel_x = (x as isize - kernel_x_min_image) as usize;
        for y in y0..=y1 {
            let kernel_y = (y as isize - kernel_y_min_image) as usize;
            image[(x, y)] -= scale_factor * kernel[(kernel_x, kernel_y)];
        }
    }
}

#[cfg(test)]
fn add_shifted_kernel(
    image: &mut Array2<f32>,
    kernel: &Array2<f32>,
    peak_index: (usize, usize),
    scale_factor: f32,
) {
    add_shifted_kernel_with_support(
        image,
        kernel,
        kernel_nonzero_support(kernel),
        peak_index,
        scale_factor,
    );
}

fn add_shifted_kernel_casa_mtmfs_model(
    image: &mut Array2<f32>,
    kernel: &Array2<f32>,
    peak_index: (usize, usize),
    gain: f32,
    coefficient: f32,
) {
    let Some(support) = kernel_nonzero_support(kernel) else {
        return;
    };
    let Some((x0, x1, y0, y1)) =
        shifted_kernel_image_bounds(image.dim(), kernel, support, peak_index)
    else {
        return;
    };
    let kernel_center = (kernel.dim().0 / 2, kernel.dim().1 / 2);
    for x in x0..=x1 {
        for y in y0..=y1 {
            let kernel_x = x as isize - peak_index.0 as isize + kernel_center.0 as isize;
            let kernel_y = y as isize - peak_index.1 as isize + kernel_center.1 as isize;
            image[(x, y)] += casa_mtmfs_scaled_kernel_value(
                kernel[(kernel_x as usize, kernel_y as usize)],
                gain,
                coefficient,
            );
        }
    }
}

fn record_shifted_kernel_support_positions(
    positions: &mut BTreeSet<(usize, usize)>,
    image_shape: (usize, usize),
    kernel: &Array2<f32>,
    peak_index: (usize, usize),
) {
    let Some(support) = kernel_nonzero_support(kernel) else {
        return;
    };
    let Some((x0, x1, y0, y1)) =
        shifted_kernel_image_bounds(image_shape, kernel, support, peak_index)
    else {
        return;
    };
    for x in x0..=x1 {
        for y in y0..=y1 {
            positions.insert((x, y));
        }
    }
}

fn kernel_nonzero_support(kernel: &Array2<f32>) -> Option<KernelSupport> {
    let mut support = None::<KernelSupport>;
    for x in 0..kernel.shape()[0] {
        for y in 0..kernel.shape()[1] {
            if kernel[(x, y)] == 0.0 {
                continue;
            }
            support = Some(match support {
                Some(current) => KernelSupport {
                    x0: current.x0.min(x),
                    y0: current.y0.min(y),
                    x1: current.x1.max(x),
                    y1: current.y1.max(y),
                },
                None => KernelSupport {
                    x0: x,
                    y0: y,
                    x1: x,
                    y1: y,
                },
            });
        }
    }
    support
}

fn add_shifted_kernel_with_support(
    image: &mut Array2<f32>,
    kernel: &Array2<f32>,
    support: Option<KernelSupport>,
    peak_index: (usize, usize),
    scale_factor: f32,
) {
    let Some(support) = support else {
        return;
    };
    let Some((x0, x1, y0, y1)) =
        shifted_kernel_image_bounds(image.dim(), kernel, support, peak_index)
    else {
        return;
    };
    let kernel_center = (kernel.shape()[0] / 2, kernel.shape()[1] / 2);
    for x in x0..=x1 {
        for y in y0..=y1 {
            let kernel_x = x as isize - peak_index.0 as isize + kernel_center.0 as isize;
            let kernel_y = y as isize - peak_index.1 as isize + kernel_center.1 as isize;
            image[(x, y)] += scale_factor * kernel[(kernel_x as usize, kernel_y as usize)];
        }
    }
}

fn shifted_kernel_support_pixel_count(
    image_shape: (usize, usize),
    kernel: &Array2<f32>,
    support: Option<KernelSupport>,
    peak_index: (usize, usize),
) -> usize {
    let Some(support) = support else {
        return 0;
    };
    let Some((x0, x1, y0, y1)) =
        shifted_kernel_image_bounds(image_shape, kernel, support, peak_index)
    else {
        return 0;
    };
    x1.saturating_sub(x0)
        .saturating_add(1)
        .saturating_mul(y1.saturating_sub(y0).saturating_add(1))
}

fn shifted_kernel_image_bounds(
    image_shape: (usize, usize),
    kernel: &Array2<f32>,
    support: KernelSupport,
    peak_index: (usize, usize),
) -> Option<(usize, usize, usize, usize)> {
    if image_shape.0 == 0 || image_shape.1 == 0 {
        return None;
    }
    let kernel_center = (kernel.shape()[0] / 2, kernel.shape()[1] / 2);
    let image_x0 = peak_index.0 as isize + support.x0 as isize - kernel_center.0 as isize;
    let image_x1 = peak_index.0 as isize + support.x1 as isize - kernel_center.0 as isize;
    let image_y0 = peak_index.1 as isize + support.y0 as isize - kernel_center.1 as isize;
    let image_y1 = peak_index.1 as isize + support.y1 as isize - kernel_center.1 as isize;
    let max_x = image_shape.0 as isize - 1;
    let max_y = image_shape.1 as isize - 1;
    if image_x1 < 0 || image_y1 < 0 || image_x0 > max_x || image_y0 > max_y {
        return None;
    }
    let x0 = image_x0.max(0) as usize;
    let y0 = image_y0.max(0) as usize;
    let x1 = image_x1.min(max_x) as usize;
    let y1 = image_y1.min(max_y) as usize;
    (x0 <= x1 && y0 <= y1).then_some((x0, x1, y0, y1))
}

fn peak_abs_value(image: &Array2<f32>) -> f32 {
    image
        .iter()
        .fold(0.0f32, |best, value| best.max(value.abs()))
}

fn peak_abs_value_parallel(image: &Array2<f32>) -> f32 {
    image.as_slice_memory_order().map_or_else(
        || peak_abs_value(image),
        |values| {
            values
                .par_chunks(65_536)
                .map(|chunk| {
                    chunk
                        .iter()
                        .fold(0.0_f32, |best, value| best.max(value.abs()))
                })
                .reduce(|| 0.0, f32::max)
        },
    )
}

fn sparse_model_flux(model: &Array2<f32>, support_positions: &BTreeSet<(usize, usize)>) -> f32 {
    support_positions
        .iter()
        .map(|&position| model[position])
        .sum()
}

#[cfg(test)]
fn dirty_clean_config(psf_cutoff: f32) -> CleanConfig {
    CleanConfig {
        niter: 0,
        major_cycle_limit: None,
        gain: 0.1,
        threshold_jy_per_beam: 0.0,
        nsigma: 0.0,
        psf_cutoff,
        minor_cycle_length: 1,
        cyclefactor: 1.0,
        min_psf_fraction: 0.05,
        max_psf_fraction: 0.8,
        hogbom_iteration_mode: HogbomIterationMode::Strict,
    }
}

fn casa_major_cycle_count(refreshes: usize, clean_niter: usize) -> usize {
    if clean_niter > 0 { refreshes + 1 } else { 0 }
}

fn expand_plane(plane: &Array2<f32>) -> Array4<f32> {
    let (nx, ny) = plane.dim();
    let mut expanded = Array4::<f32>::zeros((nx, ny, 1, 1).f());
    expanded.slice_mut(s![.., .., 0, 0]).assign(plane);
    expanded
}

fn expand_mask_plane(plane: &Array2<bool>) -> Array4<bool> {
    let (nx, ny) = plane.dim();
    let mut expanded = Array4::<bool>::from_elem((nx, ny, 1, 1).f(), false);
    expanded.slice_mut(s![.., .., 0, 0]).assign(plane);
    expanded
}

fn expand_scalar(value: f32) -> Array4<f32> {
    let mut expanded = Array4::<f32>::zeros((1, 1, 1, 1));
    expanded[(0, 0, 0, 0)] = value;
    expanded
}

