    #[test]
    fn sparse_centered_dft_matches_dense_centered_fft() {
        let mut input = Array2::<Complex32>::zeros((8, 10));
        input[(1, 7)] = Complex32::new(0.75, -0.25);
        input[(6, 2)] = Complex32::new(-0.5, 0.125);
        let nonzero = input
            .indexed_iter()
            .filter_map(|((x, y), &value)| (value.norm_sqr() > 0.0).then_some((x, y, value)))
            .collect::<Vec<_>>();
        let expected = super::centered_fft2(&input);
        let actual =
            super::centered_sparse_dft2(input.dim(), &nonzero, 2).expect("sparse centered DFT");
        let maximum_difference = expected
            .iter()
            .zip(actual.iter())
            .map(|(&left, &right)| (left - right).norm())
            .fold(0.0f32, f32::max);
        assert!(
            maximum_difference < 2.0e-6,
            "maximum sparse DFT difference {maximum_difference}"
        );
    }

    #[test]
    fn linear_madfm_matches_sorted_casacore_contract() {
        for length in [1usize, 2, 17, 1_000, 1_001] {
            let values = (0..length)
                .map(|index| {
                    let phase = index as f32 * 0.173;
                    phase.sin() * 7.0 + (index % 11) as f32 * 0.125
                })
                .collect::<Vec<_>>();
            let expected =
                casa_lattices::array_madfm(&ndarray::Array1::from(values.clone()).into_dyn());
            let actual = super::linear_madfm_f32(values);
            assert_eq!(actual, expected, "length {length}");
            let keyed = super::keyed_madfm_f32(
                &(0..length)
                    .map(|index| {
                        let phase = index as f32 * 0.173;
                        phase.sin() * 7.0 + (index % 11) as f32 * 0.125
                    })
                    .collect::<Vec<_>>(),
            );
            assert_eq!(keyed, expected, "keyed length {length}");
        }
    }

    #[test]
    fn sparse_mask_peak_search_matches_full_masked_search_and_ties() {
        let mut image = Array2::<f32>::zeros((7, 5));
        image[(6, 0)] = -8.0;
        image[(1, 1)] = 8.0;
        image[(4, 3)] = 12.0;
        let mut mask = Array2::<bool>::from_elem(image.dim(), false);
        mask[(6, 0)] = true;
        mask[(1, 1)] = true;
        mask[(0, 4)] = true;
        let positions = super::masked_positions_in_casa_peak_order(&mask);
        assert_eq!(positions, vec![(6, 0), (1, 1), (0, 4)]);
        assert_eq!(
            super::peak_location_at_positions(&image, &positions),
            super::peak_location_masked(&image, Some(&mask)),
        );
        assert_eq!(
            super::peak_location_at_positions(&image, &positions),
            Some(((6, 0), -8.0)),
        );
    }

    #[test]
    fn resident_metal_replay_compaction_discards_only_build_materialization() {
        let mut window = super::AwProjectCompactReplayWindow {
            source_samples: Vec::with_capacity(32),
            tap_requests: Vec::with_capacity(64),
            bundles: Vec::with_capacity(64),
            persistent_metal_batch: Some(super::AwProjectMetalBatch::default()),
            persistent_metal_resident_program: Some(super::AwProjectMetalResidentProgram {
                prediction_batch: super::AwProjectMetalPredictionBatch::default(),
                tile_batch: super::AwProjectMetalBatch::default(),
                tile_plan: super::AwProjectMetalTilePlan::default(),
                residual_scale_plan: super::AwProjectMetalResidualScalePlan {
                    max_kernel_norm: 0.0,
                    residual_overlap: 0,
                },
                selected_model_plan: None,
                metadata: super::AwProjectMetalResidentMetadata {
                    normalization_sumwt: 0.0,
                    gridded_samples: 0,
                    skipped_samples: 0,
                    aw_sample_census: super::AwProjectSampleStats::default(),
                },
            }),
        };
        let resident_bytes_before = window.resident_bytes();

        let released = window.compact_to_resident_metal_program();

        assert!(released > 0);
        assert_eq!(
            resident_bytes_before - window.resident_bytes(),
            released,
            "reported released bytes must match the resident-byte ledger"
        );
        assert_eq!(window.source_samples.capacity(), 0);
        assert_eq!(window.tap_requests.capacity(), 0);
        assert_eq!(window.bundles.capacity(), 0);
        assert!(window.persistent_metal_batch.is_none());
        assert!(window.persistent_metal_resident_program.is_some());
    }

