    #[test]
    fn aw_stokes_i_mueller_selection_keeps_visibility_hand_bound_to_kernel() {
        let rr = Complex32::new(1.0, 2.0);
        let ll = Complex32::new(3.0, 4.0);

        assert_eq!(aw_stokes_i_visibility_for_mueller(0, rr, ll).unwrap(), rr);
        assert_eq!(aw_stokes_i_visibility_for_mueller(15, rr, ll).unwrap(), ll);
        let error = aw_stokes_i_visibility_for_mueller(7, rr, ll).unwrap_err();
        assert!(error.to_string().contains("unsupported Mueller element 7"));
    }

    #[test]
    fn aw_stokes_i_residual_subtracts_in_correlation_domain_before_mueller_routing() {
        let rr_visibility = Complex32::new(10.0, 1.0);
        let ll_visibility = Complex32::new(20.0, 2.0);
        let rr_prediction = Complex32::new(3.0, 0.25);
        let ll_prediction = Complex32::new(5.0, 0.5);

        assert_eq!(
            aw_stokes_i_residual_for_mueller(
                0,
                rr_visibility,
                ll_visibility,
                rr_prediction,
                ll_prediction,
            )
            .unwrap(),
            rr_visibility - rr_prediction,
        );
        assert_eq!(
            aw_stokes_i_residual_for_mueller(
                15,
                rr_visibility,
                ll_visibility,
                rr_prediction,
                ll_prediction,
            )
            .unwrap(),
            ll_visibility - ll_prediction,
        );
    }

    #[test]
    fn prepared_clean_skip_publishes_dirty_plane_without_minor_cycle_backend() {
        let geometry = ImageGeometry {
            image_shape: [32, 32],
            cell_size_rad: [1.0e-4, 1.0e-4],
        };
        let request = ImagingRequest {
            geometry,
            visibility_batches: vec![point_source_visibilities(
                &[(0.0, 0.0, 0.0)],
                geometry.cell_size_rad[0],
                geometry.image_shape,
                (16.0, 16.0),
                1.0,
            )],
            gridder_mode: GridderMode::Standard,
            plane_stokes: PlaneStokes::I,
            weighting: WeightingMode::Natural,
            reffreq_hz: 1.4e9,
            selected_frequency_range_hz: [1.4e9, 1.4e9],
            deconvolver: Deconvolver::Hogbom,
            multiscale_scales: Vec::new(),
            small_scale_bias: 0.0,
            clean: CleanConfig {
                niter: 100,
                threshold_jy_per_beam: 0.0,
                minor_cycle_length: 100,
                hogbom_iteration_mode: HogbomIterationMode::CasaInclusive,
                ..CleanConfig::default()
            },
            clean_mask: None,
            initial_model: None,
            w_term_mode: WTermMode::None,
            w_project_planes: None,
            compatibility: CompatibilityMode::CasaStandardMfs,
        };
        let gridder = StandardGridder::new(geometry).unwrap();
        let weighted_batches = apply_weighting(&request, &gridder, 1).unwrap();
        let builder = StandardMfsPlannedSampleBuilder::new(geometry).unwrap();
        let mut planned_samples = Vec::<StandardMfsPlannedWeightedSample>::new();
        builder
            .plan_visibility_batch_into(&weighted_batches[0], &mut planned_samples)
            .unwrap();
        let mut run_block = StandardMfsPlannedWeightedSampleRunBlock::default();
        run_block.push_run_from_slice(&planned_samples);
        let mut replay_count = 0usize;
        let prepared =
            prepare_standard_mfs_planned_sample_run_block_clean_plane_with_execution_config(
                request,
                StandardMfsExecutionPlan::default(),
                DirtyProductFftPolicy::correctness_first(),
                |consumer| {
                    replay_count += 1;
                    consumer(&run_block)
                },
            )
            .unwrap();
        assert!(replay_count > 0);

        let result =
            skip_standard_mfs_prepared_clean_plane_with_cycle_threshold(prepared, f32::MAX)
                .unwrap();

        assert_eq!(result.diagnostics.minor_iterations, 0);
        assert_eq!(
            result.diagnostics.clean_stop_reason,
            Some(CleanStopReason::CycleThresholdReached)
        );
        let max_model = result
            .model
            .iter()
            .fold(0.0f32, |best, value| best.max(value.abs()));
        assert_eq!(max_model, 0.0);
        let max_image_residual_delta = result
            .image
            .iter()
            .zip(result.residual.iter())
            .map(|(image, residual)| (image - residual).abs())
            .fold(0.0f32, f32::max);
        assert_eq!(max_image_residual_delta, 0.0);
    }

