    #[test]
    fn mtmfs_sparse_rhs_patch_update_matches_dense_positions() {
        let shape = (32, 28);
        let positions = [(0, 0), (8, 8), (15, 12), (16, 14), (18, 16), (31, 27)];
        let mut dense = Array2::from_shape_fn(shape, |(x, y)| (x * 7 + y * 11) as f32 * 0.01);
        let mut sparse = positions
            .iter()
            .map(|position| dense[*position])
            .collect::<Vec<_>>();
        let kernel = Array2::from_shape_fn((9, 7), |(x, y)| (x * 5 + y * 3) as f32 * -0.002);
        let peak = (16, 14);
        let scale_factor = -0.17;

        super::subtract_shifted_kernel(&mut dense, &kernel, peak, scale_factor);
        super::subtract_shifted_kernel_at_positions(
            &mut sparse,
            &positions,
            &kernel,
            peak,
            scale_factor,
        );

        for (&actual, &position) in sparse.iter().zip(&positions) {
            assert_eq!(actual, dense[position]);
        }
    }

    #[test]
    fn mtmfs_bounded_cross_scale_psf_patch_matches_full_image_convolution() {
        let shape = (128, 120);
        let center = (61, 58);
        let image = Array2::from_shape_fn(shape, |(x, y)| {
            ((x * 17 + y * 11) as f32 * 0.021).sin() + ((x * 3 + y * 5) as f32 * 0.013).cos()
        });
        let left = super::make_compact_multiscale_kernel(3.0);
        let right = super::make_compact_multiscale_kernel(5.0);
        let combined = super::convolve_compact_scale_kernels(&left, &right);
        let support = super::casa_mtmfs_psf_patch_support(shape, 5.0);
        let actual = super::bounded_circular_convolution_patch(&image, &combined, center, support);
        let expected = super::fft_convolve_real_compact(&image, &combined);
        let patch_center = support / 2;

        for x in 0..support {
            for y in 0..support {
                let expected_x = (center.0 + shape.0 + x - patch_center) % shape.0;
                let expected_y = (center.1 + shape.1 + y - patch_center) % shape.1;
                assert!(
                    (actual[(x, y)] - expected[(expected_x, expected_y)]).abs() < 5.0e-4,
                    "mismatch at ({x}, {y}): actual={} expected={}",
                    actual[(x, y)],
                    expected[(expected_x, expected_y)]
                );
            }
        }
    }

    #[test]
    fn mtmfs_cached_cross_scale_rhs_update_matches_full_image_reference() {
        let shape = (64, 64);
        let center = (shape.0 / 2, shape.1 / 2);
        let compact_scale_kernels = vec![
            super::make_compact_multiscale_kernel(0.0),
            super::make_compact_multiscale_kernel(3.0),
        ];
        let psf_terms = (0..3)
            .map(|order| {
                Array2::from_shape_fn(shape, |(x, y)| {
                    let radius2 =
                        (x as f32 - center.0 as f32).powi(2) + (y as f32 - center.1 as f32).powi(2);
                    (1.0 + order as f32 * 0.1) * (-radius2 / 24.0).exp()
                })
            })
            .collect::<Vec<_>>();
        let support = super::casa_mtmfs_psf_patch_support(shape, 3.0);
        let mut psf_pair_patches = Vec::new();
        for high_scale in 0..2 {
            for low_scale in 0..=high_scale {
                let combined = super::convolve_compact_scale_kernels(
                    &compact_scale_kernels[high_scale],
                    &compact_scale_kernels[low_scale],
                );
                psf_pair_patches.push(
                    psf_terms
                        .iter()
                        .map(|psf| {
                            super::bounded_circular_convolution_patch(
                                psf, &combined, center, support,
                            )
                        })
                        .collect(),
                );
            }
        }
        let basis = super::MtmfsMultiscaleBasis {
            scale_sizes: vec![0.0, 3.0],
            compact_scale_kernels,
            scale_bias: vec![1.0, 1.0],
            scale_masks: None,
            scale_search_positions: vec![None, None],
            psf_pair_patches,
            sparse_rhs: false,
            sparse_rhs_fft_seed: false,
            scale_fft_backend: super::MtmfsScaleFftBackend::RustFft,
        };
        let residual_terms = vec![
            Array2::from_shape_fn(shape, |(x, y)| (x * 7 + y * 11) as f32 * 0.001),
            Array2::from_shape_fn(shape, |(x, y)| (x * 3 + y * 5) as f32 * -0.002),
        ];
        let mut actual = basis.convolve_residual_terms(&residual_terms);
        let mut expected = actual.clone();
        let selected_scale = 1;
        let position = (29, 37);
        let gain = 0.1;
        let coefficients = [0.8, -0.35];

        basis.subtract_rhs_component(&mut actual, selected_scale, position, gain, &coefficients);
        for (target_scale, rhs) in expected.iter_mut().enumerate() {
            let super::MtmfsScaleRhs::Dense(rhs_terms) = rhs else {
                panic!("dense reference expected");
            };
            let combined = super::convolve_compact_scale_kernels(
                &basis.compact_scale_kernels[target_scale],
                &basis.compact_scale_kernels[selected_scale],
            );
            for (residual_order, rhs_term) in rhs_terms.iter_mut().enumerate() {
                for (model_order, coefficient) in coefficients.iter().copied().enumerate() {
                    let convolved_psf = super::fft_convolve_real_compact(
                        &psf_terms[residual_order + model_order],
                        &combined,
                    );
                    super::subtract_shifted_kernel(
                        rhs_term,
                        &convolved_psf,
                        position,
                        gain * coefficient,
                    );
                }
            }
        }

        for (actual_scale, expected_scale) in actual.iter().zip(expected.iter()) {
            let (
                super::MtmfsScaleRhs::Dense(actual_scale),
                super::MtmfsScaleRhs::Dense(expected_scale),
            ) = (actual_scale, expected_scale)
            else {
                panic!("dense reference expected");
            };
            for (actual_term, expected_term) in actual_scale.iter().zip(expected_scale.iter()) {
                for (actual, expected) in actual_term.iter().zip(expected_term.iter()) {
                    assert!((actual - expected).abs() < 8.0e-4);
                }
            }
        }
    }

    #[test]
    fn mtmfs_bounded_scale_subtraction_matches_precomputed_psf_scales() {
        let shape = (32, 32);
        let center = (shape.0 / 2, shape.1 / 2);
        let psf_terms = (0..3)
            .map(|order| {
                Array2::from_shape_fn(shape, |(x, y)| {
                    let radius2 =
                        (x as f32 - center.0 as f32).powi(2) + (y as f32 - center.1 as f32).powi(2);
                    (1.0 + order as f32 * 0.1) * (-radius2 / 20.0).exp()
                })
            })
            .collect::<Vec<_>>();
        let compact = super::make_compact_multiscale_kernel(3.0);
        let full = super::make_multiscale_kernel(shape, 3.0);
        let position = (13, 19);
        let coefficients = [0.8, -0.35];
        let gain = 0.1;
        let mut actual = vec![
            Array2::from_shape_fn(shape, |(x, y)| (x * 3 + y * 5) as f32 * 0.002),
            Array2::from_shape_fn(shape, |(x, y)| (x * 7 + y * 2) as f32 * -0.001),
        ];
        let mut expected = actual.clone();

        super::subtract_mtmfs_multiscale_component(
            &mut actual,
            &psf_terms,
            &compact,
            position,
            gain,
            &coefficients,
        );
        for residual_order in 0..2 {
            for model_order in 0..2 {
                let scaled_psf =
                    super::fft_convolve_real(&psf_terms[residual_order + model_order], &full);
                super::subtract_shifted_kernel(
                    &mut expected[residual_order],
                    &scaled_psf,
                    position,
                    gain * coefficients[model_order],
                );
            }
        }

        for (actual_term, expected_term) in actual.iter().zip(expected.iter()) {
            for (actual, expected) in actual_term.iter().zip(expected_term.iter()) {
                assert!((actual - expected).abs() < 3.0e-5);
            }
        }
    }

    #[test]
    fn mtmfs_run_produces_taylor_terms_and_alpha_products() {
        let geometry = ImageGeometry {
            image_shape: [48, 48],
            cell_size_rad: [1.2e-4, 1.2e-4],
        };
        let samples = [(25.0, -12.0, 0.0), (-18.0, 21.0, 0.0), (8.0, 11.0, 0.0)];
        let low = point_source_visibilities(
            &samples,
            geometry.cell_size_rad[0],
            geometry.image_shape,
            (24.0, 24.0),
            0.7,
        );
        let high = point_source_visibilities(
            &samples,
            geometry.cell_size_rad[0],
            geometry.image_shape,
            (24.0, 24.0),
            1.3,
        );
        let mut batch = VisibilityBatch {
            u_lambda: Vec::new(),
            v_lambda: Vec::new(),
            w_lambda: Vec::new(),
            weight: Vec::new(),
            sumwt_factor: Vec::new(),
            gridable: Vec::new(),
            visibility: Vec::new(),
        };
        let mut frequencies_hz = Vec::new();
        for (source_batch, frequency_hz) in [(&low, 1.39e9_f64), (&high, 1.41e9_f64)] {
            batch
                .u_lambda
                .extend_from_slice(source_batch.u_lambda.as_slice());
            batch
                .v_lambda
                .extend_from_slice(source_batch.v_lambda.as_slice());
            batch
                .w_lambda
                .extend_from_slice(source_batch.w_lambda.as_slice());
            batch
                .weight
                .extend_from_slice(source_batch.weight.as_slice());
            batch
                .sumwt_factor
                .extend_from_slice(source_batch.sumwt_factor.as_slice());
            batch
                .gridable
                .extend_from_slice(source_batch.gridable.as_slice());
            batch
                .visibility
                .extend_from_slice(source_batch.visibility.as_slice());
            frequencies_hz.extend(std::iter::repeat_n(frequency_hz, source_batch.len()));
        }

        let result = run_mtmfs(
            &MtmfsRequest {
                geometry,
                visibility_batches: vec![batch.clone()],
                sample_frequency_batches_hz: vec![frequencies_hz.clone()],
                gridder_mode: GridderMode::Standard,
                plane_stokes: PlaneStokes::I,
                weighting: WeightingMode::Natural,
                reffreq_hz: 1.40e9,
                selected_frequency_range_hz: [1.39e9, 1.41e9],
                nterms: 2,
                multiscale_scales: Vec::new(),
                small_scale_bias: 0.0,
                w_term_mode: WTermMode::None,
                w_project_planes: None,
                clean: CleanConfig {
                    niter: 6,
                    major_cycle_limit: None,
                    gain: 0.1,
                    threshold_jy_per_beam: 0.0,
                    nsigma: 0.0,
                    psf_cutoff: 0.35,
                    minor_cycle_length: 2,
                    cyclefactor: 1.0,
                    min_psf_fraction: 0.05,
                    max_psf_fraction: 0.8,
                    hogbom_iteration_mode: HogbomIterationMode::CasaInclusive,
                },
                clean_mask: None,
                compatibility: CompatibilityMode::CasaStandardMfs,
            },
            &correctness_execution_config(),
        )
        .unwrap();

        assert_eq!(result.psf_terms.len(), 3);
        assert_eq!(result.residual_terms.len(), 2);
        assert_eq!(result.model_terms.len(), 2);
        assert_eq!(result.image_terms.len(), 2);
        assert_eq!(result.sumwt_terms.len(), 3);
        assert!(result.alpha.is_some());
        assert!(result.alpha_error.is_some());
        assert!(result.diagnostics.gridded_samples > 0);
        assert!(result.diagnostics.major_cycles > 0);
        assert!(result.diagnostics.minor_iterations > 0);
        assert_eq!(result.compatibility.channel_frequencies_hz, vec![1.40e9]);
        assert_eq!(result.image_terms[0].shape(), &[48, 48, 1, 1]);
        assert!(peak_abs_value(&result.image_terms[0].slice(s![.., .., 0, 0]).to_owned()) > 1.0e-3);
        assert!(peak_abs_value(&result.image_terms[1].slice(s![.., .., 0, 0]).to_owned()) > 1.0e-4);
        assert!(
            peak_abs_value(
                &result
                    .alpha
                    .as_ref()
                    .unwrap()
                    .slice(s![.., .., 0, 0])
                    .to_owned()
            ) > 1.0e-4
        );

        let multiscale_wproject = run_mtmfs(
            &MtmfsRequest {
                geometry,
                visibility_batches: vec![batch],
                sample_frequency_batches_hz: vec![frequencies_hz],
                gridder_mode: GridderMode::Standard,
                plane_stokes: PlaneStokes::I,
                weighting: WeightingMode::Natural,
                reffreq_hz: 1.40e9,
                selected_frequency_range_hz: [1.39e9, 1.41e9],
                nterms: 2,
                multiscale_scales: vec![0.0, 3.0, 8.0],
                small_scale_bias: 0.9,
                w_term_mode: WTermMode::WProject,
                w_project_planes: Some(4),
                clean: CleanConfig {
                    niter: 4,
                    major_cycle_limit: None,
                    gain: 0.1,
                    threshold_jy_per_beam: 0.0,
                    nsigma: 0.0,
                    psf_cutoff: 0.35,
                    minor_cycle_length: 2,
                    cyclefactor: 1.0,
                    min_psf_fraction: 0.05,
                    max_psf_fraction: 0.8,
                    hogbom_iteration_mode: HogbomIterationMode::CasaInclusive,
                },
                clean_mask: None,
                compatibility: CompatibilityMode::CasaStandardMfs,
            },
            &correctness_execution_config(),
        )
        .unwrap();

        assert_eq!(multiscale_wproject.psf_terms.len(), 3);
        assert_eq!(multiscale_wproject.model_terms.len(), 2);
        assert!(multiscale_wproject.diagnostics.gridded_samples > 0);
        assert!(multiscale_wproject.diagnostics.minor_iterations > 0);
        assert!(
            multiscale_wproject
                .diagnostics
                .minor_cycle_traces
                .iter()
                .any(|trace| trace.initial_scale_pixels.is_some_and(|scale| scale >= 0.0))
        );
    }

    #[test]
    fn hogbom_reduces_peak_residual() {
        let samples = vec![
            (-140.0, -110.0, 0.0),
            (-80.0, 60.0, 0.0),
            (45.0, -95.0, 0.0),
            (120.0, 70.0, 0.0),
            (0.0, 0.0, 0.0),
        ];
        let geometry = ImageGeometry {
            image_shape: [64, 64],
            cell_size_rad: [1.0e-4, 1.0e-4],
        };
        let batch = point_source_visibilities(&samples, 1.0e-4, [64, 64], (32.0, 32.0), 1.0);
        let dirty = run_imaging(&ImagingRequest {
            geometry,
            visibility_batches: vec![batch.clone()],
            gridder_mode: GridderMode::Standard,
            plane_stokes: PlaneStokes::I,
            weighting: WeightingMode::Natural,
            reffreq_hz: 1.4e9,
            selected_frequency_range_hz: [1.399e9, 1.401e9],
            deconvolver: Deconvolver::Hogbom,
            multiscale_scales: Vec::new(),
            small_scale_bias: 0.0,
            clean: CleanConfig::default(),
            clean_mask: None,
            initial_model: None,
            w_term_mode: WTermMode::None,
            w_project_planes: None,
            compatibility: CompatibilityMode::CasaStandardMfs,
        })
        .unwrap();
        let clean = run_imaging(&ImagingRequest {
            geometry,
            visibility_batches: vec![batch],
            gridder_mode: GridderMode::Standard,
            plane_stokes: PlaneStokes::I,
            weighting: WeightingMode::Natural,
            reffreq_hz: 1.4e9,
            selected_frequency_range_hz: [1.399e9, 1.401e9],
            deconvolver: Deconvolver::Hogbom,
            multiscale_scales: Vec::new(),
            small_scale_bias: 0.0,
            clean: CleanConfig {
                niter: 8,
                major_cycle_limit: None,
                gain: 0.2,
                threshold_jy_per_beam: 0.0,
                nsigma: 0.0,
                psf_cutoff: 0.35,
                minor_cycle_length: 2,
                cyclefactor: 1.0,
                min_psf_fraction: 0.05,
                max_psf_fraction: 0.8,
                hogbom_iteration_mode: HogbomIterationMode::CasaInclusive,
            },
            clean_mask: None,
            initial_model: None,
            w_term_mode: WTermMode::None,
            w_project_planes: None,
            compatibility: CompatibilityMode::CasaStandardMfs,
        })
        .unwrap();

        assert!(
            clean.diagnostics.final_residual_peak_jy_per_beam
                < dirty.diagnostics.final_residual_peak_jy_per_beam
        );
        let last_trace = clean
            .diagnostics
            .minor_cycle_traces
            .last()
            .expect("clean run should record a minor-cycle trace");
        assert_close_f32(
            last_trace.end_peak_residual_jy_per_beam,
            clean.diagnostics.final_residual_peak_jy_per_beam,
            1.0e-6,
        );
        assert!(clean.model[(32, 32, 0, 0)] > 0.0);
    }

